-- Parte 6: Nuovi Bloopers da 2177 a 2676 (500 query)

UPDATE errori SET descrizione_i18n = '{"it":"Quando Luke Skywalker entra nella sala del trono di Jabba the Hutt, l''oggetto che usa come bastone (o la posizione delle sue mani) cambia leggermente tra un cambio di inquadratura e l''altro prima di rivelare la sua vera intenzione.","en":"When Luke Skywalker enters Jabba the Hutt''s throne room, the prop he uses as a cane (or the position of his hands) changes slightly between cuts before revealing his true intention.","es":"Cuando Luke Skywalker entra en la sala del trono de Jabba el Hutt, el utilería que usa como bastón (o la posición de sus manos) cambia ligeramente entre plano y contraplano antes de revelar su verdadera intención.","fr":"Quand Luke Skywalker entre dans la salle du trône de Jabba le Hutt, l''accessoire qu''il utilise comme canne (ou la position de ses mains) change légèrement d''un raccord à l''autre avant de révéler sa véritable intention.","de":"Wenn Luke Skywalker Jabba the Hutts Thronsaal betritt, verändert sich die Requisite, die er als Stock benutzt (oder die Position seiner Hände), leicht zwischen den Schnitten, bevor er seine wahren Absichten offenbart."}'::jsonb WHERE id = 4759;
UPDATE errori SET descrizione_i18n = '{"it":"Nel palazzo di Jabba, durante la scena in cui la troupe discute sul da farsi, la disposizione delle tazze e dei bicchieri sul tavolo vicino a Bib Fortuna muta tra i campi lunghi e i primi piani.","en":"In Jabba''s palace, during the scene where the entourage discusses what to do next, the arrangement of cups and glasses on the table near Bib Fortuna shifts between wide shots and close-ups.","es":"En el palacio de Jabba, durante la escena en la que el séquito discute qué hacer, la disposición de las tazas y vasos en la mesa cerca de Bib Fortuna cambia entre los planos generales y los primeros planos.","fr":"Dans le palais de Jabba, pendant la scène où la cour discute de la marche à suivre, la disposition des tasses et des verres sur la table près de Bib Fortuna varie entre les plans larges et les gros plans.","de":"In Jabbas Palast, während der Szene, in der das Gefolge beratschlagt, was zu tun ist, verändert sich die Anordnung von Tassen und Gläsern auf dem Tisch in der Nähe von Bib Fortuna zwischen den Halbtotalen und Nahaufnahmen."}'::jsonb WHERE id = 4760;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le sequenze sulla luna boscosa di Endor, in alcune inquadrature ampie tra gli alberi, è possibile intravedere brevemente l''ombra di un microfono a giraffa (boom mic) proiettata sul fogliame o sulla divisa di un soldato ribelle.","en":"During the sequences on the forest moon of Endor, in some wide shots among the trees, the shadow of a boom mic can briefly be seen cast on the foliage or a rebel soldier''s uniform.","es":"Durante las secuencias en la luna boscosa de Endor, en algunos planos generales entre los árboles, se puede ver brevemente la sombra de un micrófono de pértiga (boom mic) proyectada sobre el follaje o el uniforme de un soldado rebelde.","fr":"Pendant les séquences sur la lune forestière d''Endor, dans certains plans larges parmi les arbres, on peut brièvement apercevoir l''ombre d''un micro perche (boom mic) projetée sur le feuillage ou sur l''uniforme d''un soldat rebelle.","de":"Während der Sequenzen auf dem Waldmond Endor ist in einigen Weitwinkel-Einstellungen zwischen den Bäumen kurz der Schatten eines Galgenmikrofons (Boom-Mic) auf dem Laub oder der Uniform eines Rebellen-Soldaten zu sehen."}'::jsonb WHERE id = 4761;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno del centro di comando della seconda Morte Nera, la posizione dei pannelli di controllo e lo stato dei bottoni illuminati variano in modo incoerente durante le conversazioni tra l''Imperatore, Darth Vader e gli ufficiali imperiali.","en":"Inside the command center of the second Death Star, the position of the control panels and the status of the lighted buttons vary inconsistently during conversations between the Emperor, Darth Vader, and the Imperial officers.","es":"Dentro del centro de mando de la segunda Estrella de la Muerte, la posición de los paneles de control y el estado de los botones iluminados varían de forma incoherente durante las conversaciones entre el Emperador, Darth Vader y los oficiales imperiales.","fr":"À l''intérieur du centre de commande de la seconde Étoile de la Mort, la position des panneaux de contrôle et l''état des boutons lumineux varient de manière incohérente lors des conversations entre l''Empereur, Dark Vador et les officiers impériaux.","de":"Im Inneren des Kommandozentrums des zweiten Todessterns variieren die Position der Bedienfelder und der Status der beleuchteten Knöpfe während der Gespräche zwischen dem Imperator, Darth Vader und den imperialen Offizieren inkonsistent."}'::jsonb WHERE id = 4762;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia spaziale, nei vari passaggi in cui la telecamera mostra l''interno dell''abitacolo del caccia A-wing o X-wing, i caschi dei piloti ribelli presentano segni di usura e graffi che differiscono visivamente da un''inquadratura all''altra.","en":"During the space battle, in various cuts showing the interior of the A-wing or X-wing cockpit, the rebel pilots'' helmets show wear and tear marks and scratches that visually differ from one shot to another.","es":"Durante la batalla espacial, en varios planos que muestran el interior de la cabina del caza A-wing o X-wing, los cascos de los pilotos rebeldes presentan marcas de desgaste y arañazos que difieren visualmente de un plano a otro.","fr":"Pendant la bataille spatiale, dans les différents plans montrant l''intérieur du cockpit du chasseur A-wing ou X-wing, les casques des pilotes rebelles présentent des traces d''usure et des égratignures qui diffèrent visuellement d''un plan à l''autre.","de":"Während der Raumschlacht zeigen die Helme der Rebellen-Piloten in verschiedenen Aufnahmen des Cockpits eines A-Wing oder X-Wing Abnutzungsspuren und Kratzer, die sich von Einstellung zu Einstellung optisch unterscheiden."}'::jsonb WHERE id = 4763;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la nave della Regina Amidala sfugge al blocco della Federazione dei Mercanti ed è danneggiata, i droidi astromeccanici escono a ripararla. Il droide R2-B1 viene colpito e cade nello spazio, ma in un''inquadratura successiva lo si vede nuovamente al lavoro sulla fusoliera prima di sparire definitivamente.","en":"When Queen Amidala''s ship escapes the Trade Federation blockade and is damaged, astromech droids go out to repair it. The droid R2-B1 is hit and falls into space, but in a subsequent shot it is seen working on the hull again before disappearing for good.","es":"Cuando la nave de la Reina Amidala escapa del bloqueo de la Federación de Comercio y sufre daños, los droides astromecánicos salen a repararla. El droide R2-B1 es alcanzado y cae al espacio, pero en un plano posterior se le ve de nuevo trabajando en el fuselaje antes de desaparecer definitivamente.","fr":"Quand le vaisseau de la Reine Amidala échappe au blocus de la Fédération du Commerce et est endommagé, des droïdes astromechs sortent pour le réparer. Le droïde R2-B1 est touché et tombe dans l''espace, mais dans un plan ultérieur, on le revoit à l''œuvre sur le fuselage avant de disparaître définitivement.","de":"Als das Schiff der Königin Amidala der Handelsföderation-Blockade entkommt und beschädigt wird, rücken Astromech-Droiden aus, um es zu reparieren. Der Droide R2-B1 wird getroffen und stürzt in den Weltraum, aber in einer späteren Einstellung sieht man ihn wieder an der Hülle arbeiten, bevor er endgültig verschwindet."}'::jsonb WHERE id = 4764;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Anakin mostra il suo Podracer a Qui-Gon e Shmi nella cucina, la posizione degli utensili e dei pezzi di ricambio sul tavolo da lavoro cambia in modo evidente tra le diverse inquadrature in campo medio e primo piano.","en":"In the scene where Anakin shows his Podracer to Qui-Gon and Shmi in the kitchen, the position of the tools and spare parts on the workbench noticeably changes between the medium shots and close-ups.","es":"En la escena en la que Anakin muestra su Podracer a Qui-Gon y Shmi en la cocina, la posición de las herramientas y piezas de repuesto en la mesa de trabajo cambia de forma evidente entre los planos medios y los primeros planos.","fr":"Dans la scène où Anakin montre son Podracer à Qui-Gon et Shmi dans la cuisine, la position des outils et des pièces de rechange sur l''établi change de manière flagrante entre les plans moyens et les gros plans.","de":"In der Szene, in der Anakin Qui-Gon und Shmi in der Küche seinen Podracer zeigt, verändert sich die Position der Werkzeuge und Ersatzteile auf der Werkbank zwischen den Halbtotalen und Nahaufnahmen deutlich."}'::jsonb WHERE id = 4765;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia finale su Naboo, la pistola blaster di Padmé Amidala cambia modello e impugnatura in alcune sequenze dinamiche, passando da un prop dettagliato a una versione in gomma più semplice utilizzata per gli stunt.","en":"During the final battle on Naboo, Padmé Amidala''s blaster pistol changes model and grip in some dynamic sequences, switching from a detailed prop to a simpler rubber version used for stunts.","es":"Durante la batalla final en Naboo, la pistola bláster de Padmé Amidala cambia de modelo y empuñadura en algunas secuencias dinámicas, pasando de un atrezo detallado a una versión de goma más sencilla utilizada para las escenas de riesgo.","fr":"Pendant la bataille finale sur Naboo, le pistolet blaster de Padmé Amidala change de modèle et de poignée dans certaines séquences dynamiques, passant d''un accessoire détaillé à une version en caoutchouc plus simple utilisée pour les cascades.","de":"Während der finalen Schlacht auf Naboo wechseln Modell und Griff von Padmé Amidalas Blasterpistole in einigen dynamischen Sequenzen, wobei von einer detaillierten Requisite zu einer einfacheren Gummiversion für Stunts gewechselt wird."}'::jsonb WHERE id = 4766;
UPDATE errori SET descrizione_i18n = '{"it":"Prima dell''inizio della gara di Podrace, quando i piloti presentano i loro mezzi sulla griglia di partenza, la posizione e la postura di Sebulba rispetto al suo pod cambiano drasticamente nei vari tagli di montaggio.","en":"Before the start of the Podrace, when the pilots present their vehicles on the starting grid, Sebulba''s position and posture relative to his pod change drastically across various edit cuts.","es":"Antes de que empiece la carrera de vainas, cuando los pilotos presentan sus vehículos en la parrilla de salida, la posición y la postura de Sebulba respecto a su vaina cambian drásticamente entre los distintos cortes de montaje.","fr":"Avant le début de la course de Podraces, lorsque les pilotes présentent leurs véhicules sur la grille de départ, la position et la posture de Sebulba par rapport à son module changent radicalement au fil des coupes de montage.","de":"Vor Beginn des Podrennen, wenn die Piloten ihre Fahrzeuge in der Startaufstellung präsentieren, ändern sich Sebulbas Position und Haltung zu seinem Pod in den verschiedenen Filmschnitten drastisch."}'::jsonb WHERE id = 4767;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sequenza a Mos Espa, in alcune inquadrature sullo sfondo tra la folla di alieni e cittadini, è possibile intravedere la sagoma di alcune marionette manovrate in modo imperfetto o aste di supporto non completamente cancellate nel montaggio originale in sala.","en":"During the Mos Espa sequence, in some background shots among the crowd of aliens and citizens, the silhouette of imperfectly operated puppets or support rods not completely erased can be spotted in the original theatrical cut.","es":"Durante la secuencia de Mos Espa, en algunos planos de fondo entre la multitud de alienígenas y ciudadanos, se puede vislumbrar la silueta de algunas marionetas manejadas de forma imperfecta o varillas de soporte que no se borraron por completo en el montaje original de cine.","fr":"Pendant la séquence de Mos Espa, dans certains plans d''arrière-plan au milieu de la foule d''aliens et de citoyens, on peut apercevoir la silhouette de marionnettes mal manipulées ou des tiges de soutien non entièrement effacées dans le montage original en salle.","de":"Während der Mos Espa-Sequenz sind in einigen Hintergrundeinstellungen inmitten der Menge aus Aliens und Bürgern die Silhouetten unvollkommen geführter Puppen oder Stützstangen zu sehen, die im originalen Kinocchnitt nicht vollständig entfernt wurden."}'::jsonb WHERE id = 4768;
UPDATE errori SET descrizione_i18n = '{"it":"Quando il droide di protocollo TC-14 viene distrutto o disattivato nel palazzo reale di Theed, i pezzi di cavi e la posizione delle braccia variano tra l''inquadratura in cui cade e quella successiva in primo piano.","en":"When the protocol droid TC-14 is destroyed or deactivated in the Theed royal palace, the loose wires and arm positions vary between the shot where it falls and the following close-up.","es":"Cuando el droide de protocolo TC-14 es destruido o desactivado en el palacio real de Theed, los cables sueltos y la posición de los brazos varían entre el plano en el que cae y el primer plano siguiente.","fr":"Lorsque le droïde de protocole TC-14 est détruit ou désactivé dans le palais royal de Theed, les fils électriques et la position des bras changent entre le plan où il s''effondre et le gros plan suivant.","de":"Als der Protokolldroide TC-14 im königlichen Palast von Theed zerstört oder deaktiviert wird, variieren die Kabelstücke und die Armposition zwischen der Einstellung, in der er stürzt, und der folgenden Nahaufnahme."}'::jsonb WHERE id = 4769;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''inseguimento nei bassifondi di Coruscant, quando Obi-Wan Kenobi salta fuori dal taxi per atterrare sul velivolo di Zam Wesell, la posizione del suo mantello e dei suoi capelli cambia radicalmente tra l''inquadratura del salto e quella immediatamente successiva sull''atterraggio.","en":"During the Coruscant slums chase, when Obi-Wan Kenobi jumps out of the speeder cab to land on Zam Wesell''s ship, the position of his cloak and hair changes drastically between the jump shot and the immediate landing shot.","es":"Durante la persecución en los bajos fondos de Coruscant, cuando Obi-Wan Kenobi salta del taxi aéreo para aterrizar en la nave de Zam Wesell, la posición de su capa y su cabello cambia drásticamente entre el plano del salto y el plano posterior del aterrizaje.","fr":"Pendant la poursuite dans les bas-fonds de Coruscant, quand Obi-Wan Kenobi saute du taxi pour atterrir sur le vaisseau de Zam Wesell, la position de sa cape et de ses cheveux change radicalement entre le plan du saut et le plan suivant de l''atterrissage.","de":"Während der Verfolgungsjagd in den Slums von Coruscant, als Obi-Wan Kenobi aus dem Gleiter springt, um auf dem Schiff von Zam Wesell zu landen, verändert sich die Position seines Mantels und seiner Haare drastisch zwischen der Sprungeinstellung und der direkten Landungseinstellung."}'::jsonb WHERE id = 4770;
UPDATE errori SET descrizione_i18n = '{"it":"Nel tempio Jedi, quando Yoda sta addestrando i giovani iniziati, la disposizione dei piccoli elenchi e dei banchi circolari attorno a loro subisce leggere variazioni di posizione nei cambi d''inquadratura tra i vari giovani.","en":"In the Jedi Temple, when Yoda is training the young initiates, the arrangement of the small datapad lists and the circular desks around them undergoes slight positional changes in the cuts between various younglings.","es":"En el templo Jedi, cuando Yoda está entrenando a los jóvenes iniciados, la disposición de las pequeñas listas y los pupitres circulares que los rodean sufre ligeras variaciones de posición en los cambios de plano entre los diferentes jóvenes.","fr":"Dans le temple Jedi, lorsque Yoda entraîne les jeunes initiés, la disposition des petites tablettes et des pupitres circulaires autour d''eux subit de légères variations de position lors des changements de plan entre les différents jeunes padawans.","de":"Im Jedi-Tempel, als Yoda die jungen Jünglinge ausbildet, weist die Anordnung der kleinen Datapad-Listen und der runden Pulte um sie herum leichte Positionsveränderungen bei den Umschnitten zwischen den verschiedenen Jünglingen auf."}'::jsonb WHERE id = 4771;
UPDATE errori SET descrizione_i18n = '{"it":"Nel laboratorio di Kamino, mentre Lama Su mostra ad Obi-Wan la crescita dei cloni nelle vasche, il liquido e i tubi di supporto dei cloni bambini variano lo spessore e la posizione dei riflessi di luce tra un taglio e l''altro.","en":"In the Kamino laboratory, while Lama Su shows Obi-Wan the growth of the clones in the vats, the liquid and the support tubes for the child clones vary in thickness and light reflection position between cuts.","es":"En el laboratorio de Kamino, mientras Lama Su le muestra a Obi-Wan el crecimiento de los clones en los tanques, el grosor del líquido y los tubos de soporte de los niños clon varían, al igual que la posición de los reflejos de luz entre un corte y otro.","fr":"Dans le laboratoire de Kamino, tandis que Lama Su montre à Obi-Wan la croissance des clones dans les cuves, l''épaisseur du liquide et la position des reflets lumineux sur les tubes de soutien des jeunes clones varient d''un raccord à l''autre.","de":"Im Labor von Kamino, während Lama Su Obi-Wan das Wachstum der Klone in den Tanks zeigt, variieren die Flüssigkeit und die Halterohre der Klonkinder in ihrer Dicke und der Position der Lichtreflexe zwischen den einzelnen Schnitten."}'::jsonb WHERE id = 4772;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Anakin e Padmé si trovano a bordo della nave diretta su Naboo, la ciocca di capelli sul viso di Padmé cambia continuamente lato e lunghezza a ogni stacco di montaggio durante la conversazione romantica.","en":"In the scene where Anakin and Padmé are aboard the ship bound for Naboo, the lock of hair on Padmé''s face continuously changes side and length with every editing cut during their romantic conversation.","es":"En la escena en la que Anakin y Padmé están a bordo de la nave rumbo a Naboo, el mechón de cabello en la cara de Padmé cambia continuamente de lado y longitud en cada salto de montaje durante la conversación romántica.","fr":"Dans la scène où Anakin et Padmé se trouvent à bord du vaisseau en route pour Naboo, la mèches de cheveux sur le visage de Padmé change constamment de côté et de longueur à chaque raccord de montage pendant leur conversation romantique.","de":"In der Szene, in der sich Anakin und Padmé an Bord des Schiffes nach Naboo befinden, wechseln die Strähne im Gesicht von Padmé und deren Länge bei jedem Filmschnitt während des romantischen Gesprächs kontinuierlich die Seite."}'::jsonb WHERE id = 4773;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il duello con le spade laser tra il Conte Dooku e Anakin/Obi-Wan nel hangar segreto, lo stato e l''usura del mantello di Dooku appaiono diversi a seconda che l''inquadratura sia stretta o larga.","en":"During the lightsaber duel between Count Dooku and Anakin/Obi-Wan in the secret hangar, the condition and wear of Dooku''s cape look different depending on whether the shot is a close-up or a wide shot.","es":"Durante el duelo de sables de luz entre el conde Dooku y Anakin/Obi-Wan en el hangar secreto, el estado y el desgaste de la capa de Dooku se ven diferentes según si el plano es cerrado o abierto.","fr":"Pendant le duel au sabre laser entre le comte Dooku et Anakin/Obi-Wan dans le hangar secret, l''état et l''usure de la cape de Dooku paraissent différents selon qu''il s''agit d''un plan serré ou d''un plan large.","de":"Während des Lichtschwertduells zwischen Count Dooku und Anakin/Obi-Wan im geheimen Hangar erscheinen Zustand und Abnutzung von Dookus Umhang je nach Nah- oder Totale unterschiedlich."}'::jsonb WHERE id = 4774;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Palpatine viene liberato dalle catene sulla nave di Grievous, Anakin taglia i vincoli metallici; nell''inquadratura successiva i pezzi di metallo tagliati cambiano forma e posizione sul pavimento.","en":"At the moment Palpatine is freed from his chains on Grievous''s ship, Anakin cuts the metal restraints; in the following shot, the cut pieces of metal change shape and position on the floor.","es":"En el momento en que Palpatine es liberado de sus cadenas en la nave de Grievous, Anakin corta las ataduras metálicas; en el plano siguiente, los trozos de metal cortados cambian de forma y posición en el suelo.","fr":"Au moment où Palpatine est libéré de ses chaînes sur le vaisseau de Grievous, Anakin coupe les attaches métalliques ; sur le plan suivant, les morceaux de métal coupés changent de forme et de position sur le sol.","de":"In dem Moment, in dem Palpatine auf Grievous'' Schiff von seinen Ketten befreit wird, durchtrennt Anakin die Metallfesseln; in der nächsten Einstellung verändern die abgeschnittenen Metallstücke ihre Form und Position auf dem Boden."}'::jsonb WHERE id = 4775;
UPDATE errori SET descrizione_i18n = '{"it":"Nel tempio Jedi, durante il colloquio tra Yoda e Anakin in cui si parla della premonizione di Padmé, la ciocca di capelli di Anakin cambia visibilmente posizione sulla sua fronte tra un taglio di montaggio e l''altro.","en":"In the Jedi Temple, during the conversation between Yoda and Anakin about Padmé''s premonition, Anakin''s lock of hair visibly changes position on his forehead between editing cuts.","es":"En el templo Jedi, durante la charla entre Yoda y Anakin sobre la premonición de Padmé, el mechón de pelo de Anakin cambia visiblemente de posición en su frente entre un corte de montaje y otro.","fr":"Dans le temple Jedi, pendant l''entretien entre Yoda et Anakin concernant la prémonition de Padmé, la mèche de cheveux d''Anakin change visiblement de position sur son front d''un raccord de montage à l''autre.","de":"Im Jedi-Tempel verändert sich während des Gesprächs zwischen Yoda und Anakin über Padmés Vorahnung die Haarträhne auf Anakins Stirn zwischen den Filmschnitten sichtbar in ihrer Position."}'::jsonb WHERE id = 4776;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''incontro nel corridoio in cui Obi-Wan Kenobi informa Padmé della caduta di Anakin al lato oscuro, le pieghe e la posizione del mantello di Padmé variano notevolmente tra un''inquadratura e il controcampo.","en":"During the hallway meeting where Obi-Wan Kenobi informs Padmé of Anakin''s turn to the dark side, the folds and position of Padmé''s cloak change noticeably between the shot and the reverse shot.","es":"Durante el encuentro en el pasillo en el que Obi-Wan Kenobi informa a Padmé de la caída de Anakin al lado oscuro, los pliegues y la posición de la capa de Padmé varían notablemente entre plano y contraplano.","fr":"Pendant la scène du couloir où Obi-Wan Kenobi informe Padmé du passage d''Anakin du côté obscur, les plis et la position de la cape de Padmé changent sensiblement entre le champ et le contrechamp.","de":"Während der Flurszene, in der Obi-Wan Kenobi Padmé über Anakins Übertritt zur dunklen Seite informiert, verändern sich die Falten und die Position von Padmés Umhang zwischen der Einstellung und der Gegeneinstellung deutlich."}'::jsonb WHERE id = 4777;
UPDATE errori SET descrizione_i18n = '{"it":"Su Mustafar, mentre Anakin e Obi-Wan combattono spostandosi all''interno della struttura mineraria, i tubi di vapore sullo sfondo che vengono danneggiati cambiano stato di integrità nei cambi d''inquadratura.","en":"On Mustafar, as Anakin and Obi-Wan fight while moving through the mining facility, the damaged background steam pipes change their state of integrity across cuts.","es":"En Mustafar, mientras Anakin y Obi-Wan luchan desplazándose por el interior de las instalaciones mineras, las tuberías de vapor del fondo que resultan dañadas cambian su estado de integridad entre los cambios de plano.","fr":"Sur Mustafar, alors qu''Anakin et Obi-Wan se battent en se déplaçant dans l''installation minière, l''état d''intégrité des tuyaux de vapeur endommagés à l''arrière-plan varie d''un plan à l''autre.","de":"Auf Mustafar verändern die beschädigten Dampfrohre im Hintergrund während des Kampfes zwischen Anakin und Obi-Wan in der Bergbauanlage bei den Szenenwechseln ihren Intaktheitszustand."}'::jsonb WHERE id = 4778;
UPDATE errori SET descrizione_i18n = '{"it":"Sulle rive del fiume di lava di Mustafar, quando Obi-Wan si posiziona sulla riva elevata dicendo di avere la posizione di vantaggio (''I have the high ground''), la quantità di cenere e detriti vulcanici sugli stivali di Anakin varia tra i primi piani e i campi lunghi.","en":"On the shores of Mustafar''s lava river, when Obi-Wan takes the high ground, the amount of ash and volcanic debris on Anakin''s boots varies between close-ups and wide shots.","es":"A la orilla del río de lava de Mustafar, cuando Obi-Wan se sitúa en la posición elevada diciendo que tiene ventaja (''I have the high ground''), la cantidad de ceniza y restos volcánicos en las botas de Anakin varía entre los primeros planos y los planos generales.","fr":"Sur les rives de la rivière de lave de Mustafar, lorsque Obi-Wan prend de la hauteur en disant qu''il a l''avantage (''I have the high ground''), la quantité de cendre et de débris volcaniques sur les bottes d''Anakin varie entre les gros plans et les plans larges.","de":"Am Ufer des Lavaflusses auf Mustafar, als Obi-Wan sich auf die Anhöhe begibt und sagt, er sei im Vorteil (''I have the high ground''), variiert die Menge an Asche und vulkanischem Geröll auf Anakins Stiefeln zwischen Nahaufnahmen und Totalen."}'::jsonb WHERE id = 4779;
UPDATE errori SET descrizione_i18n = '{"it":"Quando il capitano Moden Canady riceve i rapporti sulla flotta della Resistenza sul ponte della Dreadnought, la tazza che tiene in mano o i terminali di controllo vicini cambiano posizione tra l''inquadratura ravvicinata e quella larga.","en":"When Captain Moden Canady receives reports on the Resistance fleet on the Dreadnought''s bridge, the cup he is holding or the nearby control terminals change position between the close-up and the wide shot.","es":"Cuando el capitán Moden Canady recibe los informes sobre la flota de la Resistencia en el puente de la Dreadnought, la taza que sostiene en la mano o los terminales de control cercanos cambian de posición entre el plano cerrado y el plano general.","fr":"Lorsque le capitaine Moden Canady reçoit des rapports sur la flotte de la Résistance sur la passerelle du Dreadnought, la tasse qu''il tient à la main ou les terminaux de contrôle proches changent de position entre le plan serré et le plan large.","de":"Als Captain Moden Canady auf der Brücke der Dreadnought Berichte über die Flotte des Widerstands erhält, wechseln die Tasse in seiner Hand oder die nahegelegenen Steuerungsmonitore zwischen der Nahaufnahme und der Totalen ihre Position."}'::jsonb WHERE id = 4780;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Luke Skywalker si spazzola la spalla dopo il confronto con Kylo Ren sulla superficie di Crait, i cristalli di sale rosso e bianco sul suo mantello variano sensibilmente nei tagli successivi.","en":"During the scene where Luke Skywalker brushes his shoulder after the confrontation with Kylo Ren on the surface of Crait, the red and white salt crystals on his cloak change noticeably across subsequent cuts.","es":"Durante la escena en la que Luke Skywalker se sacude el polvo del hombro tras el enfrentamiento con Kylo Ren en la superficie de Crait, los cristales de sal roja y blanca de su capa varían notablemente entre los distintos cortes.","fr":"Pendant la scène où Luke Skywalker s''épaule après l''affrontement avec Kylo Ren à la surface de Crait, les cristaux de sel rouge et blanc sur sa cape changent sensiblement d''un raccord à l''autre.","de":"In der Szene, in der sich Luke Skywalker nach der Konfrontation mit Kylo Ren auf der Oberfläche von Crait die Schulter abklopft, verändern sich die roten und weißen Salzkristalle auf seinem Umhang in den aufeinanderfolgenden Schnitten deutlich."}'::jsonb WHERE id = 4781;
UPDATE errori SET descrizione_i18n = '{"it":"In un''inquadratura ravvicinata all''interno degli hangar della nave della Resistenza prima della fuga su Crait, si intravede per un fotogramma il riflesso di un pannello di illuminazione della troupe sulla visiera protettiva di un casco.","en":"In a close-up inside the Resistance ship''s hangars before fleeing to Crait, the reflection of a crew lighting panel is briefly glimpsed on a helmet''s protective visor for a single frame.","es":"En un primer plano dentro de los hangares de la nave de la Resistencia antes de la huida a Crait, se vislumbra brevemente durante un fotograma el reflejo de un panel de iluminación del equipo técnico en la visera protectora de un casco.","fr":"Dans un plan serré à l''intérieur des hangars du vaisseau de la Résistance avant la fuite vers Crait, on aperçoit pendant une seule image le reflet d''un panneau d''éclairage de l''équipe technique sur la visière de protection d''un casque.","de":"In einer Nahaufnahme im Hangar des Widerstandsschiffs vor der Flucht nach Crait ist für einen einzigen Frame die Spiegelung eines Beleuchtungspaneels der Filmcrew auf dem Schutzvisier eines Helms zu sehen."}'::jsonb WHERE id = 4782;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui C-3PO subisce la cancellazione della memoria, il cavo principale che collega il visore diagnostico al suo retro cambia orientamento e tensione tra i primi piani di Poe e i campi medi.","en":"During the scene where C-3PO undergoes memory erasure, the main cable connecting the diagnostic visor to his back changes orientation and tension between Poe''s close-ups and the medium shots.","es":"Durante la escena en la que C-3PO sufre el borrado de memoria, el cable principal que conecta el visor de diagnóstico con su espalda cambia de orientación y tensión entre los primeros planos de Poe y los planos medios.","fr":"Pendant la scène où C-3PO subit l''effacement de sa mémoire, le câble principal reliant la visière de diagnostic à son dos change d''orientation et de tension entre les gros plans de Poe et les plans moyens.","de":"Während der Szene, in der bei C-3PO das Gedächtnis gelöscht wird, verändert das Hauptkabel, das das Diagnosevisier mit seinem Rücken verbindet, zwischen Poes Nahaufnahmen und den Halbtotalen seine Ausrichtung und Spannung."}'::jsonb WHERE id = 4783;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui la spada laser di Leia viene mostrata nella tenda della Resistenza, la posizione della lama e l''inclinazione dell''elsa rispetto al tessuto cambiano leggermente tra l''inquadratura dall''alto e quella frontale.","en":"When Leia''s lightsaber is shown in the Resistance tent, the position of the blade and the angle of the hilt relative to the fabric change slightly between the overhead shot and the frontal shot.","es":"En el momento en que se muestra el sable láser de Leia en la tienda de la Resistencia, la posición de la hoja y la inclinación de la empuñadura con respecto a la tela cambian ligeramente entre el plano cenital y el plano frontal.","fr":"Au moment où le sabre laser de Leia est présenté dans la tentes de la Résistance, la position de la lame et l''inclinaison de la poignée par rapport au tissu changent légèrement entre le plan en plongée et le plan de face.","de":"Als Leias Lichtschwert im Zelt des Widerstands gezeigt wird, verändern sich die Position der Klinge und die Neigung des Griffs relativ zum Stoff leicht zwischen der Aufsicht und der Frontaleinstellung."}'::jsonb WHERE id = 4784;
UPDATE errori SET descrizione_i18n = '{"it":"Sul ponte di comando dello Star Destroyer, le mani di Hux variano la loro posizione sui comandi della console tra un''inquadratura in campo largo e la successiva ripresa ravvicinata sul suo volto.","en":"On the Star Destroyer bridge, Hux''s hands shift their position on the console controls between a wide shot and the subsequent close-up on his face.","es":"En el puente del Destructor Estelar, las manos de Hux cambian de posición en los controles de la consola entre un plano general y el posterior plano medio o primer plano de su rostro.","fr":"Sur la passerelle du Star Destroyer, les mains de Hux changent de position sur les commandes de la console entre un plan large et le gros plan suivant sur son visage.","de":"Auf der Kommandobrücke des Sternenzerstörers wechseln Huxs Hände ihre Position auf den Konsolenbedienelementen zwischen einer Totalen und der anschließenden Nahaufnahme seines Gesichts."}'::jsonb WHERE id = 4785;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''arrivo della flotta dei cittadini su Exegol, la disposizione delle navi ribelli sullo schermo di navigazione del Falcon cambia posizione in modo incoerente nei vari tagli di montaggio.","en":"During the arrival of the citizens'' fleet on Exegol, the layout of the rebel ships on the Falcon''s navigation screen changes position inconsistently across various editing cuts.","es":"Durante la llegada de la flota ciudadana a Exegol, la disposición de las naves rebeldes en la pantalla de navegación del Halcón cambia de posición de forma inconsistente entre los diferentes cortes de montaje.","fr":"Lors de l''arrivée de la flotte des citoyens sur Exegol, la disposition des vaisseaux rebelles sur l''écran de navigation du Faucon change de position de manière incohérente au fil des raccords de montage.","de":"Während der Ankunft der Bürgerflotte auf Exegol verändert sich die Anordnung der Rebellen-Schiffe auf dem Navigationsbildschirm des Falken über verschiedene Schnittwechsel hinweg inkonsistent."}'::jsonb WHERE id = 4786;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui lo Stormtrooper sbatte la testa contro la porta della sala di controllo della Morte Nera, esaminando attentamente la sequenza e dietro le quinte si può notare brevemente il riflesso dell''attrezzatura di set e dei movimenti della troupe sulla corazza lucida di alcuni soldati imperiali.","en":"During the scene where the stormtrooper hits his head against the Death Star control room door, upon close inspection of the sequence and behind-the-scenes material, the reflection of set equipment and crew movements can briefly be seen on the polished armor of some imperial soldiers.","es":"Durante la escena en la que el stormtrooper se golpea la cabeza contra la puerta de la sala de control de la Estrella de la Muerte, al examinar atentamente la secuencia y el material detrás de cámaras, se puede notar brevemente el reflejo del equipo de set y de los movimientos del equipo técnico en la brillante armadura de algunos soldados imperiales.","fr":"Dans la scène où le Stormtrooper se cogne la tête contre la porte de la salle de contrôle de l''Étoile de la Mort, en examinant attentivement la séquence et les coulisses, on peut apercevoir brièvement le reflet du matériel de plateau et des mouvements de l''équipe technique sur l''armure polie de certains soldats impériaux.","de":"In der Szene, in der der Sturmtruppler mit dem Kopf gegen die Tür des Kontrollraums des Todessterns prallt, ist bei genauerer Betrachtung der Sequenz und des Making-of kurz das Spiegelbild der Set-Ausstattung und der Crew-Bewegungen auf der polierten Rüstung einiger imperialer Soldaten zu erkennen."}'::jsonb WHERE id = 4787;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza finale della battaglia della Morte Nera, quando Luke guarda fuori dall''abitacolo del suo X-wing, i capelli biondi cambiano visibilmente stile e lunghezza tra un''inquadratura in primo piano e quella successiva con il casco.","en":"In the final sequence of the Death Star battle, when Luke looks out from the cockpit of his X-wing, his blond hair noticeably changes style and length between a close-up shot and the subsequent shot with his helmet on.","es":"En la secuencia final de la batalla de la Estrella de la Muerte, cuando Luke mira fuera de la cabina de su X-wing, su cabello fucsia o rubio cambia notablemente de estilo y longitud entre un plano detalle o primer plano y el plano posterior con el casco.","fr":"Dans la séquence finale de la bataille de l''Étoile de la Mort, lorsque Luke regarde par la verrière du cockpit de son X-wing, ses cheveux blonds changent visiblement de style et de longueur entre un gros plan et le plan suivant avec son casque.","de":"In der Schlussequenz der Todesstern-Schlacht, als Luke aus dem Cockpit seines X-Wing blickt, verändern sich seine blonden Haare zwischen einer Nahaufnahme und der darauffolgenden Aufnahme mit Helm sichtbar in Stil und Länge."}'::jsonb WHERE id = 4788;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Obi-Wan Kenobi disattiva il raggio trattore della Morte Nera e viene intercettato da Darth Vader, la spada laser di Vader cambia leggermente lunghezza della lama e impugnatura in alcune inquadrature ravvicinate a causa dell''uso di prop differenti.","en":"When Obi-Wan Kenobi deactivates the Death Star tractor beam and is intercepted by Darth Vader, Vader''s lightsaber slightly changes blade length and hilt design in some close-up shots due to the use of different props.","es":"Cuando Obi-Wan Kenobi desactiva el rayo tractor de la Estrella de la Muerte y es interceptado por Darth Vader, la espada láser de Vader cambia ligeramente la longitud de la hoja y la empuñadura en algunos planos cortos debido al uso de diferentes atrezos (props).","fr":"Quand Obi-Wan Kenobi désactive le rayon tracteur de l''Étoile de la Mort et se fait intercepter par Dark Vador, le sabre laser de Vador change légèrement de longueur de lame et de poignée dans certains gros plans en raison de l''utilisation de différents accessoires (props).","de":"Als Obi-Wan Kenobi den Traktorstrahl des Todessterns deaktiviert und von Darth Vader abgefangen wird, verändert Vaders Lichtschwert in einigen Nahaufnahmen aufgrund der Verwendung verschiedener Requisiten (Props) leicht die Klingenlänge und den Griff."}'::jsonb WHERE id = 4789;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Han Solo spara al pannello di controllo per impedire agli stormtrooper di entrare nella stanza delle comunicazioni della prigione, il buco provocato dal blaster sul pannello scompare e cambia posizione nelle inquadrature successive.","en":"At the moment Han Solo shoots the control panel to prevent the stormtroopers from entering the prison comms room, the blaster hole on the panel disappears and shifts position in subsequent shots.","es":"En el momento en que Han Solo dispara al panel de control para impedir que los stormtroopers entren en la sala de comunicaciones de la prisión, el agujero del bláster en el panel desaparece y cambia de posición en las tomas posteriores.","fr":"Au moment où Han Solo tire sur le panneau de commande pour empêcher les stormtroopers d''entrer dans la salle des communications de la prison, l''impact de blaster sur le panneau disparaît et change de position dans les plans suivants.","de":"In dem Moment, in dem Han Solo auf das Bedienfeld schießt, um zu verhindern, dass die Sturmtruppler den Gefängniskommunikationsraum betreten, verschwindet das Blasterloch auf dem Paneel und wechselt in den darauffolgenden Einstellungen seine Position."}'::jsonb WHERE id = 4790;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Luke e Obi-Wan incontrano Han Solo e Chewbacca nella cantina di Mos Eisley, in un angolo dello sfondo in basso a destra è visibile per un fotogramma il piede di un operatore di ripresa o di un membro della troupe fuori posto.","en":"In the scene where Luke and Obi-Wan meet Han Solo and Chewbacca in the Mos Eisley cantina, the foot of an out-of-place camera operator or crew member is visible for a single frame in the bottom right background corner.","es":"En la escena en la que Luke y Obi-Wan se encuentran con Han Solo y Chewbacca en la cantina de Mos Eisley, el pie de un operador de cámara o de un miembro del equipo técnico fuera de lugar se ve brevemente durante un fotograma en la esquina inferior derecha del fondo.","fr":"Dans la scène où Luke et Obi-Wan rencontrent Han Solo et Chewbacca dans la cantina de Mos Eisley, le pied d''un cadreur ou d''un membre de l''équipe technique égaré est visible pendant une seule image dans le coin inférieur droit de l''arrière-plan.","de":"In der Szene, in der Luke und Obi-Wan in der Mos-Eisley-Kantine auf Han Solo und Chewbacca treffen, ist in der unteren rechten Ecke des Hintergrunds für einen einzigen Frame der Fuß eines Kameramanns oder Crewmitglieds zu sehen."}'::jsonb WHERE id = 4791;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia di Hoth, quando i ribelli azionano il cannone a ioni, la posizione delle munizioni e dei pannelli di controllo cambia visibilmente tra il campo medio e i primi piani degli operatori.","en":"During the Battle of Hoth, when the rebels operate the ion cannon, the layout of the ammunition and control panels visibly changes between the medium shot and the close-ups of the operators.","es":"Durante la batalla de Hoth, cuando los rebeldes accionan el cañón de iones, la posición de la munición y de los paneles de control cambia visiblemente entre el plano medio y los primeros planos de los operarios.","fr":"Pendant la bataille de Hoth, lorsque les rebelles actionnent le canon à ions, la disposition des munitions et des panneaux de contrôle change visiblement entre le plan moyen et les gros plans des opérateurs.","de":"Während der Schlacht von Hoth, als die Rebellen die Ionenkanone bedienen, verändert sich die Position der Munition und der Bedienfelder zwischen der Halbtotalen und den Nahaufnahmen der Bediener sichtbar."}'::jsonb WHERE id = 4792;
UPDATE errori SET descrizione_i18n = '{"it":"Nel pianeta Dagobah, mentre Luke cammina nella palude con R2-D2, in un''inquadratura in campo largo è brevemente intravisto il cavo di controllo utilizzato dai burattinai per manovrare il droide.","en":"On the planet Dagobah, while Luke walks through the swamp with R2-D2, a wide shot briefly reveals the control wire used by the puppeteers to operate the droid.","es":"En el planeta Dagobah, mientras Luke camina por el pantano con R2-D2, en un plano general se ve brevemente el cable de control utilizado por los titiriteros para maniobrar el droide.","fr":"Sur la planète Dagobah, alors que Luke marche dans le marais avec R2-D2, un plan large laisse brièvement entrevoir le câble de commande utilisé par les marionnettistes pour actionner le droïde.","de":"Auf dem Planeten Dagobah, während Luke mit R2-D2 durch den Sumpf geht, ist in einer Totalen kurz der Steuerungsdraht zu sehen, den die Puppenspieler benutzten, um den Droiden zu bedienen."}'::jsonb WHERE id = 4793;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno del Millennium Falcon, mentre Leia pulisce la ferita a Ian Solo, la benda e gli strumenti medici sul tavolo appaiono e scompaiono o cambiano disposizione a ogni cambio d''inquadratura.","en":"Inside the Millennium Falcon, while Leia cleans Han Solo''s wound, the bandage and medical instruments on the table appear and disappear or change arrangement with every shot/reverse shot.","es":"Dentro del Halcón Milenario, mientras Leia limpia la herida de Han Solo, el vendaje y el instrumental médico sobre la mesa aparecen y desaparecen o cambian de disposición en cada plano y contraplano.","fr":"À l''intérieur du Faucon Millenium, alors que Leia soigne la blessure de Han Solo, le bandage et les instruments médicaux sur la table apparaissent et disparaissent ou changent de disposition à chaque raccord.","de":"Im Inneren des Millennium Falken, während Leia Han Solos Wunde versorgt, tauchen die Bandage und die medizinischen Instrumente auf dem Tisch auf und verschwinden wieder oder verändern bei jedem Schnitt ihre Anordnung."}'::jsonb WHERE id = 4794;
UPDATE errori SET descrizione_i18n = '{"it":"Nella Città delle Nuvole, quando Lando Calrissian entra nella sala da pranzo e affronta Dart Fener, la disposizione dei bicchieri e degli oggetti sul tavolo da portata varia tra le riprese frontali e quelle di spalle.","en":"In Cloud City, when Lando Calrissian enters the dining room and confronts Darth Vader, the placement of the glasses and objects on the serving table varies between front and reverse shots.","es":"En Ciudad Nube, cuando Lando Calrissian entra en el comedor y se enfrenta a Darth Vader, la disposición de los vasos y objetos en la mesa auxiliar varía entre los planos frontales y los contrapulidos.","fr":"Dans la Cité des Nuages, lorsque Lando Calrissian entre dans la salle à manger et fait face à Dark Vador, la disposition des verres et des objets sur le buffet varie entre les plans frontaux et les champs-contre-champs.","de":"In der Wolkenstadt, als Lando Calrissian den Speisesaal betritt und sich Darth Vader stellt, variiert die Anordnung der Gläser und Gegenstände auf dem Serviertisch zwischen Frontal- und Rückeneinstellungen."}'::jsonb WHERE id = 4795;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il duello nella Carbon Chamber, in un momento in cui Luke si scontra con Dart Fener, il movimento della bocca dell''attore non corrisponde esattamente al grugnito audio riprodotto in post-produzione.","en":"During the duel in the Carbon Chamber, in a moment when Luke clashes with Darth Vader, the actor''s mouth movement does not quite match the audio grunt dubbed in post-production.","es":"Durante el duelo en la Cámara de Carbono, en un momento en que Luke se enfrenta a Darth Vader, el movimiento de la boca del actor no coincide exactamente con el gruñido de audio reproducido en postproducción.","fr":"Pendant le duel dans la chambre de carbonisation, à un moment où Luke s''oppose à Dark Vador, le mouvement de la bouche de l''acteur ne correspond pas exactement au grognement audio mixé en post-production.","de":"Während des Duells in der Carbon-Gefrierkammer, in einem Moment, in dem Luke auf Darth Vader trifft, stimmt die Mundbewegung des Schauspielers nicht genau mit dem in der Postproduktion eingefügten Audio-Grunzen überein."}'::jsonb WHERE id = 4796;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia sulla luna boscosa di Endor, la posizione delle mani e dell''arma di un soldato imperiale (Stormtrooper) cambia visibilmente tra un''inquadratura ravvicinata e il campo largo successivo mentre cade a terra.","en":"During the battle on the forest moon of Endor, the position of an Imperial Stormtrooper''s hands and weapon noticeably changes between a close-up shot and the subsequent wide shot as he falls to the ground.","es":"Durante la batalla en la luna boscosa de Endor, la posición de las manos y el arma de un soldado imperial (Stormtrooper) cambia visiblemente entre un plano cerrado y el plano general posterior mientras cae al suelo.","fr":"Pendant la bataille sur la lune forestière d''Endor, la position des mains et de l''arme d''un Stormtrooper change visiblement entre un gros plan et le plan large suivant lorsqu''il s''écroule au sol.","de":"Während der Schlacht auf dem Waldmond Endor verändert sich die Position der Hände und der Waffe eines imperialen Sturmtrupplers merklich zwischen einer Nahaufnahme und der folgenden Totalen, als er zu Boden stürzt."}'::jsonb WHERE id = 4797;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Ian Solo viene liberato dalla lastra di carbonite nella sala del trono di Jabba, il pannello di controllo accanto a lui mostra spie luminose la cui sequenza cambia bruscamente a ogni taglio di montaggio.","en":"In the sequence where Han Solo is freed from the carbonite block in Jabba''s throne room, the control panel next to him displays indicator lights whose flashing sequence abruptly changes with every editing cut.","es":"En la secuencia en la que Han Solo es liberado de la losa de carbonita en la sala del trono de Jabba, el panel de control a su lado muestra luces indicadoras cuya secuencia cambia bruscamente en cada corte de montaje.","fr":"Dans la séquence où Han Solo est libéré du bloc de carbonite dans la salle du trône de Jabba, le panneau de commande à côté de lui affiche des voyants lumineux dont la séquence change brusquement à chaque raccord de montage.","de":"In der Sequenz, in der Han Solo in Jabbas Thronsaal aus der Karbonitplatte befreit wird, zeigt das Bedienfeld neben ihm Kontrollleuchten, deren Sequenz bei jedem Filmschnitt abrupt wechselt."}'::jsonb WHERE id = 4798;
UPDATE errori SET descrizione_i18n = '{"it":"In una delle inquadrature all''interno dell''hangar della base ribelle prima della partenza per Endor, è possibile intravedere brevemente il riflesso di un riflettore dello studio cinematografico sulla carrozzeria lucida di un caccia A-wing.","en":"In one of the shots inside the Rebel base hangar before the departure for Endor, the reflection of a studio lighting rig can be briefly glimpsed on the glossy hull of an A-wing starfighter.","es":"En uno de los planos dentro del hangar de la base rebelde antes de la partida hacia Endor, se puede vislumbrar brevemente el reflejo de un foco de estudio cinematográfico en el fuselaje brillante de un caza A-wing.","fr":"Dans l''un des plans à l''intérieur du hangar de la base rebelle avant le départ pour Endor, on peut entrapercevoir brièvement le reflet d''un projecteur de studio sur la carrosserie brillante d''un chasseur A-wing.","de":"In einer der Einstellungen im Hangar der Rebellenbasis vor dem Aufbruch nach Endor ist kurz die Reflexion eines Studio-Scheinwerfers auf der glänzenden Hülle eines A-Wing-Sternjägers zu sehen."}'::jsonb WHERE id = 4799;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Luke Skywalker entra nel palazzo di Jabba the Hutt, il teschio del droide torturatore e gli oggetti appesi alle pareti cambiano leggermente disposizione nello sfondo tra l''inquadratura in campo medio e il primo piano di Luke.","en":"When Luke Skywalker enters Jabba the Hutt''s palace, the torture droid''s skull and the objects hanging on the walls slightly shift their arrangement in the background between Luke''s medium shot and close-up.","es":"Cuando Luke Skywalker entra en el palacio de Jabba el Hutt, el cráneo del droide torturador y los objetos colgados en las paredes cambian ligeramente de disposición en el fondo entre el plano medio y el primer plano de Luke.","fr":"Quand Luke Skywalker entre dans le palais de Jabba le Hutt, le crâne du droïde tortionnaire et les objets suspendus aux murs changent légèrement de disposition à l''arrière-plan entre le plan moyen et le gros plan de Luke.","de":"Als Luke Skywalker Jabba the Hutts Palast betritt, verändert sich die Anordnung des Schädels des Folterdroiden und der an den Wänden hängenden Gegenstände im Hintergrund leicht zwischen der Halbtotalen und Lukes Nahaufnahme."}'::jsonb WHERE id = 4800;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza alla clinica Shrublands in cui Bond usa la macchina di trazione spinale per rimettersi in sesto, la posizione dei cuscini e delle cinghie di sicurezza cambia visibilmente tra un''inquadratura e l''altra mentre l''infermiera si allontana.","en":"During the sequence at the Shrublands clinic where Bond uses the spinal traction machine to straighten himself out, the position of the pillows and safety straps visibly changes between shots as the nurse walks away.","es":"Durante la secuencia en la clínica Shrublands en la que Bond usa la máquina de tracción espinal para enderezarse, la posición de los cojines y los cinturones de seguridad cambia visiblemente entre plano y plano mientras la enfermera se aleja.","fr":"Pendant la séquence à la clinique Shrublands où Bond utilise la machine de traction vertébrale pour se remettre d''aplomb, la position des coussins et des sangles de sécurité change visiblement d''un plan à l''autre alors que l''infirmière s''éloigne.","de":"Während der Sequenz in der Shrublands-Klinik, in der Bond das Streckbett für die Wirbelsäule benutzt, verändert sich die Position der Kissen und Sicherheitsgurte zwischen den Einstellungen sichtbar, während die Krankenschwester weggeht."}'::jsonb WHERE id = 4801;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della scena in cui James Bond arriva al porto delle Bahamas e incontra Felix Leiter, sul parabrezza della Chevrolet di servizio è chiaramente visibile per alcuni istanti il riflesso di un operatore della troupe con la cinepresa.","en":"During the scene where James Bond arrives at the Bahamas harbor and meets Felix Leiter, the reflection of a crew member with a camera is clearly visible for a few moments on the windshield of the government Chevrolet.","es":"En la escena en la que James Bond llega al puerto de Bahamas y se encuentra con Felix Leiter, el reflejo de un operador de cámara del equipo técnico es claramente visible durante unos instantes en el parabrisas del Chevrolet oficial.","fr":"Dans la scène où James Bond arrive au port des Bahamas et rencontre Felix Leiter, le reflet d''un membre de l''équipe technique avec sa caméra est clairement visible pendant quelques instants sur le pare-brise de la Chevrolet de service.","de":"In der Szene, in der James Bond im Hafen der Bahamas ankommt und Felix Leiter trifft, ist für einige Momente deutlich die Spiegelung eines Crewmitglieds mit einer Kamera auf der Windschutzscheibe des Dienst-Chevrolets zu sehen."}'::jsonb WHERE id = 4802;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Fatima Blush spara con il suo ombrello-arma modificato contro Bond durante l''inseguimento, i fori d''impatto dei proiettili sulla carrozzeria dell''auto variano di numero e disposizione nei successivi cambi di inquadratura.","en":"When Fatima Blush fires her modified weaponized umbrella at Bond during the chase, the number and layout of the bullet impact holes on the car body vary across successive cuts.","es":"Cuando Fatima Blush dispara contra Bond con su paraguas-arma modificado durante la persecución, el número y la disposición de los impactos de bala en la carrocería del coche varían en los sucesivos cambios de plano.","fr":"Quand Fatima Blush tire sur Bond avec son parapluie-arme modifié pendant la poursuite, le nombre et la disposition des impacts de balle sur la carrosserie de la voiture varient d''un raccord à l''autre.","de":"Als Fatima Blush während der Verfolgungsjagd mit ihrem modifizierten Waffenschirm auf Bond schießt, variieren die Anzahl und Anordnung der Einschusslöcher an der Karosserie des Autos bei den darauffolgenden Anschlüssen."}'::jsonb WHERE id = 4803;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le ricerche delle testate nucleari rubate, i monitor del centro operativo mostrano mappe satellitari e coordinate geografiche che non corrispondono alle reali rotte e posizioni geografiche citate dai dialoghi dei personaggi.","en":"During the search for the stolen nuclear warheads, the operations center monitors display satellite maps and geographical coordinates that do not match the real routes and geographical positions mentioned in the character dialogue.","es":"Durante la búsqueda de las cabezas nucleares robadas, los monitores del centro de operaciones muestran mapas por satélite y coordenadas geográficas que no se corresponden con las rutas y posiciones geográficas reales mencionadas en los diálogos de los personajes.","fr":"Pendant la recherche des têtes nucléaires volées, les moniteurs du centre des opérations affichent des cartes satellites et des coordonnées géographiques qui ne correspondent pas aux véritables routes et positions géographiques mentionnées dans les dialogues des personnages.","de":"Während der Suche nach den gestohlenen Sprengköpfen zeigen die Monitore der Einsatzzentrale Satellitenkarten und geografische Koordinaten, die nicht mit den echten Routen und geografischen Positionen übereinstimmen, die in den Dialogen der Figuren genannt werden."}'::jsonb WHERE id = 4804;
UPDATE errori SET descrizione_i18n = '{"it":"Nel combattimento finale all''interno della grotta sottomarina, l''arma brandita da uno degli scagnozzi di Largo cambia modello e finitura tra l''inquadratura larga e il primo piano in cui viene disarmato da Bond.","en":"In the final fight inside the underwater cave, the weapon wielded by one of Largo''s henchmen changes model and finish between the wide shot and the close-up where he is disarmed by Bond.","es":"En el combate final dentro de la cueva submarina, el arma que empuña uno de los esbirros de Largo cambia de modelo y acabado entre el plano general y el primer plano en el que Bond lo desarma.","fr":"Dans le combat final à l''intérieur de la grotte sous-marine, l''arme brandie par l''un des hommes de main de Largo change de modèle et de finition entre le plan large et le gros plan où il est désarmé par Bond.","de":"Im Endkampf in der Unterwasserhöhle wechseln Modell und Ausführung der Waffe, die einer von Largos Handlangern schwingt, zwischen der Totalen und der Nahaufnahme, in der er von Bond entwaffnet wird."}'::jsonb WHERE id = 4805;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cucina in cui Cooper discute con Donald e i suoi figli, la tazza di caffè tenuta da Donald cambia mano e livello di riempimento tra un''inquadratura e l''altra.","en":"In the kitchen scene where Cooper argues with Donald and his children, the coffee mug held by Donald changes hands and fill level between cuts.","es":"En la escena de la cocina en la que Cooper discute con Donald y sus hijos, la taza de café que sostiene Donald cambia de mano y de nivel de llenado entre plano y plano.","fr":"Dans la scène de cuisine où Cooper discute avec Donald et ses enfants, la tasse de café tenue par Donald change de main et de niveau de remplissage d''un plan à l''autre.","de":"In der Kücenszene, in der Cooper mit Donald und seinen Kindern diskutiert, wechseln die Hand und der Füllstand der Kaffeetasse, die Donald hält, zwischen den Einstellungen."}'::jsonb WHERE id = 4806;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i preparativi per il lancio dell''Endurance, in una rapida inquadratura laterale dell''interno della navicella si intravede brevemente l''ombra di un microfono a giraffa proiettata sulla paratia metallica.","en":"During preparations for the Endurance launch, in a quick side shot of the spacecraft interior, the shadow of a boom mic is briefly glimpsed projected onto the metal bulkhead.","es":"Durante los preparativos para el lanzamiento de la Endurance, en un plano lateral rápido del interior de la nave se ve brevemente la sombra de un micrófono de pértiga proyectada en el mamparo metálico.","fr":"Pendant les préparatifs du lancement de l''Endurance, dans un bref plan latéral de l''intérieur du vaisseau, on aperçoit brièvement l''ombre d''un micro perche projetée sur la cloison métallique.","de":"Während der Vorbereitungen für den Start der Endurance ist in einer schnellen seitlichen Einstellung des Schiffsinneren kurz der Schatten eines Galgenmikrofons an der Metallschottwand zu sehen."}'::jsonb WHERE id = 4807;
UPDATE errori SET descrizione_i18n = '{"it":"Quando l''equipaggio discute delle rotte orbitali e della fionda gravitazionale attorno a Saturno, i dati orbitali visualizzati sui monitor mostrano velocità e vettori fisicamente incompatibili con le vere leggi della meccanica celeste per quel tipo di traiettoria.","en":"When the crew discusses orbital routes and the gravitational slingshot around Saturn, the orbital data displayed on the monitors shows speeds and vectors that are physically incompatible with the true laws of celestial mechanics for that type of trajectory.","es":"Cuando la tripulación discute sobre las rutas orbitales y la asistencia gravitatoria alrededor de Saturno, los datos orbitales que se muestran en los monitores muestran velocidades y vectores físicamente incompatibles con las leyes reales de la mecánica celeste para ese tipo de trayectoria.","fr":"Quand l''équipage discute des routes orbitales et de l''effet de fronde gravitationnelle autour de Saturne, les données orbitales affichées sur les moniteurs montrent des vitesses et des vecteurs physiquement incompatibles avec les véritables lois de la mécanique céleste pour ce type de trajectoire.","de":"Als die Crew über orbitale Routen und das Gravitationsmanöver um Saturn diskutiert, zeigen die auf den Monitoren eingeblendeten Orbitaldaten Geschwindigkeiten und Vektoren, die für diese Art von Trajektorie physikalisch unvereinbar mit den wahren Gesetzen der Himmelsmechanik sind."}'::jsonb WHERE id = 4808;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno del Tesseract, quando Cooper interagisce con i vari momenti temporali attraverso i libri, la posizione dei volumi sparsi sul pavimento dietro la libreria cambia visibilmente angolazione e distanza tra le inquadrature soggettive e quelle ampie.","en":"Inside the Tesseract, when Cooper interacts with various temporal moments through the books, the position of the volumes scattered on the floor behind the bookshelf visibly changes angle and distance between the POV shots and the wide shots.","es":"Dentro del Tesseract, cuando Cooper interactúa con varios momentos temporales a través de los libros, la posición de los volúmenes esparcidos por el suelo detrás de la estantería cambia visiblemente de ángulo y distancia entre los planos subjetivos y los planos generales.","fr":"À l''intérieur du Tesseract, lorsque Cooper interagit avec divers moments temporels à travers les livres, la position des volumes éparpillés sur le sol derrière la bibliothèque change visiblement d''angle et de distance entre les plans subjectifs et les plans larges.","de":"Im Inneren des Tesseract, wenn Cooper durch die Bücher mit verschiedenen Zeitmomenten interagiert, verändern die auf dem Boden hinter dem Bücherregal verstreuten Bücher zwischen Subjektiveinstellung und Totalale sichtlich ihre Winkelposition und ihren Abstand."}'::jsonb WHERE id = 4809;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rambo esce dalla foresta e si avvicina alla pompa di benzina prima di rubare il camion, i suoi pantaloni e la giacca sono visibilmente bagnati e infangati in modo marcato, ma nell''inquadratura immediatamente successiva l''abbigliamento appare quasi asciutto e con tracce di fango completamente diverse.","en":"When Rambo emerges from the forest and approaches the gas station before stealing the truck, his pants and jacket are noticeably wet and heavily mud-stained, but in the very next shot his clothing appears almost dry with completely different mud patterns.","es":"Cuando Rambo sale del bosque y se acerca a la gasolinera antes de robar el camión, sus pantalones y su chaqueta están visiblemente mojados y muy embarrados, pero en el plano inmediatamente posterior la ropa aparece casi seca y con rastros de lodo completamente diferentes.","fr":"Quand Rambo sort de la forêt et s''approche de la station-service avant de voler le camion, son pantalon et sa veste sont visiblement mouillés et très boueux, mais sur le plan immédiatement suivant, ses vêtements apparaissent presque secs avec des traces de boue complètement différentes.","de":"Als Rambo aus dem Wald kommt und sich der Tankstelle nähert, bevor er den Truck stiehlt, sind seine Hose und Jacke sichtlich nass und stark verschlammt, aber in der nächsten Einstellung wirkt die Kleidung fast trocken und weist völlig andere Schlammspuren auf."}'::jsonb WHERE id = 4810;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rambo si trova nella giungla e riceve l''equipaggiamento, i coltelli e le armi subiscono variazioni di posizione nei foderi e nelle cinghie tra l''inquadratura larga e il primo piano.","en":"When Rambo is in the jungle receiving his gear, the knives and weapons undergo positional changes in their sheaths and straps between the wide shot and the close-up.","es":"Cuando Rambo está en la selva y recibe su equipamiento, los cuchillos y las armas sufren variaciones de posición en sus fundas y correas entre el plano general y el primer plano.","fr":"Quand Rambo est dans la jungle et reçoit son équipement, les couteaux et les armes subissent des variations de position dans leurs étuis et leurs sangle entre le plan large et le gros plan.","de":"Als Rambo im Dschungel ist und seine Ausrüstung erhält, verändern sich die Positionen der Messer und Waffen in ihren Scheiden und Riemen zwischen der Totalen und der Nahaufnahme."}'::jsonb WHERE id = 4811;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il combattimento nella foresta, in un breve controcampo in cui i soldati vietnamiti avanzano, è possibile intravedere brevemente l''ombra di un microfono a boom sul fogliame a sinistra dello schermo.","en":"During the forest fight, in a brief reverse shot where Vietnamese soldiers advance, the shadow of a boom mic can be briefly glimpsed on the foliage to the left of the screen.","es":"Durante el combate en el bosque, en un breve plano contraplano donde los soldados vietnamitas avanzan, se puede vislumbrar brevemente la sombra de un micrófono de pértiga en el follaje a la izquierda de la pantalla.","fr":"Pendant le combat dans la forêt, dans un bref champ-contrechamp où les soldats vietnamiens avancent, on peut entrevoir brièvement l''ombre d''un micro perche sur le feuillage à gauche de l''écran.","de":"Während des Kampfes im Wald ist in einer kurzen Gegenaufnahme, in der vietnamesische Soldaten vorrücken, kurz der Schatten eines Angelmikrofons (Boom-Mic) auf dem Laub links im Bild zu sehen."}'::jsonb WHERE id = 4812;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Rambo viene tenuto prigioniero nei barili d''acqua, la reazione fisica e medica successiva alle torture elettriche e alla permanenza prolungata nell''acqua contaminata non mostra i reali segni di shock ipovolemico o infezioni immediate.","en":"During the sequence where Rambo is held prisoner in water barrels, the subsequent physical and medical reaction to the electric torture and prolonged stay in contaminated water fails to show realistic signs of hypovolemic shock or immediate infections.","es":"Durante la secuencia en la que Rambo está prisionero en los barriles de agua, la reacción física y médica posterior a las torturas eléctricas y a la permanencia prolongada en agua contaminada no muestra los signos reales de shock hipovolémico o infecciones inmediatas.","fr":"Pendant la séquence où Rambo est retenu prisonnier dans des fûts d''eau, la réaction physique et médicale consécutive aux tortures électriques et au séjour prolongé dans l''eau contaminée ne montre pas les signes réels de choc hypovolémique ou d''infections immédiates.","de":"Während der Sequenz, in der Rambo in Wassertonnen gefangen gehalten wird, zeigt die physische und medizinische Reaktion nach den Elektroschocks und dem längeren Aufenthalt im kontaminierten Wasser keine realistischen Anzeichen eines hypovolämischen Schocks oder sofortiger Infektionen."}'::jsonb WHERE id = 4813;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Rambo pilota l''elicottero sovietico rubato, i danni subiti dalla cabina di pilotaggio e dai vetri cambiano intensità e forma tra le riprese esterne e le inquadrature interne dell''attore.","en":"In the sequence where Rambo pilots the stolen Soviet helicopter, the damage sustained by the cockpit and glass changes intensity and shape between exterior shots and interior shots of the actor.","es":"En la secuencia en la que Rambo pilota el helicóptero soviético robado, los daños sufridos en la cabina y los cristales cambian de intensidad y forma entre las tomas exteriores y los planos interiores del actor.","fr":"Dans la séquence où Rambo pilote l''hélicoptère soviétique volé, les dégâts subis par le cockpit et les vitres changent d''intensité et de forme entre les prises de vues extérieures et les plans intérieurs de l''acteur.","de":"In der Sequenz, in der Rambo den gestohlenen sowjetischen Hubschrauber steuert, verändern sich die Schäden am Cockpit und an den Scheiben in Intensität und Form zwischen den Außenaufnahmen und den Innenaufnahmen des Schauspielers."}'::jsonb WHERE id = 4814;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena della rabbiosa irruzione di Rambo nel quartier generale di Murdock, il movimento delle labbra di Sylvester Stallone in un piano ravvicinato non corrisponde perfettamente con l''audio delle urla registrate in post-produzione.","en":"In the scene of Rambo''s angry intrusion into Murdock''s headquarters, Sylvester Stallone''s lip movements in a close-up do not perfectly match the audio of the screams recorded in post-production.","es":"En la escena de la furiosa incursión de Rambo en el cuartel general de Murdock, el movimiento de los labios de Sylvester Stallone en un plano corto no coincide perfectamente con el audio de los gritos grabados en postproducción.","fr":"Dans la scène de l''irruption furieuse de Rambo dans le QG de Murdock, les mouvements de lèvres de Sylvester Stallone en gros plan ne correspondent pas parfaitement à l''audio des hurlements enregistrés en post-production.","de":"In der Szene von Rambos wütendem Einbruch in Mumdocks Hauptquartier stimmen die Lippenbewegungen von Sylvester Stallone in einer Nahaufnahme nicht perfekt mit dem in der Postproduktion aufgenommenen Audio der Schreie überein."}'::jsonb WHERE id = 4815;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rambo si trova all''interno della grotta o del rifugio con i mujaheddin, il fucile d''assalto AK-47 che impugna cambia ripetutamente configurazione e presenza della cinghia di trasporto tra un''inquadratura e l''altra.","en":"When Rambo is inside the cave or hideout with the mujahideen, the AK-47 assault rifle he wields repeatedly changes configuration and sling presence from one shot to the next.","es":"Cuando Rambo está dentro de la cueva o refugio con los muyahidines, el fusil de asalto AK-47 que empuña cambia repetidamente de configuración y de presencia de la correa portafusil de un plano a otro.","fr":"Quand Rambo se trouve à l''intérieur de la grotte ou de la planque avec les mandjahidines, le fusil d''assaut AK-47 qu''il brandit change de configuration et de présence de bretelle de manière répétée d''un plan à l''autre.","de":"Wenn sich Rambo in der Höhle oder dem Versteck mit den Mudschaheddin befindet, wechselt das von ihm gehaltene Sturmgewehr AK-47 von einer Einstellung zur nächsten wiederholt seine Konfiguration und das Vorhandensein des Trageriemens."}'::jsonb WHERE id = 4816;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una sequenza concitata in cui la jeep attraversa il deserto afghano sollevando molta polvere, in basso a sinistra si intravede brevemente l''ombra di un braccio telescopico con microfono boom sulla roccia.","en":"During a fast-paced sequence where the jeep drives through the Afghan desert kicking up a lot of dust, the shadow of a boom mic pole is briefly visible on the rock in the bottom left corner.","es":"Durante una secuencia frenética en la que el jeep atraviesa el desierto afgano levantando mucho polvo, la sombra de una pértiga con micrófono boom se ve brevemente sobre la roca en la parte inferior izquierda.","fr":"Pendant une séquence mouvementée où la jeep traverse le désert afghan en soulevant beaucoup de poussière, l''ombre d''une perche micro est brièvement visible sur le rocher en bas à gauche.","de":"Während einer rasanten Sequenz, in der der Jeep durch die afghanische Wüste fährt und viel Staub aufwirbelt, ist unten links kurz der Schatten einer Tonangel mit Mikrofon auf dem Felsen zu sehen."}'::jsonb WHERE id = 4817;
UPDATE errori SET descrizione_i18n = '{"it":"Nel film viene mostrato l''uso estensivo di missili Stinger da parte dei guerriglieri afghani; sebbene gli Stinger siano stati effettivamente forniti agli inizi del conflitto, la loro gestione tattica e le caratteristiche di lancio mostrate nel film presentano notevoli inesattezze rispetto alle procedure reali dell''epoca.","en":"The film extensively depicts the use of Stinger missiles by Afghan guerrillas; although Stingers were indeed supplied early in the conflict, their tactical handling and launching characteristics shown in the film present significant inaccuracies compared to actual procedures of the era.","es":"La película muestra el uso extensivo de misiles Stinger por parte de la guerrilla afgana; aunque los Stinger se suministraron efectivamente al principio del conflicto, su manejo táctico y las características de lanzamiento mostradas en la película presentan notables inexactitudes en comparación con los procedimientos reales de la época.","fr":"Le film montre l''utilisation intensive de missiles Stinger par les guerilleros afghans ; bien que les Stinger aient effectivement été fournis au début du conflit, leur manipulation tactique et leurs caractéristiques de lancement présentées dans le film comportent des inexactitudes notables par rapport aux procédures réelles de l''époque.","de":"Der Film zeigt den ausgiebigen Einsatz von Stinger-Raketen durch afghanische Guerillas; obwohl Stinger tatsächlich zu Beginn des Konflikts geliefert wurden, weisen ihre taktische Handhabung und die im Film gezeigten Starteigenschaften erhebliche Ungenauigkeiten im Vergleich zu den tatsächlichen Verfahren der damaligen Zeit auf."}'::jsonb WHERE id = 4818;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Rambo estrae la polvere da sparo da un proiettile per cauterizzarsi la ferita, la quantità di polvere versata e la posizione del bossolo variano visibilmente tra il primo piano sulle sue mani e l''inquadratura allargata.","en":"In the scene where Rambo extracts gunpowder from a bullet to cauterize his wound, the amount of powder poured and the position of the cartridge case visibly vary between the close-up on his hands and the wide shot.","es":"En la escena en la que Rambo extrae pólvora de un proyectil para cauterizarse la herida, la cantidad de pólvora vertida y la posición del casquillo varían visiblemente entre el plano detalle de sus manos y el plano general.","fr":"Dans la scène où Rambo extrait la poudre d''une balle pour cautériser sa blessure, la quantité de poudre versée et la position de la douille varient visiblement entre le gros plan sur ses mains et le plan large.","de":"In der Szene, in der Rambo Schießpulver aus einer Patrone entfernt, um seine Wunde zu kauen, variieren die Menge des ausgeschütteten Pulvers und die Position der Patronenhülse sichtlich zwischen der Nahaufnahme seiner Hände und der Totalen."}'::jsonb WHERE id = 4819;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conversazione tra Rambo e Maria alla cucina del ranch, la tazza di caffè tenuta da Maria cambia mano e livello di riempimento tra un''inquadratura e l''altra.","en":"During the conversation between Rambo and Maria in the ranch kitchen, the coffee mug held by Maria switches hands and changes its fill level between shots.","es":"Durante la conversación entre Rambo y Maria en la cocina del rancho, la taza de café que sostiene Maria cambia de mano y de nivel de llenado entre plano y plano.","fr":"Pendant la conversation entre Rambo et Maria dans la cuisine du ranch, la tasse de café tenue par Maria change de main et de niveau de remplissage d''un plan à l''autre.","de":"Während des Gesprächs zwischen Rambo und Maria in der Ranchküche wechselt die von Maria gehaltene Kaffeetasse zwischen den Einstellungen die Hand und den Füllstand."}'::jsonb WHERE id = 4820;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rambo attraversa il confine per entrare in Messico, le indicazioni stradali e la conformazione del valico di frontiera non corrispondono alla geografia reale tra Arizona e Sonora.","en":"When Rambo crosses the border into Mexico, the road signs and the layout of the border crossing do not match the actual geography between Arizona and Sonora.","es":"Cuando Rambo cruza la frontera para entrar en México, las señales de tráfico y la disposición del cruce fronterizo no se corresponden con la geografía real entre Arizona y Sonora.","fr":"Quand Rambo franchit la frontière pour entrer au Mexique, les panneaux routiers et la configuration du poste frontière ne correspondent pas à la géographie réelle entre l''Arizona et le Sonora.","de":"Wenn Rambo die Grenze nach Mexiko überquert, stimmen die Straßenschilder und die Beschaffenheit des Grenzübergangs nicht mit der realen Geographie zwischen Arizona und Sonora überein."}'::jsonb WHERE id = 4821;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Rambo viene soccorso da Carmen nei pressi della strada, le ferite e la polvere sui suoi vestiti appaiono sensibilmente ridotte rispetto alla scena dell''aggressione precedente.","en":"At the moment Rambo is rescued by Carmen near the road, his wounds and the dust on his clothes appear noticeably reduced compared to the preceding assault scene.","es":"En el momento en que Carmen rescata a Rambo cerca de la carretera, sus heridas y el polvo de su ropa parecen notablemente reducidos en comparación con la escena de la agresión anterior.","fr":"Au moment où Rambo est secouru par Carmen près de la route, ses blessures et la poussière sur ses vêtements apparaissent sensiblement réduites par rapport à la scène de l''agression précédente.","de":"In dem Moment, in dem Rambo von Carmen in der Nähe der Straße gerettet wird, wirken seine Wunden und der Staub auf seiner Kleidung im Vergleich zur vorherigen Angriffsszene deutlich reduziert."}'::jsonb WHERE id = 4822;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rambo si trova nel laboratorio sotterraneo a saldare e preparare i suoi strumenti, la posizione degli attrezzi sul bancone cambia visibilmente tra un''inquadratura ravvicinata e il campo medio.","en":"When Rambo is in the underground workshop welding and preparing his gear, the position of the tools on the workbench visibly changes between a close-up shot and the medium shot.","es":"Cuando Rambo está en el taller subterráneo soldando y preparando su equipo, la posición de las herramientas en el banco de trabajo cambia visiblemente entre un plano detalle y el plano medio.","fr":"Quand Rambo se trouve dans l''atelier souterrain pour souder et préparer son équipement, la position des outils sur l''établi change visiblement entre un plan serré et le plan moyen.","de":"Wenn sich Rambo in der unterirdischen Werkstatt befindet, um seine Ausrüstung zu schweißen und vorzubereiten, verändert sich die Position der Werkzeuge auf der Werkbank sichtlich zwischen einer Nahaufnahme und der Halbtotale."}'::jsonb WHERE id = 4823;
UPDATE errori SET descrizione_i18n = '{"it":"Le targhe delle automobili della polizia messicana e dei veicoli locali non seguono il formato reale dello stato di Sonora in cui la scena è presumibilmente ambientata.","en":"The license plates of the Mexican police cars and local vehicles do not follow the actual format of the state of Sonora where the scene is presumably set.","es":"Las matrículas de los coches de policía mexicanos y de los vehículos locales no siguen el formato real del estado de Sonora en el que supuestamente está ambientada la escena.","fr":"Les plaques d''immatriculation des voitures de police mexicaines et des véhicules locaux ne suivent pas le format réel de l''État de Sonora où la scène est censée se dérouler.","de":"Die Nummernschilder der mexikanischen Polizeiautos und der lokalen Fahrzeuge entsprechen nicht dem tatsächlichen Format des Bundesstaates Sonora, in dem die Szene vermutlich spielt."}'::jsonb WHERE id = 4824;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Rambo guida il suo pick-up verso il ranch dopo l''attacco iniziale, i danni alla carrozzeria e ai fari subiti durante la fuga variano da un''inquadratura all''altra.","en":"During the sequence where Rambo drives his pickup truck toward the ranch after the initial attack, the body damage and headlight damage sustained during the escape vary from shot to shot.","es":"Durante la secuencia en la que Rambo conduce su camioneta hacia el rancho tras el ataque inicial, los daños en la carrocería y los faros sufridos durante la huida varían de un plano a otro.","fr":"Pendant la séquence où Rambo conduit son pick-up vers le ranch après l''attaque initiale, les dégâts sur la carrosserie et les phares subis pendant la fuite varient d''un plan à l''autre.","de":"Während der Sequenz, in der Rambo nach dem ersten Angriffe seinen Pick-up zur Ranch fährt, variieren die Karosserie- und Scheinwerferschäden, die er bei der Flucht erlitten hat, von Einstellung zu Einstellung."}'::jsonb WHERE id = 4825;
UPDATE errori SET descrizione_i18n = '{"it":"Il modo in cui vengono descritte e rappresentate le rotte di transito e i controlli doganali tra Stati Uniti e Messico presenta notevoli inesattezze rispetto alle procedure reali di confine.","en":"The way transit routes and customs checkpoints between the United States and Mexico are described and depicted shows significant inaccuracies compared to actual border procedures.","es":"La forma en que se describen y representan las rutas de tránsito y los controles aduaneros entre Estados Unidos y México presenta notables inexactitudes en comparación con los procedimientos fronterizos reales.","fr":"La manière dont les itinéraires de transit et les contrôles douaniers entre les États-Unis et le Mexique sont décrits et représentés présente des inexactitudes considérables par rapport aux véritables procédures frontalières.","de":"Die Art und Weise, wie Transitrouten und Zollkontrollen zwischen den Vereinigten Staaten und Mexiko beschrieben und dargestellt werden, weist erhebliche Ungenauigkeiten im Vergleich zu den tatsächlichen Grenzverfahren auf."}'::jsonb WHERE id = 4826;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le sequenze iniziali a New Orleans, i bicchieri e i cocktail sui tavoli cambiano ripetutamente livello di riempimento e posizione tra un''inquadratura e l''altra nei dialoghi tra i partecipanti alla festa.","en":"During the opening sequences in New Orleans, the glasses and cocktails on the tables repeatedly change their fill level and position from shot to shot during the partygoers'' dialogue.","es":"Durante las secuencias iniciales en Nueva Orleans, los vasos y cócteles de las mesas cambian repetidamente de nivel de llenado y de posición de un plano a otro durante los diálogos de los asistentes a la fiesta.","fr":"Pendant les séquences d''ouverture à La Nouvelle-Orléans, les verres et les cocktails sur les tables changent constamment de niveau de remplissage et de position d''un plan à l''autre lors des dialogues entre les invités.","de":"Während der Eröffnungssequenzen in New Orleans verändern sich die Füllstände und Positionen der Gläser und Cocktails auf den Tischen während des Dialogs der Partygäste wiederholt von Einstellung zu Einstellung."}'::jsonb WHERE id = 4827;
UPDATE errori SET descrizione_i18n = '{"it":"Sebbene la prima parte del film sia ambientata nel 1959, alcuni dettagli dell''arredamento urbano e dei materiali di consumo visibili nelle strade di New Orleans riflettono lo stile e la produzione tipica della metà degli anni ''70.","en":"Although the first part of the film is set in 1959, certain details of street furniture and consumer goods visible in the streets of New Orleans reflect the style and production typical of the mid-1970s.","es":"Aunque la primera parte de la película está ambientada en 1959, algunos detalles del mobiliario urbano y de los bienes de consumo visibles en las calles de Nueva Orleans reflejan el estilo y la producción típicos de mediados de los años 70.","fr":"Bien que la première partie du film se déroule en 1959, certains détails du mobilier urbain et des produits de consommation visibles dans les rues de La Nouvelle-Orléans reflètent le style et la production typiques du milieu des années 1970.","de":"Obwohl der erste Teil des Films im Jahr 1959 spielt, spiegeln einige Details der Stadtmöblierung und der Konsumgüter, die in den Straßen von New Orleans zu sehen sind, den für die Mitte der 1970er Jahre typischen Stil und die entsprechende Produktion wider."}'::jsonb WHERE id = 4828;
UPDATE errori SET descrizione_i18n = '{"it":"Nei movimenti geografici e nei trasferimenti tra New Orleans e Firenze, i tempi di percorrenza e le coincidenze dei voli negli anni ''50 vengono rappresentati con tempistiche e modalità operative più affini al trasporto aereo commerciale dell''epoca di produzione del film.","en":"In the geographical movements and travel sequences between New Orleans and Florence, 1950s flight times and connections are depicted with schedules and operational procedures more akin to commercial air travel of the film''s production era.","es":"En los desplazamientos geográficos y traslados entre Nueva Orleans y Florencia, los tiempos de viaje y las conexiones de vuelos en los años 50 se representan con horarios y métodos operativos más propios del transporte aéreo comercial de la época de producción de la película.","fr":"Dans les déplacements géographiques et les transferts entre La Nouvelle-Orléans et Florence, les temps de trajet et les correspondances de vol dans les années 1950 sont représentés avec des horaires et des modalités opérationnelles plus proches du transport aérien commercial de l''époque de production du film.","de":"Bei den geografischen Ortswechseln und Reisen zwischen New Orleans und Florenz werden die Flugzeiten und -anschlüsse der 1950er Jahre mit Zeitplänen und Betriebsabläufen dargestellt, die eher dem kommerziellen Flugverkehr zur Zeit der Filmproduktion entsprechen."}'::jsonb WHERE id = 4829;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno dello studio di Michael a New Orleans, i documenti e le cartelline sulla scrivania cambiano disposizione geometrica e pila di appartenenza nei vari cambi di inquadratura tra i primi piani e i campi medi.","en":"Inside Michael''s studio in New Orleans, the documents and folders on the desk change their geometric arrangement and stack placement across various shot transitions between close-ups and medium shots.","es":"Dentro del estudio de Michael en Nueva Orleans, los documentos y carpetas del escritorio cambian su disposición geométrica y de pila en los diversos cambios de plano entre primeros planos y planos medios.","fr":"À l''intérieur du bureau de Michael à La Nouvelle-Orléans, les documents et les dossiers sur le bureau changent de disposition géométrique et de pile lors des divers changements de plan entre les gros plans et les plans moyens.","de":"Im Arbeitszimmer von Michael in New Orleans wechseln die Dokumente und Aktenordner auf dem Schreibtisch bei den verschiedenen Anschlüssen zwischen Nahaufnahmen und Halbtotalen ihre geometrische Anordnung und Stapelzugehörigkeit."}'::jsonb WHERE id = 4830;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le scene girate negli esterni di Firenze, la posizione delle ombre proiettate dai monumenti e dai personaggi risulta incoerente con il passare del tempo diegetico tra un''inquadratura e la successiva.","en":"During the scenes shot on location in Florence, the position of the shadows cast by monuments and characters is inconsistent with the passage of diegetic time from one shot to the next.","es":"Durante las escenas rodadas en exteriores en Florencia, la posición de las sombras proyectadas por los monumentos y los personajes resulta incoherente con el paso del tiempo diegético entre un plano y el siguiente.","fr":"Pendant les scènes tournées en extérieur à Florence, la position des ombres projetées par les monuments et les personnages est incohérente avec le passage du temps diégétique d''un plan à l''autre.","de":"Während der Außenaufnahmen in Florenz ist die Position der von Monumenten und Figuren geworfenen Schatten inkonsistent mit dem Verstreichen der diegetischen Zeit von einer Einstellung zur nächsten."}'::jsonb WHERE id = 4831;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le scene all''interno della trattoria di Bragana, i bicchieri e le bottiglie sul banco cambiano ripetutamente disposizione e livello di riempimento tra un cambio di inquadratura e l''altro.","en":"During the scenes inside Bragana''s trattoria, the glasses and bottles on the counter repeatedly change their arrangement and fill level between cuts.","es":"Durante las escenas en el interior de la trattoria de Bragana, los vasos y las botellas de la barra cambian repetidamente de disposición y nivel de llenado entre un plano y otro.","fr":"Pendant les scènes à l''intérieur de la trattoria de Bragana, les verres et les bouteilles sur le comptoir changent de disposition et de niveau de remplissage d''un raccord à l''autre.","de":"Während der Szenen in Braganas Trattoria verändern die Gläser und Flaschen auf dem Tresen bei Anschlüssen wiederholt ihre Anordnung und ihren Füllstand."}'::jsonb WHERE id = 4832;
UPDATE errori SET descrizione_i18n = '{"it":"Nei campi e controcampi della scena in cui Giovanna e Gino parlano nella cucina della trattoria, i capelli di Clara Calamai variano visibilmente nell''acconciatura e nella posizione sulla fronte tra un piano medio e il primo piano.","en":"In the shot-reverse-shot sequences of the scene where Giovanna and Gino talk in the trattoria kitchen, Clara Calamai''s hair noticeably changes in styling and forehead placement between a medium shot and a close-up.","es":"En los planos y contraplanos de la escena en la que Giovanna y Gino hablan en la cocina de la trattoria, el peinado y la posición del flequillo de Clara Calamai varían visiblemente entre el plano medio y el primer plano.","fr":"Dans les champ-contre-champs de la scène où Giovanna et Gino parlent dans la cuisine de la trattoria, la coiffure et la position des cheveux de Clara Calamai sur son front varient visiblement entre un plan moyen et un gros plan.","de":"In den Schuss-Gegenschuss-Einstellungen der Szene, in der Giovanna und Gino in der Küche der Trattoria sprechen, verändern sich Frisur und Stirnpartie von Clara Calamai zwischen Halbtotale und Nahaufnahme merklich."}'::jsonb WHERE id = 4833;
UPDATE errori SET descrizione_i18n = '{"it":"In diverse sequenze in esterni girate lungo le strade e i canali padani, il doppiaggio in post-produzione mostra evidenti sfasamenti rispetto al movimento delle labbra degli attori, accentuato dall''acustica da studio.","en":"In several exterior sequences shot along the roads and canals of the Po Valley, the post-production dubbing shows clear sync issues with the actors'' lip movements, accentuated by the studio acoustics.","es":"En varias secuencias de exteriores rodadas a lo largo de las carreteras y canales del Po, el doblaje de postproducción muestra claros desases con el movimiento de labios de los actores, acentuado por la acústica de estudio.","fr":"Dans plusieurs séquences en extérieur tournées le long des routes et des canaux de la vallée du Pô, le doublage en post-production présente un net décalage par rapport aux mouvements des lèvres des acteurs, accentué par l''acoustique de studio.","de":"In mehreren Außenaufnahmen entlang der Straßen und Kanäle des Po-Tals weist die Postproduktions-Synchronisation deutliche Asynchronitäten zu den Lippenbewegungen der Schauspieler auf, die durch die Studioakustik noch verstärkt werden."}'::jsonb WHERE id = 4834;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le riprese della sequenza della crocifissione, in un campo medio che mostra la folla e le croci sullo sfondo, il cielo passa bruscamente da una forte luce solare a un cielo coperto e cupo per poi tornare luminoso nell''inquadratura successiva, evidenziando le riprese effettuate in giorni diversi senza un corretto raccordo di luce.","en":"During the filming of the crucifixion sequence, in a medium shot showing the crowd and the crosses in the background, the sky abruptly shifts from bright sunlight to an overcast, gloomy sky, only to return to bright in the next shot, highlighting footage filmed on different days without proper lighting match.","es":"Durante el rodaje de la secuencia de la crucifixión, en un plano medio que muestra a la multitud y las cruces al fondo, el cielo pasa bruscamente de una fuerte luz solar a un cielo nublado y sombrío para volver a ser luminoso en el plano siguiente, evidenciando tomas realizadas en días distintos sin un raccord de luz correcto.","fr":"Pendant le tournage de la séquence de la crucifixion, dans un plan moyen montrant la foule et les croix en arrière-plan, le ciel passe brusquement d''un fort ensoleillement à un ciel couvert et sombre pour redevenir lumineux au plan suivant, mettant en évidence des prises de vues réalisées à des jours différents sans raccord lumière correct.","de":"Während der Kreuzigungsszene wechselt der Himmel in einer Halbtotale, die die Menge und die Kreuze im Hintergrund zeigt, abrupt von starkem Sonnenlicht zu einem bewölkten, düsteren Himmel, um in der nächsten Einstellung wieder hell zu sein – ein Beleg für an verschiedenen Tagen gedrehtes Material ohne korrekten Lichtanschluss."}'::jsonb WHERE id = 4835;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Quinto Arrio viene salvato da Ben-Hur in mare dopo lo speronamento della nave, la posizione del console romano in acqua e il modo in cui galleggia variano visibilmente tra un''inquadratura e l''altra, alternando momenti in cui affonda ad altri in cui è perfettamente a galla.","en":"During the sequence where Quintus Arrius is rescued by Ben-Hur in the sea after the ship ramming, the Roman consul''s position in the water and how he floats vary noticeably between shots, alternating between moments when he sinks and others where he is perfectly buoyant.","es":"Durante la secuencia en la que Quinto Arrio es rescatado por Ben-Hur en el mar tras el embiste al barco, la posición del cónsul romano en el agua y su forma de flotar varían visiblemente de un plano a otro, alternando momentos en los que se hunde con otros en los que flota perfectamente.","fr":"Pendant la séquence où Quintus Arrius est sauvé par Ben-Hur en mer après l''éperonnage du navire, la position du consul romain dans l''eau et sa façon de flotter varient visiblement d''un plan à l''autre, alternant des moments où il coule et d''autres où il flotte parfaitement.","de":"Während der Sequenz, in der Quintus Arrius nach der Schiffsrammung von Ben-Hur im Meer gerettet wird, verändern sich die Position des römischen Konsuls im Wasser und seine Schwimmlage von Einstellung zu Einstellung merklich, wobei sich Momente, in denen er untergeht, mit solchen abwechseln, in denen er perfekt an der Oberfläche treibt."}'::jsonb WHERE id = 4836;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Ben-Hur incontra sua madre e sua sorella dopo che sono state liberate dalla valle dei lebbrosi, la quantità di sporco e le macchie di fango sui loro volti e abiti cambiano drasticamente nei cambi di inquadratura tra i primi piani e i campi medi.","en":"In the scene where Ben-Hur meets his mother and sister after they are freed from the valley of the leppers, the amount of dirt and mud stains on their faces and costumes changes drastically during shot/reverse-shot cuts between close-ups and medium shots.","es":"En la escena en la que Ben-Hur se encuentra con su madre y su hermana tras ser liberadas del valle de los leprosos, la cantidad de suciedad y manchas de barro en sus rostros y vestuario cambia drásticamente en los cambios de plano entre primeros planos y planos medios.","fr":"Dans la scène où Ben-Hur retrouve sa mère et sa sœur après leur libération de la vallée des lépreux, la quantité de saleté et de taches de boue sur leurs visages et leurs costumes change radicalement lors des raccords entre les gros plans et les plans moyens.","de":"In der Szene, in der Ben-Hur seine Mutter und seine Schwester nach ihrer Befreiung aus dem Tal der Aussätzigen trifft, verändert sich die Menge an Schmutz und Schlammflecken in ihren Gesichtern und Kostümen bei den Anschlüssen zwischen Nahaufnahmen und halbtotale Einstellungen drastisch."}'::jsonb WHERE id = 4837;
UPDATE errori SET descrizione_i18n = '{"it":"Nei titoli di coda iniziali e in alcune sequenze di massa, vengono impiegate tecniche di stampa e caratteri tipografici che richiamano stili moderni non coerenti con i metodi di scrittura o incisione in pietra dell''epoca romana del I secolo.","en":"In the opening credits and some crowd sequences, printing techniques and typefaces are used that evoke modern styles inconsistent with 1st-century Roman writing or stone-carving methods.","es":"En los títulos de crédito iniciales y en algunas secuencias de masas, se emplean técnicas de impresión y tipografías que recuerdan a estilos modernos incoherentes con los métodos de escritura o incisión en piedra de la época romana del siglo I.","fr":"Dans le générique d''ouverture et certaines séquences de foule, des techniques d''impression et des typographies évoquant des styles modernes sont utilisées, ce qui est incohérent avec les méthodes d''écriture ou de gravure sur pierre de la Rome du Ier siècle.","de":"Im Vorspann und in einigen Massenszenen werden Drucktechniken und Schriftarten verwendet, die an moderne Stile erinnern und nicht zu den Schreib- oder Steinmetzmethoden der römischen Epoche des 1. Jahrhunderts passen."}'::jsonb WHERE id = 4838;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le scene delle galere, i rematori sono incatenati ai banchi in modo tale che, se la nave fosse affondata come poi accade, sarebbe stato totalmente impossibile per loro liberarsi in tempo, sebbene nel film molti riescano a salvarsi o a essere slegati in pochi secondi.","en":"During the galley scenes, the rowers are chained to the benches in such a way that if the ship had sunk as it later does, it would have been totally impossible for them to free themselves in time, although in the film many manage to survive or be unchained in a few seconds.","es":"Durante las escenas de las galeras, los remeros están encadenados a los bancos de tal forma que, si el barco se hubiera hundido como ocurre después, les habría sido totalmente imposible liberarse a tiempo, aunque en la película muchos logran salvarse o ser desatados en pocos segundos.","fr":"Pendant les scènes de galères, les rameurs sont enchaînés aux bancs de telle sorte que si le navire avait coulé comme cela se produit ensuite, il leur aurait été totalement impossible de se libérer à temps, bien que dans le film beaucoup parviennent à s''en sortir ou à être détachés en quelques secondes.","de":"Während der Galeerenszenen sind die Ruderer so an die Bänke gekettet, dass es für sie völlig unmöglich gewesen wäre, sich rechtzeitig zu befreien, falls das Schiff wie später geschehen gesunken wäre, obwohl sich im Film viele in wenigen Sekunden retten oder losgebunden werden."}'::jsonb WHERE id = 4839;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza della corsa delle bighe, in un''inquadratura ravvicinata sullo sfondo sabbioso e tra le tribune, si intravede brevemente l''ombra di un operatore di ripresa con la cinepresa montata su un braccio mobile.","en":"In the chariot race sequence, during a close-up against the sandy background and the stands, the shadow of a camera operator with a camera mounted on a jib arm is briefly glimpsed.","es":"En la secuencia de la carrera de cuadrigas, en un plano corto sobre el fondo de arena y entre las gradas, se vislumbra brevemente la sombra de un operador de cámara con la cámara montada en una grúa.","fr":"Dans la séquence de la course de chars, lors d''un plan rapproché sur le fond sablonneux et les tribunes, on aperçoit brièvement l''ombre d''un cadreur avec une caméra montée sur une grue.","de":"In der Wagenrennen-Sequenz ist in einer Nahaufnahme vor dem sandigen Hintergrund und den Zuschauertribünen kurz der Schatten eines Kameramanns zu sehen, dessen Kamera auf einem Kamerakran montiert ist."}'::jsonb WHERE id = 4840;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le sequenze iniziali in cui Jonathan Harker saluta Lucy prima di partire per la Transilvania, la sciarpa indossata da Isabelle Adjani cambia leggermente posizione e nodi tra un''inquadratura e l''altra.","en":"During the opening sequences where Jonathan Harker says goodbye to Lucy before leaving for Transylvania, the scarf worn by Isabelle Adjani changes position and knot slightly from shot to shot.","es":"Durante las secuencias iniciales en las que Jonathan Harker se despide de Lucy antes de partir hacia Transilvania, la bufanda que lleva Isabelle Adjani cambia ligeramente de posición y de nudo entre plano y plano.","fr":"Pendant les séquences d''ouverture où Jonathan Harker fait ses adieux à Lucy avant de partir pour la Transylvanie, l''écharpe portée par Isabelle Adjani change légèrement de position et de nœud d''un plan à l''autre.","de":"Während der Eröffnungsszenen, in denen Jonathan Harker sich vor seiner Abreise nach Transsilvanien von Lucy verabschiedet, verändern sich Position und Knoten des von Isabelle Adjani getragenen Schals von Einstellung zu Einstellung leicht."}'::jsonb WHERE id = 4841;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''imboscata nella foresta all''inizio del film, il modo in cui i soldati britannici cadono e tengono i loro moschetti cambia visibilmente tra un''inquadratura e l''altra, con le armi che appaiono e scompaiono accanto ai corpi caduti nei cambi di campo.","en":"During the forest ambush at the beginning of the film, the way British soldiers fall and hold their muskets changes visibly between shots, with the prop weapons appearing and disappearing next to the fallen bodies during cuts.","es":"Durante la emboscada en el bosque al principio de la película, la forma en que los soldados británicos caen y sostienen sus mosquetes cambia visiblemente entre plano y plano, apareciendo y desapareciendo las armas junto a los cuerpos caídos en los cambios de plano.","fr":"Pendant l''embuscade dans la forêt au début du film, la façon dont les soldats britanniques tombent et tiennent leurs mousquets change visiblement d''un plan à l''autre, les armes factices apparaissant et disparaissant à côté des corps tombés lors des raccords.","de":"Während des Hinterhalts im Wald zu Beginn des Films verändert sich die Art und Weise, wie britische Soldaten fallen und ihre Musketen halten, von Einstellung zu Einstellung sichtbar, wobei die Waffen bei den Szenenwechseln neben den gefallenen Körpern auftauchen und wieder verschwinden."}'::jsonb WHERE id = 4842;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui il maggiore Heyward parla all''interno dell''accampamento britannico, la tazza che tiene in mano passa continuamente dalla mano destra alla sinistra e viceversa tra i tagli di montaggio dei primi piani.","en":"In the scene where Major Heyward is talking inside the British camp, the cup he is holding switches continually between his right and left hand across the editing cuts of the close-ups.","es":"En la escena en la que el major Heyward habla dentro del campamento británico, la taza que sostiene pasa continuamente de la mano derecha a la izquierda y viceversa entre los cortes de montaje de los primeros planos.","fr":"Dans la scène où le major Heyward discute à l''intérieur du camp britannique, la tasse qu''il tient passe sans cesse de la main droite à la main gauche et vice-versa lors des coupes de montage des gros plans.","de":"In der Szene, in der Major Heyward im britischen Lager spricht, wechselt die Tasse, die er hält, bei den Filmschnitten der Nahaufnahmen kontinuierlich von der rechten in die linke Hand und zurück."}'::jsonb WHERE id = 4843;
UPDATE errori SET descrizione_i18n = '{"it":"La resa di Fort William Henry e i successivi eventi storici vengono fortemente compressi e romanzati rispetto ai fatti reali del 1757, inclusi i tempi di marcia e la presunta vulnerabilità totale della guarnigione.","en":"The surrender of Fort William Henry and subsequent historical events are heavily compressed and dramatized compared to the real facts of 1757, including marching times and the alleged total vulnerability of the garrison.","es":"La rendición del Fuerte William Henry y los posteriores acontecimientos históricos están muy comprimidos y novelizados en comparación con los hechos reales de 1757, incluidos los tiempos de marcha y la supuesta vulnerabilidad total de la guarnición.","fr":"La reddition du fort William Henry et les événements historiques ultérieurs sont fortement compressés et romancés par rapport aux faits réels de 1757, y compris les temps de marche et la prétendue vulnérabilité totale de la garnison.","de":"Die Kapitulation von Fort William Henry und die nachfolgenden historischen Ereignisse werden im Vergleich zu den tatsächlichen Begebenheiten von 1757 stark komprimiert und dramatisiert, einschließlich der Marschzeiten und der angeblichen völligen Verwundbarkeit der Garnison."}'::jsonb WHERE id = 4844;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la drammatica sequenza della marcia dei sopravvissuti fuori da Forte William Henry, in un''inquadratura grandangolare sui lati della colonna si intravede per un istante il movimento di un membro della troupe in abiti moderni ai margini della boscaglia.","en":"During the dramatic sequence of the survivors marching out of Fort William Henry, in a wide shot along the sides of the column, a crew member in modern clothing can be briefly glimpsed moving at the edge of the brush.","es":"Durante la dramática secuencia de la marcha de los supervivientes fuera de Fuerte William Henry, en un plano general a los lados de la columna se vislumbra brevemente el movimiento de un miembro del equipo de rodaje con ropa moderna en el margen del bosque.","fr":"Pendant la séquence dramatique de la marche des survivants hors du fort William Henry, dans un plan large sur les côtés de la colonne, on aperçoit brièvement le mouvement d''un membre de l''équipe technique en vêtements modernes à la lisière des bois.","de":"Während der dramatischen Sequenz des Abmarschs der Überlebenden aus Fort William Henry ist in einer Weitwinkeleinstellung an den Seiten der Kolonne kurz die Bewegung eines Crewmitglieds in moderner Kleidung am Rand des Gebüchs zu sehen."}'::jsonb WHERE id = 4845;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena della scalata della parete rocciosa da parte dei protagonisti prima dell''epilogo, le ferite e le macchie di sangue sul viso e sui vestiti di Occhio di Falco variano di intensità e posizione da un''inquadratura all''altra.","en":"In the scene where the protagonists climb the rock face before the epilogue, the wounds and bloodstains on Hawkeye''s face and clothes vary in intensity and position from shot to shot.","es":"En la escena de la escalada de la pared rocosa por parte de los protagonistas antes del epílogo, las heridas y las manchas de sangre en la cara y la ropa de Ojo de Halcón varían en intensidad y posición de un plano a otro.","fr":"Dans la scène de l''escalade de la paroi rocheuse par les protagonistes avant l''épilogue, les blessures et les taches de sang sur le visage et les vêtements d''Œil-de-Faucon varient en intensité et en position d''un plan à l''autre.","de":"In der Szene, in der die Protagonisten vor dem Epilog die Felswand hinaufklettern, variieren die Wunden und Blutflecken auf Hawkeyes Gesicht und Kleidung von Einstellung zu Einstellung in Intensität und Position."}'::jsonb WHERE id = 4846;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Ace Ventura si trova nel suo ufficio all''inizio del film e riceve la visita del rappresentante della colonia britannica, la tazza da tè che tiene in mano cambia posizione e livello di riempimento tra un cambio di inquadratura e l''altro.","en":"When Ace Ventura is in his office at the beginning of the film and receives a visit from the British consulate representative, the teacup he is holding changes position and fill level between cuts.","es":"Cuando Ace Ventura está en su oficina al principio de la película y recibe la visita del representante de la colonia británica, la taza de té que sostiene en la mano cambia de posición y nivel de llenado entre plano y plano.","fr":"Quand Ace Ventura est dans son bureau au début du film et reçoit la visite du représentant de la colonie britannique, la tasse de thé qu''il tient change de position et de niveau de remplissage d''un raccord à l''autre.","de":"Wenn Ace Ventura sich zu Beginn des Films in seinem Büro befindet und Besuch vom Vertreter der britischen Kolonie erhält, wechseln die Position und der Füllstand der Teetasse, die er in der Hand hält, zwischen den Einstellungen."}'::jsonb WHERE id = 4847;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Ace esplora il mercato all''aperto alla ricerca di indizi, in alto a sinistra dello schermo è possibile intravedere brevemente l''ombra di un microfono boom che si muove lungo il muro di una bancarella.","en":"During the sequence where Ace explores the open-air market looking for clues, the shadow of a boom mic moving along a stall''s wall can be briefly glimpsed in the upper left of the screen.","es":"Durante la secuencia en la que Ace explora el mercado al aire libre en busca de pistas, en la parte superior izquierda de la pantalla se puede vislumbrar brevemente la sombra de un micrófono de pértiga moviéndose a lo largo de la pared de un puesto.","fr":"Pendant la séquence où Ace explore le marché en plein air à la recherche d''indices, en haut à gauche de l''écran, on peut apercevoir brièvement l''ombre d''un micro perche se déplaçant le long du mur d''un étal.","de":"Während der Sequenz, in der Ace den Open-Air-Markt nach Hinweisen absucht, ist oben links im Bildschirm kurz der Schatten eines Galgenmikrofons zu sehen, das sich an der Wand eines Marktstands entlangbewegt."}'::jsonb WHERE id = 4848;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della discussione tra Ace e i capi delle due tribù rivali, il bastone cerimoniale retto dall''anziano Wachati passa inspiegabilmente dalla mano destra alla sinistra senza che vi sia continuità nell''azione di transizione.","en":"During the discussion between Ace and the leaders of the two rival tribes, the ceremonial staff held by the Wachati elder inexplicably switches from his right hand to his left without any continuity in the transition action.","es":"Durante la discusión entre Ace y los líderes de las dos tribus rivales, el bastón ceremonial que sostiene el anciano wachati pasa inexplicablemente de su mano derecha a la izquierda sin que haya continuidad en la acción de transición.","fr":"Au cours de la discussion entre Ace et les chefs des deux tribus rivales, le bâton de cérémonie tenu par l''ancien Wachati passe inexplicablement de sa main droite à sa main gauche sans aucune continuité dans l''action de transition.","de":"Während der Diskussion zwischen Ace und den Anführern der beiden rivalisierenden Stämme wechselt der zeremonielle Stab des ältesten Wachati unerklärlicherweise von seiner rechten in die linke Hand, ohne dass es eine Kontinuität in der Übergangshandlung gibt."}'::jsonb WHERE id = 4849;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Ace Ventura si trova nel bagno dell''aereo, il tovagliolo di carta che usa per asciugarsi cambia posizione e forma piegata tra le varie inquadrature ravvicinate e a campo largo.","en":"During the scene where Ace Ventura is in the airplane lavatory, the paper towel he uses to dry himself changes position and folded shape between close-ups and wide shots.","es":"Durante la escena en la que Ace Ventura está en el baño del avión, la toalla de papel que usa para secarse cambia de posición y de forma doblada entre los diferentes primeros planos y planos generales.","fr":"Pendant la scène où Ace Ventura se trouve dans les toilettes de l''avion, l''essuie-tout en papier qu''il utilise pour s''essuyer change de position et de pliage entre les différents gros plans et plans larges.","de":"Während der Szene, in der sich Ace Ventura in der Flugzeugtoilette befindet, verändern das Papiertuch, das er zum Abtrocknen benutzt, sowie dessen Faltform zwischen den verschiedenen Nahaufnahmen und Totalen ihre Position."}'::jsonb WHERE id = 4850;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Ace entra nella tenda del consulente britannico e si muove concitatamente, è possibile intravedere brevemente il riflesso della telecamera e di un operatore sulla superficie lucida di un oggetto di scena in metallo.","en":"In the sequence where Ace enters the British consultant''s tent and moves about frantically, the reflection of the camera and a camera operator can be briefly glimpsed on the polished surface of a metal prop.","es":"En la secuencia en la que Ace entra en la tienda del consultor británico y se mueve agitadamente, se puede vislumbrar brevemente el reflejo de la cámara y de un operador en la superficie brillante de un atrezo de metal.","fr":"Dans la séquence où Ace entre dans la tentes du conseiller britannique et s''agite, on peut apercevoir brièvement le reflet de la caméra et d''un cadreur sur la surface brillante d''un accessoire en métal.","de":"In der Sequenz, in der Ace das Zelt des britischen Beraters betritt und sich hektisch bewegt, ist auf der polierten Oberfläche einer Requisite aus Metall kurz die Spiegelung der Kamera und eines Kameramanns zu sehen."}'::jsonb WHERE id = 4851;
UPDATE errori SET descrizione_i18n = '{"it":"Il film fa riferimento a una tribù immaginaria (i Wachati e i Wachootoo) in una regione non ben definita dell''Africa, ma la flora e la fauna mostrate mescolano specie asiatiche e sudamericane in modo geograficamente impossibile per il continente africano.","en":"The film refers to a fictional tribe (the Wachatis and Wachootoos) in an undefined region of Africa, but the flora and fauna shown mix Asian and South American species in a way that is geographically impossible for the African continent.","es":"La película hace referencia a una tribu ficticia (los wachatis y wachootoos) en una región indefinida de África, pero la flora y la fauna mostradas mezclan especies asiáticas y sudamericanas de un modo geográficamente imposible para el continente africano.","fr":"Le film fait référence à une tribu imaginaire (les Wachatis et les Wachootoos) dans une région mal définie de l''Afrique, mais la flore et la faune présentées mélangent des espèces asiatiques et sud-américaines d''une manière géographiquement impossible pour le continent africain.","de":"Der Film bezieht sich auf einen fiktiven Stamm (die Wachati und Wachootoo) in einer nicht näher definierten Region Afrikas, aber die gezeigte Flora und Fauna vermischt asiatische und südamerikanische Arten auf eine für den afrikanischen Kontinent geografisch unmögliche Weise."}'::jsonb WHERE id = 4852;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle sequenze di battaglia, in basso a destra dello schermo, è possibile intravedere brevemente l''ombra di un operatore di ripresa e del braccio di un microfono boom proiettata sul terreno fangoso.","en":"During one of the battle sequences, in the bottom right of the screen, the shadow of a camera operator and a boom mic pole can be briefly glimpsed projected onto the muddy ground.","es":"Durante una de las secuencias de batalla, en la parte inferior derecha de la pantalla, se puede vislumbrar brevemente la sombra de un operador de cámara y del brazo de un micrófono boom proyectada en el suelo embarrado.","fr":"Pendant l''une des séquences de bataille, en bas à droite de l''écran, on peut apercevoir brièvement l''ombre d''un cadreur et de la perche d''un micro-boom projetée sur le sol boueux.","de":"Während einer der Kampfszenen ist unten rechts im Bildschirm kurz der Schatten eines Kameramanns und einer Tonangel auf dem schlammigen Boden zu sehen."}'::jsonb WHERE id = 4853;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della scena in cui William Wallace viene torturato prima dell''esecuzione, le ferite e i tagli sul suo viso cambiano visibilmente posizione e intensità di sangue tra un''inquadratura e l''altra.","en":"During the scene where William Wallace is tortured before his execution, the wounds and cuts on his face visibly change position and blood intensity between shots.","es":"Durante la escena en la que William Wallace es torturado antes de su ejecución, las heridas y cortes en su cara cambian visiblemente de posición y de intensidad de sangre entre plano y plano.","fr":"Dans la scène où William Wallace est torturé avant son exécution, les blessures et les coupures sur son visage changent visiblement de position et d''intensité de sang d''un plan à l''autre.","de":"In der Szene, in der William Wallace vor seiner Hinrichtung foltert wird, verändern die Wunden und Schnitte in seinem Gesicht sichtlich ihre Position und die Menge an Blut zwischen den Einstellungen."}'::jsonb WHERE id = 4854;
UPDATE errori SET descrizione_i18n = '{"it":"Durante un dialogo all''interno di una tenda, il boccale di idromele tenuto da un nobile scozzese passa inspiegabilmente dalla mano destra alla mano sinistra e viceversa a ogni cambio di inquadratura.","en":"During a dialogue inside a tent, the mug of mead held by a Scottish nobleman inexplicably switches from his right hand to his left hand and back again with every cut.","es":"Durante un diálogo dentro de una tienda, la jarra de hidromiel que sostiene un noble escocés pasa inexplicablemente de la mano derecha a la izquierda y viceversa en cada cambio de plano.","fr":"Pendant un dialogue à l''intérieur d''une tente, la chope d''hydromel tenue par un noble écossais passe inexplicablement de la main droite à la main gauche et inversement à chaque raccord.","de":"Während eines Dialogs in einem Zelt wechselt der Metkrug eines schottischen Adligen bei jedem Szenenwechsel unerklärlicherweise von der rechten in die linke Hand und zurück."}'::jsonb WHERE id = 4855;
UPDATE errori SET descrizione_i18n = '{"it":"In diverse scene che mostrano i guerrieri scozzesi in riunione, alcuni comparse indossano stivali in cuoio con suole chiaramente vulcanizzate o cucite con tecniche industriali moderne, non esistenti nel XIII secolo.","en":"In several scenes showing Scottish warriors gathered, some extras wear leather boots with soles that are clearly vulcanized or stitched using modern industrial techniques, which did not exist in the 13th century.","es":"En varias escenas que muestran a los guerreros escoceses reunidos, algunos extras llevan botas de cuero con suelas claramente vulcanizadas o cosidas con técnicas industriales modernas, inexistentes en el siglo XIII.","fr":"Dans plusieurs scenes montrant des guerriers écossais rassemblés, certains figurants portent des bottes en cuir dotées de semelles manifestement vulcanisées ou cousues selon des techniques industrielles modernes, inexistantes au XIIIe siècle.","de":"In mehreren Szenen mit versammelten schottischen Kriegern tragen einige Statisten Lederstiefel mit Sohlen, die offensichtlich vulkanisiert oder mit modernen Industrietechniken genäht sind, die es im 13. Jahrhundert noch gar nicht gab."}'::jsonb WHERE id = 4856;
UPDATE errori SET descrizione_i18n = '{"it":"Nel negozio di pegni, quando Zed e Maynard scelgono la mazza da baseball e lo sfollagente prima di abusare di Marsellus Wallace, gli oggetti impugnati e la loro posizione cambiano leggermente tra i diversi stacchi di inquadratura.","en":"In the pawnshop, when Zed and Maynard choose the baseball bat and the nightstick before assaulting Marsellus Wallace, the props held and their position change slightly across different editing cuts.","es":"En la casa de empeños, cuando Zed y Maynard eligen el bate de béisbol y la porra antes de abusar de Marsellus Wallace, los objetos empuñados y su posición cambian ligeramente entre los distintos cortes de plano.","fr":"Dans le prêteur sur gages, lorsque Zed et Maynard choisissent la batte de baseball et la matraque avant d''abuser de Marsellus Wallace, les accessoires tenus en main et leur position changent légèrement d''un raccord à l''autre.","de":"Im Pfandhaus, als Zed und Maynard den Baseballschläger und den Schlagstock auswählen, bevor sie Marsellus Wallace missbrauchen, verändern sich die gehaltenen Requisiten und deren Position leicht zwischen den verschiedenen Schnitten."}'::jsonb WHERE id = 4857;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il professor Keating cammina sui banchi dell''aula per mostrare ai ragazzi come cambiare prospettiva, i libri e i quaderni sul banco di Charlie Dalton cambiano disposizione e apertura tra un''inquadratura e l''altra.","en":"During the scene where Professor Keating walks on the classroom desks to show the boys how to change perspective, the books and notebooks on Charlie Dalton''s desk change arrangement and openness between shots.","es":"Durante la escena en la que el profesor Keating camina sobre los pupitres del aula para mostrar a los chicos cómo cambiar de perspectiva, los libros y cuadernos en el pupitre de Charlie Dalton cambian de disposición y apertura entre plano y plano.","fr":"Pendant la scène où le professeur Keating marche sur les pupitres de la classe pour montrer aux garçons comment changer de perspective, les livres et cahiers sur le pupitre de Charlie Dalton changent de disposition et d''ouverture d''un plan à l''autre.","de":"Während der Szene, in der Professor Keating über die Klassenzimmertische geht, um den Jungs zu zeigen, wie man die Perspektive wechselt, verändern die Bücher und Hefte auf Charlie Daltons Tisch ihre Anordnung und ihren Aufschlag zwischen den Einstellungen."}'::jsonb WHERE id = 4858;
UPDATE errori SET descrizione_i18n = '{"it":"Nel dormitorio, mentre i ragazzi parlano di nascosto ascoltando la radio e fumando, il bicchiere tenuto in mano da Neil Perry si svuota e si riempie parzialmente o cambia posizione tra i vari cambi di inquadratura.","en":"In the dormitory, while the boys talk secretly listening to the radio and smoking, the glass held by Neil Perry empties and partially refills or changes position across various cuts.","es":"En el dormitorio, mientras los chicos hablan a escondidas escuchando la radio y fumando, el vaso que sostiene Neil Perry se vacía y se llena parcialmente o cambia posición entre los distintos cambios de plano.","fr":"Dans le dortoir, tandis que les garçons discutent en cachette en écoutant la radio et en fumant, le verre tenu par Neil Perry se vide et se remplit partiellement ou change de position d''un raccord à l''autre.","de":"Im Wohnheim, während die Jungs heimlich reden, Radio hören und rauchen, leert und füllt sich das von Neil Perry gehaltene Glas teilweise oder wechselt seine Position zwischen den verschiedenen Schnitten."}'::jsonb WHERE id = 4859;
UPDATE errori SET descrizione_i18n = '{"it":"Ambientato nel 1959, in alcune scene all''aperto nei pressi del collegio si possono intravedere nel traffico di sfondo o parcheggiate automobili con targhe e dettagli di anni successivi, sebbene la produzione abbia cercato di mantenere il rigore storico.","en":"Set in 1959, in some outdoor scenes near the college, cars with license plates and details from subsequent years can be glimpsed in the background traffic or parked, although the production tried to maintain historical accuracy.","es":"Ambientada en 1959, en algunas escenas al aire libre cerca del colegio se pueden vislumbrar en el tráfico de fondo o aparcadas automóviles con matrículas y detalles de años posteriores, aunque la producción intentó mantener el rigor histórico.","fr":"Se déroulant en 1959, dans certaines scènes en extérieur près du collège, on peut apercevoir dans la circulation de fond ou garées des voitures dotées de plaques d''immatriculation et de détails des années suivantes, bien que la production ait tenté de maintenir la rigueur historique.","de":"Die Handlung spielt im Jahr 1959; in einigen Außenszenen in der Nähe des Internats sind im Hintergrundverkehr oder parkend Autos mit Nummernschildern und Details aus späteren Jahren zu sehen, obwohl die Produktion um historische Genauigkeit bemüht war."}'::jsonb WHERE id = 4860;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la discussione sulla poesia nel cortile della scuola, l''edizione e le rilegature di alcuni libri tenuti in mano dagli studenti riflettono standard editoriali tipici degli anni ''70 e ''80 piuttosto che del periodo fine anni ''50.","en":"During the poetry discussion in the schoolyard, the edition and bindings of some books held by the students reflect publishing standards typical of the ''70s and ''80s rather than the late ''50s period.","es":"Durante la discusión sobre poesía en el patio de la escuela, la edición y encuadernación de algunos libros sostenidos por los estudiantes reflejan estándares editoriales típicos de los años 70 y 80 en lugar de finales de los 50.","fr":"Pendant la discussion sur la poésie dans la cour de l''école, l''édition et la reliure de certains livres tenus par les étudiants reflètent des normes d''édition typiques des années 70 et 80 plutôt que de la fin des années 50.","de":"Während der Poesiediskussion auf dem Schulhof spiegeln die Ausgabe und Einbände einiger von den Schülern gehaltenen Bücher Verlagsstandards der 70er und 80er Jahre wider anstelle der späten 50er Jahre."}'::jsonb WHERE id = 4861;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Major Marquis Warren punta la pistola contro uno dei sospettati vicino al fuoco, l''impugnatura e la posizione del cane della pistola cambiano visivamente tra un primo piano e un campo medio.","en":"When Major Marquis Warren aims his gun at one of the suspects near the fire, the grip and the position of the revolver''s hammer visibly change between a close-up and a medium shot.","es":"Cuando el Mayor Marquis Warren apunta con su pistola a uno de los sospechosos cerca del fuego, la empuñadura y la posición del martillo del arma cambian visiblemente entre un primer plano y un plano medio.","fr":"Quand le Major Marquis Warren pointe son pistolet sur l''un des suspects près du feu, la poignée et la position du chien de l''arme changent visiblement entre un gros plan et un plan moyen.","de":"Als Major Marquis Warren seine Waffe auf einen der Verdächtigen am Feuer richtet, verändern sich der Griff und die Position des Hahns der Pistole sichtbar zwischen einer Nahaufnahme und einer Halbtotale."}'::jsonb WHERE id = 4862;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena della confessione nella stanza sul retro, la quantità di sangue sulla ferita e sul viso del personaggio ferito varia visibilmente tra un cambio d''inquadratura e l''altro.","en":"During the backroom confession scene, the amount of blood on the injured character''s wound and face noticeably varies between cuts.","es":"Durante la escena de la confesión en la habitación trasera, la cantidad de sangre en la herida y en la cara del personaje herido varía visiblemente entre un cambio de plano y otro.","fr":"Pendant la scène de confession dans la pièce arrière, la quantité de sang sur la blessure et le visage du personnage blessé varie visiblement d''un raccord à l''autre.","de":"Während der Beichtszene im Hinterzimmer variiert die Menge an Blut an der Wunde und im Gesicht des verletzten Charakters sichtbar zwischen den Montageeinstellungen."}'::jsonb WHERE id = 4863;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Daisy Domergue siede vicino alla stufa con la faccia insanguinata, la ciocca di capelli bagnati e insanguinati che le scende sulla guancia destra cambia spessore e posizione esatta tra un''inquadratura in primo piano e il controcampo.","en":"As Daisy Domergue sits by the stove with a bloody face, the wet, blood-matted lock of hair hanging down her right cheek changes in thickness and exact position between a close-up shot and the reverse shot.","es":"Mientras Daisy Domergue se sienta junto a la estufa con la cara ensangrentada, el mechón de cabello mojado y con sangre que le cae por la mejilla derecha cambia de grosor y de posición exacta entre un plano detalle y el contratoma.","fr":"Alors que Daisy Domergue est assise près du poêle le visage en sang, la mèche de cheveux mouillés et ensanglantés qui tombe sur sa joue droite change d''épaisseur et de position exacte entre un gros plan et le contre-champ.","de":"Während Daisy Domergue mit blutiges Gesicht am Ofen sitzt, verändert sich die nackte, blutige Haartracht, die ihr über die rechte Wange fällt, in Dicke und exakter Position zwischen einer Nahaufnahme und dem Gegenschuss."}'::jsonb WHERE id = 4864;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena della confessione di Jody e la sparatoria sotterranea, la pistola tenuta da Chris Mannix cambia mano e orientamento tra un taglio di montaggio e l''altro prima di sparare.","en":"During Jody''s confession scene and the underground shootout, the gun held by Chris Mannix changes hands and orientation between editing cuts before firing.","es":"Durante la escena de la confesión de Jody y el tiroteo subterráneo, la pistola que sostiene Chris Mannix cambia de mano y de orientación entre un corte de montaje y otro antes de disparar.","fr":"Pendant la scène de confession de Jody et la fusillade souterraine, le pistolet tenu par Chris Mannix change de main et d''orientation d''un raccord de montage à l''autre avant de tirer.","de":"Während Jodys Beichtszene und der Schießerei im Untergrund wechselt die von Chris Mannix gehaltene Waffe zwischen den Filmschnitten vor dem Schuss die Hand und die Ausrichtung."}'::jsonb WHERE id = 4865;
UPDATE errori SET descrizione_i18n = '{"it":"Il tipo di carta da lettere e il calamaio usati per la finta lettera di Abramo Lincoln al Maggiore Warren presentano caratteristiche tipografiche e materiali leggermente anacronistiche rispetto alla metà del XIX secolo, come segnalato da alcuni storici del cinema.","en":"The stationery and inkwell used for Abraham Lincoln''s fake letter to Major Warren feature slightly anachronistic typographical and material characteristics for the mid-19th century, as pointed out by film historians.","es":"El papel de cartas y el tintero utilizados para la falsa carta de Abraham Lincoln al Mayor Warren presentan características tipográficas y materiales ligeramente anacrónicas para mediados del siglo XIX, según señalaron algunos historiadores de cine.","fr":"Le papier à lettres et l''encrier utilisés pour la fausse lettre d''Abraham Lincoln au Major Warren présentent des caractéristiques typographiques et matérielles légèrement anachroniques par rapport au milieu du XIXe siècle, comme l''ont souligné certains historiens du cinéma.","de":"Das Briefpapier und das Tintenfass, die für Abraham Lincolns gefälschten Brief an Major Warren verwendet wurden, weisen für die Mitte des 19. Jahrhunderts leicht anachronistische typografische und materielle Merkmale auf, wie Filmhistoriker feststellten."}'::jsonb WHERE id = 4866;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Peter Parker si cambia i vestiti nel vicolo indossando il costume di Spider-Man, lo zaino che appoggia accanto al muro cambia posizione e orientamento tra un''inquadratura e l''altra.","en":"When Peter Parker changes his clothes in the alley into the Spider-Man suit, the backpack he leans against the wall changes position and orientation between shots.","es":"Cuando Peter Parker se cambia de ropa en el callejón para ponerse el traje de Spider-Man, la mochila que apoya junto a la pared cambia de posición y orientación entre plano y plano.","fr":"Quand Peter Parker se change dans la ruelle pour enfiler le costume de Spider-Man, le sac à dos qu''il pose contre le mur change de position et d''orientation d''un plan à l''autre.","de":"Als Peter Parker sich in der Gasse umzieht und den Spider-Man-Anzug anzieht, wechseln Position und Ausrichtung des Rucksacks, den er an die Wand lehnt, zwischen den Einstellungen."}'::jsonb WHERE id = 4867;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Happy Hogan guida il camion della Stark, i documenti e gli oggetti sul cruscotto cambiano disposizione in modo evidente tra le inquadrature frontali e quelle di profilo.","en":"During the sequence where Happy Hogan drives the Stark truck, the documents and objects on the dashboard noticeably change arrangement between frontal and profile shots.","es":"Durante la secuencia en la que Happy Hogan conduce el camión de Stark, los documentos y objetos del salpicadero cambian de disposición de forma evidente entre los planos frontales y los de perfil.","fr":"Pendant la séquence où Happy Hogan conduit le camion Stark, les documents et objets sur le tableau de bord changent visiblement de disposition entre les plans frontaux et de profil.","de":"Während der Sequenz, in der Happy Hogan den Stark-Lkw fährt, verändert sich die Anordnung der Dokumente und Gegenstände auf dem Armaturenbrett zwischen Frontal- und Profilaufnahmen deutlich."}'::jsonb WHERE id = 4868;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena dell''hotel in cui Peter parla con Ned prima della festa, il fazzoletto e gli oggetti sulla scrivania si spostano autonomamente da un taglio di montaggio all''altro.","en":"In the hotel scene where Peter talks to Ned before the party, the tissue and items on the desk shift continuity-wise from one editing cut to the next.","es":"En la escena del hotel donde Peter habla con Ned antes de la fiesta, el pañuelo y los objetos del escritorio cambian de posición de un corte de montaje a otro.","fr":"Dans la scène de l''hôtel où Peter parle à Ned avant la fête, le mouchoir et les objets sur le bureau changent de place d''un raccord de montage à l''autre.","de":"In der Hotelszene, in der Peter vor der Party mit Ned spricht, verändern das Taschentuch und die Gegenstände auf dem Schreibtisch von einem Filmschnitt zum nächsten unbemerkt ihre Position."}'::jsonb WHERE id = 4869;
UPDATE errori SET descrizione_i18n = '{"it":"Durante lo scontro finale sulla spiaggia dell''aereo cargo, in un rapido controcampo è possibile intravedere brevemente la base di supporto di un''attrezzatura di illuminazione riflessa sulla fusoliera metallica.","en":"During the final clash on the cargo plane beach, in a quick reverse shot, the support base of a lighting rig can be briefly glimpsed reflected on the metal fuselage.","es":"Durante el enfrentamiento final en la playa del avión de carga, en un plano contraplano rápido se puede ver brevemente la base de apoyo de un equipo de iluminación reflejada en el fuselaje metálico.","fr":"Pendant l''affrontement final sur la plage de l''avion-cargo, dans un champ-contrechamp rapide, on peut entrevoir brièvement la base d''un équipement d''éclairage reflétée sur le fuselage métallique.","de":"Während des finalen Kampfes am Strand des Frachtflugzeugs ist in einer schnellen Gegenaufnahme kurz die Halterung eines Beleuchtungsrigns zu sehen, die sich auf dem Rumpf spiegelt."}'::jsonb WHERE id = 4870;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Peter insegue i criminali nel quartiere e attraversa i giardini delle case, il tasso di usura e i graffi sul costume variano visivamente a seconda del cambio d''inquadratura.","en":"While Peter chases the criminals through the neighborhood and crosses residential yards, the wear and tear and scratches on his suit visibly change depending on the camera angle.","es":"Mientras Peter persigue a los criminales por el vecindario y cruza los jardines de las casas, el nivel de desgaste y los rasguños del traje varían visualmente según el cambio de plano.","fr":"Pendant que Peter poursuit les criminels dans le quartier et traverse les jardins des maisons, l''usure et les égratignures sur son costume varient visiblement selon le changement de plan.","de":"Während Peter die Kriminellen durch das Viertel verfolgt und Gärten überquert, verändern sich Abnutzung und Kratzer an seinem Kostüm je nach Einstellung sichtbar."}'::jsonb WHERE id = 4871;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Peter parla con il giudice all''esterno del tribunale, le persone sullo sfondo e i passanti compaiono e scompaiono in modo incoerente tra un''inquadratura e l''altra, tradendo la ripetizione dei ciak.","en":"During the scene where Peter talks to the judge outside the courthouse, background extras and passersby inconsistently appear and disappear from shot to shot, betraying the multiple takes.","es":"Durante la escena en la que Peter habla con el juez fuera del tribunal, la gente del fondo y los transeúntes aparecen y desaparecen de forma incoherente entre plano y plano, delatando los múltiples cortes de los takes.","fr":"Pendant la scène où Peter parle au juge devant le tribunal, les figurants en arrière-plan et les passants apparaissent et disparaissent de manière incohérente d''un plan à l''autre, trahissant les multiples prises.","de":"In der Szene, in der Peter vor dem Gerichtsgebäude mit dem Richter spricht, tauchen Statisten und Passanten im Hintergrund von Einstellung zu Einstellung inkonsistent auf und verschwinden wieder, was die verschiedenen Takes verrät."}'::jsonb WHERE id = 4872;
UPDATE errori SET descrizione_i18n = '{"it":"Nel Sanctum Sanctorum, mentre il Dottor Strange lancia l''incantesimo, i libri che fluttuano attorno alla stanza cambiano disposizione e numero nei tagli di montaggio successivi.","en":"In the Sanctum Sanctorum, as Doctor Strange casts the spell, the books floating around the room change their arrangement and number across subsequent editing cuts.","es":"En el Sanctum Sanctorum, mientras el Doctor Strange lanza el hechizo, los libros que flotan alrededor de la habitación cambian de disposición y número en los siguientes cortes de montaje.","fr":"Dans le Sanctum Sanctorum, alors que Doctor Strange lance le sort, les livres qui flottent autour de la pièce changent de disposition et de nombre au fil des raccords de montage.","de":"Im Sanctum Sanctorum verändern die im Raum schwebenden Bücher während Doctors Stranges Zauberspruch ihre Anordnung und Anzahl über aufeinanderfolgende Schnitte hinweg."}'::jsonb WHERE id = 4873;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza all''interno del laboratorio di Happy, la bottiglietta d''acqua tenuta da Peter cambia il livello del liquido all''interno e l''orientamento dell''etichetta tra i vari primi piani.","en":"In the sequence inside Happy''s lab, the water bottle held by Peter changes its liquid level and label orientation between various close-ups.","es":"En la secuencia dentro del laboratorio de Happy, la botella de agua que sostiene Peter cambia el nivel de líquido y la orientación de la etiqueta entre los distintos primeros planos.","fr":"Dans la séquence à l''intérieur du labo de Happy, la bouteille d''eau tenue par Peter change de niveau de liquide et d''orientation d''étiquette entre les différents gros plans.","de":"In der Sequenz in Happys Labor verändern sich bei der von Peter gehaltenen Wasserflasche der Füllstand und die Ausrichtung des Etiketts zwischen den verschiedenen Nahaufnahmen."}'::jsonb WHERE id = 4874;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia notturna nei pressi della Statua della Libertà, in un''inquadratura grandangolare che mostra la struttura metallica, si intravede per un istante il riflesso di una luce da studio cinematografica su una superficie lucida.","en":"During the night battle near the Statue of Liberty, in a wide shot showing the metal framework, the reflection of a studio movie light can be briefly spotted on a shiny surface.","es":"Durante la batalla nocturna cerca de la Estatua de la Libertad, en un plano general que muestra la estructura metálica, se ve brevemente el reflejo de un foco de estudio de cine en una superficie brillante.","fr":"Pendant la bataille nocturne près de la Statue de la Liberté, dans un plan large montrant la structure métallique, on aperçoit brièvement le reflet d''un projecteur de studio sur une surface brillante.","de":"Während des nächtlichen Kampfes nahe der Freiheitsstatue ist in einer Totalen, die die Metallstruktur zeigt, kurz die Reflektion eines Studio-Scheinwerfers auf einer glänzenden Oberfläche zu sehen."}'::jsonb WHERE id = 4875;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i tre Peter Parker si incontrano nel laboratorio della scuola, le bende e i cerotti applicati sui loro volti e costumi variano leggermente per forma e posizionamento a seconda dell''inquadratura.","en":"When the three Peter Parkers meet in the school lab, the bandages and plasters on their faces and suits slightly vary in shape and placement depending on the shot.","es":"Cuando los tres Peter Parker se encuentran en el laboratorio de la escuela, las vendas y los parches aplicados en sus caras y trajes varían ligeramente en forma y colocación según el plano.","fr":"Quand les trois Peter Parker se rencontrent dans le labo du lycée, les bandages et pansements sur leurs visages et leurs costumes varient légèrement en forme et en position selon le plan.","de":"Wenn die drei Peter Parkers sich im Schullabor treffen, variieren die Verbände und Pflaster in ihren Gesichtern und Kostümen je nach Einstellung leicht in Form und Platzierung."}'::jsonb WHERE id = 4876;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sparatoria sul tetto del palazzo, l''Agente Jones spara contro Neo da distanza ravvicinata. In un''inquadratura in cui Neo schiva i proiettili piegandosi all''indietro, la giacca lunga di Neo si apre mostrando chiaramente l''imbracatura e i cavi di sostegno utilizzati per la sequenza di stunt, modificando la forma e il drappeggio del cappotto tra un taglio e l''altro.","en":"During the rooftop shootout, Agent Jones shoots at Neo from close range. In a shot where Neo dodges bullets by bending backward, his long coat flies open to clearly reveal the harness and safety wires used for the stunt sequence, altering the coat''s shape and drape between cuts.","es":"Durante el tiroteo en la azotea, el Agente Jones le dispara a Neo a corta distancia. En un plano en el que Neo esquiva las balas inclinándose hacia atrás, su abrigo largo se abre revelando claramente el arnés y los cables de seguridad utilizados para la secuencia de especialistas, alterando la forma y la caída de la gabardina entre plano y contraplano.","fr":"Pendant la fusillade sur le toit, l''agent Jones tire sur Neo à bout portant. Dans un plan où Neo esquive les balles en se penchant en arrière, son long manteau s''ouvre pour révéler clairement le harnais et les câbles de sécurité utilisés pour la séquence de cascade, modifiant la forme et le tombé du manteau d''un raccord à l''autre.","de":"Während der Schießerei auf dem Dach schießt Agent Jones aus nächster Nähe auf Neo. In einer Einstellung, in der Neo den Kugeln ausweicht, indem er sich nach hinten beugt, öffnet sich sein langer Mantel und gibt den Blick auf das Gurtzeug und die Sicherungsseile für die Stunt-Sequenz frei, wodurch sich die Form und der Fall des Mantels zwischen den Schnitten verändern."}'::jsonb WHERE id = 4877;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Tank carica il programma di addestramento al combattimento nel cervello di Neo, la tastiera del computer usata da Tank mostra il cavo disconnesso o inserito in porte differenti nelle diverse inquadrature ravvicinate e a campo largo.","en":"In the scene where Tank uploads the combat training program into Neo''s brain, the computer keyboard used by Tank has its cable disconnected or plugged into different ports across various close-ups and wide shots.","es":"En la escena en la que Tank carga el programa de entrenamiento de combate en el cerebro de Neo, el teclado de la computadora que usa Tank muestra el cable desconectado o enchufado en puertos diferentes en los distintos primeros planos y planos generales.","fr":"Dans la scène où Tank télécharge le programme d''entraînement au combat dans le cerveau de Neo, le câble du clavier d''ordinateur utilisé par Tank est débranché ou branché sur des ports différents selon les gros plans et les plans larges.","de":"In der Szene, in der Tank das Kampftrainingsprogramm in Neos Gehirn lädt, ist das von Tank benutzte Computerkabel in verschiedenen Nahaufnahmen und Totalen entweder nicht angeschlossen oder steckt in anderen Anschlüssen."}'::jsonb WHERE id = 4878;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza nel cubicolo dell''ufficio della Metacortex, quando Neo riceve il pacchetto con il telefono cellulare dalla FedEx, l''audio del coperchio della scatola che si apre e della carta che si stropiccia non coincide perfettamente con i movimenti delle mani di Keanu Reeves nelle riprese da angolazioni diverse.","en":"During the sequence in the Metacortex office cubicle, when Neo receives the package with the cell phone from FedEx, the audio of the box lid opening and the paper rustling does not match up perfectly with Keanu Reeves'' hand movements across different camera angles.","es":"Durante la secuencia en el cubículo de la oficina de Metacortex, cuando Neo recibe el paquete con el teléfono móvil de FedEx, el audio de la tapa de la caja al abrirse y del papel crujiendo no coincide perfectamente con los movimientos de las manos de Keanu Reeves en las tomas desde diferentes ángulos.","fr":"Pendant la séquence dans le cubicle du bureau de Metacortex, lorsque Neo reçoit le colis contenant le téléphone portable de FedEx, le son de la boîte qui s''ouvre et du papier qui froisse ne correspond pas parfaitement aux mouvements des mains de Keanu Reeves selon les angles de caméra.","de":"Während der Sequenz im Büro-Kubus von Metacortex, als Neo das Paket mit dem Handy von FedEx erhält, stimmt das Audio des sich öffnenden Schachteldeckels und des knisternden Papiers in verschiedenen Kameraeinstellungen nicht perfekt mit den Handbewegungen von Keanu Reeves überein."}'::jsonb WHERE id = 4879;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena finale in cui Neo si allontana camminando tra la folla e indossa gli occhiali da sole prima di sollevarsi in volo, riflettersi sulle lenti degli occhiali dei passanti o sulla carrozzeria di alcune auto in sosta si intravedono brevemente sagome di membri della troupe con attrezzatura di illuminazione.","en":"In the final scene where Neo walks away through the crowd and puts on his sunglasses before taking flight, silhouettes of crew members with lighting equipment are briefly visible as reflections in the lenses of bystanders'' glasses or on the bodywork of parked cars.","es":"En la escena final en la que Neo se aleja caminando entre la multitud y se pone las gafas de sol antes de volar, se atisban brevemente las siluetas de miembros del equipo técnico con equipo de iluminación reflejadas en los cristales de las gafas de los transeúntes o en la carrocería de algunos coches aparcados.","fr":"Dans la scène finale où Neo s''éloigne dans la foule et met ses lunettes de soleil avant de s''envoler, on aperçoit brièvement les silhouettes de membres de l''équipe technique avec du matériel d''éclairage se reflétant dans les verres des lunettes des passants ou sur la carrosserie de voitures garées.","de":"In der Schlussszene, in der Neo durch die Menge davongeht und seine Sonnenbrille aufsetzt, bevor er abhebt, sind in den Brillengläsern von Passanten oder auf der Karosserie geparkter Autos kurz die Silhouetten von Crewmitgliedern mit Beleuchtungsausrüstung als Spiegelung zu erkennen."}'::jsonb WHERE id = 4880;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza d''azione sull''autostrada, in un''inquadratura ravvicinata del camion che trasporta la torta, è possibile intravedere brevemente il riflesso della troupe e delle attrezzature di illuminazione sulla carrozzeria lucida del veicolo.","en":"During the highway action sequence, in a close-up shot of the cake-delivery truck, the reflection of the crew and lighting equipment can be briefly glimpsed on the vehicle''s glossy bodywork.","es":"Durante la secuencia de acción en la autopista, en un plano detalle del camión que transporta el pastel, se puede atisbar brevemente el reflejo del equipo de filmación y de los equipos de iluminación en la carrocería brillante del vehículo.","fr":"Pendant la séquence d''action sur l''autoroute, dans un gros plan du camion de livraison de gâteaux, on peut entrapercevoir brièvement le reflet de l''équipe de tournage et du matériel d''éclairage sur la carrosserie brillante du véhicule.","de":"Während der Autobahn-Actionsequenz ist in einer Nahaufnahme des Kuchen-LKWs kurz die Spiegelung der Crew und der Beleuchtungsausrüstung auf der glänzenden Karosserie des Fahrzeugs zu sehen."}'::jsonb WHERE id = 4881;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Morpheus tiene il suo discorso infuocato ai cittadini di Zion prima della battaglia, il microfono indossato sul bavero della sua giacca cambia leggermente inclinazione e posizione tra un cambio d''inquadratura e l''altro.","en":"In the scene where Morpheus delivers his fiery speech to the citizens of Zion before the battle, the lavalier microphone clipped to his jacket lapel slightly changes its angle and position between camera angles.","es":"En la escena en la que Morpheus pronuncia su apasionado discurso a los ciudadanos de Zion antes de la batalla, el micrófono de solapa sujeto a su chaqueta cambia ligeramente de inclinación y posición entre los diferentes planos.","fr":"Dans la scène où Morpheus prononce son discours enflammé aux citoyens de Zion avant la bataille, le micro-cravate fixé au revers de sa veste change légèrement d''inclinaison et de position d''un plan à l''autre.","de":"In der Szene, in der Morpheus vor der Schlacht seine leidenschaftliche Rede an die Bürger von Zion hält, verändern sich Neigung und Position des Ansteckmikrofons an seinem Jackenrevers zwischen den verschiedenen Kameraeinstellungen leicht."}'::jsonb WHERE id = 4882;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Neo si trova nella stanza dell''Architetto, i monitor alle pareti mostrano diverse reazioni di Neo in tempo reale. In un''inquadratura specifica, lo schermo alle spalle dell''Architetto mostra un fotogramma in anticipo rispetto alla sequenza temporale effettiva della conversazione.","en":"When Neo is in the Architect''s room, the wall monitors show various real-time reactions of Neo. In one specific shot, the screen behind the Architect is one frame ahead of the actual timeline of the conversation.","es":"Cuando Neo se encuentra en la habitación del Arquitecto, los monitores de las paredes muestran varias reacciones de Neo en tiempo real. En un plano específico, la pantalla situada detrás del Arquitecto muestra un fotograma adelantado respecto a la línea de tiempo real de la conversación.","fr":"Lorsque Neo se trouve dans la pièce de l''Architecte, les moniteurs sur les murs affichent diverses réactions de Neo en temps réel. Dans un plan spécifique, l''écran derrière l''Architecte a une image d''avance par rapport au déroulement réel de la conversation.","de":"Als Neo sich im Raum des Architekten befindet, zeigen die Monitore an den Wänden verschiedene Reaktionen von Neo in Echtzeit. In einer bestimmten Einstellung ist der Bildschirm hinter dem Architekten der tatsächlichen Zeitachse des Gesprächs um einen Frame voraus."}'::jsonb WHERE id = 4883;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il combattimento tra Neo e le centinaia di cloni dell''Agente Smith nel parco (Burly Brawl), in alcune inquadrature a campo largo si notano chiaramente i cavi di sicurezza attaccati agli stuntman per le scene di volo e rimbalzo.","en":"During the fight between Neo and the hundreds of Agent Smith clones in the park (Burly Brawl), safety wires attached to the stunt performers for the flying and rebounding scenes are clearly visible in some wide shots.","es":"Durante el combate entre Neo y los cientos de clones del Agente Smith en el parque (la pelea descomunal), en algunos planos generales se aprecian claramente los cables de seguridad sujetos a los especialistas para las escenas de vuelo y rebote.","fr":"Pendant le combat entre Neo et les centaines de clones de l''agent Smith dans le parc (la bagarre générale), les câbles de sécurité attachés aux cascadeurs pour les scènes de vol et de rebond sont clairement visibles dans certains plans larges.","de":"Während des Kampfes zwischen Neo und den Hunderten von Agent-Smith-Klonen im Park (Burly Brawl) sind in einigen Totalen deutlich die Sicherungsseile zu erkennen, die für die Flug- und Rückprallszenen an den Stuntmen befestigt sind."}'::jsonb WHERE id = 4884;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della festa sotterranea a Zion, la posizione della bottiglia di colore ambrato tenuta da Trinity varia visibilmente tra la mano destra e la mano sinistra quando l''inquadratura passa da campo medio a primo piano.","en":"During the underground party in Zion, the position of the amber-colored bottle held by Trinity noticeably shifts between her right and left hand as the shot cuts from a medium shot to a close-up.","es":"Durante la fiesta subterránea en Zion, la posición de la botella de color ámbar que sostiene Trinity cambia visiblemente entre su mano derecha e izquierda cuando la toma pasa de plano medio a primer plano.","fr":"Pendant la fête souterraine à Zion, la position de la bouteille de couleur ambre tenue par Trinity change visiblement entre sa main droite et sa main gauche lorsque le plan passe d''un plan moyen à un gros plan.","de":"Während der Untergrundparty in Zion wechselt die Position der bernsteinfarbener Flasche in Trinitys Hand merklich zwischen ihrer rechten und linken Hand, wenn die Einstellung von einer Halbtotale zu einer Nahaufnahme wechselt."}'::jsonb WHERE id = 4885;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle sequenze d''azione all''interno del quartier generale di Zion, in un''inquadratura ravvicinata tra la folla è possibile intravedere per un breve istante l''ombra di un microfono a boom proiettata sulla parete di metallo alle spalle degli attori.","en":"During one of the action sequences inside the Zion headquarters, in a close-up amid the crowd, the shadow of a boom mic can be briefly glimpsed projected onto the metal wall behind the actors.","es":"Durante una de las secuencias de acción dentro del cuartel general de Zion, en un plano corto entre la multitud, se puede atisbar brevemente la sombra de un micrófono de pértiga proyectada en la pared metálica detrás de los actores.","fr":"Pendant l''une des séquences d''action à l''intérieur du quartier général de Zion, dans un plan serré au milieu de la foule, on peut apercevoir brièvement l''ombre d''un micro perche projetée sur le mur en métal derrière les acteurs.","de":"Während einer der Actionsequenzen im Hauptquartier von Zion ist in einer Nahaufnahme inmitten der Menge kurz der Schatten eines Boom-Mikrofons an der Metallwand hinter den Schauspielern zu sehen."}'::jsonb WHERE id = 4886;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Morpheus e gli altri discutono sul da farsi a bordo della nave, la tazza che Morpheus tiene in mano cambia posizione e livello di liquido tra un cambio d''inquadratura e l''altro.","en":"In the scene where Morpheus and the others discuss their next move aboard the ship, the cup Morpheus is holding changes position and liquid level between cuts.","es":"En la escena en la que Morpheus y los demás discuten qué hacer a bordo de la nave, la taza que sostiene Morpheus cambia de posición y de nivel de líquido entre plano y plano.","fr":"Dans la scène où Morpheus et les autres discutent de la marche à suivre à bord du vaisseau, la tasse que tient Morpheus change de position et de niveau de liquide d''un plan à l''autre.","de":"In der Szene, in der Morpheus und die anderen an Bord des Schiffes ihr weiteres Vorgehen besprechen, ändern sich die Position der Tasse in Morpheus'' Hand und der Füllstand der Flüssigkeit zwischen den Schnitten."}'::jsonb WHERE id = 4887;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il combattimento finale tra Neo e l''Agente Smith nel cratere pieno d''acqua, i vestiti di Neo passano dall''essere completamente inzuppati a visibilmente più asciutti e puliti a seconda dell''angolo di ripresa.","en":"During the final fight between Neo and Agent Smith in the water-filled crater, Neo''s clothes switch from being completely soaked to noticeably drier and cleaner depending on the camera angle.","es":"Durante el combate final entre Neo y el Agente Smith en el cráter lleno de agua, la ropa de Neo pasa de estar completamente empapada a verse mucho más seca y limpia según el ángulo de cámara.","fr":"Pendant le combat final entre Neo et l''agent Smith dans le cratère rempli d''eau, les vêtements de Neo passent d''une trempette complète à un état visiblement plus sec et propre selon l''angle de prise de vue.","de":"Während des finalen Kampfes zwischen Neo und Agent Smith im wassergefüllten Krater wechseln Neos Kleider je nach Kamerawinkel von durchnässt zu merklich trockener und sauberer."}'::jsonb WHERE id = 4888;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la nave si avvicina alla Città delle Macchine, i monitor di navigazione mostrano letture e diagrammi digitali che cambiano completamente disposizione e dati geometrici da un''inquadratura frontale a quella laterale.","en":"As the ship approaches the Machine City, the navigation monitors display digital readings and diagrams that completely change layout and geometric data between a front shot and a side shot.","es":"Cuando la nave se acerca a la Ciudad de las Máquinas, los monitores de navegación muestran lecturas y diagramas digitales que cambian por completo de disposición y datos geométricos entre un plano frontal y uno lateral.","fr":"Lorsque le vaisseau s''approche de la Cité des Machines, les moniteurs de navigation affichent des lectures et des diagrammes numériques dont la disposition et les données géométriques changent complètement entre un plan de face et un plan de profil.","de":"Als sich das Schiff der Maschinenstadt nähert, zeigen die Navigationsmonitore digitale Messwerte und Diagramme, deren Anordnung und geometrische Daten sich zwischen einer Frontaleinstellung und einer seitlichen Einstellung völlig verändern."}'::jsonb WHERE id = 4889;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza iniziale nella fattoria, quando i tre sicari di Sentenza irrompono nella casa di Stevens, la posizione dei bicchieri e delle stoviglie sul tavolo cambia visibilmente tra un''inquadratura e l''altra prima che inizi la sparatoria.","en":"During the opening farm sequence, when Angel Eyes'' three henchmen burst into Stevens'' house, the position of the glasses and tableware on the table changes noticeably between cuts before the shootout begins.","es":"Durante la secuencia inicial en la granja, cuando los tres pistoleros de Ojos de Ángel irrumpen en la casa de Stevens, la posición de los vasos y la vajilla en la mesa cambia notablemente de un plano a otro antes de que comience el tiroteo.","fr":"Pendant la séquence d''ouverture à la ferme, lorsque les trois hommes de main de Sentenza font irruption dans la maison de Stevens, la position des verres et de la vaisselle sur la table change visiblement d''un plan à l''autre avant que la fusillade ne commence.","de":"Während der Eröffnungssequenz auf der Farm, als die drei Schergen von Sentenza in Stevens'' Haus stürmen, verändert sich die Position der Gläser und des Geschirrs auf dem Tisch zwischen den Einstellungen deutlich, bevor die Schießerei beginnt."}'::jsonb WHERE id = 4890;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso del film, i soldati sia dell''Unione che della Confederazione utilizzano fucili e carabine a retrocarica e a ripetizione (come i fucili Henry o Springfield) che in alcuni casi non erano ancora ampiamente distribuiti o impiegati nelle specifiche fasi della Guerra di Secessione rappresentate.","en":"Throughout the film, both Union and Confederate soldiers use breech-loading and repeating rifles and carbines (such as Henry or Springfield rifles) that in some cases were not yet widely distributed or used during the specific phases of the Civil War depicted.","es":"A lo largo de la película, tanto los soldados de la Unión como los confederados utilizan rifles y carabinas de retrocarga y repetición (como los rifles Henry o Springfield) que en algunos casos aún no estaban ampliamente distribuidos o empleados en las fases específicas de la Guerra de Secesión representadas.","fr":"Tout au long du film, les soldats de l''Union et de la Confédération utilisent des fusils et des carabines à chargement par la culasse et à répétition (tels que les fusils Henry ou Springfield) qui, dans certains cas, n''étaient pas encore largement distribués ou utilisés au cours des phases spécifiques de la guerre de Sécession représentées.","de":"Im Laufe des Films verwenden sowohl Unions- als auch konföderierte Soldaten Hinterlader- und Repetiergewehre sowie -karabiner (wie Henry- oder Springfield-Gewehre), die in einigen Fällen in den dargestellten Phasen des Amerikanischen Bürgerkriegs noch gar nicht weit verbreitet oder im Einsatz waren."}'::jsonb WHERE id = 4891;
UPDATE errori SET descrizione_i18n = '{"it":"Il campo di prigionia nordista di Andersonville (ispirato nel film) viene mostrato con dinamiche e strutture differenti da quelle storiche documentate, e la presenza di ufficiali ubriachi che ascoltano musica con grammofoni a tromba anticipa di decenni la diffusione di tale tecnologia.","en":"The Northern prisoner-of-war camp of Andersonville (depicted in the film) is shown with dynamics and structures differing from documented history, and the presence of drunken officers listening to music on horn gramophones anticipates the spread of such technology by decades.","es":"El campo de prisioneros nordista de Andersonville (inspirado en la película) se muestra con dinámicas y estructuras diferentes a las históricas documentadas, y la presencia de oficiales borrachos que escuchan música con gramófonos de corneta anticipa en décadas la difusión de dicha tecnología.","fr":"Le camp de prisonniers nordiste d''Andersonville (dont le film s''inspire) est présenté avec des dynamiques et des structures différentes de l''histoire documentée, et la présence d''officiers ivres écoutant de la musique sur des gramophones à pavillon anticipe de plusieurs décennies la diffusion de cette technologie.","de":"Das nordstaatliche Kriegsgefangenenlager Andersonville (das im Film als Vorbild dient) wird mit Dynamiken und Strukturen gezeigt, die von der dokumentierten Geschichte abweichen, und die anwesenden betrunkenen Offiziere, die Musik über Trichtergrammophone hören, greifen die Verbreitung dieser Technologie um Jahrzehnte voraus."}'::jsonb WHERE id = 4892;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Tuco viene torturato da Sentenza nel deserto, le ferite e le ecchimosi sul viso del personaggio variano per intensità e posizione esatta a seconda che l''inquadratura sia un primo piano o un campo medio.","en":"In the scene where Tuco is tortured by Angel Eyes in the desert, the wounds and bruises on the character''s face vary in intensity and exact placement depending on whether the shot is a close-up or a medium shot.","es":"En la escena en la que Tuco es torturado por Ojos de Ángel en el desierto, las heridas y los hematomas en la cara del personaje varían en intensidad y posición exacta según si el plano es un primer plano o un plano medio.","fr":"Dans la scène où Tuco est torturé par Sentenza dans le désert, les blessures et les contusions sur le visage du personnage varient en intensité et en emplacement exact selon qu''il s''agit d''un gros plan ou d''un plan moyen.","de":"In der Szene, in der Tuco von Sentenza in der Wüste gefoltert wird, variieren die Wunden und Blutergüsse im Gesicht der Figur in Intensität und genauer Platzierung, je nachdem, ob es sich um eine Nahaufnahme oder eine halbtotale Einstellung handelt."}'::jsonb WHERE id = 4893;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Jill si trova all''interno del saloon a Flagstone e suona il pianoforte, il bicchiere posizionato sul bordo dello strumento cambia posizione e livello di liquido tra un''inquadratura e l''altra del montaggio alternato.","en":"During the sequence where Jill is inside the Flagstone saloon playing the piano, the glass placed on the edge of the instrument changes position and liquid level between cuts in the cross-cutting montage.","es":"Durante la secuencia en la que Jill está dentro del salón en Flagstone tocando el piano, el vaso colocado en el borde del instrumento cambia de posición y de nivel de líquido entre plano y plano del montaje paralelo.","fr":"Pendant la séquence où Jill se trouve à l''intérieur du saloon de Flagstone et joue du piano, le verre posé sur le bord de l''instrument change de position et de niveau de liquide d''un plan à l''autre dans le montage alterné.","de":"Während der Sequenz, in der sich Jill im Saloon in Flagstone befindet und Klavier spielt, verändern sich die Position des Glases am Rand des Instruments und der Füllstand der Flüssigkeit zwischen den Einstellungen des parallelen Schnitts."}'::jsonb WHERE id = 4894;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sparatoria finale tra i pistoleri di Frank e Armonica presso la struttura in costruzione a Sweetwater, in un campo medio si intravede per un istante l''ombra della giraffa del microfono boom proiettata sulla parete di legno.","en":"During the final shootout between Frank''s gunmen and Harmonica at the construction site in Sweetwater, in a medium shot the shadow of the boom microphone pole can be glimpsed for an instant cast on the wooden wall.","es":"Durante el tiroteo final entre los pistoleros de Frank y Armónica en la estructura en construcción de Sweetwater, en un plano medio se puede vislumbrar por un instante la sombra de la jirafa del micrófono boom proyectada en la pared de madera.","fr":"Au cours de la fusillade finale entre les hommes de main de Frank et Harmonica près du bâtiment en construction à Sweetwater, on aperçoit un instant, dans un plan moyen, l''ombre de la perche du micro boom projetée sur le mur en bois.","de":"Während der finalen Schießerei zwischen Franks Gunman und Harmonica an der Baustruktur in Sweetwater ist in einer halbtotalen Einstellung für einen Moment der Schatten der Tonangel (Boom-Mikrofon) an der Holzwand zu sehen."}'::jsonb WHERE id = 4895;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune inquadrature esterne ambientate nel deserto, sullo sfondo si notano linee di trasmissione elettrica moderna o pali telefonici che non appartengono al periodo storico in cui è ambientato il western.","en":"In some exterior shots set in the desert, modern electrical power lines or telephone poles can be spotted in the background that do not belong to the historical period in which the western is set.","es":"En algunas tomas exteriores ambientadas en el desierto, se pueden ver en el fondo líneas de transmisión eléctrica moderna o postes telefónicos que no corresponden al periodo histórico en el que se ambienta el western.","fr":"Dans certains plans extérieurs tournés dans le désert, on aperçoit en arrière-plan des lignes électriques modernes ou des poteaux téléphoniques qui n''appartiennent pas à la période historique dans laquelle le western est ancré.","de":"In einigen in der Wüste gedrehten Außenaufnahmen sind im Hintergrund moderne Stromleitungen oder Telefonmasten zu sehen, die nicht in die historische Epoche des Westerns passen."}'::jsonb WHERE id = 4896;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''attesa alla stazione ferroviaria di Cattle Corner, i tre pistoleri appostati passano il tempo in modi diversi. La posizione delle mani e del fucile imbracciato da uno di essi cambia nettamente tra un''inquadratura e il rispettivo controcampo.","en":"While waiting at the Cattle Corner train station, the three lying-in-wait gunmen pass the time in different ways. The position of the hands and the rifle held by one of them changes noticeably between a shot and its corresponding reverse angle.","es":"Durante la espera en la estación de tren de Cattle Corner, los tres pistoleros apostados pasan el tiempo de diversas maneras. La posición de las manos y del rifle que empuña uno de ellos cambia notablemente entre un plano y su respectivo plano contraplano.","fr":"Pendant l''attente à la gare de Cattle Corner, les trois hommes armés postés tuent le temps de différentes manières. La position des mains et du fusil épaulé par l''un d''eux change nettement entre un plan et le contrechamp respectif.","de":"Während des Wartens am Bahnhof von Cattle Corner vertreiben sich die drei auf die Lauer gelegten Revolverhelden auf verschiedene Weise die Zeit. Die Position der Hände und des von einem von ihnen gehaltenen Gewehrs ändert sich deutlich zwischen einer Einstellung und der jeweiligen Gegenschau."}'::jsonb WHERE id = 4897;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Jill McBain scende dal treno a Flagstone e cerca un mezzo per raggiungere Sweetwater, la valigia che trasporta cambia di mano e orientamento tra un primo piano e l''inquadratura a figura intera.","en":"When Jill McBain gets off the train at Flagstone and looks for a ride to Sweetwater, the suitcase she is carrying changes hands and orientation between a close-up and the full-length shot.","es":"Cuando Jill McBain baja del tren en Flagstone y busca un medio para llegar a Sweetwater, la maleta que lleva cambia de mano y de orientación entre un plano medio y el plano general.","fr":"Quand Jill McBain descend du train à Flagstone et cherche un moyen de rejoindre Sweetwater, la valise qu''elle transporte change de main et d''orientation entre un gros plan et le plan en pied.","de":"Als Jill McBain in Flagstone aus dem Zug steigt und nach einer Möglichkeit sucht, Sweetwater zu erreichen, wechseln die Hand, mit der sie den Koffer trägt, und dessen Ausrichtung zwischen einer Nahaufnahme und der Totalen."}'::jsonb WHERE id = 4898;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune scene ambientate nelle zone brulle del West e nei pressi dei cantieri ferroviari, si possono scorgere sullo sfondo tracce di strade sterrate moderne o solchi lasciati da pneumatici di autoveicoli contemporanei estranei al periodo storico.","en":"In some scenes set in the barren areas of the West and near the railroad construction sites, modern dirt road tracks or tire ruts left by contemporary motor vehicles out of place for the historical period can be spotted in the background.","es":"En algunas escenas ambientadas en las zonas áridas del Oeste y cerca de los campamentos ferroviarios, se pueden divisar en el fondo huellas de caminos de tierra modernos o surcos dejados por neumáticos de vehículos contemporáneos ajenos al período histórico.","fr":"Dans certaines scènes se déroulant dans les zones arides de l''Ouest et près des chantiers ferroviaires, on peut apercevoir en arrière-plan des traces de routes de terre modernes ou des orbites de pneus laissées par des véhicules contemporains étrangers à la période historique.","de":"In einigen Szenen, die in den kargen Gegenden des Westens und in der Nähe von Eisenbahnbaustellen spielen, sind im Hintergrund Spuren moderner Feldwege oder Reifenrillen zeitgenössischer Kraftfahrzeuge zu erkennen, die nicht in die historische Epoche passen."}'::jsonb WHERE id = 4899;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il confronto tra Cheyenne e i suoi uomini nel covo roccioso, gli oggetti sul tavolo (bottiglie, bicchieri e carte) cambiano disposizione e livello di riempimento tra i tagli di montaggio.","en":"During the confrontation between Cheyenne and his men in the rocky hideout, the objects on the table (bottles, glasses, and cards) change arrangement and fill level between editing cuts.","es":"Durante el enfrentamiento entre Cheyenne y sus hombres en el escondite rocoso, los objetos sobre la mesa (botellas, vasos y cartas) cambian de disposición y nivel de llenado entre los cortes de montaje.","fr":"Pendant la confrontation entre Cheyenne et ses hommes dans la cachette rocheuse, les objets sur la table (bouteilles, verres et cartes) changent de disposition et de niveau de remplissage entre les raccords de montage.","de":"Während der Konfrontation zwischen Cheyenne und seinen Männern im Felsenversteck verändern sich die Anordnung und der Füllstand der Gegenstände auf dem Tisch (Flaschen, Gläser und Karten) zwischen den Schnittwechseln."}'::jsonb WHERE id = 4900;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sequenza in cui Mickey accusa un malore negli spogliatoi prima del match contro Clubber Lang, la posizione del secchio e degli asciugamani sul tavolo cambia visivamente tra i vari cambi di inquadratura.","en":"During the sequence where Mickey falls ill in the locker room before the match against Clubber Lang, the position of the bucket and towels on the table visibly changes between the various camera setups.","es":"Durante la secuencia en la que Mickey sufre un malestar en los vestuarios antes del combate contra Clubber Lang, la posición del cubo y las toallas sobre la mesa cambia visiblemente entre los distintos cambios de plano.","fr":"Au cours de la séquence où Mickey est pris d''un malaise dans les vestiaires avant le match contre Clubber Lang, la position du seau et des serviettes sur la table change visuellement entre les différents plans.","de":"Während der Sequenz, in der Mickey in der Umkleidekabine vor dem Kampf gegen Clubber Lang einen Schwächeanfall erleidet, verändert sich die Position des Eimers und der Handtücher auf dem Tisch zwischen den verschiedenen Kameraeinstellungen deutlich."}'::jsonb WHERE id = 4901;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena dell''allenamento sulla spiaggia a Los Angeles, in un campo largo ripreso dall''alto è possibile intravedere brevemente l''ombra di un operatore di ripresa con la macchina da presa sulla sabbia vicino ad Apollo e Rocky.","en":"During the beach workout scene in Los Angeles, in a high-angle wide shot, the shadow of a camera operator with the camera can briefly be seen on the sand near Apollo and Rocky.","es":"Durante la escena del entrenamiento en la playa en Los Ángeles, en un plano general cenital se puede vislumbrar brevemente la sombra de un operador de cámara con la cámara en la arena cerca de Apollo y Rocky.","fr":"Pendant la scène d''entraînement sur la plage à Los Angeles, dans un plan large filmé en plongée, on peut entrevoir brièvement l''ombre d''un cadreur avec sa caméra sur le sable près d''Apollo et Rocky.","de":"Während der Strand-Trainingsszene in Los Angeles ist in einer von oben gefilmten Totalen kurz der Schatten eines Kameramanns mit der Kamera im Sand neben Apollo und Rocky zu sehen."}'::jsonb WHERE id = 4902;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conferenza stampa in cui Rocky e Clubber Lang si affrontano verbalmente prima del match decisivo, il bicchiere d''acqua davanti a Paulie scompare e riappare pieno tra un cambio di inquadratura e l''altro.","en":"During the press conference where Rocky and Clubber Lang verbally clash before the decisive match, the glass of water in front of Paulie disappears and reappears full between camera cuts.","es":"Durante la rueda de prensa en la que Rocky y Clubber Lang se enfrentan verbalmente antes del combate decisivo, el vaso de agua frente a Paulie desaparece y vuelve a aparecer lleno entre un plano y otro.","fr":"Pendant la conférence de presse où Rocky et Clubber Lang s''affrontent verbalement avant le match décisif, le verre d''eau devant Paulie disparaît et réapparaît plein entre les changements de plan.","de":"Während der Pressekonferenz, bei der sich Rocky und Clubber Lang vor dem entscheidenden Kampf verbal duellieren, verschwindet das Glas Wasser vor Paulie und taucht zwischen den Kameraeinstellungen wieder voll auf."}'::jsonb WHERE id = 4903;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso del round finale contro Clubber Lang, la cintura da campione e la disposizione dei secondi all''angolo cambiano posizione improvvisamente quando l''arbitro separa i due pugili.","en":"During the final round against Clubber Lang, the championship belt and the arrangement of the seconds in the corner suddenly change position when the referee separates the two fighters.","es":"Durante el asalto final contra Clubber Lang, el cinturón de campeón y la disposición de los segundos en la esquina cambian de posición repentinamente cuando el árbitro separa a los dos boxeadores.","fr":"Au cours du round final contre Clubber Lang, la ceinture de champion et la disposition des séconds dans le coin changent soudainement de position lorsque l''arbitre sépare les deux boxeurs.","de":"Während der finalen Runde gegen Clubber Lang wechseln der Meisterschaftsgürtel und die Positionierung der Sekundanten in der Ecke plötzlich ihre Plätze, als der Ringrichter die beiden Boxer trennt."}'::jsonb WHERE id = 4904;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la rissa finale tra Rocky e Tommy Gunn fuori dal bar, l''orologio al polso di Tommy scompare e riappare in diverse inquadrature ravvicinate prima di essere definitivamente danneggiato.","en":"During the final brawl between Rocky and Tommy Gunn outside the bar, the watch on Tommy''s wrist disappears and reappears across several close-ups before getting permanently damaged.","es":"Durante la pelea final entre Rocky y Tommy Gunn fuera del bar, el reloj en la muñeca de Tommy desaparece y vuelve a aparecer en varios primeros planos antes de ser dañado definitivamente.","fr":"Pendant la bagarre finale entre Rocky et Tommy Gunn à l''extérieur du bar, la montre au poignet de Tommy disparaît et réapparaît dans plusieurs gros plans avant d''être définitivement endommagée.","de":"Während der Schlussschlägerei zwischen Rocky und Tommy Gunn vor der Bar verschwindet und taucht Tomys Armbanduhr in mehreren Nahaufnahmen wieder auf, bevor sie endgültig beschädigt wird."}'::jsonb WHERE id = 4905;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Rocky parla con Paulie in cucina, la bottiglia di birra sul tavolo cambia livello di riempimento e posizione tra un cambio di inquadratura e l''altro senza che nessuno la tocchi.","en":"In the scene where Rocky talks to Paulie in the kitchen, the beer bottle on the table changes fill level and position between cuts without anyone touching it.","es":"En la escena en la que Rocky habla con Paulie en la cocina, la botella de cerveza en la mesa cambia de nivel de llenado y de posición entre plano y plano sin que nadie la toque.","fr":"Dans la scène où Rocky discute avec Paulie dans la cuisine, la bouteille de bière sur la table change de niveau de remplissage et de position d''un plan à l''autre sans que personne ne la touche.","de":"In der Szene, in der Rocky in der Küche mit Paulie spricht, verändert sich der Füllstand und die Position der Bierflasche auf dem Tisch zwischen den Einstellungen, ohne dass sie jemand berührt."}'::jsonb WHERE id = 4906;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Rocky Jr. litiga con i bulli a scuola, i libri e il materiale scolastico che cadono a terra cambiano disposizione da un''inquadratura dall''alto a quella ad altezza uomo.","en":"When Rocky Jr. fights with the bullies at school, the books and school supplies falling to the ground change arrangement between a high-angle shot and an eye-level shot.","es":"Cuando Rocky Jr. se pelea con los abusones en la escuela, los libros y el material escolar que caen al suelo cambian de disposición entre un plano cenital y uno a la altura de los ojos.","fr":"Quand Rocky Jr. se dispute avec les brutes à l''école, les livres et les fournitures scolaires qui tombent par terre changent de disposition entre un plan plongeant et un plan à hauteur d''homme.","de":"Als sich Rocky Jr. in der Schule mit den Schulhofschlägern streitet, verändert sich die Anordnung der Bücher und Schulsachen, die zu Boden fallen, zwischen einer Aufsicht und einer Einstellung auf Augenhöhe."}'::jsonb WHERE id = 4907;
UPDATE errori SET descrizione_i18n = '{"it":"Nel finale della rissa di strada, quando Tommy Gunn viene atterrato da Rocky, la pozzanghera d''acqua sotto la sua testa varia visibilmente di forma e dimensioni a seconda dell''angolazione della telecamera.","en":"In the street fight finale, when Tommy Gunn is knocked down by Rocky, the puddle of water beneath his head noticeably changes shape and size depending on the camera angle.","es":"En el final de la pelea callejera, cuando Rocky derriba a Tommy Gunn, el charco de agua bajo su cabeza cambia visiblemente de forma y tamaño según el ángulo de la cámara.","fr":"Dans le final de la bagarre de rue, lorsque Tommy Gunn est mis à terre par Rocky, la flaque d''eau sous sa tête varie visiblement de forme et de taille selon l''angle de la caméra.","de":"Im Finale des Straßenkampfs, als Tommy Gunn von Rocky zu Fall gebracht wird, verändert die Wasserpfütze unter seinem Kopf je nach Kamerawinkel sichtbar ihre Form und Größe."}'::jsonb WHERE id = 4908;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena del caffè a Parigi, la sigaretta tra le dita di Robert De Niro cambia visibilmente di lunghezza e stato di consumo da un''inquadratura all''altra nel montaggio alternato.","en":"During the coffee shop scene in Paris, the cigarette between Robert De Niro''s fingers visibly changes in length and burn state from shot to shot during the cross-cutting.","es":"Durante la escena del café en París, el cigarrillo entre los dedos de Robert De Niro cambia visiblemente de longitud y estado de consumo de un plano a otro en el montaje paralelo.","fr":"Pendant la scène du café à Paris, la cigarette entre les doigts de Robert De Niro change visiblement de longueur et d''état de combustion d''un plan à l''autre dans le champ-contrechamp.","de":"Während der Kaffeeszene in Paris verändert sich die Zigarette zwischen Robert De Niros Fingern beim Schuss-Gegenschuss-Verfahren von Einstellung zu Einstellung sichtbar in Länge und Abbrand."}'::jsonb WHERE id = 4909;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sparatoria nel magazzino, i bossoli dei proiettili sparati dalle armi dei mercenari scompaiono e riappaiono sul pavimento a seconda che l''inquadratura sia larga o stretta sui personaggi.","en":"During the warehouse shootout, the bullet casings fired from the mercenaries'' weapons disappear and reappear on the floor depending on whether the shot is wide or close-up on the characters.","es":"Durante el tiroteo en el almacén, los casquillos de las balas disparadas por las armas de los mercenarios desaparecen y reaparecen en el suelo según si el plano es general o cerrado sobre los personajes.","fr":"Pendant la fusillade dans l''entrepôt, les douilles des balles tirées par les armes des mercenaires disparaissent et réapparaissent sur le sol selon que le plan est large ou serré sur les personnages.","de":"Während der Schießerei im Lagerhaus verschwinden und tauchen die Patronenhülsen aus den Waffen der Söldner je nach Totale oder naher Einstellung auf die Figuren auf dem Boden auf und ab."}'::jsonb WHERE id = 4910;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''inseguimento automobilistico a Nizza e Parigi, le BMW e le Peugeot cambiano ripetutamente versione e dettagli estetici (come i cerchioni e gli specchietti retrovisori) tra i piani sequenza reali e le scene girate con gli stunt.","en":"During the car chase in Nice and Paris, the BMWs and Peugeots repeatedly change version and aesthetic details (such as wheel rims and rearview mirrors) between the real tracking shots and the scenes shot with stunt drivers.","es":"Durante la persecución automovilística en Niza y París, los BMW y Peugeot cambian repetidamente de versión y detalles estéticos (como las llantas y los retrovisores) entre los planos secuencia reales y las escenas rodadas con especialistas.","fr":"Pendant la course-poursuite à Nice et à Paris, les BMW et les Peugeot changent à plusieurs reprises de version et de détails esthétiques (comme les jantes et les rétroviseurs) entre les plans-séquences réels et les scènes tournées avec des cascadeurs.","de":"Während der Autoverfolgungsjagd in Nizza und Paris wechseln die BMWs und Peugeots zwischen echten Plansequenzen und mit Stuntleuten gedrehten Szenen wiederholt ihre Version und ästhetische Details (wie Felgen und Rückspiegel)."}'::jsonb WHERE id = 4911;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza finale nei corridoi e all''esterno dell''anfiteatro Zénith, in un''inquadratura di passaggio grandangolare si intravede brevemente l''ombra di un operatore con asta del microfono proiettata sul muro laterale.","en":"In the final sequence in the corridors and outside the Zénith amphitheater, in a wide tracking shot the shadow of a crew member with a boom mic is briefly glimpsed projected onto the side wall.","es":"En la secuencia final en los pasillos y en el exterior del anfiteatro Zénith, en un plano general de transición se ve brevemente la sombra de un operador con pértiga de micrófono proyectada en la pared lateral.","fr":"Dans la séquence finale dans les couloirs et à l''extérieur de l''amphithéâtre Zénith, dans un plan large de transition, on aperçoit brièvement l''ombre d''un perchiste avec sa perche micro projetée sur le mur latéral.","de":"In der Schlussszene in den Fluren und vor dem Amphitheater Zénith ist in einer weiten Kamerafahrt kurz der Schatten eines Tontechnikers mit einer Tonangel an der Seitenwand zu sehen."}'::jsonb WHERE id = 4912;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui il treno deraglia e attraversa le strade di Kyoto, la posizione del cappello e della sciarpa indossati da Ladybug variano visibilmente tra un''inquadratura e l''altra, passando dall''essere perfettamente sistemati a completamente bagnati e disordinati senza soluzione di continuità logica.","en":"During the sequence where the train derails and cuts through the streets of Kyoto, Ladybug''s hat and scarf noticeably change position from shot to shot, shifting from being neatly arranged to completely wet and messy with no logical continuity.","es":"Durante la secuencia en la que el tren descarrila y atraviesa las calles de Kioto, la posición del sombrero y la bufanda que lleva Ladybug varían visiblemente de un plano a otro, pasando de estar perfectamente colocados a completamente mojados y desordenados sin continuidad lógica.","fr":"Pendant la séquence où le train déraille et traverse les rues de Kyoto, la position du chapeau et de l''écharpe portés par Ladybug changent visiblement d''un plan à l''autre, passant d''un arrangement parfait à complètement mouillés et en désordre sans continuité logique.","de":"Während der Sequenz, in der der Zug entgleist und durch die Straßen von Kyōto fährt, verändern sich Hut und Schal von Ladybug von Einstellung zu Einstellung sichtbar; sie wechseln ohne logische Kontinuität von perfekt sitzend zu völlig nass und unordentlich."}'::jsonb WHERE id = 4913;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Lemon e Tangerine discutono nei corridoi dello Shinkansen, in un riflesso sul finestrino laterale è possibile scorgere brevemente la sagoma di un operatore della troupe con una telecamera di supporto.","en":"In the scene where Lemon and Tangerine argue in the Shinkansen corridors, a crew member''s silhouette operating a camera rig can be briefly spotted in the reflection of the side window.","es":"En la escena en la que Lemon y Tangerine discuten en los pasillos del Shinkansen, en un reflejo de la ventanilla lateral se puede distinguir brevemente la silueta de un miembro del equipo de rodaje con una cámara en soporte.","fr":"Dans la scène où Lemon et Tangerine se disputent dans les couloirs du Shinkansen, la silhouette d''un technicien de l''équipe manipulant une caméra stabilisée est brièvement visible dans le reflet de la vitre latérale.","de":"In der Szene, in der sich Lemon und Tangerine in den Gängen des Shinkansen streiten, ist in der Spiegelung des Seitenfensters kurz die Silhouette eines Crewmitglieds mit einem Kamera-Rig zu erkennen."}'::jsonb WHERE id = 4914;
UPDATE errori SET descrizione_i18n = '{"it":"Nel film ambientato nel 1921, in alcune inquadrature esterne delle strade di New York compaiono modelli di automobili con targhe e dettagli di immatricolazione appartenenti a un''epoca successiva.","en":"In the film set in 1921, several exterior shots of New York streets feature car models with license plates and registration details from a later era.","es":"En la película ambientada en 1921, en algunos planos exteriores de las calles de Nueva York aparecen modelos de automóviles con matrículas y detalles de matriculación de una época posterior.","fr":"Dans le film se déroulant en 1921, plusieurs plans extérieurs des rues de New York montrent des modèles de voitures dotés de plaques d''immatriculation et de détails d''une époque ultérieure.","de":"In dem im Jahr 1921 spielenden Film sind in einigen Außenaufnahmen der Straßen von New York Automodelle mit Kennzeichen und Zulassungsdetails aus einer späteren Ära zu sehen."}'::jsonb WHERE id = 4915;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la riunione del consiglio comunale in cui Brody discute sulla chiusura delle spiagge, i bicchieri e i fogli di carta sui tavoli cambiano posizione e quantità tra un''inquadratura e l''altra.","en":"During the town council meeting where Brody argues for closing the beaches, the glasses and papers on the tables change position and quantity from shot to shot.","es":"Durante la reunión del consejo municipal en la que Brody debate sobre el cierre de las playas, los vasos y los papeles de las mesas cambian de posición y cantidad de un plano a otro.","fr":"Pendant la réunion du conseil municipal où Brody plaide pour la fermeture des plages, les verres et les feuilles de papier sur les tables changent de position et de quantité d''un plan à l''autre.","de":"Während der Gemeinderatssitzung, in der Brody über die Schließung der Strände diskutiert, verändern sich Gläser und Papiere auf den Tischen von Einstellung zu Einstellung in Position und Anzahl."}'::jsonb WHERE id = 4916;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui la folla si precipita in acqua dopo il falso allarme dello squalo con la pinna finta, la bottiglia di birra tenuta da uno dei ragazzi sulla spiaggia sparisce e riappare magicamente tra le mani.","en":"When the crowd rushes into the water after the false alarm involving the fake shark fin, the beer bottle held by one of the guys on the beach magically disappears and reappears in his hands.","es":"En el momento en que la multitud se precipita al agua tras la falsa alarma del tiburón con la aleta falsa, la botella de cerveza que sostiene uno de los chicos en la playa desaparece y reaparece mágicamente en sus manos.","fr":"Au moment où la foule se précipite dans l''eau après la fausse alerte de la fausse nageoire de requin, la bouteille de bière tenue par l''un des jeunes sur la plage disparaît et réapparaît magiquement dans ses mains.","de":"In dem Moment, in dem die Menge nach dem Fehlalarm mit der falschen Haifischflosse ins Wasser stürzt, verschwindet die Bierflasche, die einer der Jungs am Strand hält, und taucht wie von Zauberhand wieder in seinen Händen auf."}'::jsonb WHERE id = 4917;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Brody, Hooper e Quint stanno bevendo e mostrando le cicatrici a bordo dell''Orca, la bottiglia di birra di Hooper cambia livello di liquido all''interno e posizione sul tavolo da un''inquadratura all''altra.","en":"While Brody, Hooper, and Quint are drinking and comparing scars aboard the Orca, Hooper''s beer bottle changes liquid level and position on the table from shot to shot.","es":"Mientras Brody, Hooper y Quint beben y muestran sus cicatrices a bordo del Orca, la botella de cerveza de Hooper cambia de nivel de líquido y de posición en la mesa de un plano a otro.","fr":"Alors que Brody, Hooper et Quint boivent et comparent leurs cicatrices à bord de l''Orca, la bouteille de bière de Hooper change de niveau de liquide et de position sur la table d''un plan à l''autre.","de":"Während Brody, Hooper und Quint an Bord der Orca trinken und ihre Narben vergleichen, verändern sich bei Hoopers Bierflasche der Füllstand des Flüssigen und ihre Position auf dem Tisch von Einstellung zu Einstellung."}'::jsonb WHERE id = 4918;
UPDATE errori SET descrizione_i18n = '{"it":"Quint racconta l''affondamento della USS Indianapolis avvenuto nel luglio del 1945, ma menziona l''orario dell''attacco alle 12:15, mentre storicamente la nave fu silurata e colpita intorno alla mezzanotte.","en":"Quint recounts the sinking of the USS Indianapolis in July 1945, but mentions the time of the attack as 12:15, whereas historically the ship was torpedoed and struck around midnight.","es":"Quint relata el hundimiento del USS Indianapolis ocurrido en julio de 1945, pero menciona la hora del ataque a las 12:15, mientras que históricamente el buque fue torpedeado y alcanzado alrededor de la medianoche.","fr":"Quint raconte le naufrage de l''USS Indianapolis survenu en juillet 1945, mais situe l''heure de l''attaque à 12 h 15, alors qu''historiquement le navire a été torpillé et touché vers minuit.","de":"Quint erzählt von der Versenkung der USS Indianapolis im Juli 1945, nennt aber als Angriffszeit 12:15 Uhr, während das Schiff historisch gesehen gegen Mitternacht torpediert und getroffen wurde."}'::jsonb WHERE id = 4919;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle riprese in mare aperto in cui l''Orca naviga e i personaggi parlano sul ponte, si intravede brevemente l''ombra di un microfono a boom oscillare sulla spalla di Roy Scheider.","en":"During one of the open-sea shoots where the Orca sails and the characters talk on deck, the shadow of a boom mic can be briefly glimpsed swaying across Roy Scheider''s shoulder.","es":"Durante uno de los rodajes en mar abierto en el que el Orca navega y los personajes hablan en cubierta, se vislumbra brevemente la sombra de un micrófono de pértiga oscilando sobre el hombro de Roy Scheider.","fr":"Pendant l''un des tournages en mer ouverte où l''Orca navigue et où les personnages discutent sur le pont, l''ombre d''un micro perche est brièvement aperçue en train de balancer sur l''épaule de Roy Scheider.","de":"Während einer der Aufnahmen auf offener See, bei denen die Orca segelt und sich die Figuren an Deck unterhalten, ist kurz der Schatten eines Galgenmikrofons zu sehen, das über Roy Scheiders Schulter schwingt."}'::jsonb WHERE id = 4920;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle sequenze finali in cui l''Orca sta affondando di poppa, gli interni della cabina mostrano l''acqua che sale rapidamente, ma nell''inquadratura successiva dall''esterno il livello dell''acqua attorno allo scafo appare notevolmente inferiore.","en":"In the final sequences where the Orca is sinking stern-first, the cabin interiors show water rising rapidly, but in the subsequent external shot, the water level around the hull appears noticeably lower.","es":"En las secuencias finales en las que el Orca se hunde por la popa, los interiores de la cabina muestran el agua subiendo rápidamente, pero en el plano exterior siguiente el nivel del agua alrededor del casco parece notablemente inferior.","fr":"Dans les séquences finales où l''Orca coule par la poupe, l''intérieur de la cabine montre l''eau monter rapidement, mais dans le plan extérieur suivant, le niveau de l''eau autour de la coque semble sensiblement plus bas.","de":"In den Schlussszenen, in denen die Orca mit dem Heck voran sinkt, zeigt das Schiffsinnere schnell steigendes Wasser, aber in der folgenden Außeneinstellung wirkt der Wasserstand um den Rumpf herum deutlich niedriger."}'::jsonb WHERE id = 4921;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il capo Brody è nel suo ufficio a parlare al telefono, i documenti sulla scrivania e la tazza da caffè cambiano visibilmente posizione tra un''inquadratura e l''altra nel montaggio alternato.","en":"During the scene where Chief Brody is in his office talking on the phone, the paperwork on the desk and the coffee mug visibly change position between cuts in the cross-cutting.","es":"Durante la escena en la que el jefe Brody está en su oficina hablando por teléfono, los papeles del escritorio y la taza de café cambian de posición de forma visible entre plano y plano en el montaje alterno.","fr":"Pendant la scène où le chef Brody est dans son bureau au téléphone, les documents sur le bureau et la tasse de café changent visiblement de position d''un plan à l''autre lors du montage alterné.","de":"Während der Szene, in der Chief Brody in seinem Büro telefoniert, wechseln die Papiere auf dem Schreibtisch und die Kaffeetasse im Schuss-Gegenschuss-Verfahren sichtlich ihre Position zwischen den Einstellungen."}'::jsonb WHERE id = 4922;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre i ragazzi sono sulle barche a vela prima dell''attacco, la bottiglia d''acqua tenuta da uno dei giovani velisti passa magicamente dalla mano destra alla sinistra e viceversa in base al cambio di inquadratura.","en":"While the kids are on the sailboats before the attack, the water bottle held by one of the young sailors magically switches from the right hand to the left and back again depending on the camera angle.","es":"Mientras los chicos están en los veleros antes del ataque, la botella de agua que sostiene uno de los jóvenes regatistas pasa mágicamente de la mano derecha a la izquierda y viceversa según el cambio de plano.","fr":"Alors que les jeunes sont sur les voiliers avant l''attaque, la bouteille d''eau tenue par l''un des jeunes navigateurs passe magiquement de la main droite à la gauche et inversement selon les raccords d''angle.","de":"Während die Jugendlichen vor dem Angriff auf den Segelbooten sind, wechselt die Wasserflasche eines jungen Seglers je nach Einstellung auf magische Weise von der rechten in die linke Hand und zurück."}'::jsonb WHERE id = 4923;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Brody sale a bordo della sua barca per mettersi alla ricerca dei ragazzi, la giacca che indossa mostra bagnature e gocce d''acqua che spariscono e riappaiono nei successivi primi piani.","en":"When Brody boards his boat to search for the kids, the jacket he is wearing shows wet patches and water droplets that disappear and reappear in subsequent close-ups.","es":"En el momento en que Brody sube a bordo de su barco para buscar a los chicos, la chaqueta que lleva puesta muestra manchas de humedad y gotas de agua que desaparecen y vuelven a aparecer en los siguientes primeros planos.","fr":"Au moment où Brody monte à bord de son bateau pour partir à la recherche des jeunes, sa veste présente des zones humides et des gouttes d''eau qui disparaissent et réapparaissent dans les gros plans suivants.","de":"Als Brody an Bord seines Bootes geht, um nach den Jugendlichen zu suchen, weist seine Jacke nass gewordene Stellen und Wassertropfen auf, die in den folgenden Nahaufnahmen verschwinden und wieder auftauchen."}'::jsonb WHERE id = 4924;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una conversazione tra Mike Brody e Kathryn Morgan nel parco, i bicchieri di bevande che tengono in mano cambiano livello di riempimento e posizione tra un''inquadratura e l''altra.","en":"During a conversation between Mike Brody and Kathryn Morgan in the park, the cups of drinks they are holding change fill levels and positions between cuts.","es":"Durante una conversación entre Mike Brody y Kathryn Morgan en el parque, los vasos de bebida que sostienen cambian de nivel de llenado y de posición de un plano a otro.","fr":"Pendant une conversation entre Mike Brody et Kathryn Morgan dans le parc, les gobelets de boissons qu''ils tiennent changent de niveau de remplissage et de position d''un plan à l''autre.","de":"Während eines Gesprächs zwischen Mike Brody und Kathryn Morgan im Park verändern die Getränkebecher, die sie in den Händen halten, zwischen den Einstellungen ihren Füllstand und ihre Position."}'::jsonb WHERE id = 4925;
UPDATE errori SET descrizione_i18n = '{"it":"Nel film viene mostrato l''uso di tecnologie 3D avanzate e subacquee per monitorare l''ambiente che non erano realisticamente disponibili o impiegabili in quel modo all''epoca in cui il film è stato distribuito (1983).","en":"The film depicts the use of advanced 3D and underwater technology to monitor the environment that were not realistically available or deployable in that manner at the time the film was released (1983).","es":"La película muestra el uso de tecnologías 3D avanzadas y submarinas para monitorizar el entorno que no estaban disponibles de forma realista ni se podían emplear de esa manera en la época en que se estrenó la película (1983).","fr":"Le film montre l''utilisation de technologies 3D avancées et sous-marines pour surveiller l''environnement, qui n''étaient pas réalistement disponibles ou exploitables de cette manière à l''époque de la sortie du film (1983).","de":"Der Film zeigt den Einsatz fortschrittlicher 3D- und Unterwassertechnologien zur Umweltüberwachung, die zu der Zeit, als der Film in die Kinos kam (1983), realistischerweise noch gar nicht in dieser Form verfügbar oder einsetzbar waren."}'::jsonb WHERE id = 4926;
UPDATE errori SET descrizione_i18n = '{"it":"Quando l''acqua comincia a invadere i tunnel subacquei del SeaWorld, la quantità di acqua visibile sul pavimento varia drasticamente tra le inquadrature larghe e i primi piani dei personaggi intrappolati.","en":"When water begins to flood SeaWorld''s underwater tunnels, the amount of water visible on the floor varies drastically between wide shots and close-ups of the trapped characters.","es":"Cuando el agua empieza a inundar los túneles submarinos de SeaWorld, la cantidad de agua visible en el suelo varía drásticamente entre los planos generales y los primeros planos de los personajes atrapados.","fr":"Quand l''eau commence à envahir les tunnels sous-marins de SeaWorld, la quantité d''eau visible sur le sol varie radicalement entre les plans larges et les gros plans des personnages piégés.","de":"Als Wasser beginnt, die Unterwassertunnels von SeaWorld zu überfluten, schwankt die Menge des auf dem Boden sichtbaren Wassers drastisch zwischen Totalen und Nahaufnahmen der eingesperrten Figuren."}'::jsonb WHERE id = 4927;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una sequenza all''aperto vicino alle vasche del SeaWorld, in un''inquadratura di profilo si intravede brevemente l''ombra di un microfono a boom proiettata sulla spalla di Dennis Quaid.","en":"During an outdoor sequence near the SeaWorld pools, in a profile shot the shadow of a boom mic is briefly glimpsed projected onto Dennis Quaid''s shoulder.","es":"Durante una secuencia al aire libre cerca de las piscinas de SeaWorld, en un plano de perfil se ve brevemente la sombra de un micrófono de pértiga proyectada sobre el hombro de Dennis Quaid.","fr":"Pendant une séquence en extérieur près des bassins de SeaWorld, dans un plan de profil, on aperçoit brièvement l''ombre d''une perche micro projetée sur l''épaule de Dennis Quaid.","de":"Während einer Außensequenz in der Nähe der SeaWorld-Beckens ist in einer Profileinstellung kurz der Schatten eines Galgenmikrofons (Boom-Mic) zu sehen, der auf Dennis Quaids Schulter fällt."}'::jsonb WHERE id = 4928;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sala di controllo, mentre i monitor mostrano l''avanzamento dello squalo, i fogli e i raccoglitori sulla scrivania di Kathryn cambiano posizione e orientamento in modo evidente tra un''inquadratura e la controinquadratura.","en":"In the control room, while the monitors show the shark''s progress, the papers and binders on Kathryn''s desk noticeably change position and orientation between a shot and the reverse shot.","es":"En la sala de control, mientras los monitores muestran el avance del tiburón, los papeles y archivadores del escritorio de Kathryn cambian notablemente de posición y orientación entre un plano y el contraplano.","fr":"Dans la salle de contrôle, alors que les moniteurs affichent la progression du requin, les documents et les classeurs sur le bureau de Kathryn changent visiblement de position et d''orientation entre un plan et le champ-contrechamp.","de":"Im Kontrollraum verändern die Papiere und Ordner auf Kathryns Schreibtisch, während die Monitore den Fortschritt des Hais zeigen, zwischen einer Einstellung und der Gegeneinstellung deutlich ihre Position und Ausrichtung."}'::jsonb WHERE id = 4929;
UPDATE errori SET descrizione_i18n = '{"it":"Viene mostrato l''uso di esplosivi subacquei per tentare di uccidere lo squalo all''interno dei tunnel; la detonazione ravvicinata dovrebbe causare gravi danni strutturali e lesioni fatali ai personaggi per pressione idrostatica, che invece rimangono illesi.","en":"Underwater explosives are used in an attempt to kill the shark inside the tunnels; the close-range detonation should cause severe structural damage and fatal injuries to the characters due to hydrostatic pressure, yet they remain unharmed.","es":"Se muestra el uso de explosivos submarinos para intentar matar al tiburón dentro de los túneles; la detonación a corta distancia debería causar graves daños estructurales y lesiones fatales a los personajes debido a la presión hidrostática, pero en su lugar resultan ilesos.","fr":"L''utilisation d''explosifs sous-marins est montrée pour tenter de tuer le requin à l''intérieur des tunnels ; la détonation à bout portant devrait causer de graves dommages structurels et des blessures fatales aux personnages en raison de la pression hydrostatique, mais ils s''en sortent indemnes.","de":"Es wird der Einsatz von Unterwassersprengstoff gezeigt, um den Hai in den Tunneln zu töten; die Nahdetonation müsste aufgrund des hydrostatischen Drucks schwere Strukturschäden und tödliche Verletzungen bei den Figuren verursachen, sie bleiben jedoch unverletzt."}'::jsonb WHERE id = 4930;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i personaggi rompono la vetrata per far defluire la pressione e l''acqua entra copiosa, nei fotogrammi successivi inquadrati dall''esterno il vetro appare inspiegabilmente intatto in alcune sezioni prima di frantumarsi di nuovo.","en":"When the characters break the glass pane to relieve pressure and water rushes in, in subsequent frames shot from the outside the glass inexplicably appears intact in certain sections before shattering again.","es":"Cuando los personajes rompen el panel de vidrio para aliviar la presión y el agua entra a raudales, en los fotogramas posteriores grabados desde el exterior el vidrio aparece inexplicablemente intacto en algunas secciones antes de volverse a romper.","fr":"Lorsque les personnages brisent la vitre pour évacuer la pression et que l''eau s''engouffre en abondance, dans les plans suivants filmés de l''extérieur, le verre apparaît inexplicablement intact dans certaines sections avant de voler de nouveau en éclats.","de":"Wenn die Figuren die Glasscheibe einschlagen, um den Druck abzulassen, und Wasser einströmt, wirkt das Glas in den darauffolgenden, von außen gefilmten Einstellungen in einigen Bereichen unerklärlicherweise intakt, bevor es erneut zersplittert."}'::jsonb WHERE id = 4931;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena nella fattoria di Perrier LaPadite, quando le SS entrano e bevono il latte, la quantità di latte rimasta nel bicchiere di Hans Landa cambia visibilmente tra un''inquadratura e l''altra mentre parla con il fattore.","en":"During the scene at Perrier LaPadite''s farm, when the SS enter and drink milk, the amount of milk left in Hans Landa''s glass visibly changes between shots while he talks to the farmer.","es":"Durante la escena en la granja de Perrier LaPadite, cuando las SS entran y beben leche, la cantidad de leche que queda en el vaso de Hans Landa cambia visiblemente de un plano a otro mientras habla con el granjero.","fr":"Pendant la scène de la ferme de Perrier LaPadite, lorsque les SS entrent et boivent du lait, la quantité de lait restant dans le verre d''Hans Landa change visiblement d''un plan à l''autre pendant qu''il discute avec le fermier.","de":"Während der Szene auf der Farm von Perrier LaPadite, als die SS das Haus betritt und Milch trinkt, verändert sich die Menge der verbleibenden Milch in Hans Landas Glas während des Gesprächs mit dem Farmer von Einstellung zu Einstellung sichtbar."}'::jsonb WHERE id = 4932;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena della taverna, viene usato un gioco di società basato sui biglietti con i nomi dei personaggi celebri; tuttavia, alcune delle battute e dei riferimenti culturali inseriti dai personaggi anticipano modi di dire o dinamiche non coerenti con il periodo del 1944.","en":"In the tavern scene, a parlor game is played using slips of paper with the names of famous characters; however, some of the lines and cultural references used by the characters anticipate idioms or dynamics inconsistent with the year 1944.","es":"En la escena de la taberna, se juega a un juego de salón basado en papeles con nombres de personajes famosos; sin embargo, algunos de los chistes y referencias culturales introducidos por los personajes anticipan modismos o dinámicas incoherentes con el período de 1944.","fr":"Dans la scène de la taverne, un jeu de société basé sur des cartons portant les noms de personnages célèbres est utilisé ; cependant, certaines répliques et références culturelles lancées par les personnages anticipent des expressions ou des dynamiques incohérentes avec l''époque de 1944.","de":"In der Tavernenszene wird ein Gesellschaftsspiel gespielt, das auf Zetteln mit Namen berühmcher Persönlichkeiten basiert; einige der von den Figuren verwendeten Zeilen und Kulturreferenzen nehmen jedoch Redewendungen oder Dynamiken vorweg, die nicht mit dem Jahr 1944 vereinbar sind."}'::jsonb WHERE id = 4933;
UPDATE errori SET descrizione_i18n = '{"it":"Nel film viene menzionato che la pellicola cinematografica infiammabile in nitrato di cellulosa brucia anche sott''acqua, un''enfatizzazione drammaturgica non del tutto corretta dal punto di vista chimico-fisico per quanto riguarda la combustione in assenza di ossigeno.","en":"The film mentions that flammable cellulose nitrate film stock burns even underwater, a dramatic exaggeration that is not entirely chemically and physically correct regarding combustion in the absence of oxygen.","es":"En la película se menciona que la película cinematográfica inflamable de nitrato de celulosa arde incluso bajo el agua, una exageración dramática que no es del todo correcta desde el punto de vista químico-físico en lo que respecta a la combustión en ausencia de oxígeno.","fr":"Il est mentionné dans le film que la pellicule cinématographique inflammable en nitrate de cellulose brûle même sous l''eau, une exagération dramatique qui n''est pas tout à fait correcte sur le plan physico-chimique en ce qui concerne la combustion en l''absence d''oxygène.","de":"Im Film wird erwähnt, dass brennbares Zellulosenitrat-Filmmaterial sogar unter Wasser brennt, eine dramatische Übertreibung, die hinsichtlich der Verbrennung ohne Sauerstoff chemisch-physikalisch nicht ganz korrekt ist."}'::jsonb WHERE id = 4934;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui il colonnello Hans Landa ispeziona la fattoria di Perrier LaPadite e fuma la sua caratteristica pipa di grandi dimensioni, la posizione e la quantità di fumo o il modo in cui tiene la pipa tra le dita variano vistosamente tra i primi piani e le inquadrature a figura intera durante il dialogo.","en":"In the scene where Colonel Hans Landa inspects Perrier LaPadite''s farm and smokes his signature large pipe, the position and amount of smoke, or the way he holds the pipe between his fingers, noticeably vary between close-ups and wide shots during the dialogue.","es":"En la escena en la que el coronel Hans Landa inspecciona la granja de Perrier LaPadite y fuma su característica pipa grande, la posición y la cantidad de humo, o la forma en que sostiene la pipa entre los dedos, varían notablemente entre los primeros planos y los planos generales durante el diálogo.","fr":"Dans la scène où le colonel Hans Landa inspecte la ferme de Perrier LaPadite et fume sa grande pipe caractéristique, la position et la quantité de fumée, ou la façon dont il tient sa pipe entre ses doigts, varient de manière flagrante entre les gros plans et les plans larges pendant le dialogue.","de":"In der Szene, in der Colonel Hans Landa Perrier LaPadites Farm inspiziert und seine charakteristische große Pfeife raucht, variieren die Position und die Menge des Rauchs sowie die Art und Weise, wie er die Pfeife zwischen den Fingern hält, während des Dialogs zwischen Nahaufnahmen und totalen Einstellungen deutlich."}'::jsonb WHERE id = 4935;
UPDATE errori SET descrizione_i18n = '{"it":"Nel campo di addestramento dei Bastardi, il tenente Aldo Raine brandisce un coltello Bowie e una pistola M1911. Sebbene la pistola fosse in uso, alcuni dettagli dell''equipaggiamento e delle fondine utilizzate da vari soldati americani in alcune inquadrature presentano specifiche varianti e modelli successivi agli anni ''40.","en":"At the Bastards'' training camp, Lieutenant Aldo Raine wields a Bowie knife and an M1911 pistol. Although the pistol was in use, certain details of the equipment and holsters worn by various American soldiers in some shots feature specific variants and models post-dating the 1940s.","es":"En el campamento de entrenamiento de los Bastardos, el teniente Aldo Raine empuña un cuchillo Bowie y una pistola M1911. Aunque la pistola estaba en uso, ciertos detalles del equipo y las cartucheras utilizadas por varios soldados estadounidenses en algunos planos presentan variantes específicas y modelos posteriores a la década de 1940.","fr":"Dans le camp d''entraînement des Bâtards, le lieutenant Aldo Raine brandit un couteau Bowie et un pistolet M1911. Bien que le pistolet fût en service, certains détails de l''équipement et des étuis de pistolet portés par divers soldats américains dans certains plans présentent des variantes spécifiques et des modèles postérieurs aux années 1940.","de":"Im Ausbildungslager der Bastards schwingt Lieutenant Aldo Raine ein Bowie-Messer und eine M1911-Pistole. Obwohl die Pistole im Einsatz war, weisen bestimmte Details der Ausrüstung und der Holster, die von verschiedenen US-Soldaten in einigen Einstellungen getragen werden, spezifische Varianten und Modelle auf, die aus der Zeit nach den 1940er Jahren stammen."}'::jsonb WHERE id = 4936;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il pranzo al ristorante francese tra Shosanna Dreyfus e il soldato tedesco Frederick Zoller, i bicchieri di vino e le posate sul tavolo si spostano leggermente di posizione tra un''inquadratura e l''altra, pur non essendoci stata alcuna interazione dei personaggi con essi.","en":"During the lunch at the French restaurant between Shosanna Dreyfus and German soldier Frederick Zoller, the wine glasses and cutlery on the table shift slightly in position between shots, even though the characters do not interact with them.","es":"Durante el almuerzo en el restaurante francés entre Shosanna Dreyfus y el soldado alemán Frederick Zoller, las copas de vino y los cubiertos de la mesa cambian ligeramente de posición entre plano y plano, a pesar de que los personajes no interactúan con ellos.","fr":"Pendant le déjeuner au restaurant français entre Shosanna Dreyfus et le soldat allemand Frederick Zoller, les verres à vin et les couverts sur la table changent légèrement de position d''un plan à l''autre, bien qu''aucun personnage n''interagisse avec eux.","de":"Während des Mittagessens im französischen Restaurant zwischen Shosanna Dreyfus und dem deutschen Soldaten Frederick Zoller verändern die Weingläser und das Besteck auf dem Tisch zwischen den Einstellungen leicht ihre Position, obwohl die Figuren sie nicht berühren."}'::jsonb WHERE id = 4937;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui i soldati britannici e tedeschi giocano a carte nella taverna, il mazzo di carte sul tavolo cambia posizione e orientamento tra i tagli di montaggio, passando da un mucchietto ordinato a carte sparse.","en":"In the sequence where British and German soldiers play cards in the tavern, the deck of cards on the table changes position and orientation between editing cuts, going from a neat stack to scattered cards.","es":"En la secuencia en la que los soldados británicos y alemanes juegan a las cartas en la taberna, la baraja de cartas de la mesa cambia de posición y orientación entre los cortes de montaje, pasando de un mazo ordenado a cartas dispersas.","fr":"Dans la séquence où des soldats britanniques et allemands jouent aux cartes dans la taverne, le jeu de cartes sur la table change de position et d''orientation entre les raccords de montage, passant d''une pile ordonnée à des cartes éparpillées.","de":"In der Sequenz, in der britische und deutsche Soldaten in der Taverne Karten spielen, verändern das Kartenspiel und seine Ausrichtung auf dem Tisch zwischen den Schnittwechseln ihre Position und gehen von einem ordentlichen Stapel zu verstreuten Karten über."}'::jsonb WHERE id = 4938;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Bridget von Hammersmark viene colpita alla gamba nella taverna, i fazzoletti e le bende usate per fermare il sangue cambiano improvvisamente posizione e consistenza quando la telecamera cambia angolazione.","en":"When Bridget von Hammersmark is shot in the leg at the tavern, the tissues and bandages used to stop the bleeding suddenly change position and texture when the camera angle cuts.","es":"En el momento en que Bridget von Hammersmark recibe un disparo en la pierna en la taberna, los pañuelos y vendajes utilizados para detener la sangre cambian repentinamente de posición y consistencia cuando cambia el ángulo de cámara.","fr":"Au moment où Bridget von Hammersmark est touchée à la jambe dans la taverne, les mouchoirs et bandages utilisés pour stopper le sang changent soudainement de position et de texture lors du changement d''angle de caméra.","de":"In dem Moment, in dem Bridget von Hammersmark in der Taverne ins Bein getroffen wird, verändern die Papiertücher und Verbände zum Stillen des Blutes plötzlich ihre Position und Beschaffenheit, wenn sich der Kamerawinkel ändert."}'::jsonb WHERE id = 4939;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza iniziale al diner, la tazza di caffè davanti a Joe Cabot (Lawrence Tierney) si sposta da sola più volte tra il tavolo e il piattino, cambiando posizione ad ogni cambio di inquadratura tra i vari attori seduti al tavolo.","en":"During the opening diner sequence, the coffee cup in front of Joe Cabot (Lawrence Tierney) moves on its own multiple times between the table and the saucer, changing position with every shot-reverse-shot among the actors seated at the table.","es":"Durante la secuencia inicial en el restaurante, la taza de café frente a Joe Cabot (Lawrence Tierney) se mueve sola varias veces entre la mesa y el platillo, cambiando de posición en cada plano y contraplano entre los actores sentados a la mesa.","fr":"Pendant la séquence d''ouverture au diner, la tasse de café devant Joe Cabot (Lawrence Tierney) se déplace toute seule à plusieurs reprises entre la table et la soucoupe, changeant de position à chaque champ-contrechamp entre les différents acteurs attablés.","de":"Während der Eröffnungssequenz im Diner bewegt sich die Kaffeetasse vor Joe Cabot (Lawrence Tierney) mehrfach wie von selbst zwischen Tisch und Untertasse hin und her und wechselt bei jedem Szenenwechsel zwischen den am Tisch sitzenden Darstellern ihre Position."}'::jsonb WHERE id = 4940;
UPDATE errori SET descrizione_i18n = '{"it":"Nel magazzino, quando Mr. White appoggia la sua borsa e la pistola sul tavolo prima dell''arrivo di Joe Cabot, la posizione del caricatore e degli oggetti cambia leggermente inquadratura dopo inquadratura senza che nessuno li tocchi.","en":"In the warehouse, when Mr. White places his bag and gun on the table before Joe Cabot arrives, the position of the magazine and objects shifts slightly from shot to shot without anyone touching them.","es":"En el almacén, cuando Mr. White coloca su bolsa y su pistola sobre la mesa antes de la llegada de Joe Cabot, la posición del cargador y de los objetos cambia ligeramente plano tras plano sin que nadie los toque.","fr":"Dans l''entrepôt, lorsque Mr. White pose son sac et son pistolet sur la table avant l''arrivée de Joe Cabot, la position du chargeur et des objets change légèrement d''un plan à l''autre sans que personne ne les touche.","de":"Im Lagerhaus, als Mr. White vor dem Eintreffen von Joe Cabot seine Tasche und seine Waffe auf den Tisch legt, verändert sich die Position des Magazins und der Gegenstände von Einstellung zu Einstellung leicht, ohne dass sie jemand berührt."}'::jsonb WHERE id = 4941;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i flashback della preparazione della rapina e delle prove dei travestimenti, i personaggi utilizzano alcuni modelli di walkie-talkie e attrezzature di comunicazione le cui specifiche e scocche presentano dettagli estetici non ancora esistenti all''epoca in cui il film è ambientato.","en":"During the flashbacks of the heist preparation and disguise tests, the characters use walkie-talkie models and communication equipment whose specs and chassis feature aesthetic details that did not yet exist when the film is set.","es":"Durante los flashbacks de la preparación del atraco y las pruebas de disfraces, los personajes utilizan modelos de walkie-talkie y equipos de comunicación cuyas especificaciones y carcasas presentan detalles estéticos que aún no existían en la época en que está ambientada la película.","fr":"Pendant les flashbacks de la préparation du braquage et des essayages de déguisements, les personnages utilisent des modèles de talkies-walkies et des équipements de communication dont les spécifications et les coques présentent des détails esthétiques qui n''existaient pas encore à l''époque où se déroule le film.","de":"Während der Rückblenden zur Vorbereitung des Überfalls und der Verkleidungsproben verwenden die Figuren Walkie-Talkie-Modelle und Kommunikationsgeräte, deren Spezifikationen und Gehäuse ästhetische Details aufweisen, die zu der Zeit, in der der Film spielt, noch gar nicht existierten."}'::jsonb WHERE id = 4942;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Mr. Pink si nasconde nel bagno del magazzino e controlla la sua pistola, il cane della pistola (hammer) si sposta ripetutamente dalla posizione armata a quella disarmata nei vari stacchi di montaggio ravvicinati.","en":"When Mr. Pink hides in the warehouse bathroom and checks his gun, the hammer of the gun repeatedly shifts between cocked and uncocked positions across various close-up editing cuts.","es":"Cuando Mr. Pink se esconde en el baño del almacén y revisa su pistola, el martillo del arma cambia repetidamente de la posición armada a la desarmada en los distintos cortes de montaje en primer plano.","fr":"Quand Mr. Pink se cache dans les toilettes de l''entrepôt et vérifie son pistolet, le marteau (chien) de l''arme passe à plusieurs reprises de la position armée à la position désarmée lors des différents raccords de montage serrés.","de":"Als Mr. Pink sich auf der Toilette des Lagerhauses versteckt und seine Pistole überprüft, wechselt der Hahn der Waffe in den verschiedenen nahen Montage-Schnitten wiederholt zwischen gespannter und ungespannter Position."}'::jsonb WHERE id = 4943;
UPDATE errori SET descrizione_i18n = '{"it":"Nel laboratorio di Tyrell, quando Deckard testa Rachael con il test Voight-Kampff, la sigaretta tra le dita di Rachael cambia visibilmente la lunghezza della cenere e la posizione tra un cambio d''inquadratura e l''altro.","en":"In Tyrell''s lab, when Deckard tests Rachael with the Voight-Kampff test, the cigarette between Rachael''s fingers visibly changes ash length and position between camera cuts.","es":"En el laboratorio de Tyrell, cuando Deckard somete a Rachael a la prueba Voight-Kampff, el cigarrillo entre los dedos de Rachael cambia visiblemente de longitud de ceniza y de posición entre un cambio de plano y otro.","fr":"Dans le laboratoire de Tyrell, lorsque Deckard fait passer le test Voight-Kampff à Rachael, la cigarette entre les doigts de Rachael change visiblement de longueur de cendre et de position d''un plan à l''autre.","de":"In Tyrells Labor, als Deckard Rachael dem Voight-Kampff-Test unterzieht, verändert die Zigarette zwischen Rachaels Fingern zwischen den Kameraschnitten sichtbar die Aschelänge und ihre Position."}'::jsonb WHERE id = 4944;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Deckard esamina la foto di Leon usando il macchinario ESPER nel suo appartamento, l''angolazione della tastiera e il modo in cui poggia le mani sui comandi variano notevolmente tra i primi piani e i campi medi.","en":"When Deckard examines Leon''s photo using the ESPER machine in his apartment, the keyboard angle and the placement of his hands on the controls vary noticeably between close-ups and medium shots.","es":"Cuando Deckard examina la foto de Leon usando la máquina ESPER en su apartamento, el ángulo del teclado y la forma en que coloca las manos en los controles varían notablemente entre los primeros planos y los planos medios.","fr":"Lorsque Deckard examine la photo de Leon à l''aide de la machine ESPER dans son appartement, l''angle du clavier et la position de ses mains sur les commandes changent sensiblement entre les gros plans et les plans moyens.","de":"Als Deckard Leons Foto mit der ESPER-Maschine in seiner Wohnung untersucht, variieren der Tastaturwinkel und die Handhaltung auf den Bedienelementen zwischen den Nahaufnahmen und Halbtotale deutlich."}'::jsonb WHERE id = 4945;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Deckard cammina per strada sotto la pioggia dopo aver visitato il negozio di serpenti di Taffey Lewis, in un breve riflesso sulle vetrine laterali è possibile intravedere brevemente l''ombra di un operatore di macchina con l''attrezzatura.","en":"In the scene where Deckard walks down the rainy street after visiting Taffey Lewis''s snake shop, a camera operator and their equipment''s shadow can be briefly glimpsed in a reflection on the side store windows.","es":"En la escena en la que Deckard camina por la calle bajo la lluvia tras visitar la tienda de serpientes de Taffey Lewis, se puede vislumbrar brevemente la sombra de un operador de cámara con su equipo en un reflejo de los escaparates laterales.","fr":"Dans la scène où Deckard marche sous la pluie après avoir visité la boutique de serpents de Taffey Lewis, on peut apercevoir brièvement l''ombre d''un cadreur et de son matériel dans le reflet des vitrines latérales.","de":"In der Szene, in der Deckard nach dem Besuch von Taffey Lewis'' Schlangengeschäft durch den Regen auf der Straße geht, ist in einer kurzen Spiegelung an den seitlichen Schaufenstern kurz der Schatten eines Kameramanns mit Ausrüstung zu sehen."}'::jsonb WHERE id = 4946;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Zhora viene inseguita da Deckard e frantuma i manichini nelle vetrine, i pezzi di vetro e i frammenti dei manichini a terra cambiano disposizione nei tagli successivi della scena.","en":"During the sequence where Zhora is chased by Deckard and smashes through store mannequins, the glass shards and mannequin fragments on the ground change arrangement across subsequent cuts in the scene.","es":"Durante la secuencia en la que Zhora es perseguida por Deckard y destroza los maniquíes de los escaparates, los trozos de vidrio y los fragmentos de los maniquíes en el suelo cambian de disposición en los sucesivos cortes de la escena.","fr":"Pendant la séquence où Zhora est poursuivie par Deckard et brise les mannequins des vitrines, la disposition des éclats de verre et des morceaux de mannequins au sol change d''un raccord à l''autre dans la scène.","de":"Während der Sequenz, in der Zhora von Deckard verfolgt wird und Schaufensterpuppen zertrümmert, verändern die Glasscherben und Puppenfragmente auf dem Boden zwischen den verschiedenen Schnitten der Szene ihre Anordnung."}'::jsonb WHERE id = 4947;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Sebastian e Roy Batty entrano nell''appartamento, i giocattoli meccanici sul tavolo cambiano posizione e alcuni di essi risultano accesi o spenti in modo incoerente tra le inquadrature.","en":"When Sebastian and Roy Batty enter the apartment, the mechanical toys on the table change position, and some of them appear turned on or off inconsistently between shots.","es":"En el momento en que Sebastian y Roy Batty entran en el apartamento, los juguetes mecánicos de la mesa cambian de posición y algunos de ellos aparecen encendidos o apagados de forma incoherente entre plano y plano.","fr":"Au moment où Sebastian et Roy Batty entrent dans l''appartement, les jouets mécaniques sur la table changent de position et certains d''entre eux s''allument ou s''éteignent de manière incohérente d''un plan à l''autre.","de":"In dem Moment, als Sebastian und Roy Batty das Apartment betreten, wechseln die mechanischen Spielzeuge auf dem Tisch ihre Position, und einige von ihnen sind zwischen den Einstellungen inkonsistent ein- oder ausgeschaltet."}'::jsonb WHERE id = 4948;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il combattimento finale tra Deckard e Roy Batty sui tetti, l''acqua che scorre copiosa sui capelli e sugli abiti di Harrison Ford varia drasticamente da inzuppati a quasi asciutti a seconda dell''inquadratura.","en":"During the final rooftop fight between Deckard and Roy Batty, the water pouring over Harrison Ford''s hair and clothes cuts drastically from soaking wet to nearly dry depending on the shot.","es":"Durante el combate final en los tejados entre Deckard y Roy Batty, el agua que cae copiosamente sobre el pelo y la ropa de Harrison Ford varía drásticamente de empapado a casi seco según el plano.","fr":"Pendant le combat final sur les toits entre Deckard et Roy Batty, l''eau qui coule abondamment sur les cheveux et les vêtements d''Harrison Ford varie radicalement d''une trempette à presque sec selon le plan.","de":"Während des finalen Dachkampfs zwischen Deckard und Roy Batty wechselt das Wasser, das in Strömen über Harrison Fords Haare und Kleidung läuft, je nach Einstellung drastisch von durchnässt zu fast trocken."}'::jsonb WHERE id = 4949;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Mick taglia un pezzo di carne con il suo coltello Bowie attorno al fuoco nell''outback, il pezzo di carne sul tagliere cambia forma e dimensione tra il campo medio e il primo piano.","en":"When Mick cuts a piece of meat with his Bowie knife by the campfire in the outback, the piece of meat on the cutting board changes shape and size between the medium shot and the close-up.","es":"Cuando Mick corta un trozo de carne con su cuchillo Bowie junto al fuego en el outback, el trozo de carne en la tabla de cortar cambia de forma y tamaño entre el plano medio y el primer plano.","fr":"Quand Mick coupe un morceau de viande avec son couteau Bowie près du feu dans l''outback, le morceau de viande sur la planche à découper change de forme et de taille entre le plan moyen et le gros plan.","de":"Als Mick am Lagerfeuer im Outback ein Stück Fleisch mit seinem Bowie-Messer schneidet, verändert das Fleischstück auf dem Schneidebrett zwischen der Halbtotale und der Nahaufnahme Form und Größe."}'::jsonb WHERE id = 4950;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Mick entra per la prima volta nella lussuosa camera d''albergo di New York, appoggia il suo grande cappello di pelle di coccodrillo sul tavolino. Nell''inquadratura successiva da un''altra angolazione, il cappello si trova in una posizione completamente diversa senza che nessuno lo abbia toccato.","en":"In the scene where Mick first enters the luxurious New York hotel room, he places his large crocodile-skin hat on the coffee table. In the next shot from a different angle, the hat is in a completely different position without anyone touching it.","es":"En la escena en la que Mick entra por primera vez en la lujosa habitación de hotel en Nueva York, deja su gran sombrero de piel de cocodrilo en la mesita. En el plano siguiente desde otro ángulo, el sombrero está en una posición completamente distinta sin que nadie lo haya tocado.","fr":"Dans la scène où Mick entre pour la première fois dans la luxueuse chambre d''hôtel à New York, il pose son grand chapeau en peau de crocodile sur la table basse. Sur le plan suivant sous un autre angle, le chapeau se trouve dans une position complètement différente sans que personne ne l''ait touché.","de":"In der Szene, in der Mick zum ersten Mal das luxuriöse New Yorker Hotelzimmer betritt, legt er seinen großen Krokodillederhut auf den Beistelltisch. In der nächsten Einstellung aus einem anderen Winkel liegt der Hut an einer völlig anderen Position, ohne dass ihn jemand berührt hat."}'::jsonb WHERE id = 4951;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Mick e Sue passeggiano nel parco di New York e Mick si avvicina a un albero, si intravede l''ombra di un microfono boom.","en":"During the sequence where Mick and Sue stroll through the New York park and Mick approaches a tree, the shadow of a boom mic is briefly visible.","es":"Durante la secuencia en la que Mick y Sue pasean por el parque de Nueva York y Mick se acerca a un árbol, se vislumbra brevemente la sombra de un micrófono de pértiga.","fr":"Pendant la séquence où Mick et Sue se promènent dans le parc de New York et où Mick s''approche d''un arbre, l''ombre d''un micro perche est brièvement visible.","de":"Während der Sequenz, in der Mick und Sue durch den New Yorker Park spazieren und Mick sich einem Baum nähert, ist kurz der Schatten eines Boom-Mikrofons zu sehen."}'::jsonb WHERE id = 4952;
UPDATE errori SET descrizione_i18n = '{"it":"Nel ristorante elegante dove Mick mangia una pietanza usando le mani e sgranocchiando il cibo, i tovaglioli e le posate accanto al suo piatto cambiano disposizione e numero di pezzi visibili tra i vari cambi di inquadratura.","en":"In the upscale restaurant where Mick eats a dish with his hands and munches on the food, the napkins and cutlery next to his plate change arrangement and piece count across various cuts.","es":"En el restaurante elegante donde Mick come un plato usando las manos y mordisqueando la comida, las servilletas y los cubiertos junto a su plato cambian de disposición y número de piezas entre los diferentes raccordes de plano.","fr":"Dans le restaurant chic où Mick mange un plat avec ses mains et grignote la nourriture, les serviettes et les couverts à côté de leur assiette changent de disposition et de nombre de pièces entre les différents raccords de plan.","de":"In dem eleganten Restaurant, in dem Mick ein Gericht mit den Händen isst und an dem Essen knabbert, verändern Servietten und Besteck neben seinem Teller zwischen den Anschlüssen und Schnitten ihre Anordnung und Stückzahl."}'::jsonb WHERE id = 4953;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il combattimento ravvicinato e concitato contro l''Acheron, la posizione della spada di un ufficiale britannico cambia bruscamente da una mano all''altra tra un''inquadratura e la successiva.","en":"During the close-quarters and frantic combat against the Acheron, a British officer''s sword position abruptly switches from one hand to the other between cuts.","es":"Durante el combate cuerpo a cuerpo y frenético contra el Acheron, la posición de la espada de un oficial británico cambia bruscamente de una mano a otra entre plano y contraplano.","fr":"Pendant le combat rapproché et frénétique contre l''Acheron, la position de l''épée d''un officier britannique change brusquement d''une main à l''autre d''un plan à l''autre.","de":"Während des hektischen Nahkampfs gegen die Acheron wechselt die Position des Schwerts eines britischen Offiziers zwischen den Einstellungen abrupt von einer Hand in die andere."}'::jsonb WHERE id = 4954;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune inquadrature ravvicinate degli strumenti di navigazione e dei compassi utilizzati a bordo della HMS Surprise, si notano finiture e leghe metalliche di precisione tipiche di lavorazioni industriali molto successive al 1805.","en":"In some close-up shots of the navigation tools and compasses used aboard the HMS Surprise, you can spot precision finishes and metal alloys typical of industrial manufacturing much later than 1805.","es":"En algunos primeros planos de los instrumentos de navegación y compases utilizados a bordo del HMS Surprise, se aprecian acabados y aleaciones metálicas de precisión típicos de fabricaciones industriales muy posteriores a 1805.","fr":"Dans quelques gros plans des instruments de navigation et des compas utilisés à bord du HMS Surprise, on remarque des finitions et des alliages métalliques de précision typiques de fabrications industrielles bien postérieures à 1805.","de":"In einigen Nahaufnahmen der Navigationsinstrumente und Kompasse an Bord der HMS Surprise sind Präzisionsveredelungen und Metalllegierungen zu erkennen, die typisch für industrielle Fertigungsmethoden sind, welche weit nach 1805 entstanden."}'::jsonb WHERE id = 4955;
UPDATE errori SET descrizione_i18n = '{"it":"La velocità con cui la HMS Surprise riesce a doppiare Capo Horn e a compire determinate manovre di raddrizzamento dell''alberatura è altamente idealizzata rispetto alle reali capacità e ai tempi tecnici delle fregate dell''epoca napoleonica.","en":"The speed at which the HMS Surprise manages to round Cape Horn and perform certain rigging righting maneuvers is highly idealized compared to the actual capabilities and technical turnaround times of Napoleonic-era frigates.","es":"La velocidad con la que el HMS Surprise logra doblar el Cabo de Hornos y realizar ciertas maniobras de enderezamiento de la arboladura está muy idealizada en comparación con las capacidades reales y los tiempos técnicos de las fragatas de la época napoleónica.","fr":"La vitesse à laquelle le HMS Surprise parvient à doubler le cap Horn et à exécuter certaines manœuvres de redressement de la mâture est hautement idéalisée par rapport aux capacités réelles et aux temps techniques des frégates de l''époque napoléonienne.","de":"Die Geschwindigkeit, mit der die HMS Surprise das Kap Hoorn umsegelt und bestimmte Manöver zur Aufrichtung der Takelage ausführt, ist im Vergleich zu den tatsächlichen Fähigkeiten und technischen Zeitrahmen von Fregatten der napoleonischen Ära stark idealisiert."}'::jsonb WHERE id = 4956;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le sequenze notturne sul ponte della nave illuminato dalle lanterne, in un angolo dello schermo si intravede per un breve istante il riflesso dell''attrezzatura di illuminazione della troupe sui vetri delle finestre della cabina.","en":"During the night sequences on the lantern-lit ship deck, the reflection of the crew''s lighting equipment is briefly glimpsed in the corner of the screen on the cabin window glass.","es":"Durante las secuencias nocturnas en la cubierta del barco iluminada por linternas, en una esquina de la pantalla se ve brevemente el reflejo del equipo de iluminación del equipo técnico en los cristales de las ventanas de la cabina.","fr":"Pendant les séquences nocturnes sur le pont du navire éclairé par des lanternes, on aperçoit brièvement dans un coin de l''écran le reflet du matériel d''éclairage de l''équipe technique sur les vitres de la cabine.","de":"Während der nächtlichen Sequenzen auf dem laternenbeleuchteten Schiffdeck ist in einer Ecke des Bildschirms kurz die Reflexion der Beleuchtungsausrüstung der Crew auf den Fensterscheiben der Kabine zu sehen."}'::jsonb WHERE id = 4957;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la riunione dei Fremen nella caverna, la ciotola d''acqua tenuta tra le mani da Stilgar cambia posizione e livello di riempimento tra un''inquadratura e l''altra.","en":"During the Fremen cave meeting, the bowl of water held in Stilgar''s hands changes position and fill level between shots.","es":"Durante la reunión de los Fremen en la cueva, el bol de agua que Stilgar sostiene entre las manos cambia de posición y de nivel de llenado entre plano y plano.","fr":"Pendant la réunion des Fremen dans la caverne, le bol d''eau tenu entre les mains de Stilgar change de position et de niveau de remplissage d''un plan à l''autre.","de":"Während des Treffens der Fremen in der Höhle verändert sich die Position und der Füllstand der Wasserschüssel in Stilgars Händen zwischen den Einstellungen."}'::jsonb WHERE id = 4958;
UPDATE errori SET descrizione_i18n = '{"it":"Nella tenda di Paul, la disposizione dei piccoli oggetti e delle mappe di proiezione olografica sul tavolo varia notevolmente tra il primo piano di Paul e l''inquadratura larga.","en":"In Paul''s tent, the arrangement of small objects and holographic projection maps on the table varies noticeably between Paul''s close-up and the wide shot.","es":"En la tienda de Paul, la disposición de los objetos pequeños y de los mapas de proyección holográfica sobre la mesa varía notablemente entre el primer plano de Paul y el plano general.","fr":"Dans la tente de Paul, la disposition des petits objets et des cartes de projection holographique sur la table varie sensiblement entre le gros plan de Paul et le plan large.","de":"In Pauls Zelt variiert die Anordnung kleiner Gegenstände und holografischer Projektionskarten auf dem Tisch deutlich zwischen Pauls Nahaufnahme und der Totalen."}'::jsonb WHERE id = 4959;
UPDATE errori SET descrizione_i18n = '{"it":"In un''inquadratura grandangolare nel deserto profondo, sul bordo inferiore dello schermo è possibile intravedere brevemente l''ombra di un braccio del microfono boom sulla sabbia.","en":"In a wide shot in the deep desert, the shadow of a boom mic pole can be briefly glimpsed on the sand at the bottom edge of the screen.","es":"En un plano general en el desierto profundo, en el borde inferior de la pantalla se puede atisbar brevemente la sombra de una pértiga de micrófono boom sobre la arena.","fr":"Dans un plan large dans le désert profond, on peut apercevoir brièvement l''ombre d''une perche de micro boom sur le sable au bord inférieur de l''écran.","de":"In einer Weitwinkelaufnahme in der tiefen Wüste ist am unteren Bildschirmrand kurz der Schatten einer Tonangel auf dem Sand zu sehen."}'::jsonb WHERE id = 4960;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''attacco alla capitale, le munizioni e le armi imbracciate dai soldati Harkonnen cambiano modello e posizione della cinghia nei diversi stacchi di montaggio delle scene d''azione.","en":"During the attack on the capital, the ammunition and weapons held by the Harkonnen soldiers change model and sling position across different cuts in the action scenes.","es":"Durante el ataque a la capital, las municiones y las armas empuñadas por los soldados Harkonnen cambian de modelo y de posición de la correa en los diferentes cortes de montaje de las escenas de acción.","fr":"Pendant l''attaque de la capitale, les munitions et les armes tenues par les soldats Harkonnen changent de modèle et de position de bretelle selon les raccords de montage des scènes d''action.","de":"Während des Angriffs auf die Hauptstadt wechseln Modell und Gurtposition der von den Harkonnen-Soldaten getragenen Munition und Waffen in den verschiedenen Filmschnitten der Actionsequenzen."}'::jsonb WHERE id = 4961;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i festeggiamenti di Capodanno nel salone principale, il bicchiere di champagne tenuto da un passeggero cambia mano tra un''inquadratura e l''altra senza che vi sia il tempo materiale per compiere il gesto.","en":"During the New Year''s Eve celebrations in the main salon, the champagne glass held by a passenger changes hands between shots without there being actual time to make the switch.","es":"Durante las celebraciones de Nochevieja en el salón principal, la copa de champán que sostiene un pasajero cambia de mano entre plano y plano sin que haya tiempo material para hacer el gesto.","fr":"Pendant les célébrations du Nouvel An dans le grand salon, la coupe de champagne tenue par un passager change de main d''un plan à l''autre sans qu''il y ait le temps matériel d''effectuer le geste.","de":"Während der Silvesterfeierlichkeiten im Hauptsalon wechselt das Champagnerglas eines Passagiers zwischen den Einstellungen die Hand, ohne dass dafür eigentlich genügend Zeit gewesen wäre."}'::jsonb WHERE id = 4962;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui i sopravvissuti camminano lungo un corridoio inclinato della nave, si intravede brevemente l''ombra di un microfono boom sulla parete metallica a sinistra dell''inquadratura.","en":"In the scene where the survivors walk along a tilted ship corridor, the shadow of a boom mic is briefly glimpsed on the metal wall to the left of the frame.","es":"En la escena en la que los supervivientes caminan por un pasillo inclinado del barco, se atisba brevemente la sombra de un micrófono boom en la pared metálica a la izquierda del plano.","fr":"Dans la scène où les survivants marchent le long d''un couloir incliné du navire, on aperçoit brièvement l''ombre d''un micro boom sur la paroi métallique à gauche du cadre.","de":"In der Szene, in der die Überlebenden einen schrägen Schiffskorridor entlanggehen, ist kurz der Schatten eines Boom-Mikrofons an der Metallwand links im Bild zu sehen."}'::jsonb WHERE id = 4963;
UPDATE errori SET descrizione_i18n = '{"it":"Nel descrivere la fisica dell''onda anomala (rogue wave), i personaggi parlano di un fenomeno sismico o maremoto in mare aperto, sebbene le onde anomale oceaniche siano solitamente causate da forti correnti che incontrano onde anomale e non da terremoti sottomarini in quella specifica area.","en":"When describing the physics of a rogue wave, the characters speak of a seismic phenomenon or open-sea tsunami, although oceanic rogue waves are usually caused by strong currents interacting with abnormal waves rather than underwater earthquakes in that specific area.","es":"Al describir la física de una ola gigante (rogue wave), los personajes hablan de un fenómeno sísmico o maremoto en alta mar, aunque las olas gigantes oceánicas suelen estar causadas por fuertes corrientes que se encuentran con olas anómalas y no por terremotos submarinos en esa zona específica.","fr":"En décrivant la physique d''une lame scélérate (rogue wave), les personnages évoquent un phénomène sismique ou un tsunami en haute mer, bien que les vagues scélérates océaniques soient généralement causées par de forts courants rencontrant des vagues anormales et non par des séismes sous-marins dans cette zone spécifique.","de":"Bei der Beschreibung der Physik einer Monsterwelle (Rogue Wave) sprechen die Figuren von einem seismischen Phänomen oder einem Tsunami auf offener See, obwohl ozeanische Monsterwellen in der Regel durch starke Strömungen verursacht werden, die auf abnorme Wellen treffen, und nicht durch Unterseebeben in diesem spezifischen Gebiet."}'::jsonb WHERE id = 4964;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la riunione nella stanza di Andy, il calendario appeso alla parete cambia il mese visualizzato o la disposizione dei giorni tra un cambio di inquadratura e l''altra.","en":"During the meeting in Andy''s room, the wall calendar changes the displayed month or the layout of the days between cuts.","es":"Durante la reunión en la habitación de Andy, el calendario colgado en la pared cambia el mes mostrado o la disposición de los días entre plano y plano.","fr":"Pendant la réunion dans la chambre d''Andy, le calendrier accroché au mur change de mois affiché ou de disposition des jours d''un plan à l''autre.","de":"Während des Meetings in Andys Zimmer ändert sich bei dem Wandkalender der angezeigte Monat oder die Anordnung der Tage zwischen den Einstellungen."}'::jsonb WHERE id = 4965;
UPDATE errori SET descrizione_i18n = '{"it":"Alla stazione di servizio Pizza Planet, quando Buzz sale sul retro del camion, la posizione degli attrezzi nella cassetta sul pianale cambia leggermente tra l''inquadratura larga e il primo piano.","en":"At the Pizza Planet gas station, when Buzz climbs onto the back of the truck, the position of the tools in the truck bed toolbox shifts slightly between the wide shot and the close-up.","es":"En la gasolinera de Pizza Planet, cuando Buzz sube a la parte trasera del camión, la posición de las herramientas en la caja cambia ligeramente entre el plano general y el primer plano.","fr":"À la station-service Pizza Planet, lorsque Buzz monte à l''arrière du camion, la position des outils dans la boîte sur le plateau change légèrement entre le plan large et le gros plan.","de":"An der Pizza-Planet-Tankstelle, als Buzz auf die Ladefläche des Lastwagens klettert, verändert sich die Position der Werkzeuge im Werkzeugkasten leicht zwischen der Totalen und der Nahaufnahme."}'::jsonb WHERE id = 4966;
UPDATE errori SET descrizione_i18n = '{"it":"Nella camera di Sid, mentre Woody cerca di farsi notare dalla finestra con la lente d''ingrandimento, la posizione degli oggetti sul tavolo da lavoro di Sid varia inspiegabilmente nei diversi stacchi di montaggio.","en":"In Sid''s room, while Woody tries to get attention from the window with the magnifying glass, the position of the objects on Sid''s workbench inexplicably varies across different editing cuts.","es":"En la habitación de Sid, mientras Woody intenta llamar la atención desde la ventana con la lupa, la posición de los objetos en el banco de trabajo de Sid varía inexplicablemente en los diferentes cortes de montaje.","fr":"Dans la chambre de Sid, tandis que Woody essaie d''attirer l''attention depuis la fenêtre avec la loupe, la position des objets sur l''établi de Sid varie inexplicablement au fil des raccords de montage.","de":"In Sids Zimmer, während Woody versucht, sich mit der Lupe am Fenster bemerkbar zu machen, verändert sich die Position der Gegenstände auf Sids Werkbank unerklärlicherweise bei den verschiedenen Schnittwechseln."}'::jsonb WHERE id = 4967;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la riunione di compleanno nella stanza di Andy, il disegno del dinosauro attaccato all''armadio cambia leggermente posizione e inclinazione tra l''inquadratura generale dei giocattoli e i primi piani sui singoli personaggi.","en":"During the birthday meeting in Andy''s room, the dinosaur drawing taped to the wardrobe changes position and tilt slightly between the master shot of the toys and the close-ups on individual characters.","es":"Durante la reunión de cumpleaños en la habitación de Andy, el dibujo del dinosaurio pegado al armario cambia ligeramente de posición e inclinación entre el plano general de los juguetes y los primeros planos de los personajes.","fr":"Pendant la réunion d''anniversaire dans la chambre d''Andy, le dessin de dinosaure collé sur l''armoire change légèrement de position et d''inclinaison entre le plan large des jouets et les gros plans sur les personnages individuels.","de":"Während des Geburtstagstreffens in Andys Zimmer verändert sich die Position und Neigung der an den Kleiderschrank geklebten Dinosaurierzeichnung leicht zwischen der Totale der Spielzeuge und den Nahaufnahmen der einzelnen Figuren."}'::jsonb WHERE id = 4968;
UPDATE errori SET descrizione_i18n = '{"it":"Nella stazione di servizio Dinoco, quando Woody e Buzz lottano sul pavimento prima dell''arrivo del camion della Pizza Planet, i cartelli pubblicitari sullo sfondo cambiano posizione tra un''inquadratura e l''altra.","en":"At the Dinoco gas station, when Woody and Buzz fight on the floor before the Pizza Planet truck arrives, the background advertising signs change position between shots.","es":"En la gasolinera Dinoco, cuando Woody y Buzz pelean en el suelo antes de la llegada del camión de Pizza Planet, los carteles publicitarios del fondo cambian de posición entre plano y plano.","fr":"À la station-service Dinoco, lorsque Woody et Buzz se bagarrent sur le sol avant l''arrivée du camion Pizza Planet, les panneaux publicitaires en arrière-plan changent de position d''un plan à l''autre.","de":"An der Dinoco-Tankstelle, als Woody und Buzz sich vor der Ankunft des Pizza-Planet-Trucks auf dem Boden prügeln, verändern die Werbeschilder im Hintergrund zwischen den Einstellungen ihre Position."}'::jsonb WHERE id = 4969;
UPDATE errori SET descrizione_i18n = '{"it":"Nella camera degli orrori di Sid, quando Woody parla con i giocattoli mutanti nel cortile illuminato dalla luce della torcia, gli attrezzi da giardino appoggiati al muro cambiano disposizione nei vari cambi di inquadratura.","en":"In Sid''s room of horrors, when Woody talks to the mutant toys in the yard illuminated by flashlight, the garden tools leaning against the wall change arrangement across camera angles.","es":"En la habitación de los horrores de Sid, cuando Woody habla con los juguetes mutantes en el patio iluminado por la linterna, las herramientas de jardín apoyadas en la pared cambian de disposición en los diferentes cambios de plano.","fr":"Dans la chambre des horreurs de Sid, lorsque Woody parle aux jouets mutants dans la cour éclairée par une lampe torche, les outils de jardin appuyés contre le mur changent de disposition au gré des changements de plan.","de":"In Sids Raum des Schreckens, wenn Woody im Schein einer Taschenlampe im Hof mit den mutierten Spielzeugen spricht, verändert sich die Anordnung der an die Wand gelehnten Gartengeräte bei den verschiedenen Einstellungswechseln."}'::jsonb WHERE id = 4970;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''inseguimento finale al camion in movimento, le scatole di cartone che cadono dal retro del furgone cambiano forma, dimensione e quantità a seconda che vengano inquadrate frontalmente o di profilo.","en":"During the final chase after the moving truck, the cardboard boxes falling from the back of the van change shape, size, and quantity depending on whether they are shot from the front or in profile.","es":"Durante la persecución final al camión en marcha, las cajas de cartón que caen de la parte trasera de la furgoneta cambian de forma, tamaño y cantidad según se enfoquen de frente o de perfil.","fr":"Pendant la course-poursuite finale après le camion en mouvement, les cartons qui tombent de l''arrière de la camionnette changent de forme, de taille et de quantité selon qu''ils sont filmés de face ou de profil.","de":"Während der finalen Verfolgungsjagd des sich bewegenden Lastwagens verändern die aus dem Heck des Transporters fallenden Pappkartons ihre Form, Größe und Menge, je nachdem, ob sie frontal oder im Profil gefilmt werden."}'::jsonb WHERE id = 4971;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Woody cerca il cappello nella stanza di Andy, la scatola sulla mensola cambia posizione tra l''inquadratura in cui Woody guarda in alto e quella successiva in primo piano.","en":"When Woody looks for his hat in Andy''s room, the box on the shelf changes position between the shot of Woody looking up and the following close-up.","es":"Cuando Woody busca su sombrero en la habitación de Andy, la caja de la estantería cambia de posición entre el plano en el que Woody mira hacia arriba y el siguiente primer plano.","fr":"Quand Woody cherche son chapeau dans la chambre d''Andy, la boîte sur l''étagère change de position entre le plan où Woody lève les yeux et le gros plan suivant.","de":"Als Woody in Andys Zimmer nach seinem Hut sucht, verändert sich die Position der Schachtel im Regal zwischen der Einstellung, in der Woody nach oben schaut, und der folgenden Nahaufnahme."}'::jsonb WHERE id = 4972;
UPDATE errori SET descrizione_i18n = '{"it":"Nel cortile durante la vendita nel garage di Andy, la limonata sul bancone della bancarella sparisce improvvisamente da un''inquadratura all''altra quando la madre di Andy parla con il collezionista Al.","en":"In the yard during Andy''s garage sale, the lemonade on the stand counter suddenly disappears from one shot to the next when Andy''s mom talks to the collector Al.","es":"En el patio durante la venta de garaje de Andy, la limonada en el mostrador del puesto desaparece repentinamente de un plano a otro cuando la madre de Andy habla con el coleccionista Al.","fr":"Dans la cour pendant le vide-grenier d''Andy, la limonade sur le comptoir du stand disparaît soudainement d''un plan à l''autre lorsque la mère d''Andy parle au collectionneur Al.","de":"Im Hof während Andys Garagenverkauf verschwindet die Limonade auf dem Standtresen plötzlich von einer Einstellung zur nächsten, als Andys Mutter mit dem Sammler Al spricht."}'::jsonb WHERE id = 4973;
UPDATE errori SET descrizione_i18n = '{"it":"Nell''appartamento di Al, mentre Woody scopre i giocattoli della sua stessa serie nella vetrina, la posizione del cappello di Stinky Pete sul piedistallo si sposta leggermente mentre la telecamera cambia angolo.","en":"In Al''s apartment, as Woody discovers the toys from his own set in the display case, the position of Stinky Pete''s hat on the pedestal shifts slightly as the camera changes angles.","es":"En el apartamento de Al, mientras Woody descubre los juguetes de su propia serie en la vitrina, la posición del sombrero de Oloroso Pete en el pedestal cambia ligeramente al cambiar el ángulo de cámara.","fr":"Dans l''appartement d''Al, alors que Woody découvre les jouets de sa propre collection dans la vitrine, la position du chapeau de Papi Pépite sur le socle change légèrement lors des changements d''angle de caméra.","de":"In Als Apartment verschiebt sich die Position von Stinky Petes Hut auf dem Sockel leicht bei jedem Kameraperspektivenwechsel, während Woody die Spielzeuge seiner eigenen Serie in der Vitrine entdeckt."}'::jsonb WHERE id = 4974;
UPDATE errori SET descrizione_i18n = '{"it":"Nel negozio Al''s Toy Barn, quando i giocattoli di Andy camminano tra le corsie piene di scatole di Buzz Lightyear, il numero di scatole impilate sullo scaffale di destra diminuisce visibilmente tagliando l''inquadratura.","en":"In Al''s Toy Barn, when Andy''s toys walk through the aisles filled with Buzz Lightyear boxes, the number of boxes stacked on the right shelf visibly decreases between cuts.","es":"En la juguetería Al''s Toy Barn, cuando los juguetes de Andy caminan por los pasillos llenos de cajas de Buzz Lightyear, el número de cajas apiladas en el estante derecho disminuye visiblemente al cortar el plano.","fr":"Chez Al''s Toy Barn, lorsque les jouets d''Andy marchent dans les allées remplies de boîtes de Buzz l''Éclair, le nombre de boîtes empilées sur l''étagère de droite diminue visiblement d''un plan à l''autre.","de":"Im Spielwarenladen Al''s Toy Barn nimmt die Anzahl der gestapelten Kartons im rechten Regal beim Szenenwechsel sichtbar ab, während Andys Spielzeuge durch die Gänge voller Buzz-Lightyear-Schachteln gehen."}'::jsonb WHERE id = 4975;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena sul carrello dei bagagli all''aeroporto, quando il secondo Buzz Lightyear rimane intrappolato nella plastica della confezione, i nastri adesivi sulla scatola cambiano orientamento tra i diversi cambi di inquadratura.","en":"During the airport luggage cart scene, when the second Buzz Lightyear gets trapped in the packaging plastic, the tape strips on the box change orientation across different shot cuts.","es":"Durante la escena del carrito de equipaje en el aeropuerto, cuando el segundo Buzz Lightyear queda atrapado en el plástico del embalaje, las cintas adhesivas de la caja cambian de orientación entre los distintos cortes de plano.","fr":"Pendant la scène du chariot à bagages à l''aéroport, lorsque le deuxième Buzz l''Éclair se retrouve piégé dans le plastique de l''emballage, les bandes adhésives sur la boîte changent d''orientation d''un raccord à l''autre.","de":"Während der Gepäckwagenszene am Flughafen, wenn der zweite Buzz Lightyear in der Plastikverpackung gefangen ist, verändert sich die Ausrichtung der Klebestreifen auf dem Karton zwischen den verschiedenen Montageeinstellungen."}'::jsonb WHERE id = 4976;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i giocattoli vengono posizionati sul tavolo nella stanza dei giochi del Sunnyside prima dell''arrivo dei bambini, la scatola con i pastelli cambia posizione e orientamento tra un''inquadratura e l''altra.","en":"When the toys are placed on the table in the Sunnyside playroom before the kids arrive, the box of crayons changes position and orientation from one shot to the next.","es":"Cuando los juguetes son colocados sobre la mesa en la sala de juegos de Sunnyside antes de la llegada de los niños, la caja de crayones cambia de posición y orientación de un plano a otro.","fr":"Lorsque les jouets sont posés sur la table dans la salle de jeux de Sunnyside avant l''arrivée des enfants, la boîte de crayons change de position et d''orientation d''un plan à l''autre.","de":"Wenn die Spielzeuge vor der Ankunft der Kinder auf dem Tisch im Sunnyside-Spielzimmer platziert werden, verändern die Buntstiftschachtel und deren Ausrichtung sich von einer Einstellung zur nächsten."}'::jsonb WHERE id = 4977;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il reset di Buzz Lightyear in modalità dimostrativa spagnola, il pannello di controllo sul suo braccio sinistro si apre e si chiude in modo non coerente tra i vari cambi di inquadratura.","en":"During Buzz Lightyear''s reset to Spanish demo mode, the control panel on his left arm opens and closes inconsistently across various camera cuts.","es":"Durante el reseteo de Buzz Lightyear al modo de demostración en español, el panel de control de su brazo izquierdo se abre y se cierra de forma incoherente entre los distintos cambios de plano.","fr":"Pendant la réinitialisation de Buzz l''Éclair en mode démonstration espagnol, le panneau de commande sur son bras gauche s''ouvre et se ferme de manière incohérente entre les différents plans.","de":"Während Buzz Lightyears Reset in den spanischen Vorführmodus öffnet und schließt sich das Bedienfeld an seinem linken Arm zwischen den verschiedenen Kameraschnitten inkonsistent."}'::jsonb WHERE id = 4978;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Rex e gli altri cercano di liberare Buzz, i ganci e le cinghie che lo tengono legato alla sedia cambiano lunghezza e disposizione da un''inquadratura ravvicinata a quella generale.","en":"At the moment Rex and the others try to free Buzz, the hooks and straps holding him tied to the chair change length and arrangement from a close-up to a wide shot.","es":"En el momento en que Rex y los demás intentan liberar a Buzz, los ganchos y correas que lo mantienen atado a la silla cambian de longitud y disposición de un plano cercano a uno general.","fr":"Au moment où Rex et les autres essaient de libérer Buzz, les crochets et les sangles qui le maintiennent attaché à la chaise changent de longueur et de disposition entre un gros plan et un plan large.","de":"In dem Moment, in dem Rex und die anderen versuchen, Buzz zu befreien, verändern die Haken und Riemen, mit denen er an den Stuhl gefesselt ist, ihre Länge und Anordnung von einer Nahaufnahme zur Totalen."}'::jsonb WHERE id = 4979;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i giocattoli sono sul marciapiede pronti per essere buttati via nella spazzatura, il sacco nero della spazzatura accanto a Woody cambia posizione e grinze visibilmente tra un''inquadratura e l''altra.","en":"When the toys are on the sidewalk ready to be thrown away in the trash, the black trash bag next to Woody visibly changes position and wrinkles from one shot to the next.","es":"Cuando los juguetes están en la acera listos para ser tirados a la basura, la bolsa de basura negra junto a Woody cambia visiblemente de posición y arrugas de un plano a otro.","fr":"Lorsque les jouets sont sur le trottoir prêts à être jetés à la poubelle, le sac poubelle noir à côté de Woody change visiblement de position et de plis d''un plan à l''autre.","de":"Wenn die Spielzeuge auf dem Gehweg bereit stehen, in den Müll geworfen zu werden, verändern der schwarze Müllsack neben Woody und dessen Faltenwurf ihre Position von einer Einstellung zur nächsten sichtbar."}'::jsonb WHERE id = 4980;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui i giocattoli entrano per la prima volta nella stanza della classe dei bruchi al Sunnyside, Ken mostra una sciarpa che in un primo piano stringe attorno al collo, mentre nell''inquadratura larga successiva la sciarpa risulta leggermente spostata sulle spalle.","en":"When the toys first enter the Caterpillar classroom at Sunnyside, Ken shows off a scarf which in a close-up is tight around his neck, while in the following wide shot the scarf appears slightly shifted onto his shoulders.","es":"Cuando los juguetes entran por primera vez en el aula de la Oruga en Sunnyside, Ken presume una bufanda que en un primer plano lleva apretada alrededor del cuello, mientras que en el plano general siguiente la bufanda aparece ligeramente desplazada sobre los hombros.","fr":"Au moment où les jouets entrent pour la première fois dans la classe des chenilles à Sunnyside, Ken montre une écharpe qu''il serre autour de son cou dans un gros plan, tandis que dans le plan large suivant, l''écharpe a légèrement glissé sur ses épaules.","de":"Als die Spielzeuge zum ersten Mal den Raupen-Klassenraum in Sunnyside betreten, präsentiert Ken einen Schal, den er in einer Nahaufnahme eng um den Hals trägt, während der Schal in der nächsten Totalen leicht auf seine Schultern gerutscht ist."}'::jsonb WHERE id = 4981;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il tentativo di fuga, quando Mr. Potato Head è smembrato nel corpo di una tortilla, i frammenti di verdura e gli altri oggetti sparsi sul tavolo variano la loro disposizione nei cambi di inquadratura.","en":"During the escape attempt, when Mr. Potato Head is dismembered inside a tortilla body, the vegetable fragments and other objects scattered across the table change their arrangement between camera cuts.","es":"Durante el intento de fuga, cuando el Señor Potato es desmembrado en el cuerpo de una tortilla, los fragmentos de verdura y otros objetos esparcidos por la mesa cambian de disposición entre plano y plano.","fr":"Pendant la tentative d''évasion, lorsque M. Patate est démembré dans le corps d''une tortilla, les fragments de légumes et autres objets éparpillés sur la table changent de disposition d''un plan à l''autre.","de":"Während des Fluchtversuchs, als Mr. Potato Head im Körper einer Tortilla zerlegt ist, verändern die Gemüsestücke und andere auf dem Tisch verstreute Gegenstände zwischen den Einstellungen ihre Anordnung."}'::jsonb WHERE id = 4982;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Lotso si trova vicino al pannello di controllo dell''inceneritore alla discarica, i pulsanti e le spie luminose cambiano colore e disposizione tra le inquadrature ravvicinate e quelle panoramiche.","en":"In the scene where Lotso stands near the incinerator control panel at the dump, the buttons and indicator lights change color and layout between close-ups and wide shots.","es":"En la escena en la que Lotso está cerca del panel de control del incinerador en el vertedero, los botones y las luces indicadoras cambian de color y disposición entre los primeros planos y los planos generales.","fr":"Dans la scène où Lotso se trouve près du panneau de commande de l''incinérateur à la décharge, les boutons et les voyants lumineux changent de couleur et de disposition entre les gros plans et les plans larges.","de":"In der Szene, in der Lotso am Bedienpult des Müllverbrennungsanlage auf dem Schrottplatz steht, ändern die Knöpfe und Kontrollleuchten zwischen Nahaufnahmen und Totalen ihre Farbe und Anordnung."}'::jsonb WHERE id = 4983;
UPDATE errori SET descrizione_i18n = '{"it":"Nel camper durante il viaggio, quando Woody parla con Forky per la prima volta, gli oggetti sul tavolino di plastica vicino al finestrino cambiano posizione e orientamento tra un''inquadratura e l''altra.","en":"In the RV during the trip, when Woody talks to Forky for the first time, the objects on the plastic table near the window change position and orientation from one shot to the next.","es":"En la autocaravana durante el viaje, cuando Woody habla con Forky por primera vez, los objetos de la mesita de plástico situada junto a la ventana cambian de posición y orientación entre plano y plano.","fr":"Dans le camping-car pendant le voyage, lorsque Woody parle à Forky pour la première fois, les objets posés sur la petite table en plastique près de la fenêtre changent de position et d''orientation d''un plan à l''autre.","de":"Im Wohnmobil während der Fahrt, als Woody zum ersten Mal mit Forky spricht, verändern die Gegenstände auf dem Plastiktisch am Fenster zwischen den Einstellungen ihre Position und Ausrichtung."}'::jsonb WHERE id = 4984;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno del negozio di antiquariato ''Second Oportunity Antiques'', quando Woody cerca di fuggire attraverso le mensole, la disposizione delle vecchie scatole di latta sullo sfondo muta visibilmente nei cambi di inquadratura.","en":"Inside the antique shop ''Second Chance Antiques'', when Woody tries to escape across the shelves, the arrangement of the old tin cans in the background visibly shifts across camera cuts.","es":"Dentro de la tienda de antigüedades ''Second Chance Antiques'', cuando Woody intenta escapar por las estanterías, la disposición de las viejas latas en el fondo cambia visiblemente entre plano y plano.","fr":"À l''intérieur de la boutique d''antiquités « Second Chance Antiques », lorsque Woody essaie de s''enfuir à travers les étagères, la disposition des vieilles boîtes de conserve à l''arrière-plan change visiblement d''un plan à l''autre.","de":"Im Antiquitätengeschäft „Second Chance Antiques“ verändert sich bei Woodys Fluchtversuch über die Regale die Anordnung der alten Blechdosen im Hintergrund bei den Szenenwechseln sichtbar."}'::jsonb WHERE id = 4985;
UPDATE errori SET descrizione_i18n = '{"it":"Nel luna park, nei pressi della giostra e delle attrazioni, la tazza da caffè tenuta in mano da un passante sullo sfondo scompare e riappare improvvisamente tra un taglio di montaggio e il successivo.","en":"At the amusement park, near the carousel and attractions, the coffee cup held by a background extra suddenly disappears and reappears between one editing cut and the next.","es":"En el parque de atracciones, cerca del carrusel y las atracciones, la taza de café que sostiene un transeúnte en segundo plano desaparece y reaparece repentinamente entre un corte de montaje y el siguiente.","fr":"Dans le parc d''attractions, près du manège et des manèges, la tasse de café tenue par un figurant en arrière-plan disparaît et réapparaît soudainement entre deux coupes au montage.","de":"Im Freizeitpark, nahe dem Karussell und den Fahrgeschäften, verschwindet und erscheint der Kaffeebecher in der Hand eines Statisten im Hintergrund zwischen zwei Schnittwechseln plötzlich wieder."}'::jsonb WHERE id = 4986;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza del flipper nel negozio di antiquariato, le palline e gli elementi decorativi sulla plancia del gioco cambiano posizione tra l''inquadratura larga e i primi piani sui giocattoli.","en":"In the pinball sequence inside the antique shop, the balls and decorative elements on the playfield change position between the wide shot and the close-ups on the toys.","es":"En la secuencia del pinball en la tienda de antigüedades, las bolas y los elementos decorativos del tablero de juego cambian de posición entre el plano general y los primeros planos de los juguetes.","fr":"Dans la séquence du flipper dans la boutique d''antiquités, les billes et les éléments décoratifs du plateau de jeu changent de position entre le plan large et les gros plans sur les jouets.","de":"In der Flipper-Sequenz im Antiquitätengeschäft verändern die Kugeln und dekorativen Elemente auf dem Spielfeld zwischen der Totalen und den Nahaufnahmen der Spielzeuge ihre Position."}'::jsonb WHERE id = 4987;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena del luna park in cui Buzz e gli altri pianificano il salvataggio vicino ai giochi a premi, i peluche appesi sulla griglia cambiano disposizione cromatica e posizione da un''inquadratura all''altra.","en":"During the amusement park scene where Buzz and the others plan the rescue near the prize games, the plush toys hanging on the grid change their color arrangement and position from one shot to the next.","es":"Durante la escena del parque de atracciones en la que Buzz y los demás planean el rescate cerca de los puestos de feria, los peluches colgados de la reja cambian su distribución de colores y posición de un plano a otro.","fr":"Pendant la scène du parc d''attractions où Buzz et les autres planifient le sauvetage près des stands de jeux, les peluches suspendues au grillage changent de disposition des couleurs et de position d''un plan à l''autre.","de":"Während der Freizeitpark-Szene, in der Buzz und die anderen in der Nähe der Budenspiele die Rettung planen, verändern die am Gitter hängenden Plüschtiere von einer Einstellung zur nächsten ihre Farbanordnung und Position."}'::jsonb WHERE id = 4988;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui il giovane Bruce Wayne si trova nel tribunale per assistere all''udienza sulla scarcerazione di Joe Chill, la posizione del cappotto e della sciarpa indossati da Rachel Dawes variano visibilmente tra un cambio di inquadratura e l''altro.","en":"During the sequence where young Bruce Wayne is at the courthouse to attend Joe Chill''s parole hearing, the position of Rachel Dawes''s coat and scarf visibly shifts between cuts.","es":"Durante la secuencia en la que el joven Bruce Wayne está en el tribunal para asistir a la vista de libertad condicional de Joe Chill, la posición del abrigo y la bufanda de Rachel Dawes varía visiblemente entre plano y plano.","fr":"Pendant la séquence où le jeune Bruce Wayne se trouve au tribunal pour assister à l''audience de libération conditionnelle de Joe Chill, la position du manteau et de l''écharpe de Rachel Dawes varie visiblement d''un plan à l''autre.","de":"Während der Szene, in der der junge Bruce Wayne im Gerichtsgebäude der Anhörung zur begünstigten Entlassung von Joe Chill beiwohnt, verändern sich die Positionen von Rachel Dawes'' Mantel und Schal zwischen den Einstellungen sichtbar."}'::jsonb WHERE id = 4989;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Henri Ducard addestra Bruce Wayne sulle nevi, il ramo di legno spezzato che Bruce usa per difendersi cambia lunghezza e forma in modo netto tra un primo piano e il campo medio.","en":"When Henri Ducard trains Bruce Wayne in the snow, the broken wooden branch Bruce uses to defend himself changes length and shape noticeably between a close-up and a medium shot.","es":"Cuando Henri Ducard entrena a Bruce Wayne en la nieve, la rama de madera rota que Bruce usa para defenderse cambia notablemente de longitud y forma entre un plano medio y un primer plano.","fr":"Quand Henri Ducard entraîne Bruce Wayne dans la neige, la branche de bois brisée que Bruce utilise pour se défendre change nettement de longueur et de forme entre un gros plan et un plan moyen.","de":"Als Henri Bruce Wayne im Schnee trainiert, verändern sich Länge und Form des abgebrochenen Holzasts, den Bruce zur Verteidigung nutzt, deutlich zwischen Nahaufnahme und halbtotaler Einstellung."}'::jsonb WHERE id = 4990;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui la Batmobile (Tumbler) atterra pesantemente dopo un salto sui tetti di Gotham, per un fotogramma sul lato destro dello schermo è possibile intravedere la struttura del cavalletto di supporto o parte dell''attrezzatura della troupe montata lateralmente.","en":"In the scene where the Batmobile (Tumbler) lands heavily after jumping across Gotham''s rooftops, for a single frame on the right side of the screen you can briefly catch a glimpse of a rig structure or side-mounted crew equipment.","es":"En la escena en la que el Batmóvil (Tumbler) aterriza pesadamente tras un salto por los tejados de Gotham, durante un fotograma en el lado derecho de la pantalla se puede atisbar la estructura de un soporte o parte del equipo de rodaje montado lateralmente.","fr":"Dans la scène où la Batmobile (Tumbler) atterrit lourdement après un saut sur les toits de Gotham, on peut apercevoir pendant une seule image, sur le côté droit de l''écran, la structure d''un support ou une partie du matériel de tournage fixé sur le côté.","de":"In der Szene, in der das Batmobil (Tumbler) nach einem Sprung über Gothams Dächer hart landet, ist für einen einzigen Frame am rechten Bildschirmrand die Struktur eines Rigs oder seitlich montiertes Equipment der Crew zu sehen."}'::jsonb WHERE id = 4991;
UPDATE errori SET descrizione_i18n = '{"it":"Nel covo dello Spaventapasseri, quando viene attivato il sistema antincendio con i sprinkler, i capelli e i vestiti di Cillian Murphy (Jonathan Crane) passano dall''essere completamente bagnati a quasi asciutti nei tagli di montaggio ravvicinati.","en":"In the Scarecrow''s hideout, when the fire sprinkler system is triggered, Cillian Murphy''s (Jonathan Crane) hair and clothes switch from being completely soaked to nearly dry across close-up editing cuts.","es":"En la guarida del Espantapájaros, cuando se activa el sistema de rociadores contra incendios, el cabello y la ropa de Cillian Murphy (Jonathan Crane) pasan de estar completamente mojados a casi secos en los cortes de montaje cerrados.","fr":"Dans la repaire de l''Épouvantail, lorsque le système de gicleurs anti-incendie est activé, les cheveux et les vêtements de Cillian Murphy (Jonathan Crane) passent d''une trempette totale à presque secs d''un raccord à l''autre en gros plan.","de":"Im Versteck der Vogelscheuche wechseln Cillian Murphys (Jonathan Crane) Haare und Kleidung nach Aktivierung der Sprinkleranlage zwischen den nahen Montage-Schnitten von komplett durchnässt zu fast trocken."}'::jsonb WHERE id = 4992;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''assalto finale al treno della monorotaia di Wayne Enterprises, il sistema di controllo remoto e le comunicazioni radio funzionano in modo anomalo rispetto alla fisica dei segnali sotterranei e alla velocità del convoglio.","en":"During the final assault on the Wayne Enterprises monorail train, the remote control system and radio communications behave inconsistently regarding underground signal physics and the train''s speed.","es":"Durante el asalto final al tren del monorraíl de Wayne Enterprises, el sistema de control remoto y las comunicaciones por radio funcionan de manera anómala en relación con la física de las señales subterráneas y la velocidad del convoy.","fr":"Lors de l''assaut final contre le train monorail de Wayne Enterprises, le système de télécommande et les communications radio fonctionnent de manière anormale au regard de la physique des signaux souterrains et de la vitesse du convoi.","de":"Während des finalen Angriffs auf den Einschienenbahn-Zug von Wayne Enterprises verhalten sich das Fernsteuersystem und die Funkkommunikation im Hinblick auf unterirdische Signalphysik und Zuggeschwindigkeit physikalisch unplausibel."}'::jsonb WHERE id = 4993;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la rapina in banca iniziale, quando il direttore della banca cerca di sparare con il fucile a pompa al primo clown, la quantità di cartucce inserite e la posizione del bossolo cambiano nei vari stacchi di montaggio prima che venga sopraffatto.","en":"During the opening bank heist, when the bank manager tries to shoot the first clown with a shotgun, the number of loaded shells and the position of the spent casing shift across various editing cuts before he is overpowered.","es":"Durante el atraco al banco inicial, cuando el director del banco intenta disparar una escopeta al primer payaso, la cantidad de cartuchos insertados y la posición del casquillo cambian en los diferentes cortes de montaje antes de ser reducido.","fr":"Pendant le braquage de banque d''ouverture, lorsque le directeur de la banque essaie de tirer au fusil à pompe sur le premier clown, le nombre de cartouches chambrées et la position de la douille changent au fil des raccords de montage avant qu''il ne soit maîtrisé.","de":"Während des Banküberfalls zu Beginn versucht der Filialleiter, den ersten Clown mit einer Schrotflinte zu erschießen, wobei sich die Anzahl der geladenen Patronen und die Position der Patronenhülse in den verschiedenen Schnitten vor seiner Überwältigung verändern."}'::jsonb WHERE id = 4994;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena dell''ufficio in cui il tenente Gordon parla con Harvey Dent, i bicchieri e i documenti sulla scrivania si spostano leggermente da un''inquadratura all''altra senza che nessuno li tocchi.","en":"In the office scene where Lieutenant Gordon talks to Harvey Dent, the glasses and paperwork on the desk shift slightly between shots without anyone touching them.","es":"En la escena de la oficina donde el teniente Gordon habla con Harvey Dent, los vasos y los papeles del escritorio se mueven ligeramente de un plano a otro sin que nadie los toque.","fr":"Dans la scène de bureau où le lieutenant Gordon discute avec Harvey Dent, les verres et les dossiers sur le bureau bougent légèrement d''un plan à l''autre sans que personne ne les touche.","de":"In der Büroszene, in der Lieutenant Gordon mit Harvey Dent spricht, verändern Gläser und Papiere auf dem Schreibtisch zwischen den Einstellungen leicht ihre Position, ohne dass sie berührt werden."}'::jsonb WHERE id = 4995;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza dell''inseguimento con la Batmobile e il camion blindato, la parte anteriore della Tumbler subisce danni ingenti in un''inquadratura, per poi apparire quasi intatta nell''inquadratura immediatamente successiva.","en":"During the chase sequence featuring the Batmobile and the armored truck, the front end of the Tumbler takes heavy damage in one shot, only to appear nearly undamaged in the very next shot.","es":"Durante la secuencia de persecución del Batmóvil y el camión blindado, la parte delantera del Tumbler sufre daños considerables en un plano, para luego aparecer casi intacta en el plano inmediatamente posterior.","fr":"Pendant la séquence de course-poursuite avec la Batmobile et le camion blindé, l''avant du Tumbler subit de gros dégâts sur un plan, avant d''apparaître presque intact sur le plan juste après.","de":"Während der Verfolgungsjagd mit dem Batmobil und dem gepanzerten Lastwagen erleidet die Frontpartie des Tumblers in einer Einstellung schwere Schäden, wirkt dann aber in der allernächsten Einstellung nahezu unbeschädigt."}'::jsonb WHERE id = 4996;
UPDATE errori SET descrizione_i18n = '{"it":"Quando il Joker viene chiuso nella cella della stazione di polizia, i fogli e gli oggetti sparsi sulla scrivania fuori dalla cella cambiano disposizione mentre Gordon parla con lui.","en":"When the Joker is locked in the police station holding cell, the papers and items scattered on the desk outside the cell change arrangement while Gordon talks to him.","es":"Cuando el Joker es encerrado en la celda de la comisaría, los papeles y objetos esparcidos en el escritorio fuera de la celda cambian de disposición mientras Gordon habla con él.","fr":"Quand le Joker est enfermé dans la cellule du commissariat, les papiers et objets éparpillés sur le bureau à l''extérieur de la cellule changent de disposition pendant que Gordon lui parle.","de":"Als der Joker in die Zelle auf dem Revier gesperrt wird, verändern die auf dem Schreibtisch vor der Zelle verstreuten Papiere und Gegenstände ihre Anordnung, während Gordon mit ihm spricht."}'::jsonb WHERE id = 4997;
UPDATE errori SET descrizione_i18n = '{"it":"Sul set del traghetto, quando i passeggeri votano per far esplodere l''altra nave, la posizione delle mani e la distanza dei personaggi dai detonatori cambiano ripetutamente tra i primi piani e i campi medi.","en":"On the ferry set, when the passengers vote on whether to blow up the other ship, the hand positions and the characters'' distance from the detonators change repeatedly between close-ups and medium shots.","es":"En el plató del ferry, cuando los pasajeros votan para hacer explotar el otro barco, la posición de las manos y la distancia de los personajes a los detonadores cambian repetidamente entre los primeros planos y los planos medios.","fr":"Sur le plateau du ferry, lorsque les passagers votent pour faire sauter l''autre navire, la position des mains et la distance des personnages par rapport aux détonateurs changent à plusieurs reprises entre les gros plans et les plans moyens.","de":"Auf dem Fähr-Set, als die Passagiere darüber abstimmen, das andere Schiff in die Luft zu jagen, verändern sich die Handpositionen und der Abstand der Figuren zu den Zündern wiederholt zwischen Nahaufnahmen und Halbtotale."}'::jsonb WHERE id = 4998;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena del borsaio alla Borsa, la borsa con i documenti che Selina Kyle consegna cambia mano o posizione tra un''inquadratura e l''altra mentre fugge dalle guardie.","en":"During the pickpocket scene at the Stock Exchange, the bag with the documents that Selina Kyle hands over changes hands or position from one shot to the next as she flees the guards.","es":"Durante la escena del carterista en la Bolsa, la bolsa con los documentos que entrega Selina Kyle cambia de mano o de posición de un plano a otro mientras huye de los guardias.","fr":"Pendant la scène du pickpocket à la Bourse, le sac contenant les documents que Selina Kyle remet change de main ou de position d''un plan à l''autre alors qu''elle fuit les gardes.","de":"Während der Taschendieb-Szene an der Börse wechseln die Tasche mit den Dokumenten, die Selina Kyle übergibt, von einer Einstellung zur nächsten die Hand oder Position, während sie vor den Wachen flieht."}'::jsonb WHERE id = 4999;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della festa di beneficenza a casa Wayne, la posizione della sciarpa di Miranda Tate (Marion Cotillard) varia visibilmente tra i primi piani e le inquadrature a figura intera durante la conversazione con Bruce.","en":"During the charity gala at Wayne Manor, the position of Miranda Tate''s (Marion Cotillard) scarf varies visibly between close-ups and wide shots during her conversation with Bruce.","es":"Durante la fiesta benéfica en la mansión Wayne, la posición de la bufanda de Miranda Tate (Marion Cotillard) varía visiblemente entre los primeros planos y los planos generales durante la conversación con Bruce.","fr":"Pendant la soirée de bienfaisance au manoir Wayne, la position de l''écharpe de Miranda Tate (Marion Cotillard) varie visiblement entre les gros plans et les plans larges lors de sa conversation avec Bruce.","de":"Während der Wohltätigkeitsgala im Wayne Manor variiert die Position von Miranda Tates (Marion Cotillard) Schal während des Gesprächs mit Bruce sichtbar zwischen Nahaufnahmen und Totalen."}'::jsonb WHERE id = 5000;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il primo scontro brutale tra Batman e Bane nelle fogne, la neve o l''acqua sui vestiti e sul volto di Batman spariscono e riappaiono misteriosamente a seconda dei cambi di angolazione della telecamera.","en":"During the first brutal fight between Batman and Bane in the sewers, the snow or water on Batman''s clothes and face mysteriously disappears and reappears depending on the camera angle changes.","es":"Durante el primer brutal enfrentamiento entre Batman y Bane en las alcantarillas, la nieve o el agua en la ropa y la cara de Batman desaparecen y reaparecen misteriosamente según los cambios de ángulo de cámara.","fr":"Lors du premier combat brutal entre Batman et Bane dans les égouts, la neige ou l''eau sur les vêtements et le visage de Batman disparaissent et réapparaissent mystérieusement selon les changements d''angle de caméra.","de":"Während des ersten brutalen Kampfes zwischen Batman und Bane in der Kanalisation verschwinden und erscheinen Schnee oder Wasser auf Batmans Kleidung und Gesicht je nach Kameraperspektive auf mysteriöse Weise wieder."}'::jsonb WHERE id = 5001;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui i mercenari di Bane fanno esplodere i ponti di Gotham, il conteggio e la sequenza visiva dei veicoli che cadono o si fermano ai blocchi stradali mostrano incongruenze di posizionamento nei campi larghi successivi.","en":"In the sequence where Bane''s mercenaries blow up Gotham''s bridges, the count and visual sequence of vehicles falling or stopping at the roadblocks show positioning inconsistencies in subsequent wide shots.","es":"En la secuencia en la que los mercenarios de Bane explotan los puentes de Gotham, el recuento y la secuencia visual de los vehículos que caen o se detienen en los controles de carretera muestran incongruencias de posición en los siguientes planos generales.","fr":"Dans la séquence où les mercenaires de Bane font sauter les ponts de Gotham, le compte et la séquence visuelle des véhicules qui tombent ou s''arrêtent aux barrages routiers montrent des incohérences de positionnement dans les plans larges suivants.","de":"In der Sequenz, in der Banes Söldner Gothams Brücken sprengen, zeigen die Anzahl und die visuelle Reihenfolge der Fahrzeuge, die abstürzen oder an den Straßensperren anhalten, in nachfolgenden Totalen Positionsinkonsistenzen."}'::jsonb WHERE id = 5002;
UPDATE errori SET descrizione_i18n = '{"it":"In una delle inquadrature ampie durante la rivolta generale a Gotham City, si intravede brevemente l''ombra di un operatore di ripresa o l''attrezzatura della troupe su un muro laterale a sinistra.","en":"In one of the wide shots during the general riot in Gotham City, the shadow of a camera operator or crew equipment is briefly glimpsed on a side wall to the left.","es":"En uno de los planos generales durante el motín general en Gotham City, se vislumbra brevemente la sombra de un operador de cámara o del equipo de rodaje en una pared lateral a la izquierda.","fr":"Dans l''un des plans larges lors de l''émeute générale à Gotham City, on aperçoit brièvement l''ombre d''un cadreur ou de l''équipement de l''équipe technique sur un mur latéral à gauche.","de":"In einer der Totalen während des allgemeinen Aufstands in Gotham City ist kurz der Schatten eines Kameramanns oder von Crew-Equipment an einer Seitenwand links zu erkennen."}'::jsonb WHERE id = 5003;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''inseguimento finale con i Tumbler e la bomba atomica, i danni subiti dalla carrozzeria e dal parabrezza del veicolo guidato da Gordon cambiano drasticamente da un''inquadratura all''altra.","en":"During the final chase with the Tumblers and the atomic bomb, the body and windshield damage sustained by the vehicle driven by Gordon changes drastically from one shot to the next.","es":"Durante la persecución final con los Tumblers y la bomba atómica, los daños en la carrocería y el parabrisas del vehículo conducido por Gordon cambian drásticamente de un plano a otro.","fr":"Pendant la course-poursuite finale avec les Tumblers et la bombe atomique, les dégâts subis par la carrosserie et le pare-brise du véhicule conduit par Gordon changent radicalement d''un plan à l''autre.","de":"Während der finalen Verfolgungsjagd mit den Tumblern und der Atombombe verändern sich die Schäden an Karosserie und Windschutzscheibe des von Gordon gefahrenen Fahrzeugs von einer Einstellung zur nächsten drastisch."}'::jsonb WHERE id = 5004;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Lucy viene trascinata nella stanza dell''hotel dal boss Mr. Jang, la valigetta che le era stata consegnata cambia posizione sul pavimento tra un''inquadratura e l''altra, passando dall''essere vicina alla porta a trovarsi più vicina al letto senza che nessuno la tocchi.","en":"When Lucy is dragged into the hotel room by the boss Mr. Jang, the briefcase she was given changes position on the floor between shots, moving from near the door to closer to the bed without anyone touching it.","es":"Cuando Lucy es arrastrada a la habitación del hotel por el jefe Mr. Jang, el maletín que le habían entregado cambia de posición en el suelo entre plano y plano, pasando de estar cerca de la puerta a encontrarse más cerca de la cama sin que nadie lo toque.","fr":"Lorsque Lucy est traînée dans la chambre d''hôtel par le boss Mr. Jang, la mallette qui lui avait été remise change de position sur le sol d''un plan à l''autre, passant de près de la porte à plus près du lit sans que personne ne la touche.","de":"Als Lucy von Boss Mr. Jang in das Hotelzimmer gezerrt wird, verändert der ihr überreichte Aktenkoffer zwischen den Einstellungen seine Position auf dem Boden und wandert von der Tür näher ans Bett, ohne dass ihn jemand berührt."}'::jsonb WHERE id = 5005;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il Professor Norman tiene la sua conferenza all''università della Sorbona a Parigi, le diapositive proiettate sullo schermo alle sue spalle mostrano scansioni cerebrali con etichette in lingua inglese, sebbene un''università francese di tale calibro utilizzi tipicamente materiale didattico in lingua francese.","en":"During the scene where Professor Norman gives his lecture at the Sorbonne University in Paris, the slides projected on the screen behind him show brain scans with English-language labels, even though a French university of that caliber would typically use French-language teaching materials.","es":"Durante la escena en la que el profesor Norman da su conferencia en la Universidad de la Sorbona en París, las diapositivas proyectadas en la pantalla a sus espaldas muestran escáneres cerebrales con etiquetas en inglés, a pesar de que una universidad francesa de ese calibre utilizaría normalmente material didáctico en francés.","fr":"Pendant la scène où le professeur Norman donne sa conférence à l''université de la Sorbonne à Paris, les diapositives projetées sur l''écran derrière lui montrent des scans cérébraux avec des étiquettes en anglais, bien qu''une université française de ce calibre utilise typiquement du matériel pédagogique en français.","de":"In der Szene, in der Professor Norman seine Vorlesung an der Sorbonne-Universität in Paris hält, zeigen die auf die Leinwand hinter ihm projizierten Dias Gehirnscans mit englischsprachigen Beschriftungen, obwohl eine französische Universität dieses Kalibers typischerweise französischsprachiges Lehrmaterial verwenden würde."}'::jsonb WHERE id = 5006;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Lucy si trova nella stanza d''albergo a Parigi e inizia a estrarre i sacchetti di CPH4 dal suo addome, il bisturi che utilizza viene poggiato sul tavolino di vetro. Nell''inquadratura successiva l''utensile si sposta di diversi centimetri e cambia angolazione rispetto al bordo del mobile.","en":"At the moment Lucy is in the hotel room in Paris and begins extracting the bags of CPH4 from her abdomen, the scalpel she uses is placed on the glass coffee table. In the next shot, the tool moves by several centimeters and changes angle relative to the edge of the piece of furniture.","es":"En el momento en que Lucy está en la habitación de hotel en París y comienza a extraer las bolsas de CPH4 de su abdomen, el bisturí que utiliza se coloca sobre la mesa de centro de cristal. En el plano siguiente, la herramienta se desplaza varios centímetros y cambia de ángulo con respecto al borde del mueble.","fr":"Au moment où Lucy se trouve dans la chambre d''hôtel à Paris et commence à extraire les sachets de CPH4 de son abdomen, le bistouris qu''elle utilise est posé sur la table basse en verre. Dans le plan suivant, l''instrument se déplace de plusieurs centimètres et change d''angle par rapport au bord du meuble.","de":"In dem Moment, in dem sich Lucy im Hotelzimmer in Paris befindet und beginnt, die CPH4-Beutel aus ihrem Unterleib zu entfernen, wird das von ihr benutzte Skalpell auf dem Glastisch abgelegt. In der nächsten Einstellung verschiebt sich das Werkzeug um mehrere Zentimeter und ändert seinen Winkel zur Kante des Möbelstücks."}'::jsonb WHERE id = 5007;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui il capitano Del Rio interroga i criminali all''interno della prefettura di polizia a Parigi, in un primo piano riflesso sugli occhiali da sole di uno degli agenti sullo sfondo è brevemente visibile la sagoma di un membro della troupe con unaasta del microfono.","en":"In the sequence where Captain Del Rio interrogates the criminals inside the police headquarters in Paris, in a close-up reflected on the sunglasses of one of the officers in the background, the silhouette of a crew member with a boom mic is briefly visible.","es":"En la secuencia en la que el capitán Del Rio interroga a los criminales dentro de la prefectura de policía en París, en un primer plano reflejado en las gafas de sol de uno de los agentes al fondo se vislumbra brevemente la silueta de un miembro del equipo con una pértiga de micrófono.","fr":"Dans la séquence où le capitaine Del Rio interroge les criminels à l''intérieur de la préfecture de police à Paris, dans un gros plan reflété sur les lunettes de soleil de l''un des agents à l''arrière-plan, la silhouette d''un membre de l''équipe technique avec une perche micro est brièvement visible.","de":"In der Sequenz, in der Hauptkommissar Del Rio die Kriminellen im Polizeipräsidium in Paris verhört, ist in einer Nahaufnahme, die sich in der Sonnenbrille eines der Agenten im Hintergrund spiegelt, kurz die Silhouette eines Crewmitglieds mit einer Tonangel zu sehen."}'::jsonb WHERE id = 5008;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Truman cammina per la città e saluta i vicini, tiene in mano una rivista. Tra un''inquadratura e l''altra, la rivista cambia mano e le pagine si aprono o si chiudono improvvisamente senza che lui compia il gesto.","en":"As Truman walks through town waving to his neighbors, he is holding a magazine. Between cuts, the magazine switches hands and the pages suddenly open or close without him making the motion.","es":"Mientras Truman camina por la ciudad saludando a los vecinos, sostiene una revista. Entre plano y plano, la revista cambia de mano y las páginas se abren o se cierran de repente sin que él haga el gesto.","fr":"Alors que Truman marche en ville en saluant ses voisins, il tient un magazine. D''un plan à l''autre, le magazine change de main et les pages s''ouvrent ou se ferment soudainement sans qu''il n''ait fait le geste.","de":"Während Truman durch die Stadt geht und die Nachbarn grüßt, hält er eine Zeitschrift in der Hand. Zwischen den Einstellungen wechselt die Zeitschrift die Hand und die Blätter öffnen oder schließen sich plötzlich, ohne dass er diese Bewegung macht."}'::jsonb WHERE id = 5009;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Truman si trova nel seminterrato della sua casa e cerca di telefonare, in un angolo dello specchio si riflette brevemente l''ombra di un operatore di ripresa della troupe.","en":"In the scene where Truman is in his basement trying to make a phone call, the shadow of a crew cameraman is briefly reflected in the corner of the mirror.","es":"En la escena en la que Truman está en el sótano de su casa intentando hacer una llamada, en una esquina del espejo se refleja brevemente la sombra de un operador de cámara del equipo.","fr":"Dans la scène où Truman est dans la cave de sa maison et essaie de passer un coup de fil, on aperçoit brièvement l''ombre d''un cadreur de l''équipe technique qui se reflète dans un coin du miroir.","de":"In der Szene, in der sich Truman im Keller seines Hauses befindet und telefonieren möchte, spiegelt sich kurz der Schatten eines Kameramanns der Crew in einer Ecke des Spiegels."}'::jsonb WHERE id = 5010;
UPDATE errori SET descrizione_i18n = '{"it":"Nel salotto di casa Burbank, mentre Meryl guarda la televisione e parla con Truman, la tazza da tè sul tavolino cambia posizione e orientamento del manico in modo evidente tra i vari cambi di inquadratura.","en":"In the Burbank living room, while Meryl watches television and talks to Truman, the teacup on the coffee table noticeably changes position and handle orientation across various camera cuts.","es":"En el salón de la casa de los Burbank, mientras Meryl ve la televisión y habla con Truman, la taza de té en la mesa de centro cambia de posición y la orientación del asa de manera evidente entre los distintos cambios de plano.","fr":"Dans le salon des Burbank, pendant que Meryl regarde la télévision et parle à Truman, la tasse de thé sur la table basse change visiblement de position et d''orientation de l''anse d''un champ/contrechamp à l''autre.","de":"Im Wohnzimmer der Burbanks verändern die Teetasse auf dem Couchtisch und die Ausrichtung ihres Henkels zwischen den verschiedenen Szenenwechseln deutlich ihre Position, während Meryl fernsieht und mit Truman spricht."}'::jsonb WHERE id = 5011;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Truman fugge in auto e viene inseguito dalle auto della produzione, il rumore del motore della sua station wagon cambia improvvisamente passando da un suono a quattro cilindri a un rombo V8 nei diversi stacchi di montaggio.","en":"During the sequence where Truman escapes by car and is chased by production vehicles, the engine noise of his station wagon suddenly shifts from a four-cylinder sound to a V8 roar across different editing cuts.","es":"Durante la secuencia en la que Truman huye en coche y es perseguido por los vehículos de producción, el ruido del motor de su station wagon cambia de repente pasando de un sonido de cuatro cilindros a un rugido V8 en los distintos cortes de montaje.","fr":"Pendant la séquence où Truman s''enfuit en voiture et est poursuivi par les véhicules de la production, le bruit du moteur de son break change soudainement, passant d''un son quatre cylindres à un vrombissement de V8 au fil des coupes de montage.","de":"Während der Sequenz, in der Truman mit dem Auto flieht und von Produktionsfahrzeugen verfolgt wird, wechselt das Motorgeräusch seines Kombis bei den verschiedenen Schnittwechseln plötzlich von einem Vierzylinder-Sound zu einem V8-Brüllen."}'::jsonb WHERE id = 5012;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Truman è legato all''imbarcazione durante la tempesta simulata, la corda che lo trattiene al ponte della barca cambia legatura e tensione tra le inquadrature larghe e i primi piani.","en":"When Truman is tied to the boat during the simulated storm, the rope securing him to the deck changes its knot and tension between the wide shots and close-ups.","es":"Cuando Truman está atado a la embarcación durante la tormenta simulada, la cuerda que lo sujeta a la cubierta cambia de nudo y tensión entre los planos generales y los primeros planos.","fr":"Quand Truman est attaché à l''embarcation pendant la tempête simulée, la corde qui le retient au pont du bateau change de nœud et de tension entre les plans larges et les gros plans.","de":"Als Truman während des simulierten Sturms an das Boot gefesselt ist, verändern sich die Bindung und die Spannung des Seils, das ihn an Deck hält, zwischen den Totalen und den Nahaufnahmen."}'::jsonb WHERE id = 5013;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle scene di battaglia nella foresta, in basso a destra nell''inquadratura è possibile intravedere brevemente l''estremità di un microfono a boom che sbuca tra il fogliame.","en":"During one of the forest battle scenes, the tip of a boom mic can be briefly glimpsed poking out through the foliage in the lower right corner of the shot.","es":"Durante una de las escenas de batalla en el bosque, en la parte inferior derecha del plano se puede vislumbrar brevemente el extremo de un micrófono de pértiga asomando entre el follaje.","fr":"Pendant l''une des scènes de bataille dans la forêt, on peut apercevoir brièvement le bout d''un micro-perche dépassant du feuillage en bas à droite du cadre.","de":"Während einer der Waldschlachtszenen ist unten rechts im Bild kurz die Spitze eines Galgenmikrofons (Boom-Mic) zu sehen, die aus dem Laub herausschaut."}'::jsonb WHERE id = 5014;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Benjamin Martin e i suoi figli lavorano il legno nel portico, gli strumenti appoggiati sul tavolo cambiano posizione e orientamento da un''inquadratura all''altra senza che nessuno li tocchi.","en":"In the scene where Benjamin Martin and his sons are woodworking on the porch, the tools resting on the table change position and orientation from shot to shot without anyone touching them.","es":"En la escena en la que Benjamin Martin y sus hijos trabajan la madera en el porche, las herramientas apoyadas en la mesa cambian de posición y orientación de un plano a otro sin que nadie las toque.","fr":"Dans la scène où Benjamin Martin et ses fils travaillent le bois sur le porche, les outils posés sur la table changent de position et d''orientation d''un plan à l''autre sans que personne ne les touche.","de":"In der Szene, in der Benjamin Martin und seine Söhne auf der Veranda Holz bearbeiten, verändern die auf dem Tisch liegenden Werkzeuge von Einstellung zu Einstellung ihre Position und Ausrichtung, ohne dass sie jemand berührt."}'::jsonb WHERE id = 5015;
UPDATE errori SET descrizione_i18n = '{"it":"Durante gli scontri della battaglia finale, un soldato britannico cade a terra colpito, ma nell''inquadratura successiva a campo largo lo stesso attore si vede chiaramente rialzarsi e correre via sullo sfondo.","en":"During the final battle skirmishes, a British soldier falls to the ground hit, but in the subsequent wide shot, the same actor is clearly seen getting back up and running away in the background.","es":"Durante los combates de la batalla final, un soldado británico cae al suelo herido, pero en el plano general siguiente se ve claramente al mismo actor levantarse y huir al fondo.","fr":"Pendant les accrochages de la bataille finale, un soldat britannique s''effondre au sol, touché, mais sur le plan large suivant, on voit clairement le même acteur se relever et s''enfuir à l''arrière-plan.","de":"Während der Gefechte der Schlussschlacht geht ein britischer Soldat getroffen zu Boden, aber in der folgenden Totalen ist deutlich zu sehen, wie derselbe Schauspieler wieder aufsteht und im Hintergrund davonläuft."}'::jsonb WHERE id = 5016;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la drammatica scena in cui Gabriel Martin viene colpito a morte, la posizione del corpo e il modo in cui giace a terra variano sensibilmente tra l''inquadratura iniziale in campo medio e il successivo primo piano sul volto disperato di Benjamin.","en":"During the dramatic scene where Gabriel Martin is fatally shot, his body position and the way he lies on the ground change noticeably between the initial medium shot and the subsequent close-up on Benjamin''s desperate face.","es":"Durante la dramática escena en la que Gabriel Martin recibe un disparo mortal, la posición de su cuerpo y la forma en que yace en el suelo varían notablemente entre el plano medio inicial y el posterior primer plano del rostro desesperado de Benjamin.","fr":"Pendant la scène dramatique où Gabriel Martin est mortellement touché, la position de son corps et sa façon d''être allongé changent sensiblement entre le plan moyen initial et le gros plan suivant sur le visage désespéré de Benjamin.","de":"Während der dramatischen Szene, in der Gabriel Martin tödlich getroffen wird, verändern sich seine Körperposition und die Art, wie er auf dem Boden liegt, deutlich zwischen der anfänglichen halbtoten Einstellung (Medium Shot) und der darauffolgenden Nahaufnahme von Benjamins verzweifeltem Gesicht."}'::jsonb WHERE id = 5017;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso di una delle scene all''interno della fattoria, si possono notare alcuni chiodi a testa piatta di fabbricazione industriale moderna utilizzati per assemblare parti del mobilio in legno, anziché i tradizionali chiodi forgiati a mano dell''epoca coloniale.","en":"During one of the scenes inside the farmhouse, some modern industrially manufactured flat-head nails can be spotted assembling parts of the wooden furniture, instead of the traditional hand-forged nails of the colonial era.","es":"Durante una de las escenas dentro de la granja, se pueden ver algunos clavos de cabeza plana de fabricación industrial moderna utilizados para ensamblar partes de los muebles de madera, en lugar de los tradicionales clavos forjados a mano de la época colonial.","fr":"Dans l''une des scènes à l''intérieur de la ferme, on peut apercevoir des clous à tête plate de fabrication industrielle moderne utilisés pour assembler des parties du mobilier en bois, au lieu des traditionnels clous forgés à main de l''époque coloniale.","de":"In einer der Szenen im Inneren des Farmhauses sind einige modern industriell gefertigte Flachkopfnägel zu sehen, die zur Montage von Holzmöbeln verwendet wurden, anstelle der traditionellen handgeschmiedeten Nägel der Kolonialzeit."}'::jsonb WHERE id = 5018;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia decisiva, i cannoni dell''esercito britannico sparano con una cadenza di tiro e una gittata notevolmente superiori rispetto alle capacità effettive dell''artiglieria leggera da campagna utilizzata nel 1781 durante la guerra d''indipendenza.","en":"During the decisive battle, the British army cannons fire with a rate of fire and range significantly greater than the actual capabilities of the light field artillery used in 1781 during the Revolutionary War.","es":"Durante la batalla decisiva, los cañones del ejército británico disparan con una cadencia de fuego y un alcance considerablemente superiores a las capacidades reales de la artillería ligera de campaña utilizada en 1781 durante la Guerra de Independencia.","fr":"Pendant la bataille décisive, les canons de l''armée britannique tirent avec une cadence de tir et une portée nettement supérieures aux capacités réelles de l''artillerie légère de campagne utilisée en 1781 pendant la guerre d''indépendance.","de":"Während der Entscheidungsschlacht schießen die Kanonen der britischen Armee mit einer Feuerate und Reichweite, die deutlich über den tatsächlichen Fähigkeiten der leichten Feldartillerie liegen, die 1781 während des Unabhängigkeitskrieges eingesetzt wurde."}'::jsonb WHERE id = 5019;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle scene all''aperto, il bicchiere di tè freddo tenuto da uno dei personaggi cambia livello di riempimento e posizione della cannuccia tra un''inquadratura e la successiva.","en":"During one of the outdoor scenes, the glass of iced tea held by one of the characters changes its fill level and straw position between one shot and the next.","es":"Durante una de las escenas al aire libre, el vaso de té helado que sostiene uno de los personajes cambia su nivel de llenado y la posición de la pajita entre un plano y el siguiente.","fr":"Pendant l''une des scènes en extérieur, le verre de thé glacé tenu par l''un des personnages change de niveau de remplissage et de position de paille d''un plan à l''autre.","de":"Während einer der Außenszenen verändert sich der Füllstand des Eistees und die Position des Strohhalms in dem Glas, das einer der Figuren hält, zwischen den einzelnen Einstellungen."}'::jsonb WHERE id = 5020;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle sequenze in cui i veicoli circolano per le strade del Mississippi, le auto parcheggiate sullo sfondo cambiano modello e posizione tra le inquadrature adiacenti.","en":"In the sequences where vehicles drive through the streets of Mississippi, the parked cars in the background change models and positions between adjacent shots.","es":"En las secuencias en las que los vehículos circulan por las calles de Mississippi, los coches aparcados al fondo cambian de modelo y posición entre planos adyacentes.","fr":"Dans les séquences où les véhicules circulant dans les rues du Mississippi apparaissent, les voitures garées en arrière-plan changent de modèle et de position d''un plan à l''autre.","de":"In den Sequenzen, in denen Fahrzeuge durch die Straßen von Mississippi fahren, wechseln die parkenden Autos im Hintergrund zwischen benachbarten Einstellungen sowohl das Modell als auch die Position."}'::jsonb WHERE id = 5021;
UPDATE errori SET descrizione_i18n = '{"it":"Essendo il film ambientato nel 1985 (anno in cui si svolge il romanzo originale di John Grisham, sebbene il film adotti una collocazione temporale contemporanea agli anni ''90), compaiono occasionalmente modelli di automobili o elementi architettonici leggermente posteriori all''anno di riferimento.","en":"Since the film is set in 1985 (the year of John Grisham''s original novel, although the film adopts a contemporary 1990s setting), car models or architectural elements slightly later than the reference year occasionally appear.","es":"Dado que la película está ambientada en 1985 (año en que transcurre la novela original de John Grisham, aunque la película adopta una ambientación contemporánea de los años 90), aparecen ocasionalmente modelos de automóviles o elementos arquitectónicos ligeramente posteriores al año de referencia.","fr":"Le film se déroulant en 1985 (l''année du roman original de John Grisham, bien que le film adopte une période contemporaine des années 90), on y aperçoit occasionnellement des modèles de voitures ou des éléments architecturaux légèrement postérieurs à l''année de référence.","de":"Da der Film im Jahr 1985 spielt (dem Jahr des Originalromans von John Grisham, obwohl der Film eine zeitliche Einordnung in die 1990er Jahre wählt), tauchen gelegentlich Automodelle oder architektonische Elemente auf, die etwas später als das Referenzjahr sind."}'::jsonb WHERE id = 5022;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Anton Chigurh usa il fucile da macello pneumatico per aprire la serratura della porta dell''ufficio, la bombola di gas collegata cambia leggermente posizione e orientamento rispetto al tubo tra un''inquadratura e l''altra.","en":"When Anton Chigurh uses the pneumatic captive bolt pistol to open the office door lock, the attached gas cylinder slightly changes position and orientation relative to the hose between shots.","es":"Cuando Anton Chigurh usa la pistola de perno cautivo neumática para abrir la cerradura de la puerta de la oficina, la bombona de gas conectada cambia ligeramente de posición y orientación con respecto a la manguera entre plano y plano.","fr":"Quand Anton Chigurh utilise le pistolet d''abattage pneumatique pour ouvrir la serrure de la porte du bureau, la bouteille de gaz raccordée change légèrement de position et d''orientation par rapport au tuyau d''un plan à l''autre.","de":"Als Anton Chigurh die pneumatische Bolzenschussgerät benutzt, um das Bürotürschloss zu öffnen, verändern sich die Position und Ausrichtung der angeschlossenen Gasflasche in Bezug auf den Schlauch zwischen den Einstellungen leicht."}'::jsonb WHERE id = 5023;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Llewelyn Moss acquista gli stivali da un adolescente sulla strada, lo sfondo mostra vari cartelli stradali e modelli di pick-up che presentano riflettori e dettagli di omologazione stradale introdotti negli Stati Uniti solo verso la fine degli anni ''90.","en":"In the scene where Llewelyn Moss buys boots from a teenager on the road, the background features various road signs and pickup truck models displaying reflectors and road-approval details introduced in the US only in the late 1990s.","es":"En la escena en la que Llewelyn Moss le compra las botas a un adolescente en la carretera, el fondo muestra varias señales de tráfico y modelos de camionetas pickup que presentan reflectores y detalles de homologación vial introducidos en EE. UU. solo a finales de los 90.","fr":"Dans la scène où Llewelyn Moss achète des bottes à un adolescent sur la route, l''arrière-plan montre divers panneaux de signalisation et modèles de pick-up dotés de réflecteurs et de détails d''homologation routière introduits aux États-Unis seulement vers la fin des années 90.","de":"In der Szene, in der Llewelyn Moss einem Jugendlichen am Straßenrand Stiefel abkauft, sind im Hintergrund verschiedene Straßenschilder und Pick-up-Modelle zu sehen, die Reflektoren und Straßenzulassungsdetails aufweisen, die erst in den späten 1990er Jahren in den USA eingeführt wurden."}'::jsonb WHERE id = 5024;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza dell''inseguimento nel deserto tra Moss e Chigurh, le targhe dei veicoli della polizia di frontiera e delle auto locali mostrano combinazioni di lettere e numeri e adesivi di immatricolazione annuali non conformi al sistema utilizzato nel Texas nel 1980.","en":"During the desert chase sequence between Moss and Chigurh, the license plates on the border patrol vehicles and local cars feature letter-number combinations and annual registration stickers that do not match the system used in Texas in 1980.","es":"Durante la secuencia de la persecución en el desierto entre Moss y Chigurh, las placas de los vehículos de la patrulla fronteriza y de los autos locales muestran combinaciones de letras y números y calcomanías de matriculación anual que no coinciden con el sistema utilizado en Texas en 1980.","fr":"Pendant la séquence de poursuite dans le désert entre Moss et Chigurh, les plaques d''immatriculation des véhicules de la patrouille frontalière et des voitures locales affichent des combinaisons de lettres et de chiffres ainsi que des vignettes de contrôle annuelles non conformes au système en vigueur au Texas en 1980.","de":"Während der Wüstenverfolgungsszene zwischen Moss und Chigurh zeigen die Nummernschilder der Grenzschutzfahrzeuge und der lokalen Autos Buchstaben-Zahlen-Kombinationen und Jahres-Prüfplaketten, die nicht dem 1980 in Texas verwendeten System entsprechen."}'::jsonb WHERE id = 5025;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui lo sceriffo Ed Tom Bell visita lo zio Ellis, la tazza da caffè che Ellis tiene in mano cambia livello di riempimento e impugnatura tra i diversi campi e controcampi della conversazione.","en":"In the scene where Sheriff Ed Tom Bell visits Uncle Ellis, the coffee mug Ellis is holding changes its fill level and how it is gripped across the shot-reverse-shot cuts of the conversation.","es":"En la escena en la que el sheriff Ed Tom Bell visita al tío Ellis, la taza de café que sostiene Ellis cambia de nivel de llenado y de forma de agarre entre los planos y contraplanos de la conversación.","fr":"Dans la scène où le shérif Ed Tom Bell rend visite à son oncle Ellis, la tasse de café que tient Ellis change de niveau de remplissage et de prise en main au fil des champs et contre-champs de la conversation.","de":"In der Szene, in der Sheriff Ed Tom Bell Onkel Ellis besucht, ändern sich der Füllstand der Kaffeetasse, die Ellis hält, sowie die Art und Weise, wie er sie greift, zwischen den Schuss-Gegenschuss-Einstellungen des Gesprächs."}'::jsonb WHERE id = 5026;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il sergente Hartman interroga le reclute nel dormitorio, la rivista che un marine tenuto in mano cambia posizione e orientamento tra un''inquadratura e l''altra.","en":"During the scene where Sergeant Hartman interrogates the recruits in the barracks, the magazine a marine is holding changes position and orientation from one shot to the next.","es":"Durante la escena en la que el sargento Hartman interroga a los reclutas en el dormitorio, la revista que sostiene un marine cambia de posición y orientación de un plano a otro.","fr":"Pendant la scène où le sergent Hartman interroge les recrus dans le dortoir, le magazine qu''un marine tient à la main change de position et d''orientation d''un plan à l''autre.","de":"Während der Szene, in der Sergeant Hartman die Rekruten im Wohnheim verhört, wechseln Position und Ausrichtung des Magazins, das ein Marine hält, von einer Einstellung zur nächsten."}'::jsonb WHERE id = 5027;
UPDATE errori SET descrizione_i18n = '{"it":"Nella prima parte del film, ambientata nel 1967, si possono notare alcuni dettagli dell''equipaggiamento e della base che appartengono a specifiche produzioni successive o non coerenti con il periodo esatto.","en":"In the first part of the film, set in 1967, some equipment and base details can be spotted that belong to specific later productions or are inconsistent with the exact period.","es":"En la primera parte de la película, ambientada en 1967, se pueden apreciar algunos detalles del equipamiento y de la base que pertenecen a producciones posteriores específicas o que no son coherentes con la época exacta.","fr":"Dans la première partie du film, qui se déroule en 1967, on peut remarquer certains détails de l''équipement et de la base qui proviennent de productions ultérieures spécifiques ou qui ne sont pas cohérents avec la période exacte.","de":"Im ersten Teil des Films, der 1967 spielt, sind einige Ausstattungs- und Basisdetails zu erkennen, die zu bestimmten späteren Produktionen gehören oder nicht mit der exakten Zeitperiode übereinstimmen."}'::jsonb WHERE id = 5028;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i combattimenti urbani a Huế, in un''inquadratura ravvicinata tra le macerie, si intravede brevemente l''attrezzatura della troupe riflessa sulla visiera di un elmetto.","en":"During the urban combat in Huế, in a close-up shot among the rubble, the crew''s equipment can be briefly glimpsed reflected on a helmet visor.","es":"Durante los combates urbanos en Huế, en un plano corto entre los escombros, se puede vislumbrar brevemente el equipo del equipo de rodaje reflejado en la visera de un casco.","fr":"Pendant les combats urbains à Huế, dans un plan serré au milieu des débris, on aperçoit brièvement l''équipement de l''équipe de tournage se refléter sur la visière d''un casque.","de":"Während der Häuserkämpfe in Huế ist in einer Nahaufnahme zwischen den Trümmern kurz das Equipment der Filmcrew auf dem Visier eines Helms spiegelnd zu erkennen."}'::jsonb WHERE id = 5029;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sparatoria contro il cecchino invisibile, la quantità di fumo e macerie attorno ai soldati varia drasticamente tra i campi medi e i primi piani consecutivi.","en":"During the shootout against the unseen sniper, the amount of smoke and rubble around the soldiers varies drastically between the medium shots and the consecutive close-ups.","es":"Durante el tiroteo contra el francotirador invisible, la cantidad de humo y escombros alrededor de los soldados varía drásticamente entre los planos medios y los primeros planos consecutivos.","fr":"Au cours de la fusillade contre le tireur embusqué invisible, la quantité de fumée et de débris autour des soldats varie considérablement entre les plans moyens et les gros plans consécutifs.","de":"Während des Schusswechsels mit dem unsichtbaren Scharfschützen variiert die Menge an Rauch und Trümmern um die Soldaten drastisch zwischen den Halbtotale-Einstellungen und den aufeinanderfolgenden Nahaufnahmen."}'::jsonb WHERE id = 5030;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui il Presidente Whitmore e gli altri ufficiali pianificano la missione nell''Area 51, le cartine e i documenti sparsi sulla console centrale cambiano disposizione e posizione esatta tra i primi piani e le inquadrature a campo largo.","en":"During the sequence where President Whitmore and the other officers plan the mission in Area 51, the maps and documents scattered on the central console change their layout and exact position between the close-ups and the wide shots.","es":"Durante la secuencia en la que el presidente Whitmore y los demás oficiales planifican la misión en el Área 51, los mapas y documentos esparcidos por la consola central cambian de disposición y posición exacta entre los primeros planos y los planos generales.","fr":"Pendant la séquence où le président Whitmore et les autres officiers planifient la mission dans la Zone 51, les cartes et les documents éparpillés sur la console centrale changent de disposition et de position exacte entre les gros plans et les plans larges.","de":"Während der Sequenz, in der Präsident Whitmore und die anderen Offiziere die Mission in Area 51 planen, ändern die auf der Mittelkonsole verstreuten Karten und Dokumente ihre Anordnung und exakte Position zwischen den Nahaufnahmen und den Totaleinstellungen."}'::jsonb WHERE id = 5031;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Eliot Ness guida la sua auto per le strade di Chicago, si possono notare nel traffico o parcheggiati alcuni modelli di automobili (come berline o camioncini) prodotti diversi anni dopo il 1930, anno in cui è ambientata la storia.","en":"During the sequence where Eliot Ness drives his car through the streets of Chicago, some car models (such as sedans or pickup trucks) can be spotted in traffic or parked that were manufactured several years after 1930, the year in which the story is set.","es":"Durante la secuencia en la que Eliot Ness conduce su coche por las calles de Chicago, se pueden ver en el tráfico o aparcados algunos modelos de automóviles (como berlinas o camionetas) fabricados varios años después de 1930, año en el que se ambienta la historia.","fr":"Pendant la séquence où Eliot Ness conduit sa voiture dans les rues de Chicago, on peut apercevoir dans la circulation ou garés certains modèles de voitures (tels que des berlines ou des pick-up) produits plusieurs années après 1930, année où se déroule l''histoire.","de":"Während der Sequenz, in der Eliot Ness mit seinem Auto durch die Straßen von Chicago fährt, sind im Verkehr oder parkend einige Automobilmodelle (wie Limousinen oder Pick-ups) zu sehen, die erst einige Jahre nach 1930 – dem Handlungsjahr der Geschichte – hergestellt wurden."}'::jsonb WHERE id = 5032;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena del caveau in Canada, durante il conflitto a fuoco iniziale, un milite della polizia canadese viene colpito e cade vicino a delle casse di alcolici. Nei cambi di inquadratura successivi, la posizione del corpo e le armi cadute attorno ad esso variano sensibilmente.","en":"In the Canadian vault scene, during the initial shootout, a Canadian Mountie is shot and falls near some crates of liquor. In subsequent shot/reverse-shot setups, the body''s position and the dropped weapons around it change noticeably.","es":"En la escena de la cámara acorazada en Canadá, durante el tiroteo inicial, un policía montado canadiense recibe un disparo y cae cerca de unas cajas de licor. En los cambios de plano sucesivos, la posición del cuerpo y las armas caídas a su alrededor varían notablemente.","fr":"Dans la scène du coffre-fort au Canada, lors de la fusillade initiale, un officier de la police montée canadienne est touché et tombe près de caisses d''alcool. Dans les champs-contrechamps suivants, la position du corps et les armes tombées autour de lui changent sensiblement.","de":"In der Tresorszene in Kanada wird während des anfänglichen Feuergefechts ein kanadischer Polizist getroffen und fällt in die Nähe von Alkoholkisten. In den darauffolgenden Kameraeinstellungen verändern sich die Position des Körpers und die um ihn herumliegenden Waffen deutlich."}'::jsonb WHERE id = 5033;
UPDATE errori SET descrizione_i18n = '{"it":"Le armi automatiche e i fucili a pompa branditi da alcuni membri della banda di Al Capone e dagli agenti federali includono modelli di anni successivi o configurazioni non storicamente accurate per i primi anni trenta del proibizionismo.","en":"The automatic weapons and shotguns brandished by some members of Al Capone''s gang and federal agents include later models or configurations that are not historically accurate for the early 1930s Prohibition era.","es":"Las armas automáticas y escopetas blandidas por algunos miembros de la banda de Al Capone y los agentes federales incluyen modelos de años posteriores o configuraciones históricamente inexactas para principios de los años treinta de la época de la ley seca.","fr":"Les armes automatiques et les fusils à pompe brandis par certains membres du gang d''Al Capone et les agents fédéraux incluent des modèles d''années ultérieures ou des configurations historiquement inexactes pour le début des années 1930, à l''époque de la Prohibition.","de":"Die Maschinenpistolen und Schrotflinten, die von einigen Mitgliedern von Al Capones Gang und Bundesagenten geschwungen werden, beinhalten Modelle aus späteren Jahren oder Konfigurationen, die für die frühen 1930er Jahre zur Zeit der Prohibition historisch nicht korrekt sind."}'::jsonb WHERE id = 5034;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Jim Malone (Sean Connery) viene sorpreso dall''assassino nel suo appartamento, l''uomo armato rompe una vetrata della porta d''ingresso. Subito dopo, in alcune inquadratura ravvicinate, i frammenti di vetro sul pavimento cambiano disposizione e quantità tra un taglio e l''altro.","en":"When Jim Malone (Sean Connery) is ambushed by the assassin in his apartment, the gunman breaks a glass panel on the front door. Immediately after, in a few close-ups, the glass fragments on the floor change arrangement and quantity between cuts.","es":"En el momento en que Jim Malone (Sean Connery) es sorprendido por el asesino en su apartamento, el pistolero rompe un panel de vidrio de la puerta de entrada. Justo después, en algunos primeros planos, los fragmentos de vidrio en el suelo cambian de disposición y cantidad entre corte y corte.","fr":"Au moment où Jim Malone (Sean Connery) est surpris par l''assassin dans son appartement, l''homme armé brise un panneau vitré de la porte d''entrée. Juste après, dans certains gros plans, les fragments de verre sur le sol changent de disposition et de quantité d''un raccord à l''autre.","de":"In dem Moment, in dem Jim Malone (Sean Connery) von dem Mörder in seiner Wohnung überrascht wird, schlägt der bewaffnete Mann eine Glasscheibe der Haustür ein. Unmittelbar danach verändern sich in einigen Nahaufnahmen die Anordnung und Menge der Glasscherben auf dem Boden zwischen den Schnittwechseln."}'::jsonb WHERE id = 5035;
UPDATE errori SET descrizione_i18n = '{"it":"La cartellonistica e le insegne stradali visibili sullo sfondo in alcune scene esterne girate a Chicago mostrano font di caratteri tipografici e segnaletica moderna non coerente con l''estetica urbana degli anni trenta.","en":"The billboards and street signs visible in the background of certain exterior scenes shot in Chicago feature modern typefaces and signage that are inconsistent with the 1930s urban aesthetic.","es":"La cartelería y las señales de tráfico visibles al fondo en algunas escenas exteriores rodadas en Chicago muestran fuentes tipográficas y señalización moderna que no son coherentes con la estética urbana de los años treinta.","fr":"Les panneaux d''affichage et les signalisations routières visibles en arrière-plan dans certaines scènes d''extérieur tournées à Chicago présentent des polices de caractères et une signalétique modernes qui ne correspondent pas à l''esthétique urbaine des années 1930.","de":"Die Plakate und Straßenschilder, die im Hintergrund einiger in Chicago gedrehten Außenaufnahmen zu sehen sind, weisen moderne Schriftarten und Beschilderungen auf, die nicht zur urbanen Ästhetik der 1930er Jahre passen."}'::jsonb WHERE id = 5036;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la troupe sbarca su Skull Island e assiste alla cerimonia dei nativi, in alcune inquadrature ad ampio raggio i membri della troupe (come Jack Driscoll e Carl Denham) cambiano posizione di diversi metri rispetto ai tagli di montaggio precedenti.","en":"When the film crew lands on Skull Island and witnesses the native ceremony, in certain wide shots the crew members (like Jack Driscoll and Carl Denham) change positions by several meters compared to the previous editing cuts.","es":"Cuando el equipo de filmación desembarca en Skull Island y asiste a la ceremonia de los nativos, en algunos planos generales los miembros del equipo (como Jack Driscoll y Carl Denham) cambian de posición varios metros en comparación con los cortes de montaje anteriores.","fr":"Lorsque l''équipe de tournage débarque sur Skull Island et assiste à la cérémonie des natifs, dans certains plans larges, les membres de l''équipe (comme Jack Driscoll et Carl Denham) changent de position de plusieurs mètres par rapport aux coupes de montage précédentes.","de":"Als die Filmcrew auf Skull Island landet und der Zeremonie der Eingeborenen beiwohnt, verändern die Crewmitglieder (wie Jack Driscoll und Carl Denham) in einigen Totalen ihre Position im Vergleich zu den vorherigen Montagecuts um mehrere Meter."}'::jsonb WHERE id = 5037;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui il gigantesco stegosauro attacca i marinai nella giungla, la vegetazione circostante e gli alberi calpestati o distrutti appaiono e scompaiono misteriosamente tra un''inquadratura in live-action e i modellini in stop-motion.","en":"In the scene where the giant stegosaurus attacks the sailors in the jungle, the surrounding vegetation and the trampled or destroyed trees mysteriously appear and disappear between live-action footage and stop-motion animation models.","es":"En la escena en la que el estegosaurio gigante ataca a los marineros en la selva, la vegetación circundante y los árboles pisoteados o destruidos aparecen y desaparecen misteriosamente entre los planos de acción real y las maquetas en stop-motion.","fr":"Dans la scène où le stégosaure géant attaque les marins dans la jungle, la végétation environnante et les arbres piétinés ou détruits apparaissent et disparaissent mystérieusement entre les plans en prise de vue réelle et les maquettes en stop-motion.","de":"In der Szene, in der der riesige Stegosaurus die Matrosen im Dschungel angreift, taucht die umliegende Vegetation und die zertretenen oder zerstörten Bäume zwischen Live-Action-Aufnahmen und Stop-Motion-Modellen auf mysteriöse Weise auf und verschwindet wieder."}'::jsonb WHERE id = 5038;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la cattura di Kong sull''isola, i marinai usano una bombola di gas per stordirlo. La posizione della maschera e del tubo di erogazione cambia nettamente tra l''inquadratura ravvicinata e quella larga.","en":"During Kong''s capture on the island, the sailors use a gas canister to knock him out. The position of the mask and the delivery hose changes markedly between the close-up and the wide shot.","es":"Durante la captura de Kong en la isla, los marineros usan una bombona de gas para aturdirlo. La posición de la máscara y el tubo de suministro cambia notablemente entre el plano cerrado y el plano general.","fr":"Pendant la capture de Kong sur l''île, les marins utilisent une bonbonne de gaz pour l''assommer. La position du masque et du tuyau d''alimentation change nettement entre le gros plan et le plan large.","de":"Während der Gefangennahme von Kong auf der Insel benutzen die Matrosen eine Gasflasche, um ihn zu betäuben. Die Position der Maske und des Zufuhrschlauchs verändert sich deutlich zwischen der Nahaufnahme und der Totalen."}'::jsonb WHERE id = 5039;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Kong viene esibito incatenato sul palco a New York, le catene di metallo pesanti che lo bloccano cambiano spessore e tipo di maglia a seconda che si tratti del gorilla animatronico in primo piano o della ripresa con i modellini in stop-motion.","en":"When Kong is exhibited chained on stage in New York, the heavy metal chains restraining him change in thickness and link type depending on whether it''s the animatronic gorilla in close-up or the stop-motion puppet shot.","es":"Cuando Kong es exhibido encadenado en el escenario en Nueva York, las pesadas cadenas de metal que lo sujetan cambian de grosor y de tipo de eslabón según se trate del gorila animatrónico en primer plano o de la toma con maquetas en stop-motion.","fr":"Lorsque Kong est exposé enchaîné sur scène à New York, les lourdes chaînes en métal qui le retiennent changent d''épaisseur et de type de maillon selon qu''il s''agit du gorille animatronique en gros plan ou du plan avec les marionnettes en stop-motion.","de":"Als Kong auf der Bühne in New York angekettet zur Schau gestellt wird, verändern sich die schweren Metallketten, die ihn festhalten, in ihrer Dicke und Gliederart, je nachdem, ob es sich um den animatronischen Gorilla in der Nahaufnahme oder um die Aufnahme mit den Stop-Motion-Puppen handelt."}'::jsonb WHERE id = 5040;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la fuga di Kong per le strade di New York, le auto della polizia ribaltate e distrutte cambiano modello e posizione esatta della targa tra un''inquadratura e l''altra.","en":"During Kong''s rampage through the streets of New York, the overturned and wrecked police cars change models and exact license plate positions between shots.","es":"Durante la huida de Kong por las calles de Nueva York, los coches de policía volcado y destrozados cambian de modelo y de posición exacta de la matrícula entre plano y plano.","fr":"Pendant la cavale de Kong dans les rues de New York, les voitures de police retournées et détruites changent de modèle et d''emplacement exact de plaque d''immatriculation d''un plan à l''autre.","de":"Während Kongs Wutanfall in den Straßen von New York wechseln die umgestürzten und zerstörten Polizeiautos zwischen den Einstellungen in Modell und genauer Position des Nummernschilds."}'::jsonb WHERE id = 5041;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Fred Wilson (Charles Grodin) si avvicina alla gabbia di King Kong sulla nave, la bottiglia che tiene in mano cambia posizione e livello di riempimento tra un''inquadratura e l''altra.","en":"When Fred Wilson (Charles Grodin) approaches King Kong''s cage on the ship, the bottle he is holding changes position and fill level between cuts.","es":"Cuando Fred Wilson (Charles Grodin) se acerca a la jaula de King Kong en el barco, la botella que sostiene cambia de posición y de nivel de líquido entre un plano y otro.","fr":"Quand Fred Wilson (Charles Grodin) s''approche de la cage de King Kong sur le navire, la bouteille qu''il tient à la main change de position et de niveau de remplissage d''un plan à l''autre.","de":"Als sich Fred Wilson (Charles Grodin) auf dem Schiff King Kongs Käfig nähert, verändern sich Position und Füllstand der Flasche, die er in der Hand hält, von Einstellung zu Einstellung."}'::jsonb WHERE id = 5042;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza nella giungla in cui Jack Prescott (Jeff Bridges) e Dwan (Jessica Lange) scappano dagli indigeni, in basso a destra dell''inquadratura è possibile intravedere brevemente l''ombra di un operatore di macchina sulla vegetazione.","en":"During the jungle sequence where Jack Prescott (Jeff Bridges) and Dwan (Jessica Lange) escape from the natives, the shadow of a camera operator can be briefly glimpsed on the foliage in the bottom right of the frame.","es":"Durante la secuencia en la selva en la que Jack Prescott (Jeff Bridges) y Dwan (Jessica Lange) huyen de los indígenas, en la parte inferior derecha del encuadre se puede atisbar brevemente la sombra de un operador de cámara sobre la vegetación.","fr":"Pendant la séquence dans la jungle où Jack Prescott (Jeff Bridges) et Dwan (Jessica Lange) échappent aux indigènes, on peut entrapercevoir brièvement l''ombre d''un cadreur sur la végétation en bas à droite du cadre.","de":"Während der Dschungelszene, in der Jack Prescott (Jeff Bridges) und Dwan (Jessica Lange) vor den Eingeborenen fliehen, ist unten rechts im Bild kurz der Schatten eines Kameraoperators auf der Vegetation zu sehen."}'::jsonb WHERE id = 5043;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena dell''arrivo della nave da carico con King Kong a New York, le manovre di attracco e i rimorchiatori visibili sullo sfondo non corrispondono alle procedure portuali reali dell''epoca per quel tipo di imbarcazione.","en":"In the scene of the cargo ship''s arrival with King Kong in New York, the docking maneuvers and the tugboats visible in the background do not match actual port procedures of the era for that type of vessel.","es":"En la escena de la llegada del carguero con King Kong a Nueva York, las maniobras de atraque y los remolcadores visibles al fondo no se corresponden con los procedimientos portuarios reales de la época para ese tipo de embarcación.","fr":"Dans la scène de l''arrivée du cargo transportant King Kong à New York, les manœuvres d''amarrage et les remorqueurs visibles à l''arrière-plan ne correspondent pas aux réelles procédures portuaires de l''époque pour ce type de navire.","de":"In der Szene der Ankunft des Frachtschiffs mit King Kong in New York entsprechen die Manöver beim Anlegen und die im Hintergrund sichtbaren Schlepper nicht den tatsächlichen Hafenverfahren jener Epoche für diesen Schiffstyp."}'::jsonb WHERE id = 5044;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il climax sul World Trade Center, le ferite e i graffi sul petto e sulle braccia di King Kong variano in modo evidente per forma e intensità tra le inquadrature in studio con il pupazzo meccanico e quelle con l''attore nel costume.","en":"During the climax on the World Trade Center, the wounds and scratches on King Kong''s chest and arms vary noticeably in shape and intensity between the studio shots featuring the mechanical puppet and those with the actor in the suit.","es":"Durante el clímax en el World Trade Center, las heridas y los rasguños en el pecho y los brazos de King Kong varían de forma evidente en cuanto a forma e intensidad entre los planos en plató con el animatronic y los que muestran al actor con el disfraz.","fr":"Pendant le climax sur le World Trade Center, les blessures et les égratignures sur la poitrine et les bras de King Kong varient de manière évidente en forme et en intensité entre les plans en studio avec la marionnette mécanique et ceux avec l''acteur dans le costume.","de":"Während des Höhepunkts auf dem World Trade Center variieren die Wunden und Kratzer auf King Kongs Brust und Armen in Form und Intensität deutlich zwischen den Studioaufnahmen mit der mechanischen Puppe und denen mit dem Darsteller im Kostüm."}'::jsonb WHERE id = 5045;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sala comando della nave della Petrox, alcuni strumenti di navigazione e monitor sullo sfondo mostrano componenti elettroniche e display digitali non ancora esistenti o diffusi nel periodo in cui è ambientata la storia.","en":"In the control room of the Petrox ship, some navigation instruments and background monitors display electronic components and digital screens that did not yet exist or were not widespread during the story''s setting.","es":"En la sala de control del barco de Petrox, algunos instrumentos de navegación y monitores del fondo muestran componentes electrónicos y pantallas digitales que aún no existían o no estaban extendidos en la época en que se ambienta la historia.","fr":"Dans la salle de commandement du navire de la Petrox, certains instruments de navigation et moniteurs en arrière-plan affichent des composants électroniques et des écrans numériques qui n''existaient pas encore ou n''étaient pas répandus à l''époque où se déroule l''histoire.","de":"In der Kommandozentrale des Petrox-Schiffs zeigen einige Navigationsinstrumente und Monitore im Hintergrund elektronische Bauteile und Digitaldisplays, die zu der Zeit, in der die Handlung spielt, noch gar nicht existierten oder verbreitet waren."}'::jsonb WHERE id = 5046;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la troupe sale a bordo della Venture, la quantità di bagagli e casse sul ponte cambia visibilmente di posizione e numero tra l''inquadratura larga d''insieme e i primi piani sui singoli attori.","en":"When the crew boards the Venture, the amount of luggage and crates on deck visibly changes position and number between the wide establishing shot and the close-ups on individual actors.","es":"Cuando la tripulación sube a bordo del Venture, la cantidad de equipaje y cajas en cubierta cambia visiblemente de posición y número entre el plano general y los primeros planos de los actores.","fr":"Quand l''équipe monte à bord du Venture, la quantité de bagages et de caisses sur le pont change visiblement de position et de nombre entre le plan large d''ensemble et les gros plans sur les acteurs individuels.","de":"Als die Crew an Bord der Venture geht, verändern sich Anzahl und Position des Gepäcks und der Kisten an Deck zwischen der Totalen und den Nahaufnahmen der einzelnen Schauspieler sichtbar."}'::jsonb WHERE id = 5047;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le scene ambientate nel 1933 sull''isola, alcune delle attrezzature fotografiche e di illuminazione di Carl Denham mostrano dettagli di componenti meccaniche e finiture che sarebbero state introdotte solo decenni più tardi.","en":"During the scenes set in 1933 on the island, some of Carl Denham''s camera and lighting equipment show mechanical component details and finishes that would only be introduced decades later.","es":"Durante las escenas ambientadas en 1933 en la isla, algunos de los equipos fotográficos y de iluminación de Carl Denham muestran detalles de componentes mecánicos y acabados que no se introducirían hasta décadas más tarde.","fr":"Pendant les scènes se déroulant en 1933 sur l''île, certains équipements de prise de vue et d''éclairage de Carl Denham présentent des détails de composants mécaniques et des finitions qui n''ont été introduits que des décennies plus tard.","de":"In den Szenen, die 1933 auf der Insel spielen, weisen einige von Carl Denhams Kamera- und Beleuchtungsgeräten Details von mechanischen Komponenten und Verarbeitungen auf, die erst Jahrzehnte später eingeführt wurden."}'::jsonb WHERE id = 5048;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la fuga dagli insetti giganti nella fossa, la torcia elettrica in mano a uno dei marinai si accende e si spegne alternativamente tra un cambio di inquadratura e l''altro senza che il personaggio prema l''interruttore.","en":"During the escape from the giant insects in the pit, the flashlight held by one of the sailors alternately turns on and off between cuts without the character pressing the switch.","es":"Durante la huida de los insectos gigantes en el foso, la linterna en manos de uno de los marineros se enciende y se apaga alternativamente entre plano y plano sin que el personaje pulse el interruptor.","fr":"Pendant la fuite face aux insectes géants dans la fosse, la lampe torche tenue par l''un des marins s''allume et s''éteint alternativement d''un plan à l''autre sans que le personnage n''actionne l''interrupteur.","de":"Während der Flucht vor den Rieseninsekten in der Grube geht die Taschenlampe in der Hand eines Matrosen zwischen den Einstellungen abwechselnd an und aus, ohne dass der Charakter den Schalter drückt."}'::jsonb WHERE id = 5049;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle sequenze della giungla in cui i personaggi corrono inseguiti dai dinosauri, in un fotogramma riflesso nell''acqua fangosa è possibile intravedere brevemente la sagoma di un operatore di ripresa con attrezzatura moderna.","en":"In the jungle sequences where the characters run while chased by dinosaurs, a cameraman with modern equipment can be briefly glimpsed in a single frame reflected in the muddy water.","es":"En las secuencias de la selva en las que los personajes corren perseguidos por los dinosaurios, en un fotograma reflejado en el agua fangosa se puede vislumbrar brevemente la silueta de un operador de cámara con equipo moderno.","fr":"Dans les séquences de la jungle où les personnages courent poursuivis par des dinosaures, on peut apercevoir brièvement la silhouette d''un cadreur avec du matériel moderne dans un fotogramme reflété par l''eau boueuse.","de":"In den Dschungelszenen, in denen die von Dinosauriern gejagten Charaktere rennen, ist in einer Einstellung im schlammigen Wasser kurz die Silhouette eines Kameramanns mit modernem Equipment zu erkennen."}'::jsonb WHERE id = 5050;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Kong viene esposto a Broadway nel 1933, le locandine e i cartelloni promozionali all''esterno del teatro utilizzano font tipografici e impostazioni grafiche tipiche della fine degli anni ''40 anziché dell''epoca della Depressione.","en":"During the sequence where Kong is exhibited on Broadway in 1933, the posters and promotional billboards outside the theater use typographic fonts and graphic layouts typical of the late 1940s rather than the Depression era.","es":"Durante la secuencia en la que Kong es exhibido en Broadway en 1933, los carteles y vallas publicitarias fuera del teatro utilizan tipografías y diseños gráficos propios de finales de los años 40 en lugar de la época de la Depresión.","fr":"Pendant la séquence où Kong est exposé à Broadway en 1933, les affiches et panneaux publicitaires à l''extérieur du théâtre utilisent des polices de caractères et des designs graphiques typiques de la fin des années 1940 plutôt que de l''époque de la Grande Dépression.","de":"Während der Sequenz, in der Kong 1933 am Broadway ausgestellt wird, verwenden die Plakate und Werbetafeln vor dem Theater Typografien und Grafikdesigns, die eher für das späte 1940er Jahre als für die Ära der Great Depression typisch sind."}'::jsonb WHERE id = 5051;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui i Troll (Tom, William e Bert) stanno cucinando attorno al fuoco, la posizione delle padelle e dei pezzi di montone infilzati sugli spiedi cambia visibilmente tra un''inquadratura e l''altra.","en":"During the scene where the Trolls (Tom, William, and Bert) are cooking around the fire, the position of the pans and the pieces of mutton skewered on the spits changes noticeably between shots.","es":"Durante la escena en la que los trolls (Tom, William y Bert) cocinan alrededor del fuego, la posición de las sartenes y de los trozos de cordero ensartados en los espetos cambia visiblemente de un plano a otro.","fr":"Pendant la scène où les trolls (Tom, William et Bert) cuisinent autour du feu, la position des poêles et des morceaux de mouton embrochés change visiblement d''un plan à l''autre.","de":"Während der Szene, in der die Trolls (Tom, William und Bert) am Feuer kochen, verändert sich die Position der Pfannen und der auf Spieße gesteckten Hammelfleischstücke von Einstellung zu Einstellung sichtbar."}'::jsonb WHERE id = 5052;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Gandalf utilizza la sua magia per spaccare la roccia e far entrare la luce del sole che pietrifica i troll, le spaccature nella roccia alle spalle dei troll variano nella forma e nell''ampiezza tra i campi lunghi e i primi piani.","en":"When Gandalf uses his magic to crack the rock and let in the sunlight that turns the trolls to stone, the cracks in the rock behind the trolls vary in shape and width between wide shots and close-ups.","es":"Cuando Gandalf usa su magia para romper la roca y dejar entrar la luz del sol que petrifica a los trolls, las grietas en la roca detrás de los trolls varían en forma y tamaño entre los planos generales y los primeros planos.","fr":"Quand Gandalf utilise sa magie pour fendre la roche et laisser entrer la lumière du soleil qui pétrifie les trolls, les fissures dans la roche derrière les trolls varient en forme et en largeur entre les plans larges et les gros plans.","de":"Als Gandalf seine Magie einsetzt, um den Felsen zu sprengen und das Sonnenlicht hereinzulassen, das die Trolle versteinert, variieren die Risse im Felsen hinter den Trollen zwischen Totale und Nahaufnahme in Form und Breite."}'::jsonb WHERE id = 5053;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui i nani arrivano a Casa Baggins e saccheggiano la dispensa, Bofur lancia una salsiccia e un boccale: in un''inquadratura il tavolo è quasi vuoto, ma nell''angolazione opposta compaiono improvvisamente altri piatti di portata.","en":"In the sequence where the dwarves arrive at Bag End and raid the pantry, Bofur throws a sausage and a mug: in one shot the table is almost empty, but from the reverse angle, other serving platters suddenly appear.","es":"En la secuencia en la que los enanos llegan a Bolsón Cerrado y saquean la despensa, Bofur lanza una salchicha y una jarra: en un plano la mesa está casi vacía, pero en el contraplano aparecen repentinamente otras fuentes de comida.","fr":"Dans la séquence où les nains arrivent à Bagatelle et pillent le garde-manger, Bofur lance une saucisse et une chope : dans un plan la table est presque vide, mais dans le champ-contrechamp opposé, d''autres plats de service apparaissent soudainement.","de":"In der Sequenz, in der die Zwerge in Beutelsend ankommen und die Speisekammer plündern, wirft Bofur eine Wurst und einen Krug: In einer Einstellung ist der Tisch fast leer, aber aus der Gegenachse tauchen plötzlich weitere Servierplatten auf."}'::jsonb WHERE id = 5054;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la battaglia finale sui pini contro i Warg, la posizione delle mani di Thorin mentre impugna l''ascia cambia rapidamente nei tagli di montaggio ravvicinati.","en":"During the final battle on the pines against the Wargs, the position of Thorin''s hands while wielding his axe changes rapidly in close-up editing cuts.","es":"Durante la batalla final en los pinos contra los huargos, la posición de las manos de Thorin empuñando el hacha cambia rápidamente en los cortes de montaje cerrados.","fr":"Pendant la bataille finale sur les pins contre les Wargs, la position des mains de Thorin lorsqu''il brandit sa hache change rapidement lors des coupes de montage serrées.","de":"Während der finalen Schlacht auf den Kiefern gegen die Orks (Warge) verändert sich die Position von Thorins Händen beim Halten seiner Axt in den nahen Montage-Schnitten rasant."}'::jsonb WHERE id = 5055;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza nel Regno Silviano di Thranduil, in un''inquadratura ravvicinata di Legolas, è possibile intravedere brevemente l''ombra di un microfono boom sulla parete rocciosa alle sue spalle.","en":"During the sequence in Thranduil''s Woodland Realm, in a close-up shot of Legolas, the shadow of a boom mic can be briefly glimpsed on the rock wall behind him.","es":"Durante la secuencia en el Reino de los Bosques de Thranduil, en un plano corto de Legolas, se puede vislumbrar brevemente la sombra de un micrófono de pértiga en la pared rocosa detrás de él.","fr":"Pendant la séquence dans le Royaume sylvestre de Thranduil, dans un plan serré de Legolas, on peut apercevoir brièvement l''ombre d''un micro perche sur la paroi rocheuse derrière lui.","de":"Während der Sequenz in Thranduils Waldreich ist in einer Nahaufnahme von Legolas kurz der Schatten eines Boom-Mikrofons an der Felswand hinter ihm zu sehen."}'::jsonb WHERE id = 5056;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i nani escono dai barili alla fine della fuga sul fiume a Esgaroth (Lago-città), Bard l''Arciere aiuta Kili. La posizione dell''arco di Bard e delle frecce sulla sua spalla cambia in modo evidente tra un''inquadratura frontale e quella laterale.","en":"When the dwarves emerge from the barrels at the end of the river escape in Esgaroth (Lake-town), Bard the Bowman helps Kili. The position of Bard''s bow and the arrows on his shoulder visibly changes between a front shot and a side shot.","es":"Cuando los enanos salen de los barriles al final de la huida por el río en Esgaroth (Ciudad del Lago), Bardo el Arquero ayuda a Kili. La posición del arco de Bardo y las flechas en su espalda cambia de forma evidente entre un plano frontal y uno lateral.","fr":"Quand les nains sortent des tonneau à la fin de la fuite sur la rivière à Esgaroth (Lacs-Ville), Bard l''Archer aide Kili. La position de l''arc de Bard et des flèches sur son épaule change de manière visible entre un plan de face et un plan de profil.","de":"Als die Zwerge am Ende der Flucht auf dem Fluss in Esgaroth (Seestadt) aus den Fässern steigen, hilft Bard der Bogenschütze Kili. Die Position von Bards Bogen und den Pfeilen auf seiner Schulter verändert sich zwischen einer Frontaleinstellung und einer Seitenaufnahme deutlich."}'::jsonb WHERE id = 5057;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Smaug soffia le sue fiamme all''interno della fucina della Montagna Solitaria, le catene e le leve metalliche utilizzate dai nani per manovrare i canali di fusione dell''oro cambiano posizione e orientamento rispetto all''inquadratura precedente.","en":"The moment Smaug breathes his flames inside the forge of the Lonely Mountain, the chains and metal levers used by the dwarves to maneuver the molten gold channels change position and orientation compared to the previous shot.","es":"En el momento en que Smaug exhala sus llamas dentro de la fragua de la Montaña Solitaria, las cadenas y palancas metálicas utilizadas por los enanos para maniobrar los canales de fundición de oro cambian de posición y orientación respecto al plano anterior.","fr":"Au moment où Smaug crache ses flammes à l''intérieur de la forge de la Montagne Solitaire, les chaînes et les leviers métalliques utilisés par les nains pour manœuvrer les canaux de fusion de l''or changent de position et d''orientation par rapport au plan précédent.","de":"In dem Moment, in dem Smaug seine Flammen in die Schmiede des Einsamen Berges speit, verändern die von den Zwergen zur Steuerung der Goldkanäle benutzten Ketten und Metallhebel ihre Position und Ausrichtung im Vergleich zur vorherigen Einstellung."}'::jsonb WHERE id = 5058;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Bilbo si arrampica sulla montagna di tesori per recuperare l''Arkenstone, la quantità di gioielli e calici poggiati intorno a lui varia drasticamente da un primo piano al campo largo successivo.","en":"When Bilbo climbs the mountain of treasure to retrieve the Arkenstone, the amount of jewels and goblets resting around him varies drastically from a close-up to the following wide shot.","es":"Cuando Bilbo trepa por la montaña de tesoros para recuperar la Piedra del Arca, la cantidad de joyas y cálices colocados a su alrededor varía drásticamente de un primer plano al plano general siguiente.","fr":"Quand Bilbo grimpe sur la montagne de trésors pour récupérer l''Arkenstone, la quantité de bijoux et de calices posés autour de lui varie radicalement d''un gros plan au plan large suivant.","de":"Als Bilbo auf den Schatzberg klettert, um den Arkenstein zu bergen, variiert die Menge der um ihn herumliegenden Juwelen und Kelche drastisch von einer Nahaufnahme zur nächsten Totalen."}'::jsonb WHERE id = 5059;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Bard l''Arciere affronta il drago Smaug sulla torre di Pontelagolungo, impugna il suo arco nero e le frecce. In un''inquadratura ravvicinata il numero di frecce nella faretra cambia drasticamente rispetto all''inquadratura precedente.","en":"When Bard the Bowman confronts the dragon Smaug on the tower in Lake-town, he wields his black bow and arrows. In a close-up shot, the number of arrows in the quiver changes drastically compared to the previous shot.","es":"Cuando Bardo el Arquero se enfrenta al dragón Smaug en la torre de Ciudad del Lago, empuña su arco negro y sus flechas. En un plano detalle, el número de flechas en el carcaj cambia drásticamente en comparación con el plano anterior.","fr":"Quand Bard l''Archer affronte le dragon Smaug sur la tour de Lac-Ville, il brandit son arc noir et ses flèches. Dans un plan serré, le nombre de flèches dans le carquois change radicalement par rapport au plan précédent.","de":"Als Bard der Bogenschütze auf dem Turm von Seestadt dem Drachen Smaug gegenübertritt, führt er seinen schwarzen Bogen und Pfeile. In einer Großaufnahme verändert sich die Anzahl der Pfeile im Köcher drastisch im Vergleich zur vorherigen Einstellung."}'::jsonb WHERE id = 5060;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i preparativi per la battaglia fuori da Erebor, Gandalf parla con Dain Piediferro. La posizione del bastone di Gandalf e il modo in cui lo tiene variano visibilmente tra i campi e i controcampi della conversazione.","en":"During the preparations for the battle outside Erebor, Gandalf speaks with Dain Ironfoot. The position of Gandalf''s staff and the way he holds it vary visibly between the shots and reverse shots of the conversation.","es":"Durante los preparativos para la batalla a las afueras de Erebor, Gandalf habla con Dain Pie de Hierro. La posición del bastón de Gandalf y la forma en que lo sostiene varían visiblemente entre los planos y contraplanos de la conversación.","fr":"Pendant les préparatifs de la bataille devant Erebor, Gandalf discute avec Dain Pied-de-Fer. La position du bâton de Gandalf et la façon dont il le tient varient de manière visible entre les champs et contre-champs de la conversation.","de":"Während der Vorbereitungen für die Schlacht vor Erebor spricht Gandalf mit Dain Eisenfuß. Die Position von Gandalfs Stab und die Art, wie er ihn hält, variieren während der Schuss-Gegenschuss-Einstellungen des Gesprächs sichtlich."}'::jsonb WHERE id = 5061;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della carica degli orchi contro le linee degli elfi, la neve sul terreno cambia altezza e consistenza in modo evidente tra un cambio di inquadratura e l''altro nei campi lunghi.","en":"During the orcs'' charge against the elf lines, the snow on the ground visibly changes depth and texture between cuts in the long shots.","es":"Durante la carga de los orcos contra las líneas de los elfos, la nieve en el suelo cambia de altura y consistencia de manera evidente entre un cambio de plano y otro en los planos generales.","fr":"Pendant la charge des orques contre les lignes elfiques, la neige au sol change visiblement de hauteur et de consistance d''un raccord à l''autre dans les plans larges.","de":"Während des Sturms der Orks auf die Linien der Elben verändert sich die Höhe und Konsistenz des Schnees auf dem Boden bei Szenenwechseln in den Totalen deutlich."}'::jsonb WHERE id = 5062;
UPDATE errori SET descrizione_i18n = '{"it":"Legolas esegue le sue famose acrobazie sulle rocce che crollano. In una sequenza in cui salcia nel vuoto, i supporti digitali e i punti di ancoraggio per le acrobazie in CGI lasciano intravedere una leggera sovrapposizione innaturale con lo sfondo.","en":"Legolas performs his famous stunts on the collapsing rocks. In a sequence where he leaps into the void, the digital rigs and CGI stunt anchor points reveal a slight, unnatural overlap with the background.","es":"Legolas realiza sus famosas acrobacias sobre las rocas que se desploman. En una secuencia en la que salta al vacío, los soportes digitales y los puntos de apoyo para las acrobacias en CGI dejan entrever una ligera superposición antinatural con el fondo.","fr":"Legolas exécute ses fameuses cascades sur les rochers qui s''effondrent. Dans une séquence où il saute dans le vide, les rigs numériques et les points d''ancrage des cascades en CGI laissent entrevoir une légère superposition contre nature avec le fond.","de":"Legolas vollführt seine berühmten Stunts auf den einstürzenden Felsen. In einer Sequenz, in der er in den Abgrund springt, offenbaren die digitalen Rigs und CGI-Stunthaltepunkte eine leicht unnatürliche Überlappung mit dem Hintergrund."}'::jsonb WHERE id = 5063;
UPDATE errori SET descrizione_i18n = '{"it":"Nel duello sul ghiaccio tra Thorin e Azog, la quantità di ghiaccio rotto attorno ai loro piedi e i detriti fluttuanti variano da un''inquadratura all''altra in modo incoerente con l''azione appena svolta.","en":"In the ice duel between Thorin and Azog, the amount of broken ice around their feet and the floating debris vary inconsistently from shot to shot, defying the action that just took place.","es":"En el duelo sobre hielo entre Thorin y Azog, la cantidad de hielo roto alrededor de sus pies y los escombros flotantes varían de un plano a otro de manera incoherente con la acción que acaba de ocurrir.","fr":"Dans le duel sur la glace entre Thorin et Azog, la quantité de glace brisée autour de leurs pieds et les débris flottants varient d''un plan à l''autre de manière incohérente par rapport à l''action qui vient de se dérouler.","de":"Im Eisduell zwischen Thorin und Azog variieren die Menge an gebrochenem Eis um ihre Füße herum und die treibenden Trümmerteile von Einstellung zu Einstellung unkonsistent zur gerade stattgefundenen Handlung."}'::jsonb WHERE id = 5064;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena del ristorante in cui Harry e Sally discutono per la prima volta dopo il viaggio in auto, la tazza da caffè davanti a Sally cambia posizione e orientamento del manico più volte tra un''inquadratura e l''altra.","en":"During the restaurant scene where Harry and Sally argue for the first time after the car ride, the coffee mug in front of Sally changes position and handle orientation multiple times between shots.","es":"Durante la escena del restaurante en la que Harry y Sally discuten por primera vez después del viaje en coche, la taza de café frente a Sally cambia de posición y de orientación del asa varias veces entre plano y plano.","fr":"Pendant la scène du restaurant où Harry et Sally se disputent pour la première fois après le trajet en voiture, la tasse de café devant Sally change de position et d''orientation d''anse à plusieurs reprises d''un plan à l''autre.","de":"Während der Kaffeeszenen im Restaurant, in der Harry und Sally sich zum ersten Mal nach der Autofahrt streiten, wechseln die Kaffeetasse vor Sally und die Ausrichtung ihres Henkels zwischen den Einstellungen mehrfach die Position."}'::jsonb WHERE id = 5065;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sequenza ambientata nel 1981 in cui Harry e Sally parlano al telefono guardando la televisione, in primo piano si nota un modello di apparecchio telefonico o un dettaglio di arredo che appartiene a una produzione successiva alla metà degli anni ottanta.","en":"During the 1981 sequence where Harry and Sally talk on the phone while watching television, a close-up reveals a telephone model or set decoration detail belonging to a production era after the mid-1980s.","es":"Durante la secuencia ambientada en 1981 en la que Harry y Sally hablan por teléfono viendo la televisión, en un primer plano se nota un modelo de teléfono o un detalle de atrezo perteneciente a una época posterior a mediados de los ochenta.","fr":"Au cours de la séquence se déroulant en 1981 où Harry et Sally parlent au téléphone en regardant la télévision, un gros plan révèle un modèle de téléphone ou un détail de décors postérieur au milieu des années 1980.","de":"In der 1981 spielenden Sequenz, in der Harry und Sally telefonieren und dabei fernsehen, ist in einer Nahaufnahme ein Telefonmodell oder Requisitendetail zu sehen, das aus einer Produktionsepoche nach Mitte der 1980er Jahre stammt."}'::jsonb WHERE id = 5066;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in libreria in cui Harry e Sally si incontrano casualmente dopo anni, i libri sullo scaffale alle spalle di Harry cambiano titolo e disposizione da un''inquadratura all''altra.","en":"In the bookstore scene where Harry and Sally run into each other by chance after years, the books on the shelf behind Harry change titles and arrangement from shot to shot.","es":"En la escena de la librería en la que Harry y Sally se encuentran por casualidad después de años, los libros de la estantería detrás de Harry cambian de título y disposición de un plano a otro.","fr":"Dans la scène de la librairie où Harry et Sally se croisent par hasard après des années, les livres sur l''étagère derrière Harry changent de titre et de disposition d''un plan à l''autre.","de":"In der Buchhandlungsszene, in der sich Harry und Sally nach Jahren zufällig treffen, wechseln die Buchtitel und die Anordnung der Bücher im Regal hinter Harry von Einstellung zu Einstellung."}'::jsonb WHERE id = 5067;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conversazione notturna al telefono tra Harry e Sally divisi nei rispettivi appartamenti, in un cambio di inquadratura il movimento delle labbra di Meg Ryan risulta leggermente fuori sincrono rispetto all''audio della battuta pronunciata.","en":"During the late-night phone conversation between Harry and Sally in their respective apartments, in one cut Meg Ryan''s lip movements are slightly out of sync with the audio of her spoken line.","es":"Durante la conversación telefónica nocturna entre Harry y Sally en sus respectivos apartamentos, en un cambio de plano el movimiento de los labios de Meg Ryan está ligeramente desincronizado con respecto al audio de su diálogo.","fr":"Pendant la conversation téléphonique nocturne entre Harry et Sally dans leurs appartements respectifs, lors d''un raccord, les mouvements de lèvres de Meg Ryan sont légèrement désynchronisés par rapport à l''audio de sa réplique.","de":"Während des nächtlichen Telefongesprächs zwischen Harry und Sally in ihren jeweiligen Apartments sind Meg Ryans Lippenbewegungen in einer Wechselszene leicht asynchron zum Ton ihres gesprochenen Dialogs."}'::jsonb WHERE id = 5068;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della festa di compleanno in cui Harry affronta la crisi per i 40 anni, il bicchiere tenuto in mano da Harry passa dall''essere quasi pieno a metà vuoto e viceversa tra tagli di montaggio ravvicinati senza che lui beva.","en":"During the birthday party where Harry faces his 40-year-old crisis, the glass Harry is holding goes from almost full to half empty and back between tight editing cuts without him taking a drink.","es":"Durante la fiesta de cumpleaños en la que Harry atraviesa la crisis de los 40, el vaso que sostiene Harry pasa de estar casi lleno a medio vacío y viceversa entre cortes de montaje cerrados sin que él beba.","fr":"Pendant la fête d''anniversaire où Harry fait face à sa crise de la quarantaine, le verre qu''il tient passe de presque plein à moitié vide et inversement entre des coupes de montage serrées sans qu''il ne boive.","de":"Während der Geburtstagsfeier, bei der Harry seine Midlifecrisis durchlebt, wechselt das Glas in Harrys Hand zwischen nahen Filmschnitten unbemerkt und ohne dass er trinkt von fast voll zu halb leer und zurück."}'::jsonb WHERE id = 5069;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle sequenze finali in cui Harry cammina per le strade innevate di New York diretto alla festa di Capodanno, la quantità di neve accumulata sui cappotti dei passanti e sulle auto varia visibilmente tra un''inquadratura e l''altra.","en":"In the final sequences where Harry walks through the snowy streets of New York heading to the New Year''s Eve party, the amount of snow accumulated on the passersby''s coats and cars varies noticeably from shot to shot.","es":"En las secuencias finales en las que Harry camina por las calles nevadas de Nueva York rumbo a la fiesta de Año Nuevo, la cantidad de nieve acumulada en los abrigos de los transeúntes y en los coches varía notablemente entre plano y plano.","fr":"Dans les séquences finales où Harry marche dans les rues enneigées de New York pour se rendre à la fête du Nouvel An, la quantité de neige accumulée sur les manteaux des passants et sur les voitures varie visiblement d''un plan à l''autre.","de":"In den Schlussszenen, in denen Harry auf dem Weg zur Silvesterparty durch die verschneiten Straßen von New York geht, variiert die Menge des angesammelten Schnees auf den Mänteln der Passanten und auf den Autos von Einstellung zu Einstellung sichtbar."}'::jsonb WHERE id = 5070;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la lezione in classe, i gessetti e i libri sulla cattedra del professore cambiano disposizione e numero tra un primo piano e il campo medio.","en":"During the classroom lesson, the chalk and books on the professor''s desk change arrangement and number between a close-up and a medium shot.","es":"Durante la clase, las tizas y los libros del escritorio del profesor cambian de disposición y número entre un plano medio y un primer plano.","fr":"Pendant le cours, les craies et les livres sur le bureau du professeur changent de disposition et de nombre entre un gros plan et un plan moyen.","de":"Während der Unterrichtsstunde verändern sich Anordnung und Anzahl der Kreidestücke und Bücher auf dem Pult des Professors zwischen einer Nahaufnahme und einer Halbtotale."}'::jsonb WHERE id = 5071;
UPDATE errori SET descrizione_i18n = '{"it":"In una sequenza girata per le strade di Parigi, si intravede brevemente il riflesso di un operatore con la macchina da presa nella vetrina di un negozio sullo sfondo.","en":"In a sequence shot on the streets of Paris, the reflection of a camera operator is briefly glimpsed in a shop window in the background.","es":"En una secuencia rodada en las calles de París, se ve brevemente el reflejo de un operador de cámara en el escaparate de una tienda al fondo.","fr":"Dans une séquence tournée dans les rues de Paris, on aperçoit brièvement le reflet d''un cadreur avec sa caméra dans la vitrine d''un magasin en arrière-plan.","de":"In einer Sequenz, die in den Straßen von Paris gedreht wurde, ist im Hintergrund kurz die Spiegelung eines Kameramanns im Schaufenster eines Ladens zu sehen."}'::jsonb WHERE id = 5072;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della discussione tra i genitori di Vic in cucina, la tazza di caffè tenuta da François Brasseur passa da una mano all''altra e il livello del liquido varia improvvisamente tra i cambi di inquadratura.","en":"During the argument between Vic''s parents in the kitchen, the coffee cup held by François Brasseur switches hands and the liquid level suddenly varies between camera cuts.","es":"Durante la discusión entre los padres de Vic en la cocina, la taza de café que sostiene François Brasseur cambia de mano y el nivel del líquido varía repentinamente entre los cambios de plano.","fr":"Pendant la dispute entre les parents de Vic dans la cuisine, la tasse de café tenue par François Brasseur change de main et le niveau du liquide varie soudainement entre les raccords de plans.","de":"Während der Auseinandersetzung zwischen Vics Eltern in der Küche wechselt die von François Brasseur gehaltene Kaffeetasse die Hand, und der Füllstand der Flüssigkeit ändert sich zwischen den Einstellungen plötzlich."}'::jsonb WHERE id = 5073;
UPDATE errori SET descrizione_i18n = '{"it":"In una conversazione all''aperto tra Vic e Poupette, il movimento delle labbra di Denise Grey non coincide perfettamente con le battute audio in alcune riprese ravvicinate.","en":"During an outdoor conversation between Vic and Poupette, Denise Grey''s lip movements do not perfectly match the audio dialogue in a few close-up shots.","es":"En una conversación al aire libre entre Vic y Poupette, el movimiento de los labios de Denise Grey no coincide perfectamente con el diálogo de audio en algunas tomas cerradas.","fr":"Lors d''une conversation en plein air entre Vic et Poupette, les mouvements de lèvres de Denise Grey ne correspondent pas parfaitement aux répliques audio dans certains plans serrés.","de":"Während eines Gesprächs im Freien zwischen Vic und Poupette stimmen Denise Greys Lippenbewegungen in einigen Nahaufnahmen nicht perfekt mit dem Audiodialog überein."}'::jsonb WHERE id = 5074;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Kevin Lomax arriva per la prima volta a New York e scende dal taxi con Mary Ann, la valigia che estrae dal bagagliaio cambia mano e orientamento tra l''inquadratura in cui la solleva e quella successiva in cui cammina verso l''hotel.","en":"When Kevin Lomax first arrives in New York and gets out of the taxi with Mary Ann, the suitcase he pulls from the trunk changes hands and orientation between the shot where he lifts it and the subsequent shot where he walks toward the hotel.","es":"Cuando Kevin Lomax llega por primera vez a Nueva York y sale del taxi con Mary Ann, la maleta que saca del maletero cambia de mano y de orientación entre el plano en el que la levanta y el siguiente en el que camina hacia el hotel.","fr":"Quand Kevin Lomax arrive pour la première fois à New York et sort du taxi avec Mary Ann, la valise qu''il sort du coffre change de main et d''orientation entre le plan où il la soulève et le plan suivant où il marche vers l''hôtel.","de":"Als Kevin Lomax das erste Mal in New York ankommt und mit Mary Ann aus dem Taxi steigt, wechseln Hand und Ausrichtung des Koffers, den er aus dem Kofferraum zieht, zwischen der Einstellung, in der er ihn anhebt, und der folgenden Einstellung, in der er zum Hotel geht."}'::jsonb WHERE id = 5075;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conversazione nello studio di Kevin, il bicchiere di scotch sulla scrivania si riempie e si svuota parzialmente tra i cambi d''inquadratura ravvicinati e i campi medi, senza che nessuno tocchi la bottiglia.","en":"During the conversation in Kevin''s office, the glass of scotch on the desk partially fills and empties between close-up cuts and medium shots, without anyone touching the bottle.","es":"Durante la conversación en el despacho de Kevin, el vaso de whisky que está sobre el escritorio se llena y se vacía parcialmente entre los planos cortos y los planos medios, sin que nadie toque la botella.","fr":"Pendant la conversation dans le bureau de Kevin, le verre de scotch sur le bureau se remplit et se vide partiellement entre les raccords de plans rapprochés et les plans moyens, sans que personne ne touche la bouteille.","de":"Während des Gesprächs in Kevins Büro füllt und leert sich das Glas Scotch auf dem Schreibtisch zwischen Nahaufnahmen und Halbtotalen teilweise, ohne dass jemand die Flasche berührt."}'::jsonb WHERE id = 5076;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso del processo a Alex Cullen, la procedura e la dinamica delle obiezioni in un''aula di tribunale di New York presentano diverse licenze cinematografiche rispetto alla realtà giuridica americana, in particolare riguardo all''ammissibilità immediata di alcune prove testimoniali non verificate.","en":"During the Alex Cullen trial, the courtroom procedure and objections in a New York court take several cinematic liberties compared to actual American legal reality, particularly regarding the immediate admissibility of certain unverified testimonial evidence.","es":"Durante el juicio a Alex Cullen, el procedimiento y la dinámica de las objeciones en un tribunal de Nueva York presentan varias licencias cinematográficas en comparación con la realidad jurídica estadounidense, en particular en cuanto a la admisibilidad inmediata de ciertas pruebas testimoniales no verificadas.","fr":"Pendant le procès d''Alex Cullen, la procédure et la dynamique des objections dans un tribunal de New York prennent plusieurs libertés cinématographiques par rapport à la réalité juridique américaine, notamment en ce qui concerne l''admissibilité immédiate de certains témoignages non vérifiés.","de":"Während des Prozesses gegen Alex Cullen weisen das Verfahren und die Dynamik der Einwände in einem Gerichtssaal in New York einige filmische Freiheiten gegenüber der US-amerikanischen Rechtsrealität auf, insbesondere hinsichtlich der sofortigen Zulässigkeit bestimmter nicht verifizierter Zeugenaussagen."}'::jsonb WHERE id = 5077;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Mary Ann vaga per strada in stato confusionale, la borsa che porta a tracolla passa da una spalla all''altra in modo repentino tra un cambio di marciapiede e l''altro.","en":"In the sequence where Mary Ann wanders the street in a daze, her crossbody bag abruptly switches from one shoulder to the other between cuts as she crosses the sidewalk.","es":"En la secuencia en la que Mary Ann deambula por la calle en estado de confusión, el bolso que lleva cruzado cambia repentinamente de un hombro a otro entre plano y plano al cambiar de acera.","fr":"Dans la séquence où Mary Ann erre dans la rue en état de confusion, le sac en bandoulière qu''elle porte change brusquement d''épaule d''un raccord de plan à l''autre lorsqu''elle change de trottoir.","de":"In der Sequenz, in der Mary Ann verwirrt durch die Straße irrt, wechselt die Umhängetasche, die sie trägt, zwischen den Schnitten beim Seitenwechsel des Bürgersteigs abrupt von einer Schulter zur anderen."}'::jsonb WHERE id = 5078;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena dell''ospedale, quando Kevin urla disperato rivolgendosi al letto, in un primo piano il movimento della bocca termina bruscamente mentre l''eco della sua voce continua chiaramente nella colonna sonora.","en":"In the hospital scene, when Kevin screams desperately toward the bed, in a close-up his mouth movement ends abruptly while the echo of his voice clearly continues on the soundtrack.","es":"En la escena del hospital, cuando Kevin grita desesperado hacia la cama, en un primer plano el movimiento de su boca termina bruscamente mientras el eco de su voz continúa claramente en la banda sonora.","fr":"Dans la scène de l''hôpital, lorsque Kevin crie désespérément vers le lit, dans un gros plan le mouvement de sa bouche s''arrête brusquement tandis que l''écho de sa voix continue clairement sur la bande sonore.","de":"In der Kinoszene des Hospitals, als Kevin verzweifelt das Bett anschreit, endet in einer Nahaufnahme die Mundbewegung abrupt, während das Echo seiner Stimme auf der Tonspur deutlich weiter zu hören ist."}'::jsonb WHERE id = 5079;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui la polizia interroga il Nightrider dopo l''incidente iniziale, la quantità di sangue sulla faccia del criminale varia visibilmente tra un primo piano e l''inquadratura larga.","en":"During the sequence where the police interrogate the Nightrider after the initial crash, the amount of blood on the criminal''s face visibly varies between a close-up and the wide shot.","es":"Durante la secuencia en la que la policía interroga al Nightrider tras el accidente inicial, la cantidad de sangre en la cara del criminal varía visiblemente entre un primer plano y el plano general.","fr":"Pendant la séquence où la police interroge le Nightrider après l''accident initial, la quantité de sang sur le visage du criminel varie visiblement entre un gros plan et le plan large.","de":"Während der Sequenz, in der die Polizei den Nightrider nach dem anfänglichen Unfall verhört, variiert die Menge an Blut im Gesicht des Kriminellen sichtlich zwischen einer Nahaufnahme und der Totalen."}'::jsonb WHERE id = 5080;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Max guida la sua auto di famiglia con Jessie e Sprog, la posizione del peluche appeso allo specchietto retrovisore cambia ripetutamente tra le riprese interne e quelle esterne.","en":"When Max drives his family car with Jessie and Sprog, the position of the plush toy hanging from the rearview mirror repeatedly changes between interior and exterior shots.","es":"Cuando Max conduce su coche familiar con Jessie y Sprog, la posición del peluche colgado del espejo retrovisor cambia repetidamente entre los planos interiores y exteriores.","fr":"Quand Max conduit sa voiture familiale avec Jessie et Sprog, la position de la peluche suspendue au rétroviseur change de façon répétée entre les plans intérieurs et extérieurs.","de":"Wenn Max mit Jessie und Sprog sein Familienauto fährt, ändert sich die Position des Plüschtiers am Rückspiegel zwischen Innen- und Außenaufnahmen wiederholt."}'::jsonb WHERE id = 5081;
UPDATE errori SET descrizione_i18n = '{"it":"In una delle inquadrature ampie lungo la strada desertica, è possibile intravedere brevemente il riflesso della telecamera o del mezzo di supporto sulla carrozzeria lucida di un veicolo della polizia.","en":"In one of the wide shots along the desert road, the reflection of the camera or the rig vehicle can be briefly glimpsed on the polished bodywork of a police car.","es":"En uno de los planos generales a lo largo de la carretera desértica, se puede vislumbrar brevemente el reflejo de la cámara o del vehículo de apoyo en la carrocería brillante de un coche de policía.","fr":"Dans l''un des plans larges le long de la route déserte, on peut apercevoir brièvement le reflet de la caméra ou de la voiture régie sur la carrosserie brillante d''un véhicule de police.","de":"In einer der Totalen entlang der Wüstenstraße ist kurz das Spiegelung der Kamera oder des Kamerafahrzeugs auf der polierten Karosserie eines Polizeifahrzeugs zu erahnen."}'::jsonb WHERE id = 5082;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il saccheggio della cittadina da parte della gang di Toecutter, un vetro di una finestra viene distrutto ma, nell''inquadratura immediatamente successiva da angolazione diversa, il vetro appare nuovamente intatto prima di rompersi di nuovo.","en":"During the sacking of the small town by Toecutter''s gang, a window glass is smashed, but in the immediately following shot from a different angle, the glass appears intact again before breaking once more.","es":"Durante el saqueo del pueblo por parte de la banda de Toecutter, el cristal de una ventana es destruido, pero en el plano inmediatamente posterior desde un ángulo diferente, el cristal aparece de nuevo intacto antes de romperse otra vez.","fr":"Pendant le pillage de la petite ville par la bande de Toecutter, une vitre est brisée mais, dans le plan immédiatement suivant sous un angle différent, la vitre apparaît à nouveau intacte avant de se casser une seconde fois.","de":"Während der Plünderung der kleinen Stadt durch Toecutters Gang wird eine Fensterscheibe eingeschlagen, aber in der unmittelbar folgenden Einstellung aus einem anderen Winkel erscheint das Glas wieder intakt, bevor es erneut bricht."}'::jsonb WHERE id = 5083;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Goose cade con la moto dopo il sabotaggio della sua ruota, il casco che indossa a terra differisce leggermente per dettagli e finiture rispetto a quello indossato durante la corsa precedente.","en":"When Goose crashes his motorcycle after his wheel is sabotaged, the helmet he wears on the ground slightly differs in details and finish from the one worn during the preceding chase.","es":"Cuando Goose sufre un accidente con su moto tras el sabotaje de su rueda, el casco que lleva en el suelo difiere ligeramente en detalles y acabados del que llevaba durante la persecución anterior.","fr":"Quand Goose chute à moto après le sabotage de sa roue, le casque qu''il porte au sol diffère légèrement dans les détails et les finitions de celui porté pendant la course-poursuite précédente.","de":"Als Goose nach der Sabotage an seinem Rad mit dem Motorrad stürzt, unterscheidet sich der Helm, den er am Boden trägt, in Details und Verarbeitung leicht von dem, den er während der vorherigen Verfolgungsjagd trug."}'::jsonb WHERE id = 5084;
UPDATE errori SET descrizione_i18n = '{"it":"Le ferite e le bende sul corpo di Goose all''ospedale cambiano posizione e consistenza estetica tra la scena in cui Max va a trovarlo e le inquadrature successive.","en":"Goose''s wounds and bandages in the hospital change position and aesthetic texture between the scene where Max visits him and the subsequent shots.","es":"Las heridas y los vendajes en el cuerpo de Goose en el hospital cambian de posición y textura estética entre la escena en la que Max va a visitarlo y los planos siguientes.","fr":"Les blessures et les bandages sur le corps de Goose à l''hôpital changent de position et d''aspect visuel entre la scène où Max lui rend visite et les plans suivants.","de":"Gooses Wunden und Verbände im Krankenhaus verändern ihre Position und ästhetische Beschaffenheit zwischen der Szene, in der Max ihn besucht, und den darauffolgenden Einstellungen."}'::jsonb WHERE id = 5085;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Max indossa la sua uniforme di pelle nera e si prepara nella base della MFP, gli stivali cambiano tipo di fibbia e suola tra un primo piano e la figura intera.","en":"In the scene where Max puts on his black leather uniform and gears up at the MFP base, his boots change the type of buckle and sole between a close-up and a wide shot.","es":"En la escena en la que Max se pone su uniforme de cuero negro y se prepara en la base de la MFP, las botas cambian de tipo de hebilla y suela entre un primer plano y un plano general.","fr":"Dans la scène où Max enfile son uniforme en cuir noir et se prépare à la base de la MFP, les bottes changent de type de boucle et de semelle entre un gros plan et un plan large.","de":"In der Szene, in der Max seine schwarze Lederuniform anzieht und sich in der MFP-Basis vorbereitet, wechseln bei seinen Stiefeln Schnallenart und Sohle zwischen einer Nahaufnahme und einer Totalen."}'::jsonb WHERE id = 5086;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle sequenze all''interno del compound, in un''inquadratura ravvicinata su uno dei personaggi secondari, si intravede brevemente il braccio di un microfono a boom riflettersi sulla carrozzeria lucida di un veicolo parcheggiato sullo sfondo.","en":"During one of the sequences inside the compound, in a close-up on a secondary character, a boom mic pole is briefly seen reflecting off the shiny bodywork of a vehicle parked in the background.","es":"Durante una de las secuencias dentro del recinto, en un plano corto de uno de los personajes secundarios, se ve brevemente el brazo de un micrófono de pértiga reflejarse en la carrocería brillante de un vehículo aparcado al fondo.","fr":"Pendant l''une des séquences à l''intérieur du complexe, dans un plan serré sur un personnage secondaire, on aperçoit brièvement la perche d''un micro perche se refléter sur la carrosserie brillante d''un véhicule garé à l''arrière-plan.","de":"Während einer der Sequenzen im Compound ist in einer Nahaufnahme einer Nebenfigur kurz der Arm eines Galgenmikrofons zu sehen, der sich auf der glänzenden Karosserie eines im Hintergrund geparkten Fahrzeugs spiegelt."}'::jsonb WHERE id = 5087;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Max riceve la benzina e i proiettili dalla comunità, il fucile a canne mozze che tiene in mano cambia angolazione e posizione della cinghia tra un''inquadratura frontale e il controcampo.","en":"When Max receives the gasoline and bullets from the community, the sawed-off shotgun he is holding changes angle and sling position between a front shot and the reverse shot.","es":"Cuando Max recibe la gasolina y las balas de la comunidad, la escopeta recortada que sostiene cambia de ángulo y de posición de la correa entre un plano frontal y el contracampo.","fr":"Lorsque Max reçoit l''essence et les munitions de la communauté, le fusil à canon scié qu''il tient change d''angle et de position de bretelle entre un plan de face et le champ-contrechamp.","de":"Als Max Benzin und Munition von der Gemeinschaft erhält, wechseln bei der abgesägten Schrotflinte, die er hält, der Winkel und die Riemenposition zwischen einer Frontale und dem Gegenschuss."}'::jsonb WHERE id = 5088;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''attacco dei predoni al perimetro della raffineria, un motociclista cade rovinosamente a terra sollevando molta polvere; nell''inquadratura immediatamente successiva, la moto scivola via ma la posizione del corpo dello stuntman è visibilmente diversa e più avanzata rispetto all''impatto.","en":"During the raiders'' attack on the refinery perimeter, a biker crashes heavily to the ground, kicking up a lot of dust; in the immediately following shot, the motorcycle slides away, but the stuntman''s body position is visibly different and further ahead compared to the impact.","es":"Durante el ataque de los asaltantes al perímetro de la refinería, un motociclista cae estrepitosamente al suelo levantando mucho polvo; en el plano inmediatamente posterior, la moto se desliza, pero la posición del cuerpo del doble de acción es visiblemente diferente y está más adelantada respecto al impacto.","fr":"Pendant l''attaque des pillards sur le périmètre de la raffinerie, un motard fait une lourde chute au sol en soulevant beaucoup de poussière ; dans le plan immédiatement suivant, la moto glisse, mais la position du corps du cascadeur est visiblement différente et plus avancée par rapport à l''impact.","de":"Während des Angriffs der Plünderer auf das Raffineriegelände stürzt ein Motorradfahrer heftig zu Boden und wirbelt viel Staub auf; in der unmittelbar folgenden Einstellung rutscht das Motorrad weg, aber die Position des Stuntmans unterscheidet sich sichtlich und liegt weiter vorne als beim Aufprall."}'::jsonb WHERE id = 5089;
UPDATE errori SET descrizione_i18n = '{"it":"In una delle inquadrature ampie nel deserto durante l''inseguimento della petroliera, si nota brevemente sulla sabbia l''ombra del veicolo con la cinepresa utilizzata per le riprese in movimento.","en":"In one of the wide shots in the desert during the tanker chase, the shadow of the camera rig vehicle used for the moving shots is briefly visible on the sand.","es":"En uno de los planos generales en el desierto durante la persecución de la pipa, se ve brevemente en la arena la sombra del vehículo de cámara utilizado para los planos en movimiento.","fr":"Dans l''un des plans larges dans le désert pendant la poursuite du camion-citerne, on aperçoit brièvement sur le sable l''ombre du véhicule caméra utilisé pour les prises de vues en mouvement.","de":"In einer der Totalen in der Wüste während der Tankerverfolgungsjagd ist auf dem Sand kurz der Schatten des Kamerawagens zu sehen, der für die Fahraufnahmen genutzt wurde."}'::jsonb WHERE id = 5090;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle scene finali dell''inseguimento, il trucco sul viso di Max (ferite e sangue finto) varia in modo evidente per intensità e posizione della crosta sulla guancia sinistra tra i vari cambi di inquadratura.","en":"In the final chase scenes, the makeup on Max''s face (wounds and fake blood) varies noticeably in intensity and scab position on his left cheek across the various cuts.","es":"En las escenas finales de la persecución, el maquillaje en la cara de Max (heridas y sangre falsa) varía notablemente en intensidad y en la posición de la costra en la mejilla izquierda entre los diferentes cambios de plano.","fr":"Dans les scènes finales de la poursuite, le maquillage sur le visage de Max (blessures et faux sang) varie de manière flagrante en intensité et quant à la position de la croûte sur la joue gauche entre les différents plans.","de":"In den finalen Verfolgungsszenen verändert sich das Make-up in Max'' Gesicht (Wunden und Kunstblut) bezüglich Intensität und der Position der Kruste auf der linken Wange zwischen den verschiedenen Schnitten deutlich."}'::jsonb WHERE id = 5091;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Max entra per la prima volta a Bartertown e viene perquisito, la pistola che gli viene confiscata cambia mano tra un''inquadratura e l''altra mentre le guardie gliela sfilano.","en":"When Max enters Bartertown for the first time and is frisked, the gun confiscated from him changes hands between shots as the guards take it from him.","es":"Cuando Max entra por primera vez a Bartertown y es registrado, la pistola que le confiscan cambia de mano de un plano a otro mientras los guardias se la quitan.","fr":"Quand Max entre pour la première fois à Bartertown et se fait fouiller, le pistolet qui lui est confisqué change de main d''un plan à l''autre pendant que les gardes le lui retirent.","de":"Als Max das erste Mal Bartertown betritt und durchsucht wird, wechselt die Pistole, die ihm abgenommen wird, zwischen den Einstellungen die Hand, während die Wachen sie ihm wegnehmen."}'::jsonb WHERE id = 5092;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Max viene legato alla ruota della fortuna all''esterno di Bartertown come punizione, la posizione delle corde attorno al suo petto varia notevolmente nei diversi cambi di inquadratura.","en":"In the sequence where Max is tied to the Wheel of Fortune outside Bartertown as punishment, the position of the ropes around his chest varies noticeably across different shot changes.","es":"En la secuencia en la que Max es atado a la rueda de la fortuna a las afueras de Bartertown como castigo, la posición de las cuerdas alrededor de su pecho varía notablemente entre los diferentes cambios de plano.","fr":"Dans la séquence où Max est attaché à la roue de la fortune à l''extérieur de Bartertown en guise de punition, la position des cordes autour de sa poitrine varie sensiblement d''un changement de plan à l''autre.","de":"In der Sequenz, in der Max zur Strafe an das Glücksrad außerhalb von Bartertown gefesselt wird, variiert die Position der Seile um seine Brust bei den verschiedenen Szenen- und Einstellungswechseln deutlich."}'::jsonb WHERE id = 5093;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena notturna nel rifugio sotterraneo dei bambini, in un''inquadratura grandangolare si intravede brevemente il riflesso di un riflettore della troupe su una superficie metallica di sfondo.","en":"During the night scene in the children''s underground hideout, a wide shot briefly reveals the reflection of a crew''s lighting rig on a background metal surface.","es":"Durante la escena nocturna en el refugio subterráneo de los niños, en un plano general se ve brevemente el reflejo de un foco de iluminación del equipo técnico en una superficie metálica de fondo.","fr":"Pendant la scène nocturne dans le repaire souterrain des enfants, un plan large laisse entrevoir brièvement le reflet d''un projecteur de l''équipe technique sur une surface métallique en arrière-plan.","de":"Während der Nactszene im unterirdischen Versteck der Kinder ist in einer Weitwinkelaufnahme kurz die Reflexion eines Scheinwerfers der Filmcrew auf einer metallischen Hintergrundoberfläche zu sehen."}'::jsonb WHERE id = 5094;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il caotico inseguimento finale con i treni, la quantità di fumo nero e il danno alla marmitta di uno dei veicoli inseguiti fluttuano visibilmente tra i tagli di montaggio.","en":"During the chaotic final train chase, the amount of black smoke and the damage to the exhaust pipe of one of the pursued vehicles fluctuate visibly between editing cuts.","es":"Durante la caótica persecución final con los trenes, la cantidad de humo negro y los daños en el tubo de escape de uno de los vehículos perseguidos fluctúan visiblemente entre los cortes de montaje.","fr":"Pendant la course-poursuite finale chaotique avec les trains, la quantité de fumée noire et les dégâts sur le pot d''échappement de l''un des véhicules poursuivis varient visiblement d''un raccord de montage à l''autre.","de":"Während der chaotischen finalen Zugverfolgungsjagd schwanken die Menge des schwarzen Rauchs und die Beschädigung des Auspuffs eines der verfolgten Fahrzeuge zwischen den Montagecuts deutlich sichtbar."}'::jsonb WHERE id = 5095;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle sequenze d''azione nel deserto, in un''inquadratura ravvicinata della cabina della War Rig, si può intravedere brevemente il riflesso di una telecamera e di membri della troupe sui vetri laterali del veicolo.","en":"During one of the desert action sequences, in a close-up shot of the War Rig''s cab, the reflection of a camera and crew members can be briefly glimpsed on the vehicle''s side windows.","es":"Durante una de las secuencias de acción en el desierto, en un plano cerrado de la cabina del War Rig, se puede atisbar brevemente el reflejo de una cámara y de miembros del equipo en los cristales laterales del vehículo.","fr":"Pendant l''une des séquences d''action dans le désert, dans un plan serré de la cabine du War Rig, on peut entrapercevoir brièvement le reflet d''une caméra et de membres de l''équipe technique sur les vitres latérales du véhicule.","de":"Während einer der Actionsequenzen in der Wüste ist in einer Nahaufnahme der War-Rig-Kabine kurz die Reflexion einer Kamera und von Crewmitgliedern in den Seitenscheiben des Fahrzeugs zu erkennen."}'::jsonb WHERE id = 5096;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Max viene legato davanti alla macchina di Nux come ''sacca di sangue'', la lunghezza e la posizione della catena e delle fascette che lo tengono bloccato variano visibilmente tra un cambio d''inquadratura e l''altro.","en":"When Max is tied to the front of Nux''s car as a ''blood bag'', the length and position of the chain and zip ties holding him down vary visibly between shot changes.","es":"Cuando Max es atado al frente del coche de Nux como ''bolsa de sangre'', la longitud y la posición de la cadena y las bridas que lo mantienen sujeto varían visiblemente entre plano y plano.","fr":"Quand Max est attaché à l''avant de la voiture de Nux en tant que « poche de sang », la longueur et la position de la chaîne et des attaches qui le maintiennent bloqué varient visiblement d''un plan à l''autre.","de":"Wenn Max als ‚Blutbeutel‘ vor Nux’ Auto gefesselt ist, variieren die Länge und Position der Kette und der Kabelbinder, die ihn festhalten, von Einstellung zu Einstellung sichtbar."}'::jsonb WHERE id = 5097;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la tempesta di sabbia, l''Interceptors di Max viene distrutto e capovolto. Nelle inquadrature successive, la quantità di danni subiti dalla parte anteriore della vettura cambia drasticamente prima dell''impatto definitivo.","en":"During the sandstorm, Max''s Interceptor is wrecked and flipped over. In subsequent shots, the amount of damage sustained by the front end of the car changes drastically before the final crash.","es":"Durante la tormenta de arena, el Interceptor de Max es destrozado y volcado. En los planos siguientes, la cantidad de daños sufridos en la parte delantera del coche cambia drásticamente antes del impacto definitivo.","fr":"Pendant la tempête de sable, l''Interceptor de Max est détruit et retourné. Dans les plans suivants, l''ampleur des dégâts subis par l''avant de la voiture change radicalement avant l''impact final.","de":"Während des Sandsturms wird Max’ Interceptor zerstört und überschlägt sich. In den folgenden Einstellungen verändert sich das Ausmaß der Schäden an der Frontpartie des Wagens vor dem finalen Crash drastisch."}'::jsonb WHERE id = 5098;
UPDATE errori SET descrizione_i18n = '{"it":"Le ferite sul volto e sul corpo dell''Imperatrice Furiosa (interpretata da Charlize Theron) cambiano posizione, intensità e persino presenza tra le scene d''azione e i momenti di dialogo più calmi.","en":"The wounds on the face and body of Imperator Furiosa (played by Charlize Theron) shift in position, intensity, and even presence between action scenes and calmer dialogue moments.","es":"Las heridas en la cara y el cuerpo de la Imperator Furiosa (interpretada por Charlize Theron) cambian de posición, intensidad e incluso presencia entre las escenas de acción y los momentos de diálogo más tranquilos.","fr":"Les blessures sur le visage et le corps de l''Imperator Furiosa (jouée par Charlize Theron) changent de position, d''intensité et même de présence entre les scènes d''action et les moments de dialogue plus calmes.","de":"Die Wunden im Gesicht und am Körper von Imperator Furiosa (gespielt von Charlize Theron) verändern ihre Position, Intensität und teilweise sogar ihre Präsenz zwischen den Actionsequenzen und ruhigeren Dialogszenen."}'::jsonb WHERE id = 5099;
UPDATE errori SET descrizione_i18n = '{"it":"In una panoramica veloce durante l''inseguimento nelle gole rocciose, si nota per un fotogramma il cavo di sicurezza di uno stuntman attaccato a un motociclista che sta compiendo un salto.","en":"In a fast panning shot during the rocky gorge chase, a stuntman''s safety wire attached to a jumping motorcyclist is visible for a single frame.","es":"En un paneo rápido durante la persecución en los desfiladeros rocosos, se ve durante un fotograma el cable de seguridad de un doble de acción sujeto a un motociclista que está realizando un salto.","fr":"Dans un mouvement de panoramique rapide lors de la course-poursuite dans les gorges rocheuses, on aperçoit pendant une seule image le câble de sécurité d''un cascadeur relié à un motard effectuant un saut.","de":"In einem schnellen Schwenk während der Verfolgungsjagd in den Felsenschluchten ist für einen einzigen Frame das Sicherheitsseil eines Stuntmans zu sehen, das an einem Motorradfahrer befestigt ist, der einen Sprung ausführt."}'::jsonb WHERE id = 5100;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la War Rig si ferma definitivamente al ritorno verso la Cittadella, il numero e la disposizione dei fori di proiettile sul parabrezza e sulla carrozzeria differiscono notevolmente rispetto all''inquadratura precedente.","en":"When the War Rig comes to a final stop on the return to the Citadel, the number and placement of the bullet holes on the windshield and bodywork differ significantly from the previous shot.","es":"Cuando el War Rig se detiene definitivamente en el camino de regreso a la Ciudadela, el número y la disposición de los agujeros de bala en el parabrisas y la carrocería difieren notablemente con respecto al plano anterior.","fr":"Lorsque le War Rig s''arrête définitivement lors du retour vers la Citadelle, le nombre et la disposition des impacts de balle sur le pare-brise et la carrosserie diffèrent sensiblement par rapport au plan précédent.","de":"Als der War Rig bei der Rückkehr zur Zitadelle endgültig zum Stehen kommt, unterscheiden sich Anzahl und Anordnung der Einschusslöcher auf der Windschutzscheibe und der Karosserie deutlich im Vergleich zur vorherigen Einstellung."}'::jsonb WHERE id = 5101;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui la giovane Furiosa si nasconde tra le rocce del Green Place per seminare gli inseguitori, il ramo spezzato che stringe in mano cambia angolazione e lunghezza visibile tra un primo piano e il campo largo successivo.","en":"During the sequence where young Furiosa hides among the rocks of the Green Place to shake off her pursuers, the broken branch she grips changes angle and visible length between a close-up and the following wide shot.","es":"Durante la secuencia en la que la joven Furiosa se esconde entre las rocas de Green Place para despistar a sus perseguidores, la rama rota que sostiene en la mano cambia de ángulo y longitud visible entre un primer plano y el plano general posterior.","fr":"Pendant la séquence où la jeune Furiosa se cache parmi les rochers du Green Place pour semer ses poursuivants, la branche cassée qu''elle serre dans sa main change d''angle et de longueur visible entre un gros plan et le plan large suivant.","de":"Während der Sequenz, in der sich die junge Furiosa in den Felsen des Green Place versteckt, um ihre Verfolger abzuhängen, ändern sich der Winkel und die sichtbare Länge des abgebrochenen Zweigs, den sie in der Hand hält, zwischen einer Nahaufnahme und der folgenden Totalen."}'::jsonb WHERE id = 5102;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso dell''assalto alla War Rig, la posizione delle taniche di benzina legate sul tetto della cabina varia visibilmente: in un''inquadratura dal basso sono inclinate verso destra, mentre nel taglio immediatamente successivo appaiono perfettamente verticali e legate con una foga differente.","en":"During the assault on the War Rig, the position of the fuel cans strapped to the cab roof varies noticeably: in a low-angle shot they are tilted to the right, while in the very next cut they appear perfectly vertical and tied down with a different tightness.","es":"Durante el asalto al War Rig, la posición de las latas de gasolina atadas al techo de la cabina varía visiblemente: en un plano picado ascendente (contrapicado) están inclinadas hacia la derecha, mientras que en el corte inmediatamente posterior aparecen perfectamente verticales y atadas con un arnés diferente.","fr":"Pendant l''assaut du War Rig, la position des bidons d''essence attachés sur le toit de la cabine varie de manière visible : dans un plan en contre-plongée, ils sont inclinés vers la droite, tandis que dans le raccord immédiatement suivant, ils apparaissent parfaitement verticaux et attachés différemment.","de":"Während des Angriffs auf den War Rig variiert die Position der auf dem Kabinendach festgezurten Benzinkanister merklich: In einer Untersicht sind sie nach rechts geneigt, während sie im unmittelbar folgenden Schnitt perfekt vertikal und mit einer anderen Spannung vertäut erscheinen."}'::jsonb WHERE id = 5103;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno di Bullet Farm, quando Praetorian Jack combatte contro gli scagnozzi, le macchie di grasso e olio sulle sue braccia cambiano densità e forma geometrica nei vari cambi di inquadratura della scena d''azione.","en":"Inside Bullet Farm, when Praetorian Jack fights the goons, the grease and oil stains on his arms change density and pattern across the various cuts of the action sequence.","es":"Dentro de Bullet Farm, cuando Praetorian Jack lucha contra los secuaces, las manchas de grasa y aceite en sus brazos cambian de densidad y forma geométrica en los distintos cortes de la escena de acción.","fr":"À l''intérieur de Bullet Farm, lorsque Praetorian Jack se bat contre les sbires, les taches de graisse et d''huile sur ses bras changent de densité et de forme géométrique au fil des différents raccords de la scène d''action.","de":"In Bullet Farm, als Praetorian Jack gegen die Handlanger kämpft, verändern sich Dichte und Form der Fett- und Ölflecken auf seinen Armen bei den verschiedenen Schnitten der Actionsequenz."}'::jsonb WHERE id = 5104;
UPDATE errori SET descrizione_i18n = '{"it":"In una rapida inquadratura grandangolare durante l''inseguimento nel deserto, è possibile intravedere brevemente per un fotogramma il riflesso di una cinepresa e di un operatore sulla carrozzeria metallica lucida di uno dei buggy di contorno.","en":"In a quick wide shot during the desert chase, the reflection of a camera and a camera operator can be briefly glimpsed for a single frame on the shiny metal body of one of the background buggies.","es":"En un rápido plano gran angular durante la persecución por el desierto, se puede atisbar brevemente durante un fotograma el reflejo de una cámara y de un operador en la carrocería metálica brillante de uno de los buggies secundarios.","fr":"Dans un plan grand-angle rapide pendant la course-poursuite dans le désert, on peut apercevoir brièvement, pendant une seule image, le reflet d''une caméra et d''un cadreur sur la carrosserie métallique brillante de l''un des buggies de second plan.","de":"In einer schnellen Weitwinkeleinstellung während der Wüstenverfolgungsjagd ist für einen einzigen Frame kurz die Reflexion einer Kamera und eines Kameramanns auf der glänzenden Metallkarosserie eines der Hintergrund-Buggies zu erkennen."}'::jsonb WHERE id = 5105;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''epilogo nel frutteto, i residui di terra e polvere sui vestiti di Furiosa variano notevolmente tra i dettagli ravvicinati del volto e le inquadrature a figura intera mentre cammina tra gli alberi.","en":"During the epilogue in the orchard, the dirt and dust residue on Furiosa''s clothes varies considerably between close-ups of her face and full-body shots as she walks among the trees.","es":"Durante el epílogo en el huerto, los restos de tierra y polvo en la ropa de Furiosa varían notablemente entre los primeros planos de su rostro y los planos de cuerpo entero mientras camina entre los árboles.","fr":"Pendant l''épilogue dans le verger, les résidus de terre et de poussière sur les vêtements de Furiosa varient considérablement entre les gros plans sur son visage et les plans en pied lorsqu''elle marche parmi les arbres.","de":"Während des Epilogs im Obstgarten variieren die Erd- und Staubspuren auf Furiosas Kleidung erheblich zwischen den Nahaufnahmen ihres Gesichts und den Totalen, in denen sie durch die Bäume geht."}'::jsonb WHERE id = 5106;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Sonny estrae la scatola con le armi dal sacchetto di carta all''interno della banca, la disposizione delle pistole e delle munizioni all''interno della scatola cambia visibilmente tra il primo piano e l''inquadratura successiva.","en":"When Sonny pulls the box of weapons out of the paper bag inside the bank, the arrangement of the guns and ammunition inside the box changes noticeably between the close-up and the following shot.","es":"Cuando Sonny saca la caja con las armas de la bolsa de papel dentro del banco, la disposición de las pistolas y la munición en el interior de la caja cambia visiblemente entre el primer plano y la toma siguiente.","fr":"Quand Sonny sort la boîte d''armes du sac en papier à l''intérieur de la banque, la disposition des armes et des munitions à l''intérieur de la boîte change visiblement entre le gros plan et le plan suivant.","de":"Als Sonny die Kiste mit den Waffen in der Bank aus der Papiertüte zieht, verändert sich die Anordnung der Pistolen und der Munition in der Kiste merklich zwischen der Nahaufnahme und der Folgeeinstellung."}'::jsonb WHERE id = 5107;
UPDATE errori SET descrizione_i18n = '{"it":"Il telefono usato da Sonny per parlare con la polizia all''interno della banca cambia modello o posizione del filo tra una ripresa e l''altra mentre è sotto forte stress emotivo.","en":"The telephone used by Sonny to talk to the police inside the bank changes model or cord placement between takes while he is under heavy emotional stress.","es":"El teléfono que usa Sonny para hablar con la policía dentro del banco cambia de modelo o de posición del cable de una toma a otra mientras se encuentra bajo un intenso estrés emocional.","fr":"Le téléphone utilisé par Sonny pour parler à la police à l''intérieur de la banque change de modèle ou de position de fil d''une prise à l''autre alors qu''il est sous un forte tension émotionnelle.","de":"Das Telefon, das Sonny benutzt, um in der Bank mit der Polizei zu sprechen, wechselt während starker emotionaler Belastung von einer Aufnahme zur nächsten das Modell oder die Position des Kabels."}'::jsonb WHERE id = 5108;
UPDATE errori SET descrizione_i18n = '{"it":"Le tapparelle e le finestre della banca, colpite o aperte dai personaggi in vari momenti concitati, mostrano doghe piegate in modo diverso nei tagli di montaggio successivi.","en":"The bank''s shutters and windows, hit or opened by the characters in various tense moments, show slats bent differently across successive editing cuts.","es":"Las persianas y ventanas del banco, golpeadas o abiertas por los personajes en varios momentos tensos, muestran lamas dobladas de forma diferente en los cortes de montaje sucesivos.","fr":"Les volets et les fenêtres de la banque, frappés ou ouverts par les personnages lors de plusieurs moments tendus, présentent des lames pliées différemment d''un raccord de montage à l''autre.","de":"Die Jalousien und Fenster der Bank, die von den Figuren in verschiedenen spannenden Momenten getroffen oder geöffnet werden, weisen in aufeinanderfolgenden Montage-Schnitten unterschiedlich verbogene Lamellen auf."}'::jsonb WHERE id = 5109;
UPDATE errori SET descrizione_i18n = '{"it":"In una delle inquadrature ampie riprese dall''esterno della folla di fronte alla banca, per una frazione di secondo è possibile intravedere l''asta di un microfono boom riflettersi nella vetrina di un negozio limitrofo.","en":"In one of the wide shots filmed from outside the crowd in front of the bank, for a fraction of a second a boom mic pole can be seen reflecting in the window of a nearby shop.","es":"En uno de los planos generales rodados desde el exterior de la multitud frente al banco, durante una fracción de segundo se puede vislumbrar la pértiga de un micrófono boom reflejándose en el escaparate de una tienda cercana.","fr":"Dans l''un des plans larges filmés de l''extérieur de la foule devant la banque, on peut apercevoir une fraction de seconde la perche d''un micro perche se refléter dans la vitrine d''un magasin voisin.","de":"In einer der Totalen, die von außerhalb der Menschenmenge vor der Bank gedreht wurden, ist für einen Bruchteil einer Sekunde die Angel einer Boom-Mikrofonstange in der Schaufensterscheibe eines umliegenden Ladens zu sehen."}'::jsonb WHERE id = 5110;
UPDATE errori SET descrizione_i18n = '{"it":"I sacchetti della spazzatura e i resti delle pizze consumate dagli ostaggi all''interno della banca cambiano posizione e quantità vicino al bancone tra le scene notturne e quelle successive.","en":"The garbage bags and leftovers of pizzas eaten by the hostages inside the bank change position and quantity near the counter between the night scenes and subsequent shots.","es":"Las bolsas de basura y los restos de pizza consumidos por los rehenes dentro del banco cambian de posición y cantidad cerca del mostrador entre las escenas nocturnas y las posteriores.","fr":"Les sacs poubelles et les restes de pizzas consommées par les otages à l''intérieur de la banque changent de position et de quantité près du comptoir entre les scènes de nuit et les plans suivants.","de":"Die Müllsäcke und die Reste der von den Geiseln in der Bank verzehrten Pizzen verändern zwischen den nächtlichen Szenen und den darauffolgenden Einstellungen ihre Position und Menge in der Nähe des Schalters."}'::jsonb WHERE id = 5111;
UPDATE errori SET descrizione_i18n = '{"it":"Durante alcune scene d''azione all''aperto, diversi attori e comparse indossano calzature con suole in gomma vulcanizzata moderna anziché scarponi d''epoca regolamentari della cavalleria ottocentesca.","en":"During some outdoor action scenes, several actors and extras wear footwear with modern vulcanized rubber soles instead of period-accurate regulation 19th-century cavalry boots.","es":"Durante algunas escenas de acción al aire libre, varios actores y extras llevan calzado con suelas de caucho vulcanizado moderno en lugar de las botas reglamentarias de época de la caballería del siglo XIX.","fr":"Pendant certaines scènes d''action en extérieur, plusieurs acteurs et figurants portent des chaussures à semelles en caoutchouc vulcanisé moderne au lieu des bottes réglementaires d''époque de la cavalerie du XIXe siècle.","de":"Während einiger Action-Außenszenen tragen mehrere Schauspieler und Statisten Schuhe mit modernen Vulkanisurkautschuk-Sohlen anstelle vorschriftsmäßiger historischer Kavalleriestiefel aus dem 19. Jahrhundert."}'::jsonb WHERE id = 5112;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Cresta e Honus riposano accanto a un fuoco da campo, la quantità di legna consumata e la posizione delle borracce cambiano visibilmente tra un''inquadratura e l''altra.","en":"In the scene where Cresta and Honus rest next to a campfire, the amount of burned wood and the position of the canteens visibly change from one shot to the next.","es":"En la escena en la que Cresta y Honus descansan junto a una hoguera, la cantidad de madera consumida y la posición de las cantimploras cambian visiblemente de un plano a otro.","fr":"Dans la scène où Cresta et Honus se reposent près d''un feu de camp, la quantité de bois consumé et la position des gourdes changent visiblement d''un plan à l''autre.","de":"In der Szene, in der Cresta und Honus an einem Lagerfeuer ausruhen, verändern sich die Menge des verbrauchten Holzes und die Position der Feldflaschen von Einstellung zu Einstellung sichtbar."}'::jsonb WHERE id = 5113;
UPDATE errori SET descrizione_i18n = '{"it":"In un primo piano stretto su Peter Strauss mentre cavalca nel deserto, è possibile intravedere brevemente l''ombra di un microfono a giraffa proiettata sulla roccia alle sue spalle.","en":"In a tight close-up of Peter Strauss riding through the desert, the shadow of a boom microphone can be briefly glimpsed cast against the rock behind him.","es":"En un primer plano cerrado de Peter Strauss cabalgando por el desierto, se puede atisbar brevemente la sombra de un micrófono de pértiga proyectada sobre la roca a sus espaldas.","fr":"Dans un gros plan serré de Peter Strauss chevauchant dans le désert, on peut entrapercevoir brièvement l''ombre d''un micro-perche projetée sur le rocher derrière lui.","de":"In einer engen Großaufnahme von Peter Strauss beim Ritt durch die Wüste ist kurz der Schatten eines Galgenmikrofons zu sehen, der auf den Felsen hinter ihm geworfen wird."}'::jsonb WHERE id = 5114;
UPDATE errori SET descrizione_i18n = '{"it":"In una sequenza dialogata tra i soldati, il movimento delle labbra di un attore secondario non coincide affatto con le battute audio che si sentono in sottofondo, chiaro segno di un ridoppiaggio in post-produzione.","en":"In a dialogue sequence between the soldiers, a supporting actor''s lip movements do not match the background audio lines at all, a clear sign of post-production ADR.","es":"En una secuencia de diálogo entre los soldados, el movimiento de los labios de un actor secundario no coincide en absoluto con las líneas de audio que se escuchan de fondo, un claro signo de doblaje en postproducción.","fr":"Dans une séquence de dialogue entre les soldats, les mouvements des lèvres d''un acteur secondaire ne correspondent pas du tout aux répliques audio entendues en fond, signe manifeste d''un doublage en post-production.","de":"In einer Dialogsequenz zwischen den Soldaten stimmen die Lippenbewegungen eines Nebendarstellers überhaupt nicht mit den im Hintergrund zu hörenden Audiodialogen überein, ein klarer Hinweis auf nachträgliches ADR (Nachynchronisation)."}'::jsonb WHERE id = 5115;
UPDATE errori SET descrizione_i18n = '{"it":"Le ferite e le bende applicate sui personaggi cambiano drasticamente lato del corpo o spariscono completamente a seconda che la ripresa sia frontale o di profilo.","en":"The injuries and bandages applied to the characters drastically switch sides of the body or completely disappear depending on whether the shot is frontal or in profile.","es":"Las heridas y vendajes aplicados a los personajes cambian drásticamente de lado del cuerpo o desaparecen por completo según el plano sea frontal o de perfil.","fr":"Les blessures et les bandages appliqués sur les personnages changent radicalement de côté du corps ou disparaissent complètement selon que le plan est de face ou de profil.","de":"Die Verletzungen und Verbände der Figuren wechseln drastisch die Körperseite oder verschwinden komplett, je nachdem, ob es sich um eine Frontal- oder Profileinstellung handelt."}'::jsonb WHERE id = 5116;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza del treno che trasporta Katniss e Peeta verso Capitol City, in un''inquadratura in cui si riflettono i finestrini, è possibile intravedere brevemente l''ombra di un operatore della troupe con una cinepresa.","en":"During the train sequence carrying Katniss and Peeta to Capitol City, in a shot reflecting off the windows, the shadow of a crew member with a camera can be briefly glimpsed.","es":"Durante la secuencia del tren que transporta a Katniss y Peeta hacia el Capitolio, en un plano donde se reflejan las ventanas, se puede vislumbrar brevemente la sombra de un miembro del equipo técnico con una cámara.","fr":"Pendant la séquence du train transportant Katniss et Peeta vers le Capitole, dans un plan reflétant les vitres, on peut entrevoir brièvement l''ombre d''un technicien de l''équipe avec une caméra.","de":"Während der Zugszene, die Katniss und Peeta in die Kapitol-Stadt bringt, ist in einer Einstellung mit Spiegelung in den Fenstern kurz der Schatten eines Crewmitglieds mit einer Kamera zu erkennen."}'::jsonb WHERE id = 5117;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sessione di addestramento in cui Katniss si esercita a lanciare i coltelli, i bersagli colpiti mostrano i coltelli conficcati con inclinazioni differenti tra l''inquadratura larga e il primo piano ravvicinato dell''arma.","en":"During the training session where Katniss practices knife throwing, the hit targets show the knives stuck at different angles between the wide shot and the tight close-up of the weapon.","es":"Durante la sesión de entrenamiento en la que Katniss practica el lanzamiento de cuchillos, los blancos alcanzados muestran los cuchillos clavados con diferentes inclinaciones entre el plano general y el primer plano cerrado del arma.","fr":"Pendant la session d''entraînement où Katniss s''exerce au lancer de couteaux, les cibles touchées montrent les couteaux plantés avec des inclinaisons différentes entre le plan large et le gros plan serré de l''arme.","de":"Während der Trainingseinheit, in der Katniss das Messerwerfen übt, stecken die Messer in den Zielscheiben zwischen der Totalen und der nahen Nahaufnahme der Waffe in unterschiedlichen Winkeln."}'::jsonb WHERE id = 5118;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Katniss si arrampica sull''albero per sfuggire ai Tributi Favoriti che la braccano, lo zaino che indossa scompare e riappare o cambia la disposizione delle cinghie tra una ripresa dal basso e la vista dall''alto.","en":"When Katniss climbs the tree to escape the pursuing Career Tributes, the backpack she wears disappears and reappears, or its strap arrangement changes between a low-angle shot and an overhead view.","es":"En el momento en que Katniss trepa al árbol para escapar de los Tributos Profesionales que la persiguen, la mochila que lleva desaparece y vuelve a aparecer, o cambia la disposición de las correas entre un plano contrapicado y una vista cenital.","fr":"Au moment où Katniss grimpe à l''arbre pour échapper aux Tributs Carrières qui la traquent, le sac à dos qu''elle porte disparaît et réapparaît, ou la disposition des sangle change entre une contre-plongée et une vue en surplomb.","de":"In dem Moment, in dem Katniss auf den Baum klettert, um den verfolgenden Karrieristen zu entkommen, verschwindet und reappearing der Rucksack, den sie trägt, oder die Anordnung der Riemen ändert sich zwischen einer Untersicht und einer Aufsicht."}'::jsonb WHERE id = 5119;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Katniss si trova all''interno della Cornucopia per recuperare la medicina per Peeta, il numero e la posizione delle sacche e delle attrezzature mediche intorno a lei variano visibilmente quando la telecamera cambia angolazione.","en":"When Katniss is inside the Cornucopia to retrieve the medicine for Peeta, the number and position of the bags and medical equipment around her visibly change when the camera changes angles.","es":"Cuando Katniss está dentro de la Cornucopia para recuperar la medicina para Peeta, el número y la posición de las bolsas y el equipo médico a su alrededor varían visiblemente cuando cambia el ángulo de cámara.","fr":"Quand Katniss se trouve à l''intérieur de la Cornucopia pour récupérer le médicament pour Peeta, le nombre et la position des sacs et du matériel médical autour d''elle varient visiblement lors des changements d''angle de caméra.","de":"Als Katniss sich im Inneren des Füllhorns befindet, um die Medizin für Peeta zu holen, variieren Anzahl und Position der Taschen und der medizinischen Ausrüstung um sie herum bei Kamerawinkelwechseln sichtbar."}'::jsonb WHERE id = 5120;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la festa a casa di Snow, il bicchiere tenuto da un ospite cambia mano e livello di riempimento tra un''inquadratura e l''altra mentre parla con Katniss.","en":"During the party at Snow''s mansion, the glass held by a guest changes hands and fill level between cuts while talking to Katniss.","es":"Durante la fiesta en la casa de Snow, la copa que sostiene un invitado cambia de mano y de nivel de llenado entre plano y plano mientras habla con Katniss.","fr":"Pendant la fête chez Snow, le verre tenu par un invité change de main et de niveau de remplissage d''un plan à l''autre en parlant avec Katniss.","de":"Während der Party in Snows Haus wechselt das Glas, das ein Gast hält, zwischen den Einstellungen die Hand und den Füllstand, während er mit Katniss spricht."}'::jsonb WHERE id = 5121;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Katniss e Peeta si salutano sul treno prima di entrare nell''arena, i segni di sudore e le ciocche bagnate sulla fronte di Katniss variano drasticamente nei cambi di inquadratura.","en":"When Katniss and Peeta say goodbye on the train before entering the arena, the sweat stains and wet locks of hair on Katniss''s forehead vary drastically across shot changes.","es":"Cuando Katniss y Peeta se despiden en el tren antes de entrar en la arena, las marcas de sudor y los mechones mojados en la frente de Katniss varían drásticamente entre plano y plano.","fr":"Quand Katniss et Peeta se font leurs adieux dans le train avant d''entrer dans l''arène, les traces de sueur et les mèches mouillées sur le front de Katniss varient considérablement d''un plan à l''autre.","de":"Als Katniss und Peeta sich im Zug vor dem Betreten der Arena verabschieden, variieren die Schweißflecken und nassen Haarlocken auf Katniss'' Stirn bei den Szenenwechseln drastisch."}'::jsonb WHERE id = 5122;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui i tributi salgono sulle piattaforme dell''arena prima del countdown, il numero di piastrine e la disposizione dell''acqua intorno cambiano leggermente nei dettagli.","en":"In the scene where the tributes step onto the arena platforms before the countdown, the number of metal plates and the arrangement of the surrounding water change slightly in the details.","es":"En la escena en la que los tributos suben a las plataformas de la arena antes de la cuenta atrás, el número de placas y la disposición del agua alrededor cambian ligeramente en los detalles.","fr":"Dans la scène où les tributs montent sur les plates-formes de l''arène avant le compte à rebours, le nombre de plaques et la disposition de l''eau autour changent légèrement dans les détails.","de":"In der Szene, in der die Tribute vor dem Countdown die Plattformen der Arena betreten, verändern sich die Anzahl der Platten und die Anordnung des Wassers drumherum in den Details leicht."}'::jsonb WHERE id = 5123;
UPDATE errori SET descrizione_i18n = '{"it":"In una rapida inquadratura grandangolare mentre i personaggi corrono attraverso la fitta nebbia velenosa nella giungla, si intravede per un fotogramma il riflesso di un pannello riflettente della troupe su un elmetto o una superficie lucida.","en":"In a quick wide shot as the characters run through the thick poisonous fog in the jungle, the reflection of a crew''s reflector panel can be glimpsed for a single frame on a helmet or shiny surface.","es":"En un plano general rápido mientras los personajes corren a través de la densa niebla venenosa en la selva, se vislumbra durante un fotograma el reflejo de una pantalla reflectora del equipo técnico en un casco o superficie brillante.","fr":"Dans un plan large rapide alors que les personnages courent à travers l''épais brouillard vénéneux dans la jungle, on entrevoit pendant une seule image le reflet d''un panneau réflecteur de l''équipe sur un casque ou une surface brillante.","de":"In einer schnellen Weitwinkelaufnahme, während die 캐릭터 durch den dichten giftigen Nebel im Dschungel rennen, ist für einen einzelnen Frame die Spiegelung eines Reflektorschirms der Crew auf einem Helm oder einer glänzenden Oberfläche zu erahnen."}'::jsonb WHERE id = 5124;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Beetee collega i cavi all''albero prima della scossa elettrica, la lunghezza e la disposizione del filo che tiene in mano variano in modo evidente tra i primi piani e i campi medi.","en":"When Beetee connects the wires to the tree before the electric shock, the length and layout of the wire he is holding noticeably change between close-ups and medium shots.","es":"Cuando Beetee conecta los cables al árbol antes de la descarga eléctrica, la longitud y la disposición del cable que tiene en la mano varían de forma evidente entre los primeros planos y los planos medios.","fr":"Quand Beetee connecte les câbles à l''arbre avant la décharge électrique, la longueur et la disposition du fil qu''il tient dans sa main changent de manière évidente entre les gros plans et les plans moyens.","de":"Als Beetee vor dem Elektroschock die Kabel an den Baum anschließt, verändern sich die Länge und der Verlauf des Kabels, das er in der Hand hält, zwischen Nahaufnahmen und Halbtotalen deutlich."}'::jsonb WHERE id = 5125;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Katniss si trova nei corridoi del Distretto 13 e indossa la sua uniforme grigia, la zip della giacca sale e scende leggermente di livello tra un''inquadratura e l''altra durante il dialogo con Haymitch.","en":"When Katniss is in the corridors of District 13 wearing her grey uniform, her jacket zipper moves slightly up and down between cuts during her dialogue with Haymitch.","es":"Cuando Katniss se encuentra en los pasillos del Distrito 13 con su uniforme gris, la cremallera de la chaqueta sube y baja ligeramente de nivel entre plano y plano durante el diálogo con Haymitch.","fr":"Quand Katniss se trouve dans les couloirs du District 13 et porte son uniforme gris, la fermeture éclair de sa veste monte et descend légèrement d''un plan à l''autre pendant le dialogue avec Haymitch.","de":"Als Katniss sich in den Korridoren von Distrikt 13 befindet und ihre graue Uniform trägt, verändert sich die Position des Reißverschlusses ihrer Jacke zwischen den Einstellungen während des Dialogs mit Haymitch leicht."}'::jsonb WHERE id = 5126;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la trasmissione del primo propos nel Distretto 4, i monitor sullo sfondo mostrano sequenze di immagini che cambiano ordine cronologico rispetto alla diretta vista nelle inquadrature precedenti.","en":"During the broadcast of the first propos in District 4, the background monitors show image sequences that change chronological order compared to the live feed seen in previous shots.","es":"Durante la transmisión del primer propos en el Distrito 4, los monitores del fondo muestran secuencias de imágenes que cambian de orden cronológico respecto a la emisión en directo vista en los planos anteriores.","fr":"Pendant la diffusion du premier propos dans le District 4, les moniteurs en arrière-plan montrent des séquences d''images dont l''ordre chronologique change par rapport au direct vu dans les plans précédents.","de":"Während der Ausstrahlung des ersten Propos in Distrikt 4 zeigen die Monitore im Hintergrund Bildsequenzen, deren chronologische Reihenfolge sich im Vergleich zur Live-Übertragung in vorherigen Einstellungen verändert hat."}'::jsonb WHERE id = 5127;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui i ribelli entrano nei tunnel bui per sfuggire ai bombardamenti, per un istante si nota il riflesso di una luce di riempimento della troupe sulla visiera di un casco protettivo.","en":"In the sequence where the rebels enter the dark tunnels to escape the bombings, the reflection of a crew fill light can briefly be seen on the visor of a protective helmet.","es":"En la secuencia en la que los rebeldes entran en los túneles oscuros para escapar de los bombardeos, se ve brevemente el reflejo de una luz de relleno del equipo en la visera de un casco protector.","fr":"Dans la séquence où les rebelles entrent dans les tunnels sombres pour échapper aux bombardements, on aperçoit brièvement le reflet d''une lumière de remplissage de l''équipe technique sur la visière d''un casque de protection.","de":"In der Sequenz, in der die Rebellen die dunklen Tunnel betreten, um den Bombardements zu entkommen, ist für einen Moment die Reflexion eines Aufhellers der Crew auf dem Visier eines Schutzhelms zu sehen."}'::jsonb WHERE id = 5128;
UPDATE errori SET descrizione_i18n = '{"it":"Nel centro di comando del Distretto 13, la tazza di caffè sulla console di Beetee cambia posizione rispetto al bordo del tavolo e al blocco di appunti digitale tra un primo piano e un campo medio.","en":"In the District 13 command center, the coffee mug on Beetee''s console changes position relative to the edge of the table and the digital notepad between a close-up and a medium shot.","es":"En el centro de mando del Distrito 13, la taza de café en la consola de Beetee cambia de posición respecto al borde de la mesa y el bloc de notas digital entre un primer plano y un plano medio.","fr":"Dans le centre de commande du District 13, la tasse à café sur la console de Beetee change de position par rapport au bord de la table et au bloc-notes numérique entre un gros plan et un plan moyen.","de":"Im Kommandozentrum von Distrikt 13 verändert sich die Position der Kaffeetasse auf Betees Konsole im Verhältnis zur Tischkante und dem digitalen Notizblock zwischen einer Nahaufnahme und einer Halbtotale."}'::jsonb WHERE id = 5129;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Katniss si risveglia nel letto dopo l''attacco di Johanna, il collare medico e le coperte cambiano disposizione in modo evidente tra un''inquadratura ravvicinata e quella a campo largo.","en":"When Katniss wakes up in bed after Johanna''s attack, the medical collar and blankets noticeably change arrangement between a close-up shot and a wide shot.","es":"Cuando Katniss se despierta en la cama tras el ataque de Johanna, el collarín médico y las mantas cambian de disposición de forma evidente entre un plano corto y un plano general.","fr":"Quand Katniss se réveille dans son lit après l''attaque de Johanna, la collier cervical et les couvertures changent visiblement de disposition entre un plan serré et un plan large.","de":"Als Katniss nach Johannas Angriff im Bett aufwacht, verändern sich die Position der Halskrause und der Decken zwischen einer Nahaufnahme und einer Totale deutlich."}'::jsonb WHERE id = 5130;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza concitata nei tunnel bui di Capitol City contro le lucertole mutanti, in un breve controcampo è possibile intravedere brevemente l''ombra di un microfono boom sulla parete bagnata.","en":"During the intense sequence in the dark tunnels of Capitol City against the mutant lizards, in a quick reverse shot the shadow of a boom mic can be briefly glimpsed on the wet wall.","es":"Durante la frenética secuencia en los oscuros túneles de Capitol City contra los lagartos mutantes, en un breve plano contraplano se puede atisbar fugazmente la sombra de un micrófono de pértiga en la pared mojada.","fr":"Pendant la séquence mouvementée dans les sombres tunnels de Capitol City contre les lézards mutants, on peut apercevoir brièvement l''ombre d''un micro perche sur le mur mouillé lors d''un contrechamp rapide.","de":"Während der rasanten Sequenz in den dunklen Tunneln von Capitol City gegen die mutierten Echsen ist in einer kurzen Gegenschuss-Einstellung kurz der Schatten eines Galgenmikrofons an der nassen Wand zu sehen."}'::jsonb WHERE id = 5131;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui il gruppo si rifugia nell''appartamento abbandonato, il cibo e le stoviglie sul tavolo cambiano posizione e quantità tra l''inquadratura in cui li guardano e il primo piano successivo.","en":"In the scene where the group takes refuge in the abandoned apartment, the food and tableware on the table change position and quantity between the shot where they look at them and the subsequent close-up.","es":"En la escena en la que el grupo se refugia en el apartamento abandonado, la comida y la vajilla de la mesa cambian de posición y cantidad entre el plano en el que los miran y el primer plano posterior.","fr":"Dans la scène où le groupe se réfugie dans l''appartement abandonné, la nourriture et la vaisselle sur la table changent de position et de quantité entre le plan où ils les regardent et le gros plan suivant.","de":"In der Szene, in der sich die Gruppe in der verlassenen Wohnung versteckt, verändern sich Essen und Geschirr auf dem Tisch in Position und Anzahl zwischen der Einstellung, in der sie darauf schauen, und der folgenden Nahaufnahme."}'::jsonb WHERE id = 5132;
UPDATE errori SET descrizione_i18n = '{"it":"Durante l''esecuzione finale del Presidente Snow, la posizione delle guardie di Capitol City attorno al palo del boia varia leggermente tra i diversi stacchi di montaggio.","en":"During President Snow''s final execution, the position of the Capitol City guards around the execution post varies slightly between different editing cuts.","es":"Durante la ejecución final del presidente Snow, la posición de los guardias de Capitol City alrededor del poste de la horca varía ligeramente entre los distintos cortes de montaje.","fr":"Pendant l''exécution finale du Président Snow, la position des gardes de Capitol City autour du poteau d''exécution varie légèrement d''un raccord de montage à l''autre.","de":"Während der finalen Hinrichtung von Präsident Snow variiert die Position der Wachen aus Capitol City rund um den Hinrichtungspfahl zwischen den verschiedenen Schnittwechseln leicht."}'::jsonb WHERE id = 5133;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Gru entra nel suo ufficio e parla con il Dr. Nefario, la tazza di caffè sulla scrivania cambia posizione e inclinazione tra le inquadrature successive.","en":"When Gru enters his office and talks to Dr. Nefario, the coffee mug on the desk changes position and tilt between successive shots.","es":"Cuando Gru entra en su despacho y habla con el Dr. Nefario, la taza de café del escritorio cambia de posición e inclinación entre planos sucesivos.","fr":"Quand Gru entre dans son bureau et parle au Dr Nefario, la tasse à café sur le bureau change de position et d''inclinaison entre les plans successifs.","de":"Wenn Gru sein Büro betritt und mit Dr. Nefario spricht, verändern sich Position und Neigung der Kaffeetasse auf dem Schreibtisch zwischen den aufeinanderfolgenden Einstellungen."}'::jsonb WHERE id = 5134;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la visita all''orfanotrofio, le bambine indossano cappotti e sciarpe che scompaiono e riappaiono improvvisamente tra un cambio d''inquadratura e l''altro mentre escono dall''edificio.","en":"During the orphanage visit, the little girls wear coats and scarves that suddenly disappear and reappear between camera cuts as they exit the building.","es":"Durante la visita al orfanato, las niñas llevan abrigos y bufandas que desaparecen y reaparecen repentinamente entre un plano y otro al salir del edificio.","fr":"Pendant la visite de l''orphelinat, les fillettes portent des manteaux et des écharpes qui disparaissent et réapparaissent soudainement d''un plan à l''autre alors qu''elles sortent du bâtiment.","de":"Während des Besuchs im Waisenhaus tragen die Mädchen Mäntel und Schals, die zwischen den verschiedenen Kameraeinstellungen beim Verlassen des Gebäudes plötzlich verschwinden und wieder auftauchen."}'::jsonb WHERE id = 5135;
UPDATE errori SET descrizione_i18n = '{"it":"Nella cucina di Gru, i biscotti disposti sul piatto cambiano disposizione e numero quando le tre bambine si avvicinano per prenderli.","en":"In Gru''s kitchen, the cookies arranged on the plate change their arrangement and number when the three little girls reach out to grab them.","es":"En la cocina de Gru, las galletas colocadas en el plato cambian de disposición y número cuando las tres niñas se acercan a cogerlas.","fr":"Dans la cuisine de Gru, les biscuits disposés sur l''assiette changent de disposition et de nombre lorsque les trois fillettes s''approchent pour les attraper.","de":"In Grus Küche verändern die auf dem Teller angerichteten Kekse ihre Anordnung und Anzahl, als sich die drei Mädchen nähern, um sie sich zu nehmen."}'::jsonb WHERE id = 5136;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza del parco di divertimenti Super Silly Fun Land, i baracchini e i dettagli dello sfondo variano visibilmente di posizione quando la telecamera cambia angolazione.","en":"During the Super Silly Fun Land amusement park sequence, the booths and background details noticeably shift position when the camera angle changes.","es":"Durante la secuencia del parque de atracciones Super Silly Fun Land, los puestos y los detalles del fondo cambian visiblemente de posición cuando cambia el ángulo de cámara.","fr":"Pendant la séquence du parc d''attractions Super Silly Fun Land, les stands et les détails de l''arrière-plan changent visiblement de position lors des changements d''angle de caméra.","de":"Während der Vergnügungspark-Sequenz von Super Silly Fun Land verändern die Buden und Hintergrunddetails bei einem Kameraschwenk bzw. Szenenwechsel sichtbar ihre Position."}'::jsonb WHERE id = 5137;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Gru viene catturato da Lucy Wilde e infilato nel bagagliaio della sua auto, la borsa che indossa sulla spalla scompare improvvisamente tra un''inquadratura e l''altra mentre viene caricato nel veicolo.","en":"When Gru is captured by Lucy Wilde and shoved into the trunk of her car, the bag he is wearing over his shoulder suddenly disappears between cuts as he is loaded into the vehicle.","es":"Cuando Gru es capturado por Lucy Wilde y metido en el maletero de su coche, el bolso que lleva al hombro desaparece repentinamente entre plano y plano mientras es cargado en el vehículo.","fr":"Quand Gru est capturé par Lucy Wilde et fourré dans le coffre de sa voiture, le sac qu''il porte à l''épaule disparaît soudainement d''un plan à l''autre alors qu''il est chargé dans le véhicule.","de":"Als Gru von Lucy Wilde gefangen genommen und in den Kofferraum ihres Autos gesteckt wird, verschwindet die Tasche, die er über der Schulter trägt, plötzlich zwischen zwei Einstellungen, während er in das Fahrzeug verladen wird."}'::jsonb WHERE id = 5138;
UPDATE errori SET descrizione_i18n = '{"it":"Nel quartier generale della AVL, quando Silas Caprifico mostra a Gru le varie armi e gadget (come il rossetto stordente), gli oggetti sul tavolo cambiano disposizione e numero tra un''inquadratura larga e i primi piani.","en":"At the AVL headquarters, when Silas Ramsbottom shows Gru various weapons and gadgets (like the lipstick taser), the props on the table change arrangement and number between a wide shot and close-ups.","es":"En el cuartel general de la AVL, cuando Silas Carneros muestra a Gru varias armas y dispositivos (como el pintalabios aturdidor), los objetos de la mesa cambian de disposición y número entre un plano general y los primeros planos.","fr":"Au QG de l''AVL, lorsque Silas de Puant montre à Gru les différentes armes et gadgets (comme le rouge à lèvres Taser), les accessoires sur la table changent de disposition et de nombre entre un plan large et les gros plans.","de":"Im Hauptquartier der AVL verändern die Requisiten auf dem Tisch ihre Anordnung und Anzahl zwischen einer Totalen und Nahaufnahmen, als Silas Ramsbottom Gru verschiedene Waffen und Gadgets (wie den Lippenstift-Taser) zeigt."}'::jsonb WHERE id = 5139;
UPDATE errori SET descrizione_i18n = '{"it":"All''interno del ristorante in stile messicano ''Salsa & Salsa'' gestito da Eduardo al centro commerciale, i bicchieri sui tavoli vicini cambiano posizione e livello di liquido tra un cambio di inquadratura e l''altro durante la conversazione.","en":"Inside the Mexican-style restaurant ''Salsa & Salsa'' run by Eduardo at the mall, the glasses on nearby tables change position and liquid level between cuts during the conversation.","es":"Dentro del restaurante de estilo mexicano ''Salsa & Salsa'' regentado por Eduardo en el centro comercial, los vasos de las mesas cercanas cambian de posición y de nivel de líquido entre plano y plano durante la conversación.","fr":"À l''intérieur du restaurant de style mexicain ''Salsa & Salsa'' tenu par Eduardo au centre commercial, les verres sur les tables voisines changent de position et de niveau de liquide d''un plan à l''autre pendant la conversation.","de":"Im mexikanischen Restaurant „Salsa & Salsa“ von Eduardo im Einkaufszentrum verändern die Gläser auf den Nebentischen während des Gesprächs zwischen den Kameraeinstellungen ihre Position und ihren Füllstand."}'::jsonb WHERE id = 5140;
UPDATE errori SET descrizione_i18n = '{"it":"Nel laboratorio segreto dove i Minions vengono trasformati in mostri viola, le fiale e gli strumenti chimici sul bancone di El Macho variano per colore e disposizione nei diversi stacchi di montaggio.","en":"In the secret laboratory where the Minions are turned into purple monsters, the vials and chemical equipment on El Macho''s counter vary in color and arrangement across different cuts.","es":"En el laboratorio secreto donde los Minions son transformados en monstruos morados, los viales y el instrumental químico del mostrador de El Macho varían en color y disposición en los distintos cortes de montaje.","fr":"Dans le laboratoire secret où les Minions sont transformés en monstres violet, les fioles et le matériel chimique sur le comptoir d''El Macho varient en couleur et en disposition au fil des raccords.","de":"In dem geheimen Labor, in dem die Minions in lila Monster verwandelt werden, variieren die Ampullen und chemischen Geräte auf El Machos Tresen bei den verschiedenen Schnitten in Farbe und Anordnung."}'::jsonb WHERE id = 5141;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza finale sulla spiaggia e vicino agli scogli, gli attrezzi e i componenti del cannone anti-PX-4 usati dalle ragazze e da Dr. Nefario cambiano posizione sulla sabbia tra un''inquadratura e la successiva.","en":"During the final sequence on the beach and near the rocks, the tools and anti-PX-4 cannon components used by the girls and Dr. Nefario change position on the sand between shots.","es":"Durante la secuencia final en la playa y cerca de las rocas, las herramientas y los componentes del cañón anti-PX-4 utilizados por las niñas y el Dr. Nefario cambian de posición en la arena de un plano a otro.","fr":"Pendant la séquence finale sur la plage et près des rochers, les outils et les composants du canon anti-PX-4 utilisés par les filles et le Dr Nefario changent de position sur le sable d''un plan à l''autre.","de":"Während der Schlussszene am Strand und nahe den Felsen verändern die Werkzeuge und Komponenten der Anti-PX-4-Kanone, die von den Mädchen und Dr. Nefario benutzt werden, zwischen den Einstellungen ihre Position im Sand."}'::jsonb WHERE id = 5142;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui i Minions viaggiano in autostrada verso Orlando nel 1968, si vede brevemente un cartello stradale con uno stile di carattere e una segnaletica autostradale statunitense che riflette standard introdotti solo negli anni ''70.","en":"During the scene where the Minions are road-tripping to Orlando in 1968, a road sign is briefly seen featuring a font style and US highway signage reflecting standards introduced only in the 1970s.","es":"Durante la escena en la que los Minions viajan por la autopista hacia Orlando en 1968, se ve brevemente una señal de tráfico con un estilo de tipografía y señalización estadounidense que refleja estándares introducidos solo en la década de 1970.","fr":"Pendant la scène où les Minions prennent l''autoroute pour Orlando en 1968, on aperçoit brièvement un panneau routier dont la police de caractères et la signalétique américaine correspondent à des normes introduites seulement dans les années 1970.","de":"In der Szene, in der die Minions 1968 auf dem Highway nach Orlando unterwegs sind, ist kurz ein Straßenschild mit einer Schriftart und US-Autobahnbeschilderung zu sehen, die Standards widerspiegeln, die erst in den 1970er Jahren eingeführt wurden."}'::jsonb WHERE id = 5143;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Scarlet Sterminator entra nel suo laboratorio segreto, i gadget tecnologici sul tavolo cambiano disposizione e numero tra un cambio di inquadratura e l''altro senza che nessun personaggio li tocchi.","en":"When Scarlet Overkill enters her secret laboratory, the tech gadgets on the table change arrangement and number between cuts without any character touching them.","es":"Cuando Scarlet Overkill entra en su laboratorio secreto, los dispositivos tecnológicos de la mesa cambian de disposición y número entre plano y plano sin que ningún personaje los toque.","fr":"Quand Scarlet Overkill entre dans son laboratoire secret, les gadgets technologiques sur la table changent de disposition et de nombre d''un plan à l''autre sans qu''aucun personnage ne les touche.","de":"Als Scarlet Overkill ihr geheimes Labor betritt, verändern die technischen Gadgets auf dem Tisch zwischen den Einstellungen ihre Anordnung und Anzahl, ohne dass sie von einer Figur berührt werden."}'::jsonb WHERE id = 5144;
UPDATE errori SET descrizione_i18n = '{"it":"Nel Regno Unito del 1968, in alcune sequenze di fuga per le strade di Londra, si possono notare modelli di automobili e furgoni britannici che riportano targhe con formati e combinazioni alfanumeriche non in uso in quel determinato anno.","en":"In 1968 the UK, during some chase sequences through the streets of London, British car and van models can be spotted featuring license plates with formats and alphanumeric combinations not in use in that specific year.","es":"En el Reino Unido de 1968, durante algunas secuencias de persecución por las calles de Londres, se pueden ver modelos de automóviles y furgonetas británicas con matrículas cuyos formatos y combinaciones alfanuméricas no se usaban en ese año en particular.","fr":"Dans le Royaume-Uni de 1968, lors de certaines séquences de course-poursuite dans les rues de Londres, on peut apercevoir des modèles de voitures et de camionnettes britanniques arborant des plaques d''immatriculation aux formats et combinaisons alphanumériques non utilisés cette année-là.","de":"Im Großbritannien des Jahres 1968 sind in einigen Verfolgungsjagden durch die Straßen von London britische Auto- und Transportermodelle zu sehen, deren Kennzeichen Formate und alphanumerische Kombinationen aufweisen, die in jenem Jahr noch gar nicht gebräuchlich waren."}'::jsonb WHERE id = 5145;
UPDATE errori SET descrizione_i18n = '{"it":"La rappresentazione dell''incoronazione della Regina Elisabetta II all''interno della storia mostra elementi di protocollo e dettagli storici della cerimonia alterati rispetto agli eventi reali del 1953, sebbene il film sia ambientato nel 1968 (anno in cui la Regina era già sul trono da quindici anni e non fu incoronata).","en":"The depiction of Queen Elizabeth II''s coronation within the story features protocol elements and historical details of the ceremony altered compared to the actual 1953 events, even though the film is set in 1968 (when the Queen had already been on the throne for fifteen years and was not crowned).","es":"La representación de la coronación de la Reina Isabel II en la historia muestra elementos de protocolo y detalles históricos de la ceremonia alterados en comparación con los eventos reales de 1953, a pesar de que la película está ambientada en 1968 (año en el que la Reina llevaba quince años en el trono y no fue coronada).","fr":"La représentation du couronnement de la reine Élisabeth II dans l''histoire présente des éléments de protocole et des détails historiques de la cérémonie modifiés par rapport aux événements réels de 1953, bien que le film se déroule en 1968 (année où la reine était déjà sur le trône depuis quinze ans et n''a pas été couronnée).","de":"Die Darstellung der Krönung von Königin Elizabeth II. in der Handlung zeigt Protokollelemente und historische Details der Zeremonie, die gegenüber den realen Ereignissen von 1953 verändert wurden, obwohl der Film im Jahr 1968 spielt (in dem die Königin bereits seit fünfzehn Jahren auf dem Thron saß und nicht gekrönt wurde)."}'::jsonb WHERE id = 5146;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il Detective Loki interroga Keller Dover a casa sua dopo la scomparsa delle bambine, la tazza di caffè sul tavolo cambia posizione e livello di liquido tra un''inquadratura e l''altra del controcampo.","en":"During the scene where Detective Loki questions Keller Dover at his home after the girls'' disappearance, the coffee mug on the table changes position and liquid level between shots in the shot-reverse-shot setup.","es":"Durante la escena en la que el detective Loki interroga a Keller Dover en su casa tras la desaparición de las niñas, la taza de café sobre la mesa cambia de posición y de nivel de líquido entre plano y contraplano.","fr":"Pendant la scène où le détective Loki interroge Keller Dover chez lui après la disparition des fillettes, la tasse de café sur la table change de position et de niveau de liquide d''un plan à l''autre du champ-contrechamp.","de":"Während der Szene, in der Detective Loki Keller Dover nach dem Verschwinden der Mädchen zu Hause verhört, verändern sich die Position der Kaffeetasse auf dem Tisch und der Flüssigkeitsstand zwischen den Einstellungen im Schuss-Gegenschuss."}'::jsonb WHERE id = 5147;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Keller tiene prigioniero Alex nella vecchia casa, la bottiglia d''acqua e gli strumenti utilizzati per la tortura cambiano disposizione sul tavolino di legno tra i primi piani e i campi medi.","en":"When Keller keeps Alex captive in the old house, the water bottle and the torture tools change arrangement on the wooden coffee table between close-ups and medium shots.","es":"Cuando Keller mantiene prisionero a Alex en la vieja casa, la botella de agua y los instrumentos utilizados para la tortura cambian de disposición en la mesa de madera entre los primeros planos y los planos medios.","fr":"Quand Keller retient Alex prisonnier dans la vieille maison, la bouteille d''eau et les instruments de torture changent de disposition sur la table basse en bois entre les gros plans et les plans moyens.","de":"Wenn Keller Alex in dem alten Haus gefangen hält, verändern die Wasserflasche und die Folterwerkzeuge ihre Anordnung auf dem Holztisch zwischen den Nahaufnahmen und Halbtotale-Einstellungen."}'::jsonb WHERE id = 5148;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sequenza notturna in cui Loki insegue il sospettato sotto la pioggia battente, la pettinatura e il grado di bagnato dei capelli dell''attore Jake Gyllenhaal variano notevolmente tra un cambio di inquadratura e il successivo.","en":"During the nighttime sequence where Loki chases the suspect in the pouring rain, actor Jake Gyllenhaal''s hairstyle and how wet his hair is vary noticeably from one camera angle to the next.","es":"Durante la secuencia nocturna en la que Loki persigue al sospechoso bajo la lluvia torrencial, el peinado y el grado de humedad del cabello del actor Jake Gyllenhaal varían notablemente de un cambio de plano a otro.","fr":"Au cours de la séquence nocturne où Loki poursuit le suspect sous une pluie battante, la coiffure et le degré d''humidité des cheveux de l''acteur Jake Gyllenhaal varient considérablement d''un changement de plan à l''autre.","de":"Während der nächtlichen Sequenz, in der Loki den Verdächtigen im strömenden Regen verfolgt, variieren die Frisur und der Nässegrad der Haare von Schauspieler Jake Gyllenhaal von einem Szenenwechsel zum nächsten deutlich."}'::jsonb WHERE id = 5149;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui il Detective Loki si reca al negozio di animali e parla con il proprietario, la disposizione dei volantini e delle locandine sulla bacheca dietro al bancone cambia visibilmente tra un''inquadratura e l''altra.","en":"During the scene where Detective Loki visits the pet store and talks to the owner, the arrangement of flyers and posters on the bulletin board behind the counter visibly changes between shots.","es":"Durante la escena en la que el detective Loki va a la tienda de animales y habla con el dueño, la disposición de los folletos y carteles en el tablón de anuncios detrás del mostrador cambia visiblemente entre plano y plano.","fr":"Pendant la scène où le détective Loki se rend à animalerie et parle au propriétaire, la disposition des prospectus et des affiches sur le panneau d''affichage derrière le comptoir change visiblement d''un plan à l''autre.","de":"Während der Szene, in der Detective Loki das Zoogeschäft betritt und mit dem Besitzer spricht, verändert sich die Anordnung der Flyer und Poster an der Pinnwand hinter dem Tresen zwischen den Einstellungen sichtbar."}'::jsonb WHERE id = 5150;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Keller Dover è nel furgone e riceve una telefonata, lo schermo dello smartphone mostra chiaramente la schermata della rubrica o il desktop anziché una chiamata in corso attiva, a seconda dell''angolazione della telecamera.","en":"When Keller Dover is in the van and receives a phone call, the smartphone screen clearly displays the contacts menu or the home screen instead of an active ongoing call, depending on the camera angle.","es":"Cuando Keller Dover está en la furgoneta y recibe una llamada telefónica, la pantalla del smartphone muestra claramente la agenda de contactos o el escritorio en lugar de una llamada activa en curso, según el ángulo de la cámara.","fr":"Quand Keller Dover est dans la camionnette et reçoit un appel téléphonique, l''écran du smartphone affiche clairement le répertoire ou le bureau au lieu d''un appel en cours, selon l''angle de la caméra.","de":"Wenn Keller Dover im Lieferwagen sitzt und einen Anruf erhält, zeigt das Smartphone-Display je nach Kamerawinkel deutlich das Kontakte-Menü oder den Startbildschirm anstelle eines aktiven laufenden Anrufs."}'::jsonb WHERE id = 5151;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui il Detective Loki corre disperatamente nel buio della notte alla ricerca della casa dei Jones, in un rapido controcampo grandangolare è possibile intravedere brevemente la sagoma di un operatore di ripresa sul lato sinistro dell''inquadratura.","en":"During the sequence where Detective Loki runs desperately through the dark night looking for the Jones house, in a quick wide-angle reverse shot the silhouette of a camera operator can be briefly glimpsed on the left side of the frame.","es":"Durante la secuencia en la que el detective Loki corre desesperadamente en la oscuridad de la noche buscando la casa de los Jones, en un rápido contraplano gran angular se puede atisbar brevemente la silueta de un operador de cámara en el lado izquierdo del plano.","fr":"Pendant la séquence où le détective Loki court désespérément dans la nuit noire à la recherche de la maison des Jones, dans un contrechamp grand-angle rapide, on peut entrevoir brièvement la silhouette d''un cadreur sur le côté gauche du cadre.","de":"Während der Sequenz, in der Detective Loki verzweifelt durch die dunkle Nacht auf der Suche nach dem Haus der Jones rennt, ist in einer schnellen Weitwinkel-Gegenschusseinstellung kurz die Silhouette eines Kameramanns am linken Bildrand zu erahnen."}'::jsonb WHERE id = 5152;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Nancy Birch serve il caffè in cucina, il cucchiaino accanto alla tazza cambia posizione dal lato destro al lato sinistro del piattino nei diversi tagli di montaggio tra i dialoghi.","en":"In the scene where Nancy Birch serves coffee in the kitchen, the teaspoon next to the cup changes position from the right to the left side of the saucer across different editing cuts during the dialogue.","es":"En la escena en la que Nancy Birch sirve café en la cocina, la cucharilla al lado de la taza cambia de posición del lado derecho al izquierdo del platillo en los diferentes cortes de montaje entre los diálogos.","fr":"Dans la scène où Nancy Birch sert le café dans la cuisine, la petite cuillère à côté de la tasse change de position du côté droit au côté gauche de la soucoupe lors des raccordements de montage pendant les dialogues.","de":"In der Szene, in der Nancy Birch in der Küche Kaffee serviert, wechselt der Teelöffel neben der Tasse bei den verschiedenen Schnittwechseln während des Dialogs seine Position von der rechten auf die linke Seite der Untertasse."}'::jsonb WHERE id = 5153;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le sequenze ambientate negli anni ''10 e ''20 a bordo del transatlantico, alcuni passeggeri indossano tagli di capelli e abiti chiaramente ispirati alla moda degli anni ''90, periodo in cui il film è stato effettivamente girato e prodotto.","en":"During the sequences set in the 1910s and 1920s aboard the ocean liner, some passengers wear haircuts and costumes clearly inspired by 1990s fashion, the period when the film was actually shot and produced.","es":"Durante las secuencias ambientadas en las décadas de 1910 y 1920 a bordo del transatlántico, algunos pasajeros llevan cortes de pelo y ropa claramente inspirados en la moda de los años 90, época en la que la película fue rodada y producida.","fr":"Pendant les séquences se déroulant dans les années 1910 et 1920 à bord du paquebot, certains passagers portent des coupes de cheveux et des costumes clairement inspirés de la mode des années 90, période durant laquelle le film a réellement été tourné et produit.","de":"Während der Sequenzen, die in den 1910er und 1920er Jahren an Bord des Ozeanriesen spielen, tragen einige Passagiere Haarschnitte und Kostüme, die deutlich von der Mode der 1990er Jahre inspiriert sind – der Zeit, in der der Film tatsächlich gedreht und produziert wurde."}'::jsonb WHERE id = 5154;
UPDATE errori SET descrizione_i18n = '{"it":"Il personaggio di Max Tooney racconta di aver suonato la tromba con una tecnica e arrangiamenti tipici delle big band swing, uno stile musicale che non si era ancora sviluppato nella forma descritta durante i primi anni del secolo in cui si svolge la scena.","en":"The character Max Tooney recounts playing the trumpet with a technique and arrangements typical of swing big bands, a musical style that had not yet developed in the described form during the early years of the century in which the scene takes place.","es":"El personaje de Max Tooney cuenta que tocó la trompeta con una técnica y unos arreglos típicos de las big bands de swing, un estilo musical que aún no se había desarrollado en la forma descrita durante los primeros años del siglo en que transcurre la escena.","fr":"Le personnage de Max Tooney raconte avoir joué de la trompette avec une technique et des arrangements typiques des big bands swing, un style musical qui ne s''était pas encore développé sous la forme décrite au début du siècle où se déroule la scène.","de":"Die Figur Max Tooney erzählt, dass er Trompete mit einer Technik und Arrangements gespielt hat, die für Swing-Big-Bands typisch sind – ein Musikstil, der sich in der beschriebenen Form in den frühen Jahren des Jahrhunderts, in denen die Szene spielt, noch gar nicht entwickelt hatte."}'::jsonb WHERE id = 5155;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Max ritrova la tromba arrugginita all''interno del deposito dei rottami, la disposizione degli strumenti musicali intorno a lui cambia sensibilmente tra un''inquadratura ravvicinata e il campo largo successivo.","en":"In the scene where Max finds the rusted trumpet inside the scrap yard, the arrangement of musical instruments around him changes noticeably between a close-up and the following wide shot.","es":"En la escena en la que Max encuentra la trompeta oxidada dentro del depósito de chatarra, la disposición de los instrumentos musicales a su alrededor cambia notablemente entre un plano corto y el plano general posterior.","fr":"Dans la scène où Max retrouve la trompette rouillée à l''intérieur de la casse, la disposition des instruments de musique autour de lui change sensiblement entre un gros plan et le plan large suivant.","de":"In der Szene, in der Max die verrostete Trompete auf dem Schrottplatz findet, verändert sich die Anordnung der Musikinstrumente um ihn herum deutlich zwischen einer Nahaufnahme und der darauffolgenden Totalen."}'::jsonb WHERE id = 5156;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle scene di massa nel campo di addestramento dei gladiatori, è possibile intravedere brevemente l''ombra di un microfono boom proiettata sulla parete rocciosa sullo sfondo.","en":"During one of the crowd scenes in the gladiatorial training camp, the shadow of a boom mic can be briefly glimpsed projected onto the rock wall in the background.","es":"Durante una de las escenas de masas en el campo de entrenamiento de gladiadores, se puede vislumbrar brevemente la sombra de un micrófono de pértiga proyectada en la pared rocosa del fondo.","fr":"Pendant l''une des scènes de foule dans le camp d''entraînement des gladiateurs, on peut entrapercevoir brièvement l''ombre d''une perche micro projetée sur la paroi rocheuse en arrière-plan.","de":"Während einer der Massenszenen im Gladiatorentrainingslager ist kurz der Schatten eines Galgenmikrofons (Boom-Mic) zu sehen, der auf die Felswand im Hintergrund geworfen wird."}'::jsonb WHERE id = 5157;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza della grande battaglia finale, la posizione di un elmo romano indossato da un centurione cambia drasticamente tra un''inquadratura in campo largo e il successivo primo piano, passando dall''essere allacciato a completamente rimosso.","en":"In the final grand battle sequence, the position of a Roman helmet worn by a centurion changes drastically between a wide shot and the subsequent close-up, going from being strapped on to completely removed.","es":"En la secuencia de la gran batalla final, la posición del casco romano que lleva un centurión cambia drásticamente entre un plano general y el primer plano posterior, pasando de estar abrochado a estar completamente quitado.","fr":"Dans la séquence de la grande bataille finale, la position d''un casque romain porté par un centurion change radicalement entre un plan large et le gros plan suivant, passant d''attaché à complètement retiré.","de":"In der Sequenz der großen Endschlacht verändert sich die Position eines von einem Centurio getragenen römischen Helms drastisch zwischen einer Totalen und der folgenden Nahaufnahme, wobei er einmal festgeschnallt und im nächsten Moment komplett abgenommen ist."}'::jsonb WHERE id = 5158;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune inquadrature dei soldati romani in marcia, le calzature (caligae) presentano suole in gomma moderna o cuciture industriali chiaramente visibili, anacronistiche per il I secolo a.C.","en":"In some shots of the marching Roman soldiers, the footwear (caligae) features clearly visible modern rubber soles or industrial stitching, which are anachronistic for the 1st century BC.","es":"En algunos planos de los soldados romanos marchando, el calzado (caligae) muestra suelas de goma moderna o costuras industriales claramente visibles, anacrónicas para el siglo I a. C.","fr":"Dans certains plans de soldats romains en marche, les chaussures (caligae) présentent des semelles en caoutchouc moderne ou des coutures industrielles clairement visibles, anachroniques pour le Ier siècle av. J.-C.","de":"In einigen Einstellungen marschierender römischer Soldaten weisen das Schuhwerk (Caligae) deutlich sichtbare moderne Gummisohlen oder Industrienähte auf, was für das 1. Jahrhundert v. Chr. anachronistisch ist."}'::jsonb WHERE id = 5159;
UPDATE errori SET descrizione_i18n = '{"it":"Durante un dialogo concitato tra i senatori romani, il movimento delle labbra di uno degli attori secondari non coincide affatto con l''audio della battuta pronunciata in primo piano.","en":"During a heated dialogue between the Roman senators, the lip movements of one of the supporting actors do not match at all with the audio of the line spoken in the close-up.","es":"Durante un diálogo acalorado entre los senadores romanos, el movimiento de los labios de uno de los actores secundarios no coincide en absoluto con el audio de la frase pronunciada en el primer plano.","fr":"Pendant un dialogue animé entre les sénateurs romains, les mouvements des lèvres de l''un des acteurs secondaires ne correspondent pas du tout à l''audio de la réplique prononcée en gros plan.","de":"Während eines hitzigen Dialogs zwischen den römischen Senatoren stimmen die Lippenbewegungen eines der Nebendarsteller überhaupt nicht mit dem Audio des in der Nahaufnahme gesprochenen Satzes überein."}'::jsonb WHERE id = 5160;
UPDATE errori SET descrizione_i18n = '{"it":"La rappresentazione della crocifissione di massa lungo la Via Appia mostra un posizionamento delle croci e una tecnica di esecuzione non del tutto aderenti ai resoconti storici romani dell''epoca.","en":"The depiction of the mass crucifixion along the Appian Way shows a placement of the crosses and execution technique that are not entirely consistent with historical Roman accounts of the era.","es":"La representación de la crucifixión masiva a lo largo de la Vía Apia muestra una colocación de las cruces y una técnica de ejecución que no se ajustan del todo a los relatos históricos romanos de la época.","fr":"La représentation de la crucifixion de masse le long de la Voie appienne présente un placement des croix et une technique d''exécution qui ne sont pas tout à fait conformes aux récits historiques romains de l''époque.","de":"Die Darstellung der Massenkreuzigung entlang der Via Appia zeigt eine Platzierung der Kreuze und eine Hinrichtungstechnik, die nicht ganz den historischen römischen Berichten der Epoche entsprechen."}'::jsonb WHERE id = 5161;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il viaggio in nave verso il Giappone, Nathan Algren e i soldati americani discutono sul ponte; sullo sfondo si vedono parti dell''imbarcazione e accessori di navigazione che rispecchiano standard tecnologici navali di decenni successivi rispetto al 1876.","en":"During the voyage to Japan by ship, Nathan Algren and the American soldiers discuss on deck; in the background, parts of the watercraft and navigation props reflect naval technological standards from decades after 1876.","es":"Durante el viaje en barco hacia Japón, Nathan Algren y los soldados estadounidenses discuten en la cubierta; de fondo se ven partes de la embarcación y atrezzo de navegación que reflejan estándares tecnológicos navales de décadas posteriores a 1876.","fr":"Pendant le voyage en bateau vers le Japon, Nathan Algren et les soldats américains discutent sur le pont ; on aperçoit en arrière-plan des éléments de l''embarcation et des accessoires de navigation qui reflètent des standards technologiques navals postérieurs à 1876.","de":"Während der Schiffsreise nach Japan diskutieren Nathan Algren und die amerikanischen Soldaten an Deck; im Hintergrund sind Teile des Wasserfahrzeugs und Requisiten für die Navigation zu sehen, die auf Schiffbaustandards aus Jahrzehnten nach 1876 verweisen."}'::jsonb WHERE id = 5162;
UPDATE errori SET descrizione_i18n = '{"it":"Nel villaggio montano, quando Algren riceve per la prima volta la ciotola di riso e il tè da Taka, la posizione delle sue mani tra un''inquadratura e l''altra cambia repentinamente da stringere la ciotola con entrambe le mani a tenerla con una sola.","en":"In the mountain village, when Algren first receives the bowl of rice and tea from Taka, the position of his hands cuts abruptly between shots, shifting from gripping the bowl with both hands to holding it with just one.","es":"En el pueblo de montaña, cuando Algren recibe por primera vez el bol de arroz y el té de Taka, la posición de sus manos cambia repentinamente de un plano a otro, pasando de sostener el bol con ambas manos a sujetarlo con una sola.","fr":"Dans le village de montagne, lorsque Algren reçoit pour la première fois le bol de riz et le thé de Taka, la position de ses mains change brusquement d''un plan à l''autre, passant de tenir le bol à deux mains à le tenir d''une seule main.","de":"Im Bergdorf, als Algren zum ersten Mal die Reisschüssel und den Tee von Taka erhält, wechselt die Position seiner Hände zwischen den Einstellungen abrupt von zwei händisch umschlossener Schüssel zu einer einhändigen Halterung."}'::jsonb WHERE id = 5163;
UPDATE errori SET descrizione_i18n = '{"it":"Durante i preparativi strategici dei samurai prima dello scontro finale, le tattiche e i movimenti di schieramento descritti non corrispondono alle reali tattiche militari impiegate dai samurai storici della ribellione di Satsuma, ricalcando invece schemi cinematografici occidentali.","en":"During the samurai''s strategic preparations before the final clash, the tactics and deployment movements depicted do not match the actual military tactics used by historical samurai of the Satsuma Rebellion, instead mirroring Western cinematic tropes.","es":"Durante los preparativos estratégicos de los samuráis antes del enfrentamiento final, las tácticas y movimientos de despliegue descritos no se corresponden con las tácticas militares reales empleadas por los samuráis históricos de la rebelión de Satsuma, imitando en su lugar esquemas cinematográficos occidentales.","fr":"Pendant les préparatifs stratégiques des samouraïs avant l''affrontement final, les tactiques et mouvements de déploiement décrits ne correspondent pas aux réelles tactiques militaires employées par les samouraïs historiques de la rébellion de Satsuma, calquant plutôt des codes cinématographiques occidentaux.","de":"Während der strategischen Vorbereitungen der Samurai vor dem finalen Zusammenstoß entsprechen die dargestellten Taktiken und Aufstellungsbewegungen nicht den tatsächlichen militärischen Taktiken der historischen Samurai der Satsuma-Rebellion, sondern spiegeln stattdessen westliche Filmklischees wider."}'::jsonb WHERE id = 5164;
UPDATE errori SET descrizione_i18n = '{"it":"Negli istanti successivi alla carica finale a cavallo, le ferite e le macchie di sangue sul costume di Tom Cruise variano in modo evidente per forma e intensità tra le inquadrature ravvicinate e quelle a campo largo.","en":"In the moments following the final cavalry charge, the wounds and bloodstains on Tom Cruise''s costume visibly vary in shape and intensity between close-up shots and wide shots.","es":"En los instantes posteriores a la carga final a caballo, las heridas y las manchas de sangre en el vestuario de Tom Cruise varían de manera evidente en forma e intensidad entre los planos cerrados y los planos generales.","fr":"Dans les instants suivant la charge finale à cheval, les blessures et les taches de sang sur le costume de Tom Cruise varient de manière évidente en forme et en intensité entre les plans serrés et les plans larges.","de":"In den Momenten nach dem finalen Reiterangriff verändern sich die Wunden und Blutflecken auf Tom Cruises Kostüm in Form und Intensität sichtlich zwischen den Nahaufnahmen und den Totalen."}'::jsonb WHERE id = 5165;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la famiglia McCallister si sveglia di fretta a causa della sveglia non suonata, nella scena in cui la mamma corre nel corridoio, i suoi capelli cambiano visibilmente acconciatura e volume tra un''inquadratura e l''altra a causa dei diversi ciak uniti in fase di montaggio.","en":"When the McCallister family wakes up in a rush due to the missed alarm, in the scene where the mom runs down the hallway, her hair visibly changes style and volume between cuts due to different takes being stitched together in the editing room.","es":"Cuando la familia McCallister se despierta apresuradamente debido a que no sonó el despertador, en la escena en la que la madre corre por el pasillo, su pelo cambia visiblemente de peinado y volumen entre plano y plano debido a las diferentes tomas unidas en el montaje.","fr":"Lorsque la famille McCallister se réveille en catastrophe à cause du réveil qui n''a pas sonné, dans la scène où la mère court dans le couloir, ses cheveux changent visiblement de coiffure et de volume d''un plan à l''autre en raison des différentes prises assemblées au montage.","de":"Als die Familie McCallister wegen des ausgebliebenen Weckrufs in Eile aufwacht und die Mutter durch den Flur rennt, verändern sich Frisur und Volumen ihrer Haare zwischen den Einstellungen sichtbar durch verschiedene Takes, die beim Schnitt zusammengefügt wurden."}'::jsonb WHERE id = 5166;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in aeroporto in cui la famiglia corre per imbarcarsi in fretta sull''aereo, in un campo largo laterale è possibile intravedere brevemente l''ombra di un microfono boom che oscilla nella parte superiore dell''inquadratura.","en":"During the airport scene where the family runs to board the plane in a hurry, in a wide lateral shot the shadow of a boom mic can be briefly glimpsed swaying at the top of the frame.","es":"Durante la escena del aeropuerto en la que la familia corre para embarcar rápido en el avión, en un plano general lateral se puede vislumbrar brevemente la sombra de un micrófono de pértiga oscilando en la parte superior del fotograma.","fr":"Pendant la scène de l''aéroport où la famille court pour embarquer en catastrophe dans l''avion, dans un plan large latéral, on peut apercevoir brièvement l''ombre d''un micro perche qui oscille en haut du cadre.","de":"Während der Flughafenszene, in der die Familie eilig rennt, um ins Flugzeug zu steigen, ist in einer seitlichen Totalen kurz der Schatten eines Boom-Mikrofons zu sehen, der im oberen Bildrand schwingt."}'::jsonb WHERE id = 5167;
UPDATE errori SET descrizione_i18n = '{"it":"Nel negozio di alimentari, quando Kevin paga la spesa alla cassa, il sacchetto di carta cambia posizione sul bancone e il modo in cui tiene il denaro varia repentinamente tra l''inquadratura frontale e quella di profilo.","en":"At the grocery store, when Kevin pays for his items at the register, the paper bag shifts position on the counter and the way he holds the cash changes abruptly between the front-facing shot and the profile shot.","es":"En la tienda de ultramarinos, cuando Kevin paga la compra en la caja, la bolsa de papel cambia de posición en el mostrador y la forma en que sostiene el dinero varía repentinamente entre el plano frontal y el de perfil.","fr":"À l''épicerie, lorsque Kevin paie ses courses à la caisse, le sac en papier change de position sur le comptoir et sa façon de tenir l''argent varie brusquement entre le plan frontal et le plan de profil.","de":"Im Lebensmittelladen, als Kevin an der Kasse bezahlt, verändert die Papiertüte ihre Position auf dem Tresen und die Art, wie er das Geld hält, wechselt zwischen der Frontale und der Profilaufnahme abrupt."}'::jsonb WHERE id = 5168;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Harry e Marv irrompono nella cucina dei vicini o durante le esplorazioni della casa, la finta neve sulle finestre e sui gradini esterni diminuisce o aumenta visibilmente a seconda dell''angolazione della cinepresa.","en":"When Harry and Marv break into the neighbors'' kitchen or explore the house, the fake snow on the windows and outside steps visibly decreases or increases depending on the camera angle.","es":"Cuando Harry y Marv irrumpen en la cocina de los vecinos o durante las exploraciones de la casa, la nieve artificial en las ventanas y los escalones exteriores disminuye o aumenta visiblemente según el ángulo de la cámara.","fr":"Quand Harry et Marv s''introduisent dans la cuisine des voisins ou explorent la maison, la fausse neige sur les fenêtres et les marches extérieures diminue ou augmente visiblement selon l''angle de la caméra.","de":"Wenn Harry und Marv in die Küche der Nachbarn einbrechen oder das Haus erkunden, nimmt das künstliche Schnee auf den Fenstern und Außentreppen je nach Kameraperspektive sichtbar zu oder ab."}'::jsonb WHERE id = 5169;
UPDATE errori SET descrizione_i18n = '{"it":"Nella celebre scena in cui Kevin spaventa i ladri usando il cartonato rotante di Michael Jordan collegato a un trenino elettrico, la posizione della sedia e del filo elettrico sul pavimento cambia tra l''inquadratura larga e i primi piani.","en":"In the famous scene where Kevin scares the burglars using the rotating Michael Jordan cutout connected to an electric train, the position of the chair and the power cord on the floor changes between the wide shot and the close-ups.","es":"En la famosa escena en la que Kevin asusta a los ladrones usando la silueta de cartón giratoria de Michael Jordan conectada a un tren eléctrico, la posición de la silla y el cable eléctrico en el suelo cambia entre el plano general y los primeros planos.","fr":"Dans la célèbre scène où Kevin effraie les cambrioleurs à l''aide de la silhouette pivotante de Michael Jordan reliée à un train électrique, la position de la chaise et du fil électrique sur le sol change entre le plan large et les gros plans.","de":"In der berühmten Szene, in der Kevin die Einbrecher mit dem sich drehenden Pappaufsteller von Michael Jordan erschreckt, der an eine elektrische Eisenbahn angeschlossen ist, verändert sich die Position des Stuhls und des Stromkabels auf dem Boden zwischen der Totale und den Nahaufnahmen."}'::jsonb WHERE id = 5170;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Marv subisce il colpo del ferro da stiro in faccia lanciato dalle scale, il segno nero e la forma della bruciatura sul suo viso variano e si attenuano visibilmente nelle scene immediatamente successive.","en":"When Marv takes the iron to the face thrown down the stairs, the black mark and the shape of the burn on his face vary and noticeably fade in the immediately following scenes.","es":"Cuando Marv recibe el golpe de la plancha en la cara lanzada desde las escaleras, la marca negra y la forma de la quemadura en su rostro varían y se atenúan visiblemente en las escenas inmediatamente posteriores.","fr":"Quand Marv prend le fer à repasser en plein visage lancé depuis les escaliers, la trace noire et la forme de la brûlure sur son visage varient et s''atténuent visiblement dans les scènes immédiatement suivantes.","de":"Als Marv das Bügeleisen ins Gesicht bekommt, das die Treppe heruntergeworfen wurde, verändern sich der schwarze Abdruck und die Form der Verbrennung in den darauffolgenden Szenen sichtbar und werden blasser."}'::jsonb WHERE id = 5171;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Harry e Marv inseguono Kevin fuori dalla casa sulla neve, in un campo medio in cui i ladri scivolano sul ghiaccio si notano chiaramente le sagome imbottite delle protezioni e dei cuscinetti protettivi indossati dagli stuntman sotto i vestiti.","en":"In the sequence where Harry and Marv chase Kevin outside the snow-covered house, in a medium shot where the burglars slip on the ice, the padded shapes of the protective gear and body pads worn by the stuntmen under their clothes are clearly visible.","es":"En la secuencia en la que Harry y Marv persiguen a Kevin fuera de la casa nevada, en un plano medio en el que los ladrones resbalan sobre el hielo se notan claramente las siluetas acolchadas de las protecciones y coderas/rodilleras que llevan los especialistas bajo la ropa.","fr":"Dans la séquence où Harry et Marv poursuivent Kevin à l''extérieur de la maison dans la neige, dans un plan moyen où les cambrioleurs glissent sur la glace, on distingue clairement les silhouettes rembourrées des protections et des coussinets portés par les cascadeurs sous leurs vêtements.","de":"In der Sequenz, in der Harry und Marv Kevin vor dem eingeschneiten Haus verfolgen, sind in einer Halbtotale, in der die Einbrecher auf dem Eis ausrutschen, deutlich die gepolsterten Umrisse der Protektoren zu erkennen, die die Stuntmen unter ihrer Kleidung trugen."}'::jsonb WHERE id = 5172;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i Wet Bandits catturano Kevin nel seminterrato e Harry si toglie il berretto, i suoi capelli sono completamente bagnati e arruffati in un''inquadratura, mentre in quella successiva appaiono notevolmente più asciutti e pettinati.","en":"When the Wet Bandits capture Kevin in the basement and Harry takes off his beanie, his hair is completely wet and messy in one shot, while in the next one it looks noticeably drier and combed.","es":"Cuando los Wet Bandits capturan a Kevin en el sótano y Harry se quita el gorro, su cabello está completamente mojado y revuelto en un plano, mientras que en el siguiente aparece notablemente más seco y peinado.","fr":"Quand les Casseurs Flotteurs capturent Kevin dans la cave et qu''Harry enlève son bonnet, ses cheveux sont complètement mouillés et ébouriffés sur un plan, tandis que sur le suivant ils apparaissent nettement plus secs et coiffés.","de":"Als die „Wet Bandits“ Kevin im Keller schnappen und Harry seine Mütze abnimmt, sind seine Haare in einer Einstellung völlig nass und zerzaust, während sie in der nächsten Einstellung deutlich trocken und gekämmt wirken."}'::jsonb WHERE id = 5173;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Kevin arriva a New York e prende un taxi giallo, la posizione della cintura di sicurezza e il modo in cui è seduto cambiano tra l''inquadratura interna ed esterna mentre il taxi si muove.","en":"When Kevin arrives in New York and takes a yellow cab, the position of the seatbelt and the way he is sitting change between the interior and exterior shots while the taxi is moving.","es":"Cuando Kevin llega a Nueva York y toma un taxi amarillo, la posición del cinturón de seguridad y su postura cambian entre el plano interior y el exterior mientras el taxi está en marcha.","fr":"Quand Kevin arrive à New York et prend un taxi jaune, la position de la ceinture de sécurité et sa façon d''être assis changent entre le plan intérieur et extérieur pendant que le taxi roule.","de":"Als Kevin in New York ankommt und ein gelbes Taxi nimmt, wechseln die Position des Sicherheitsgurts und seine Sitzposition während der Fahrt zwischen Innen- und Außenaufnahme."}'::jsonb WHERE id = 5174;
UPDATE errori SET descrizione_i18n = '{"it":"Nel momento in cui Kevin entra nel Plaza Hotel e si avvicina al bancone della reception, la sciarpa che indossa al collo cambia improvvisamente nodo e lunghezza tra i vari campi medi e primi piani.","en":"The moment Kevin enters the Plaza Hotel and approaches the front desk, the scarf he is wearing around his neck suddenly changes its knot and length between various medium shots and close-ups.","es":"En el momento en que Kevin entra en el Hotel Plaza y se acerca al mostrador de recepción, la bufanda que lleva al cuello cambia repentinamente de nudo y longitud entre los distintos planos medios y primeros planos.","fr":"Au moment où Kevin entre au Plaza Hotel et s''approche du comptoir de la réception, l''écharpe qu''il porte autour du cou change soudainement de nœud et de longueur entre les différents plans moyens et gros plans.","de":"In dem Moment, in dem Kevin das Plaza Hotel betritt und sich der Rezeption nähert, verändern sich bei den verschiedenen Halbtotalen und Nahaufnahmen plötzlich der Knoten und die Länge des Schals, den er um den Hals trägt."}'::jsonb WHERE id = 5175;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la preparazione delle trappole nel condominio in ristrutturazione, gli attrezzi e i barattoli di vernice disposti sui ripiani cambiano posizione e quantità tra un taglio e l''altro.","en":"During the preparation of the traps in the townhouse under renovation, the tools and paint cans arranged on the shelves change position and quantity between cuts.","es":"Durante la preparación de las trampas en la casa en obras, las herramientas y los botes de pintura colocados en las estanterías cambian de posición y cantidad entre plano y plano.","fr":"Pendant la préparation des pièges dans la maison en rénovation, les outils et les pots de peinture disposés sur les étagères changent de position et de quantité d''un raccord à l''autre.","de":"Während der Vorbereitung der Fallen in dem sich in Renovierung befindlichen Haus verändern die Werkzeuge und Farbdosen auf den Regalen zwischen den einzelnen Cuts (Schnitten) ihre Position und Anzahl."}'::jsonb WHERE id = 5176;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Harry e Marv inseguono Kevin a Central Park, i cumuli di neve sugli alberi e sul terreno variano visibilmente di volume e consistenza nelle diverse angolazioni della ripresa.","en":"When Harry and Marv chase Kevin in Central Park, the snowdrifts on the trees and ground noticeably vary in volume and consistency across different camera angles.","es":"Cuando Harry y Marv persiguen a Kevin en Central Park, los montones de nieve en los árboles y en el suelo varían visiblemente en volumen y consistencia entre los distintos ángulos de toma.","fr":"Quand Harry et Marv poursuivent Kevin à Central Park, les amas de neige sur les arbres et le sol varient visiblement de volume et de consistance selon les angles de prise de vue.","de":"Als Harry und Marv Kevin im Central Park jagen, variieren die Schneehäufen auf den Bäumen und am Boden in den verschiedenen Kameraeinstellungen sichtbar in Volumen und Beschaffenheit."}'::jsonb WHERE id = 5177;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Alex riceve l''auto radiocomandata all''aeroporto, la scatola è aperta in un''inquadratura e chiusa o tenuta diversamente nell''inquadratura immediatamente successiva.","en":"When Alex receives the radio-controlled car at the airport, the box is open in one shot and closed or held differently in the very next shot.","es":"Cuando Alex recibe el coche teledirigido en el aeropuerto, la caja está abierta en un plano y cerrada o sujeta de otra manera en el plano inmediatamente posterior.","fr":"Quand Alex reçoit la voiture télécommandée à l''aéroport, la boîte est ouverte sur un plan et fermée ou tenue différemment sur le plan immédiatement suivant.","de":"Als Alex das ferngesteuerte Auto am Flughafen erhält, ist die Schachtel in einer Einstellung offen und in der direkt folgenden Einstellung geschlossen oder anders gehalten."}'::jsonb WHERE id = 5178;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui i ladri cercano di entrare dalla porta sul retro, la neve sul cappotto di Jernigan (Olek Krupa) scompare e riappare tra i vari cambi di inquadratura.","en":"During the scene where the burglars try to break in through the back door, the snow on Jernigan''s (Olek Krupa) coat disappears and reappears across various shot/cuts.","es":"Durante la escena en la que los ladrones intentan entrar por la puerta trasera, la nieve del abrigo de Jernigan (Olek Krupa) desaparece y vuelve a aparecer entre los distintos cambios de plano.","fr":"Pendant la scène où les cambrioleurs essaient d''entrer par la porte de derrière, la neige sur le manteau de Jernigan (Olek Krupa) disparaît et réapparaît au fil des raccords.","de":"Während der Szene, in der die Einbrecher versuchen, durch die Hintertür einzudringen, verschwindet der Schnee auf Jernigans (Olek Krupa) Mantel und taucht bei verschiedenen Szenenwechseln wieder auf."}'::jsonb WHERE id = 5179;
UPDATE errori SET descrizione_i18n = '{"it":"Il numero di lattine e bottiglie che Alex posiziona sulle scale per la trappola varia visibilmente nel taglio di montaggio tra la vista dall''alto e la ripresa dal basso.","en":"The number of cans and bottles Alex places on the stairs for the trap visibly varies in the editing cut between the overhead view and the low-angle shot.","es":"El número de latas y botellas que Alex coloca en las escaleras para la trampa varía visiblemente en el corte de montaje entre la vista cenital y el plano contrapicado.","fr":"Le nombre de canettes et de bouteilles qu''Alex place sur les escaliers pour le piège varie visiblement dans le raccord de montage entre la vue en plongée et la contre-plongée.","de":"Die Anzahl der Dosen und Flaschen, die Alex für die Falle auf der Treppe platziert, variiert im Schnitt zwischen der Aufsicht und der Untersicht sichtbar."}'::jsonb WHERE id = 5180;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la polizia circonda la casa alla fine del film, le auto della polizia cambiano posizione e orientamento tra un totale e i primi piani sui criminali.","en":"When the police surround the house at the end of the film, the police cars change position and orientation between an establishing shot and the close-ups on the criminals.","es":"Cuando la policía rodea la casa al final de la película, los coches patrulla cambian de posición y orientación entre un plano general y los primeros planos de los criminales.","fr":"Quand la police encercle la maison à la fin du film, les voitures de police changent de position et d''orientation entre un plan large et les gros plans sur les criminels.","de":"Als die Polizei das Haus am Ende des Films umstellt, wechseln die Polizeiautos ihre Position und Ausrichtung zwischen einer Totalen und den Nahaufnahmen der Kriminellen."}'::jsonb WHERE id = 5181;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Kevin prepara la cioccolata calda, la tazza cambia posizione vicino al bordo del tavolo tra un''inquadratura ravvicinata e il campo medio.","en":"When Kevin prepares hot chocolate, the mug changes position near the edge of the table between a close-up and a medium shot.","es":"Cuando Kevin prepara el chocolate caliente, la taza cambia de posición cerca del borde de la mesa entre un plano cerrado y un plano medio.","fr":"Quand Kevin prépare le chocolat chaud, la tasse change de position près du bord de la table entre un gros plan et un plan moyen.","de":"Als Kevin heiße Tasse Kakao zubereitet, verändert die Tasse ihre Position nahe der Tischkante zwischen einer Nahaufnahme und einer halbtotale Einstellung."}'::jsonb WHERE id = 5182;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Marv e Vera camminano lungo il vialetto ghiacciato, si nota brevemente l''ombra di una telecamera su un carrello riflessa nella portiera dell''auto.","en":"During the scene where Marv and Vera walk along the icy driveway, the shadow of a dolly-mounted camera is briefly visible reflected in the car door.","es":"Durante la escena en la que Marv y Vera caminan por el camino de entrada helado, se ve brevemente la sombra de una cámara sobre un dolly reflejada en la puerta del coche.","fr":"Pendant la scène où Marv et Vera marchent sur l''allée glacée, on aperçoit brièvement l''ombre d''une caméra sur chariot se refléter dans la portière de la voiture.","de":"Während der Szene, in der Marv und Vera die eisige Einfahrt entlanggehen, ist kurz der Schatten einer Dolly-Kamera zu sehen, der sich in der Autotür spiegelt."}'::jsonb WHERE id = 5183;
UPDATE errori SET descrizione_i18n = '{"it":"Il cappotto indossato da Natalie varia la posizione della sciarpa e il modo in cui è abbottonato mentre cammina verso l''ingresso principale della villa.","en":"The coat worn by Natalie varies in scarf placement and how it is buttoned while she walks toward the main entrance of the mansion.","es":"El abrigo que lleva Natalie varía en la colocación de la bufanda y en cómo está abrochado mientras camina hacia la entrada principal de la mansión.","fr":"Le manteau porté par Natalie change de position d''écharpe et de boutonnage alors qu''elle marche vers l''entrée principale du manoir.","de":"Der von Natalie getragene Mantel variiert in der Position des Schals und darin, wie er geknöpft ist, während sie auf den Haupteingang der Villa zuläuft."}'::jsonb WHERE id = 5184;
UPDATE errori SET descrizione_i18n = '{"it":"In una conversazione tra Marv e Peter, il movimento delle labbra di Marv non coincide perfettamente con l''audio delle battute pronunciate durante un primo piano stretto.","en":"During a conversation between Marv and Peter, Marv''s lip movements do not perfectly match the audio of his lines during a tight close-up.","es":"En una conversación entre Marv y Peter, el movimiento de los labios de Marv no coincide perfectamente con el audio de sus diálogos durante un primer plano cerrado.","fr":"Pendant une conversation entre Marv et Peter, les mouvements des lèvres de Marv ne correspondent pas parfaitement à l''audio de ses répliques lors d''un gros plan serré.","de":"Während eines Gesprächs zwischen Marv und Peter stimmen Marvs Lippenbewegungen in einer engen Nahaufnahme nicht perfekt mit dem Audio seiner Dialogzeilen überein."}'::jsonb WHERE id = 5185;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Chris entra nella sua cucina e posa una borsa della spesa sul tavolo, la quantità e la disposizione degli oggetti che estrae variano visibilmente tra il primo piano e l''inquadratura larga successiva.","en":"When Chris enters her kitchen and sets a grocery bag on the table, the quantity and arrangement of the items she unpacks visibly change between the close-up and the following wide shot.","es":"Cuando Chris entra en su cocina y coloca una bolsa de la compra sobre la mesa, la cantidad y disposición de los objetos que saca varían visiblemente entre el primer plano y el plano general posterior.","fr":"Quand Chris entre dans sa cuisine et pose un sac de courses sur la table, la quantité et la disposition des articles qu''elle en sort varient visiblement entre le gros plan et le plan large suivant.","de":"Als Chris ihre Küche betritt und eine Einkaufstasche auf dem Tisch abstellt, verändern sich die Anzahl und Anordnung der Gegenstände, die sie auspackt, sichtbar zwischen der Nahaufnahme und der folgenden Totalen."}'::jsonb WHERE id = 5186;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conversazione tra Padre Karras e sua madre nel dormitorio, il movimento delle labbra della donna in alcune inquadrature di sbieco non coincide perfettamente con l''audio delle sue battute.","en":"During the conversation between Father Karras and his mother in the dorm, the woman''s lip movements in some angled shots do not perfectly match the audio of her lines.","es":"Durante la conversación entre el padre Karras y su madre en el dormitorio, el movimiento de los labios de la mujer en algunos planos escorados no coincide perfectamente con el audio de sus diálogos.","fr":"Pendant la conversation entre le père Karras et sa mère dans le dortoir, les mouvements des lèvres de la femme dans certains plans obliques ne correspondent pas parfaitement à l''audio de ses répliques.","de":"Während des Gesprächs zwischen Vater Karras und seiner Mutter im Wohnheim stimmen die Lippenbewegungen der Frau in einigen schrägen Einstellungen nicht perfekt mit dem Audio ihrer Dialogzeilen überein."}'::jsonb WHERE id = 5187;
UPDATE errori SET descrizione_i18n = '{"it":"Nel corso della sequenza in cui il Detective Kinderman interroga Padre Karras nel cortile dell''università, il cappotto di Karras è allacciato in un''inquadratura e completamente sbottonato in quella immediatamente successiva senza che ci sia stato tempo per farlo.","en":"During the sequence where Detective Kinderman interrogates Father Karras in the university courtyard, Karras''s coat is buttoned in one shot and completely unbuttoned in the very next shot without enough time having passed to do so.","es":"Durante la secuencia en la que el detective Kinderman interroga al padre Karras en el patio de la universidad, el abrigo de Karras está abrochado en un plano y completamente desabrochado en el plano inmediatamente posterior sin que haya habido tiempo para ello.","fr":"Au cours de la séquence où le détective Kinderman interroge le père Karras dans la cour de l''université, le manteau de Karras est boutonné sur un plan et complètement déboutonné sur le plan immédiatement suivant sans qu''il y ait eu le temps de le faire.","de":"Während der Sequenz, in der Detective Kinderman Vater Karras im Universitätsinnenhof verhört, ist Karras'' Mantel in einer Einstellung geknöpft und in der darauffolgenden Einstellung komplett aufgeknöpft, ohne dass dafür genügend Zeit vergangen ist."}'::jsonb WHERE id = 5188;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Padre Karras si avvicina alla porta d''ingresso della casa di Georgetown sotto la pioggia, per un breve fotogramma si intravede il riflesso dell''attrezzatura di illuminazione e di un operatore nella vetrata lucida della porta.","en":"In the scene where Father Karras approaches the front door of the Georgetown house in the rain, the reflection of lighting equipment and a crew member can be glimpsed in the glass pane of the door for a single frame.","es":"En la escena en la que el padre Karras se acerca a la puerta principal de la casa de Georgetown bajo la lluvia, se puede atisbar brevemente el reflejo del equipo de iluminación y de un operador en el cristal brillante de la puerta.","fr":"Dans la scène où le père Karras s''approche de la porte d''entrée de la maison de Georgetown sous la pluie, on aperçoit brièvement le reflet du matériel d''éclairage et d''un cadreur dans la vitre brillante de la porte.","de":"In der Szene, in der sich Vater Karras im Regen der Haustür des Georgetown-Hauses nähert, ist für einen kurzen Frame die Spiegelung der Beleuchtungsausrüstung und eines Kameraleute in der glänzenden Glastür zu sehen."}'::jsonb WHERE id = 5189;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il rito dell''esorcismo nella camera da letto, la bottiglia d''acqua benedetta tenuta da Padre Karras passa dall''essere quasi piena a visibilmente a metà tra un cambio di inquadratura e l''altro.","en":"During the bedroom exorcism sequence, the bottle of holy water held by Father Karras goes from being nearly full to visibly half-empty between cuts.","es":"Durante el rito del exorcismo en el dormitorio, la botella de agua bendita que sostiene el padre Karras pasa de estar casi llena a verse visiblemente a la mitad de un plano a otro.","fr":"Pendant le rite de l''exorcisme dans la chambre, la bouteille d''eau bénite tenue par le père Karras passe d''presque pleine à visiblement à moitié vide d''un plan à l''autre.","de":"Während des Exorzismus-Rituals im Schlafzimmer wechselt die von Vater Karras gehaltene Weihwasserflasche zwischen den verschiedenen Einstellungen von fast voll zu sichtbar halbvoll."}'::jsonb WHERE id = 5190;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Laurie Strode cerca di difendersi da Michael Myers armata di un appendiabiti di filo di ferro, l''oggetto cambia forma e orientamento visibilmente tra un''inquadratura ravvicinata e il campo medio mentre l''asskiller le si avvicina.","en":"When Laurie Strode tries to defend herself against Michael Myers using a wire coat hanger, the prop visibly changes shape and orientation between a close-up and a medium shot as the killer approaches her.","es":"Cuando Laurie Strode intenta defenderse de Michael Myers armada con una percha de alambre, el objeto cambia visiblemente de forma y orientación entre un plano detalle y un plano medio mientras el asesino se le acerca.","fr":"Quand Laurie Strode essaie de se défendre contre Michael Myers armée d''un cintre en fil de fer, l''accessoire change visiblement de forme et d''orientation entre un gros plan et un plan moyen alors que le tueur s''approche d''elle.","de":"Als Laurie Strode versucht, sich mit einem Kleiderbügel aus Draht gegen Michael Myers zu verteidigen, verändert die Requisite zwischen einer Nahaufnahme und einer Halbtotale sichtbar ihre Form und Ausrichtung, während sich der Killer ihr nähert."}'::jsonb WHERE id = 5191;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Annie Brackett guida la sua station wagon per andare a prendere i bambini, l''autoradio e alcuni dettagli della plancia del veicolo mostrano componenti di modelli successivi rispetto all''anno in cui si svolge la vicenda (1978).","en":"During the scene where Annie Brackett drives her station wagon to pick up the kids, the car radio and certain dashboard details feature components from newer models than the year in which the story is set (1978).","es":"Durante la escena en la que Annie Brackett conduce su station wagon para ir a buscar a los niños, la radio del coche y algunos detalles del salpicadero muestran componentes de modelos posteriores al año en que transcurre la trama (1978).","fr":"Pendant la scène où Annie Brackett conduit son break pour aller chercher les enfants, l''autoradio et certains détails du tableau de bord affichent des composants de modèles postérieurs à l''année où se déroule l''intrigue (1978).","de":"Während der Szene, in der Annie Brackett ihren Kombi fährt, um die Kinder abzuholen, zeigen das Autoradio und einige Details des Armaturenbretts Bauteile von Modellen, die neuer sind als das Jahr, in dem die Handlung spielt (1978)."}'::jsonb WHERE id = 5192;
UPDATE errori SET descrizione_i18n = '{"it":"Nelle sequenze iniziali ambientate nel 1963, il cielo notturno di Haddonfield (Illinois) mostra la costellazione e la posizione della luna in modo astronomicamente incompatibile con la data esatta del delitto di Judith Myers.","en":"In the opening sequences set in 1963, the night sky over Haddonfield, Illinois, displays constellations and moon positions that are astronomically incompatible with the exact date of Judith Myers'' murder.","es":"En las secuencias iniciales ambientadas en 1963, el cielo nocturno de Haddonfield (Illinois) muestra las constelaciones y la posición de la luna de forma astronómicamente incompatible con la fecha exacta del asesinato de Judith Myers.","fr":"Dans les séquences d''ouverture se déroulant en 1963, le ciel nocturne de Haddonfield (Illinois) présente des constellations et une position de la lune astronomiquement incompatibles avec la date exacte du meurtre de Judith Myers.","de":"In den Anfangssequenzen, die im Jahr 1963 spielen, zeigen der Nachthimmel von Haddonfield (Illinois) und die Mondposition Konstellationen, die astronomisch nicht mit dem exakten Datum von Judith Myers'' Mord übereinstimmen."}'::jsonb WHERE id = 5193;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Georgie guarda dentro la fogna per parlare con Pennywise, la posizione della sua mano destra sul bordo del cemento cambia visibilmente tra un''inquadratura e l''altra nel taglio del montaggio.","en":"When Georgie looks into the storm drain to talk to Pennywise, the position of his right hand on the concrete edge changes noticeably between cuts.","es":"Cuando Georgie mira dentro de la alcantarilla para hablar con Pennywise, la posición de su mano derecha sobre el borde de cemento cambia visiblemente de un plano a otro en el corte de montaje.","fr":"Quand Georgie regarde dans l''égout pour parler à Pennywise, la position de sa main droite sur le bord en béton change visiblement d''un plan à l''autre lors du montage.","de":"Als Georgie in den Abwasserkanal schaut, um mit Pennywise zu sprechen, verändert sich die Position seiner rechten Hand auf der Betonkante im Schnitt zwischen den Einstellungen deutlich."}'::jsonb WHERE id = 5194;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una scena in cui i ragazzi camminano per le strade di Derry, sullo sfondo si nota un modello di automobile con targa o dettagli di immatricolazione successivi all''estate del 1989.","en":"During a scene where the kids are walking through the streets of Derry, a car model with license plates or registration details newer than the summer of 1989 can be spotted in the background.","es":"Durante una escena en la que los chicos caminan por las calles de Derry, se puede ver de fondo un modelo de coche con matrícula o detalles de matriculación posteriores al verano de 1989.","fr":"Pendant une scène où les enfants marchent dans les rues de Derry, on aperçoit en arrière-plan un modèle de voiture avec des plaques d''immatriculation ou des détails postérieurs à l''été 1989.","de":"In einer Szene, in der die Jungs durch die Straßen von Derry gehen, ist im Hintergrund ein Automodell mit Nummernschildern oder Zulassungsdetails zu sehen, die neuer sind als der Sommer 1989."}'::jsonb WHERE id = 5195;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui i Perdenti sono nella cava a fare il bagno, gli asciugamani e i vestiti lasciati sugli scogli cambiano posizione e disposizione tra le inquadrature larghe e i primi piani dei personaggi.","en":"In the scene where the Losers are swimming in the quarry, the towels and clothes left on the rocks change position and arrangement between wide shots and close-ups of the characters.","es":"En la escena en la que los Perdedores se bañan en la cantera, las toallas y la ropa dejadas en las rocas cambian de posición y disposición entre los planos generales y los primeros planos de los personajes.","fr":"Dans la scène où les Ratés se baignent dans la carrières, les serviettes et les vêtements laissés sur les rochers changent de position et de disposition entre les plans larges et les gros plans des personnages.","de":"In der Szene, in der die Verlierer im Steinbruch baden, verändern die Handtücher und Kleidungsstücke, die auf den Felsen zurückgelassen wurden, zwischen den Totalen und den Nahaufnahmen der Figuren ihre Position und Anordnung."}'::jsonb WHERE id = 5196;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui Ben fugge da Henry Bowers nella biblioteca, in un''inquadratura grandangolare tra gli scaffali dei libri si intraintende brevemente l''ombra di un operatore della troupe sul pavimento.","en":"During the sequence where Ben flees from Henry Bowers in the library, in a wide shot between the bookshelves the shadow of a crew member is briefly glimpsed on the floor.","es":"Durante la secuencia en la que Ben huye de Henry Bowers en la biblioteca, en un plano general entre las estanterías de libros se ve brevemente la sombra de un miembro del equipo en el suelo.","fr":"Pendant la séquence où Ben fuit Henry Bowers dans la bibliothèque, dans un plan large entre les étagères de livres, on aperçoit brièvement l''ombre d''un technicien sur le sol.","de":"Während der Sequenz, in der Ben vor Henry Bowers in der Bibliothek flieht, ist in einer Weitwinkelaufnahme zwischen den Bücherregalen kurz der Schatten eines Crewmitglieds auf dem Boden zu sehen."}'::jsonb WHERE id = 5197;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i ragazzi entrano nella casa abbandonata di Neibolt Street, le torce elettriche che impugnano passano dall''essere accese a spente e viceversa a seconda dei tagli di ripresa senza che i personaggi azionino gli interruttori.","en":"When the kids enter the abandoned house on Neibolt Street, the flashlights they are holding switch from on to off and back again across cuts without the characters operating the switches.","es":"Cuando los chicos entran en la casa abandonada de Neibolt Street, las linternas que sostienen pasan de estar encendidas a apagadas y viceversa entre los cortes de cámara sin que los personajes accionen los interruptores.","fr":"Quand les enfants entrent dans la maison abandonnée de Neibolt Street, les lampes de poche qu''ils tiennent s''allument et s''éteignent d''un plan à l''autre sans que les personnages n''actionnent les interrupteurs.","de":"Wenn die Jungs das verlassene Haus in der Neibolt Street betreten, wechseln die Taschenlampen, die sie halten, zwischen den Schnitten von an zu aus und umgekehrt, ohne dass die Figuren die Schalter betätigen."}'::jsonb WHERE id = 5198;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cucina in cui la madre di Elliott prepara la cena, il cartone del latte sul bancone cambia posizione e orientamento dell''etichetta tra un''inquadratura e l''altra mentre le persone si muovono nella stanza.","en":"During the kitchen scene where Elliott''s mother prepares dinner, the milk carton on the counter changes position and label orientation between shots as people move around the room.","es":"Durante la escena de la cocina en la que la madre de Elliott prepara la cena, el cartón de leche en la encimera cambia de posición y de orientación de la etiqueta entre plano y plano mientras las personas se mueven por la habitación.","fr":"Pendant la scène de cuisine où la mère d''Elliott prépare le dîner, la brique de lait sur le plan de travail change de position et d''orientation d''étiquette d''un plan à l''autre alors que les personnages se déplacent dans la pièce.","de":"Während der Küchenszene, in der Elliotts Mutter das Abendessen zubereitet, ändern sich die Position des Milchkartyons auf der Anrichte und die Ausrichtung des Etiketts zwischen den Einstellungen, während sich Personen im Raum bewegen."}'::jsonb WHERE id = 5199;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Elliott mostra E.T. ai suoi fratelli nella camera da letto, in un''inquadratura ravvicinata riflessa sulla finestra è possibile intravedere brevemente l''ombra di un operatore della troupe.","en":"In the sequence where Elliott shows E.T. to his siblings in the bedroom, in a close-up reflected on the window the shadow of a crew member can be briefly glimpsed.","es":"En la secuencia en la que Elliott muestra a E.T. a sus hermanos en el dormitorio, en un plano corto reflejado en la ventana se puede atisbar brevemente la sombra de un miembro del equipo.","fr":"Dans la séquence où Elliott montre E.T. à ses frères et sœurs dans la chambre, dans un gros plan réfléchi sur la fenêtre, on peut entrapercevoir brièvement l''ombre d''un technicien.","de":"In der Sequenz, in der Elliott seinen Geschwistern E.T. im Schlafzimmer zeigt, ist in einer Nahaufnahme, die sich im Fenster spiegelt, kurz der Schatten eines Crewmitglieds zu erahnen."}'::jsonb WHERE id = 5200;
UPDATE errori SET descrizione_i18n = '{"it":"Quando gli scienziati governativi irrompono nella casa di Elliott allestendo il laboratorio medico, la disposizione dei monitor di controllo e dei tubi di ossigeno attorno al letto di E.T. varia notevolmente tra i campi lunghi e i primi piani.","en":"When government scientists raid Elliott''s house setting up the medical lab, the arrangement of control monitors and oxygen tubes around E.T.''s bed varies significantly between wide shots and close-ups.","es":"Cuando los científicos gubernamentales irrumpen en la casa de Elliott montando el laboratorio médico, la disposición de los monitores de control y las tuberías de oxígeno alrededor de la cama de E.T. varía notablemente entre los planos generales y los primeros planos.","fr":"Lorsque les scientifiques du gouvernement font irruption dans la maison d''Elliott pour installer le laboratoire médical, la disposition des moniteurs de contrôle et des tubes d''oxygène autour du lit d''E.T. varie considérablement entre les plans larges et les gros plans.","de":"Als Regierungswissenschaftler in Elliotts Haus einfallen und das medizinische Labor einrichten, variiert die Anordnung der Überwachungsmonitore und Sauerstoffschläuche um E.T.s Bett erheblich zwischen Totalen und Nahaufnahmen."}'::jsonb WHERE id = 5201;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la celebre scena finale in cui le biciclette si alzano in volo, nella ripresa dal basso del gruppo in controluce contro la luna, i cavi di sostegno utilizzati per sollevare le biciclette degli stuntman risultano parzialmente visibili prima di essere corretti in post-produzione.","en":"During the famous final scene where the bicycles take flight, in the low-angle shot of the group backlit against the moon, the support wires used to lift the stuntmen''s bicycles are partially visible before being fixed in post-production.","es":"Durante la famosa escena final en la que las bicicletas echan a volar, en el plano contrapicado del grupo contras Luz contra la luna, los cables de apoyo utilizados para elevar las bicicletas de los especialistas son parcialmente visibles antes de ser corregidos en postproducción.","fr":"Pendant la célèbre scène finale où les vélos s''envolent, dans le plan en contre-plongée du groupe à contre-jour devant la lune, les câbles de soutien utilisés pour soulever les vélos des cascadeurs sont partiellement visibles avant d''être corrigés en post-production.","de":"Während der berühmten Finalszene, in der die Fahrräder abheben, sind in der Untersicht der Gruppe im Gegenlicht vor dem Mond die Haltekabel, die zum Hochheben der Fahrräder der Stuntmen verwendet wurden, teilweise sichtbar, bevor sie in der Postproduktion entfernt wurden."}'::jsonb WHERE id = 5202;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui John Coffrey viene portato nella sua cella per la prima volta, i secchi e gli oggetti sul pavimento vicino al blocco cambiano posizione tra le inquadrature larghe e i primi piani sulle guardie.","en":"During the scene where John Coffrey is brought to his cell for the first time, the buckets and objects on the floor near the cell block change position between wide shots and close-ups on the guards.","es":"Durante la escena en la que John Coffrey es llevado a su celda por primera vez, los cubos y objetos en el suelo cerca del bloque cambian de posición entre los planos generales y los primeros planos de los guardias.","fr":"Pendant la scène où John Coffrey est conduit dans sa cellule pour la première fois, les seaux et les objets sur le sol près du bloc changent de position entre les plans larges et les gros plans sur les gardes.","de":"Während der Szene, in der John Coffrey zum ersten Mal in seine Zelle gebracht wird, wechseln Eimer und Gegenstände auf dem Boden in der Nähe des Zellblocks ihre Position zwischen Totalen und Nahaufnahmen der Wärter."}'::jsonb WHERE id = 5203;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune scene del film sono visibili elementi di illuminazione e canaline elettriche moderne o rivisitate che non corrispondono agli standard tecnologici del 1935 nel sud degli Stati Uniti.","en":"In some scenes of the film, modern or updated lighting fixtures and electrical conduits are visible, which do not match the 1935 technological standards in the American South.","es":"En algunas escenas de la película se pueden ver elementos de iluminación y canaletas eléctricas modernas o actualizadas que no se corresponden con los estándares tecnológicos de 1935 en el sur de Estados Unidos.","fr":"Dans certaines scenes du film, des luminaires et des goulottes électriques modernes ou actualisés sont visibles, ce qui ne correspond pas aux normes technologiques de 1935 dans le sud des États-Unis.","de":"In einigen Szenen des Films sind moderne oder nachträglich angebrachte Beleuchtungskörper und Kabelkanäle zu sehen, die nicht den technologischen Standards des Jahres 1935 im amerikanischen Süden entsprechen."}'::jsonb WHERE id = 5204;
UPDATE errori SET descrizione_i18n = '{"it":"Le targhe delle automobili e dei veicoli della polizia mostrati nel corso della pellicola presentano formati e font tipografici non coerenti con quelli effettivamente utilizzati nello stato della Louisiana nel 1935.","en":"The license plates of the cars and police vehicles shown throughout the film feature formats and typographic fonts that are inconsistent with those actually used in the state of Louisiana in 1935.","es":"Las matrículas de los automóviles y vehículos policiales que aparecen a lo largo de la película presentan formatos y fuentes tipográficas que no coinciden con los utilizados realmente en el estado de Luisiana en 1935.","fr":"Les plaques d''immatriculation des voitures et des véhicules de police montrés tout au long du film présentent des formats et des polices typographiques non conformes à ceux réellement utilisés dans l''État de Louisiane en 1935.","de":"Die Nummernschilder der Autos und Polizeifahrzeuge im Laufe des Films weisen Formate und Schriftarten auf, die nicht mit denen übereinstimmen, die 1935 tatsächlich im Bundesstaat Louisiana verwendet wurden."}'::jsonb WHERE id = 5205;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Percy Wetmore calpesta e rompe il topo di Mr. Jingles, la posizione dei pezzi del rocchetto di filato e dei detriti sul pavimento muta sensibilmente nei diversi cambi di inquadratura.","en":"When Percy Wetmore steps on and breaks Mr. Jingles'' mouse, the position of the spool of thread pieces and debris on the floor changes noticeably across different cuts.","es":"Cuando Percy Wetmore pisa y rompe el ratón de Mr. Jingles, la posición de los trozos del carrete de hilo y de los escombros en el suelo cambia notablemente entre los distintos planos.","fr":"Lorsque Percy Wetmore écrase et brise la souris de Mr. Jingles, la position des morceaux de la bobine de fil et des débris sur le sol change sensiblement d''un plan à l''autre.","de":"Als Percy Wetmore auf Mr. Jingles'' Maus tritt und sie zerbricht, verändert sich die Position der Garnrollenstücke und Trümmer auf dem Boden bei den verschiedenen Kameraeinstellungen merklich."}'::jsonb WHERE id = 5206;
UPDATE errori SET descrizione_i18n = '{"it":"Durante le scene nel braccio della morte, alcuni documenti cartacei e registri carcerari mostrano la dattiloscritto con caratteri tipografici e spazggiature che ricordano macchine da scrivere digitali o modelli successivi agli anni trenta.","en":"During the death row scenes, some paperwork and prison ledgers show typescript with typefaces and spacing reminiscent of digital typewriters or models later than the 1930s.","es":"Durante las escenas en el corredor de la muerte, algunos documentos en papel y registros penitenciarios muestran texto mecanografiado con fuentes y espaciados que recuerdan a máquinas de escribir digitales o modelos posteriores a los años treinta.","fr":"Pendant les scènes dans le couloir de la mort, certains documents papier et registres pénitentiaires affichent des dactylographies aux caractères et aux espacements rappelant des machines à écrire numériques ou des modèles postérieurs aux années 1930.","de":"Während der Szenen im Todestrakt zeigen einige Papierdokumente und Gefängnisregister Schreibmaschinenschrift mit Schriftarten und Abständen, die an digitale Schreibmaschinen oder Modelle aus der Zeit nach den 1930er Jahren erinnern."}'::jsonb WHERE id = 5207;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i sette nani tornano dalla miniera e marciano cantando verso casa, l''ordine in cui camminano varia leggermente tra i campi lunghi e i primi piani prima dell''arrivo alla porta.","en":"When the seven dwarfs return from the mine and march home singing, the order in which they walk varies slightly between long shots and close-ups before reaching the door.","es":"Cuando los siete enanitos vuelven de la mina y marchan cantando hacia casa, el orden en el que caminan varía ligeramente entre los planos generales y los primeros planos antes de llegar a la puerta.","fr":"Quand les sept nains reviennent de la mine et marchent en chantant vers chez eux, l''ordre dans lequel ils marchent varie légèrement entre les plans larges et les gros plans avant d''arriver à la porte.","de":"Wenn die sieben Zwerge von der Mine zurückkehren und singend nach Hause marschieren, variiert die Reihenfolge, in der sie gehen, zwischen den Totalen und Großaufnahmen leicht, bevor sie die Tür erreichen."}'::jsonb WHERE id = 5208;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Biancaneve prepara la zuppa per i nani e usa il cucchiaio per assaggiarla, la posizione del mestolo e dei barattoli di spezie sulla mensola alle sue spalle cambia tra un''inquadratura e l''altra.","en":"While Snow White prepares the soup for the dwarfs and uses the spoon to taste it, the position of the ladle and the spice jars on the shelf behind her changes from one shot to the next.","es":"Mientras Blancanieves prepara la sopa para los enanitos y usa la cuchara para probarla, la posición del cucharón y de los tarros de especias en el estante detrás de ella cambia de un plano a otro.","fr":"Pendant que Blanche-Neige prépare la soupe pour les nains et utilise la cuillère pour y goûter, la position de la louche et des pots d''épices sur l''étagère derrière elle change d''un plan à l''autre.","de":"Während Schneewittchen die Suppe für die Zwerge zubereitet und sie mit dem Löffel probiert, verändert sich die Position der Schöpfkelle und der Gewürzdosen im Regal hinter ihr von Einstellung zu Einstellung."}'::jsonb WHERE id = 5209;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui la Regina Cattiva prepara la pozione magica nel suo laboratorio segreto, la disposizione delle bottiglie, dei teschi e degli ingredienti magici sul tavolo cambia posizione tra le varie inquadrature.","en":"During the sequence where the Evil Queen prepares the magic potion in her secret laboratory, the arrangement of the bottles, skulls, and magic ingredients on the table changes position across various shots.","es":"Durante la secuencia en la que la Reina Malvada prepara la poción mágica en su laboratorio secreto, la disposición de las botellas, las calaveras y los ingredientes mágicos sobre la mesa cambia de posición entre los distintos planos.","fr":"Pendant la séquence où la Reine méchante prépare la potion magique dans son laboratoire secret, la disposition des bouteilles, des crânes et des ingrédients magiques sur la table change de position d''un plan à l''autre.","de":"Während der Sequenz, in der die Böse Königin den Zaubertrank in ihrem geheimen Labor zubereitet, verändert sich die Anordnung der Flaschen, Schädel und magischen Zutaten auf dem Tisch zwischen den verschiedenen Einstellungen."}'::jsonb WHERE id = 5210;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la strega arriva alla casetta dei nani con la mela avvelenata, il cesto che tiene in mano mostra variazioni nella disposizione delle mele e del tessuto di copertura tra un cambio di inquadratura e l''altro.","en":"When the witch arrives at the dwarfs'' cottage with the poisoned apple, the basket she holds shows variations in the arrangement of the apples and the covering cloth between cuts.","es":"Cuando la bruja llega a la cabaña de los enanitos con la manzana envenenada, la cesta que sostiene en la mano muestra variaciones en la disposición de las manzanas y de la tela de cobertura entre un plano y otro.","fr":"Quand la sorcière arrive à la chaumière des nains avec la pomme empoisonnée, le panier qu''elle tient dans les mains présente des variations dans la disposition des pommes et du tissu de couverture d''un plan à l''autre.","de":"Wenn die Hexe mit dem vergiften Apfel an der Zwergenhütte ankommt, weist der Korb, den sie in den Händen hält, bei den Szenenwechseln Unterschiede in der Anordnung der Äpfel und des Abdecktuchs auf."}'::jsonb WHERE id = 5211;
UPDATE errori SET descrizione_i18n = '{"it":"Quando i tre amici sono in viaggio e fermano l''auto per fare benzina o nei pressi di un autogrill, la bottiglietta d''acqua o gli oggetti sul cruscotto cambiano posizione tra l''inquadratura dall''interno e quella esterna.","en":"When the three friends are on a road trip and stop the car for gas or near a service station, the water bottle or objects on the dashboard change position between the interior and exterior shots.","es":"Cuando los tres amigos están de viaje y detienen el coche para repostar o cerca de una área de descanso, la botellita de agua o los objetos del salpicadero cambian de posición entre el plano interior y el exterior.","fr":"Quand les trois amis sont en voyage et arrêtent la voiture pour faire le plein ou près d''une aire d''autoroute, la bouteille d''eau ou les objets sur le tableau de bord changent de position entre le plan intérieur et le plan extérieur.","de":"Wenn die drei Freunde auf Reisen sind und das Auto zum Tanken oder an einer Raststätte anhalten, verändern die Wasserflasche oder Gegenstände auf dem Armaturenbrett ihre Position zwischen der Innen- und der Außenaufnahme."}'::jsonb WHERE id = 5212;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la celebre scena della partita di bocce (o altra attività all''aperto durante il viaggio), gli oggetti personali dei protagonisti nelle tasche o posizionati sulle panchine scompaiono e ricompaiono a seconda dei cambi di inquadratura.","en":"During the famous bocce game scene (or another outdoor activity during the trip), the protagonists'' personal items in their pockets or placed on the benches disappear and reappear depending on the camera cuts and shot changes.","es":"Durante la famosa escena del juego de bochas (u otra actividad al aire libre durante el viaje), los objetos personales de los protagonistas en los bolsillos o colocados en los bancos desaparecen y reaparecen según los cambios de plano.","fr":"Pendant la célèbre scène de la partie de boules (ou d''une autre activité en plein air pendant le voyage), les effets personnels des protagonistes dans leurs poches ou posés sur les bancs disparaissent et réapparaissent selon les changements de plan.","de":"Während der berühmten Boccia-Szene (oder einer anderen Outdoor-Aktivität während der Reise) verschwinden und reappearing die persönlichen Gegenstände der Protagonisten in ihren Taschen oder auf den Bänken je nach Szenenwechsel und Einstellung."}'::jsonb WHERE id = 5213;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui sono ospiti nella villa del futuro suocero (Carlo Croccolo), i bicchieri e i piatti sul tavolo variano il livello di riempimento tra un primo piano e il campo totale.","en":"In the sequence where they are guests at the future father-in-law''s villa (Carlo Croccolo), the glasses and plates on the table vary in their fill levels between a close-up and a master shot (wide shot).","es":"En la secuencia en la que son invitados en la villa del futuro suegro (Carlo Croccolo), los vasos y platos de la mesa varían su nivel de llenado entre un primer plano y un plano general.","fr":"Dans la séquence où ils sont invités dans la villa du futur beau-père (Carlo Croccolo), les verres et les assiettes sur la table changent de niveau de remplissage entre un gros plan et un plan large.","de":"In der Sequenz, in der sie in der Villa des zukünftigen Schwiegervaters (Carlo Croccolo) zu Gast sind, variieren der Füllstand der Gläser und Teller auf dem Tisch zwischen einer Nahaufnahme und einer Totale."}'::jsonb WHERE id = 5214;
UPDATE errori SET descrizione_i18n = '{"it":"La celebre scultura lignea, la gamba di Garibaldi, presenta piccoli dettagli e segni distintivi che differiscono leggermente tra le inquadrature ravvicinate e quelle in cui viene maneggiata in campo largo.","en":"The famous wooden sculpture, Garibaldi''s leg, features small details and distinct marks that differ slightly between close-up shots and wide shots where it is being handled.","es":"La famosa escultura de madera, la pierna de Garibaldi, presenta pequeños detalles y marcas distintivas que difieren ligeramente entre los planos detalle y las tomas generales en las que se manipula.","fr":"La célèbre sculpture en bois, la jambe de Garibaldi, présente de petits détails et des marques distinctives qui diffèrent légèrement entre les gros plans et les plans larges où elle est manipulée.","de":"Die berühmte Holzskulptur, Garibaldis Bein, weist kleine Details und markante Merkmale auf, die sich zwischen Nahaufnahmen und den Einstellungen in der Totale, in denen sie gehandhabt wird, leicht unterscheiden."}'::jsonb WHERE id = 5215;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Baby entra nella sala da ballo dello staff per la prima volta, i bicchieri sul tavolo vicino a lei cambiano disposizione tra un''inquadratura e l''altra.","en":"When Baby enters the staff dance hall for the first time, the glasses on the table near her change arrangement between cuts.","es":"Cuando Baby entra por primera vez en la sala de baile del personal, los vasos de la mesa cercana cambian de disposición de un plano a otro.","fr":"Quand Baby entre pour la première fois dans la salle de bal du personnel, les verres sur la table près d''elle changent de disposition d''un plan à l''autre.","de":"Als Baby zum ersten Mal den Tanzsaal des Personals betritt, verändert sich die Anordnung der Gläser auf dem Tisch in ihrer Nähe von einer Einstellung zur nächsten."}'::jsonb WHERE id = 5216;
UPDATE errori SET descrizione_i18n = '{"it":"Il film è ambientato nell''estate del 1963, ma Baby indossa in alcune scene modelli di scarpe da ginnastica o pantaloni che sono stilisticamente riconducibili alla metà degli anni ''80.","en":"The film is set in the summer of 1963, but in some scenes Baby wears sneakers or trousers whose style traces back to the mid-1980s.","es":"La película está ambientada en el verano de 1963, pero en algunas escenas Baby lleva zapatillas de deporte o pantalones cuyo estilo se remonta a mediados de los años 80.","fr":"Le film se déroule à l''été 1963, mais dans certaines scènes, Baby porte des baskets ou des pantalons dont le style renvoie au milieu des années 1980.","de":"Der Film spielt im Sommer 1963, aber in einigen Szenen trägt Baby Sneaker oder Hosen, die stilistisch eher in die Mitte der 1980er Jahre passen."}'::jsonb WHERE id = 5217;
UPDATE errori SET descrizione_i18n = '{"it":"Durante una delle prove di ballo nella cabina di Johnny, in alto a sinistra si intravede per un breve fotogramma l''ombra di un microfono a boom sul soffitto in legno.","en":"During one of the dance rehearsals in Johnny''s cabin, the shadow of a boom mic can be briefly glimpsed on the wooden ceiling in the top-left corner for a single frame.","es":"Durante uno de los ensayos de baile en la cabaña de Johnny, en la esquina superior izquierda se ve brevemente la sombra de un micrófono de pértiga (boom mic) en el techo de madera.","fr":"Pendant l''une des répétitions de danse dans la cabane de Johnny, on aperçoit brièvement l''ombre d''un micro perche (boom mic) sur le plafond en bois dans le coin supérieur gauche.","de":"Während einer der Tanzproben in Johnns Hütte ist oben links für einen kurzen Moment der Schatten eines Boom-Mikrofons an der Holzwede zu sehen."}'::jsonb WHERE id = 5218;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Johnny viene accusato ingiustamente del furto del portafoglio, la giacca che tiene in mano passa dall''essere piegata a essere spiegazzata a seconda dei cambi di inquadratura.","en":"In the scene where Johnny is falsely accused of stealing the wallet, the jacket he is holding switches from neatly folded to crumpled depending on the camera cuts and shot changes.","es":"En la escena en la que acusan injustamente a Johnny del robo de la cartera, la chaqueta que lleva en la mano pasa de estar doblada a estar arrugada según los cambios de plano.","fr":"Dans la scène où Johnny est faussement accusé du vol du portefeuille, la veste qu''il tient passe d''soigneusement pliée à froissée selon les changements de plan.","de":"In der Szene, in der Johnny fälschlicherweise des Geldbörsendiebstahls beschuldigt wird, wechselt die Jacke, die er in der Hand hält, je nach Einstellung zwischen sauber gefaltet und verknittert."}'::jsonb WHERE id = 5219;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Melvin entra nel ristorante e si siede al solito tavolo servito da Carol, il tovagliolo sul tavolo cambia posizione e piegatura tra un cambio di inquadratura e l''altro.","en":"When Melvin enters the restaurant and sits at his usual table served by Carol, the napkin on the table changes its position and fold between camera cuts.","es":"Cuando Melvin entra en el restaurante y se sienta en su mesa habitual atendida por Carol, la servilleta de la mesa cambia de posición y doblez entre los cambios de plano.","fr":"Quand Melvin entre dans le restaurant et s''assoit à sa table habituelle servie par Carol, la serviette sur la table change de position et de pliage d''un plan à l''autre.","de":"Als Melvin das Restaurant betritt und sich an seinen Stammtisch setzt, der von Carol bedient wird, verändert sich die Position und Faltung der Serviette auf dem Tisch zwischen den Einstellungen."}'::jsonb WHERE id = 5220;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il viaggio in macchina verso Baltimora, la tazza di caffè che Melvin tiene in mano o poggia sul cruscotto mostra una quantità di liquido visibilmente diversa tra un primo piano e l''inquadratura larga.","en":"During the car ride to Baltimore, the amount of liquid in the coffee cup Melvin holds or places on the dashboard visibly changes between a close-up and the wide shot.","es":"Durante el viaje en coche a Baltimore, la taza de café que Melvin sostiene o apoya en el salpicadero muestra una cantidad de líquido visiblemente distinta entre un plano medio y el plano general.","fr":"Pendant le trajet en voiture vers Baltimore, la quantité de liquide dans la tasse à café que Melvin tient ou pose sur le tableau de bord varie visiblement entre un gros plan et le plan large.","de":"Während der Autofahrt nach Baltimore unterscheidet sich die Menge des Kaffees in dem Becher, den Melvin hält oder auf dem Armaturenbrett abstellt, zwischen einer Nahaufnahme und der Totalen sichtbar voneinander."}'::jsonb WHERE id = 5221;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena dell''hotel in cui Melvin, Carol e Simon parlano nella stanza, il movimento delle labbra di Helen Hunt in un primo piano non coincide perfettamente con l''audio della battuta pronunciata.","en":"In the hotel room scene where Melvin, Carol, and Simon are talking, Helen Hunt''s lip movements in a close-up do not perfectly match the audio of her spoken line.","es":"En la escena del hotel en la que Melvin, Carol y Simon hablan en la habitación, el movimiento de los labios de Helen Hunt en un primer plano no coincide perfectamente con el audio de su frase.","fr":"Dans la scène de l''hôtel où Melvin, Carol et Simon discutent dans la chambre, les mouvements des lèvres d''Helen Hunt dans un gros plan ne correspondent pas parfaitement à l''audio de sa réplique.","de":"In der Hotelszene, in der Melvin, Carol und Simon im Zimmer sprechen, stimmen Helen Hunts Lippenbewegungen in einer Nahaufnahme nicht perfekt mit dem Audio ihres Dialogs überein."}'::jsonb WHERE id = 5222;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la riunione del Pentagono, i documenti e le cartelline sulla scrivania del Direttore dell''FBI Womack cambiano disposizione e posizione tra un''inquadratura ravvicinata e quella a campo largo.","en":"During the Pentagon meeting, the documents and folders on FBI Director Womack''s desk change arrangement and position between a close-up shot and the wide shot.","es":"Durante la reunión del Pentágono, los documentos y carpetas en el escritorio del director del FBI, Womack, cambian de disposición y posición entre un plano detalle y el plano general.","fr":"Pendant la réunion au Pentagone, la disposition et la position des documents et des dossiers sur le bureau du directeur du FBI Womack changent entre un plan serré et le plan large.","de":"Während des Pentagons-Meetings verändern sich die Anordnung und Position der Dokumente und Aktenordner auf dem Schreibtisch von FBI-Direktor Womack zwischen einer Nahaufnahme und der Totalen."}'::jsonb WHERE id = 5223;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Stanley Goodspeed disinnesca la sfera di vetro con il gas VX nel bagno dell''hotel Fairmont, i cavi e i contatti elettrici vengono maneggiati in modo cinematografico ma scientificamente non plausibile per un ordigno chimico di quel tipo.","en":"In the scene where Stanley Goodspeed defuses the glass orb containing VX gas in the Fairmont hotel bathroom, the wires and electrical contacts are handled in a cinematic yet scientifically implausible way for a chemical device of that type.","es":"En la escena en la que Stanley Goodspeed desactiva la esfera de cristal con gas VX en el baño del hotel Fairmont, los cables y contactos eléctricos se manipulan de forma cinematográfica pero científicamente inverosímil para un artefacto químico de ese tipo.","fr":"Dans la scène où Stanley Goodspeed désamorce l''orbe de verre contenant le gaz VX dans la salle de bains de l''hôtel Fairmont, les câbles et les contacts électriques sont manipulés de manière cinématographique mais scientifiquement invraisemblable pour un engin chimique de ce type.","de":"In der Szene, in der Stanley Goodspeed die Glaskugel mit dem VX-Gas im Badezimmer des Fairmont-Hotels entschärft, werden die Kabel und elektrischen Kontakte auf eine filmische, aber für ein solches chemisches Gerät wissenschaftlich unplausible Weise gehandhabt."}'::jsonb WHERE id = 5224;
UPDATE errori SET descrizione_i18n = '{"it":"Durante il violento scontro a fuoco nel corridoio dei sotterranei di Alcatraz, i corpi dei marines caduti cambiano leggermente posizione e distanza dalle pareti tra i tagli di montaggio.","en":"During the violent shootout in the Alcatraz subterranean hallway, the bodies of the fallen Marines slightly change position and distance from the walls between editing cuts.","es":"Durante el violento tiroteo en el pasillo subterráneo de Alcatraz, los cuerpos de los marines caídos cambian ligeramente de posición y de distancia respecto a las paredes entre los cortes de montaje.","fr":"Pendant la violente fusillade dans le couloir souterrain d''Alcatraz, les corps des Marines tombés changent légèrement de position et de distance par rapport aux murs entre les raccords de montage.","de":"Während des heftigen Feuergefechts im unterirdischen Gang von Alcatraz verändern die Leichen der gefallenen Marines zwischen den Filmschnitten leicht ihre Position und ihren Abstand zu den Wänden."}'::jsonb WHERE id = 5225;
UPDATE errori SET descrizione_i18n = '{"it":"I caccia F/A-18 Hornet inviati per bombardare Alcatraz montano armamenti e configurazioni di volo che non corrispondono alle procedure standard operative della US Navy per quel tipo di missione d''attacco ravvicinato.","en":"The F/A-18 Hornet fighters sent to bomb Alcatraz carry weapons and flight configurations that do not match the US Navy''s standard operating procedures for that type of close air support mission.","es":"Los cazas F/A-18 Hornet enviados para bombardear Alcatraz llevan armamento y configuraciones de vuelo que no se corresponden con los procedimientos operativos estándar de la US Navy para ese tipo de misión de ataque cercano.","fr":"Les chasseurs F/A-18 Hornet envoyés pour bombarder Alcatraz arborent des armements et des configurations de vol qui ne correspondent pas aux procédures opérationnelles standard de l''US Navy pour ce type de mission d''attaque au sol.","de":"Die zur Bombardierung von Alcatraz entsandten F/A-18 Hornet-Kampfflugzeuge tragen Bewaffnungen und Flugkonfigurationen, die nicht den Standard-Einsatzverfahren der US Navy für diese Art von Nahangriffsmission entsprechen."}'::jsonb WHERE id = 5226;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Goodspeed segnala la propria posizione con il verde fumogeno alla fine del film, la camicia e la giacca del personaggio presentano strappi e macchie di fango la cui estensione varia visivamente da un''inquadratura all''altra.","en":"When Goodspeed signals his position with a green smoke flare at the end of the film, the character''s shirt and jacket show tears and mud stains whose extent visibly varies from shot to shot.","es":"Cuando Goodspeed señala su posición con la bengala de humo verde al final de la película, la camisa y la chaqueta del personaje presentan roturas y manchas de barro cuya extensión varía visiblemente de un plano a otro.","fr":"Lorsque Goodspeed signale sa position avec une fumigène vert à la fin du film, la chemise et la veste du personnage présentent des déchirures et des taches de boue dont l''étendue varie visiblement d''un plan à l''autre.","de":"Als Goodspeed am Ende des Films seine Position mit einer grünen Rauchkerze markiert, weisen Hemd und Jacke des Charakters Risse und Schmutzflecken auf, deren Ausdehnung von Einstellung zu Einstellung sichtbar variiert."}'::jsonb WHERE id = 5227;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Charlie trova la moneta nella neve e corre verso il negozio per comprare la barretta di cioccolato, la sciarpa al suo collo cambia improvvisamente posizione e nodo tra un''inquadratura e l''altra.","en":"When Charlie finds the coin in the snow and runs to the shop to buy the chocolate bar, his scarf suddenly changes position and knot style between shots.","es":"Cuando Charlie encuentra la moneda en la nieve y corre hacia la tienda para comprar la barra de chocolate, la bufanda alrededor de su cuello cambia repentinamente de posición y de nudo entre un plano y otro.","fr":"Quand Charlie trouve la pièce dans la neige et court vers la boutique pour acheter sa tablette de chocolat, l''écharpe autour de son cou change soudainement de position et de nœud d''un plan à l''autre.","de":"Als Charlie die Münze im Schnee findet und zum Laden rennt, um die Schokoriegel zu kaufen, verändern sich Position und Knoten seines Schals zwischen den Einstellungen plötzlich."}'::jsonb WHERE id = 5228;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui i bambini entrano per la prima volta nella sala di cioccolata attraverso le porte giganti, in un breve riflesso sui bottoni della giacca di Willy Wonka è possibile intravedere la sagoma di un membro della troupe con l''attrezzatura.","en":"During the sequence where the children first enter the chocolate room through the giant doors, a crew member with equipment can be briefly glimpsed in the reflection on Willy Wonka''s jacket buttons.","es":"Durante la secuencia en la que los niños entran por primera vez en la sala de chocolate a través de las puertas gigantes, se puede vislumbrar brevemente la silueta de un miembro del equipo técnico en el reflejo de los botones de la chaqueta de Willy Wonka.","fr":"Pendant la séquence où les enfants pénètrent pour la première fois dans la salle de chocolat par les portes géantes, on peut apercevoir brièvement la silhouette d''un technicien dans le reflet des boutons de la veste de Willy Wonka.","de":"Während der Sequenz, in der die Kinder zum ersten Mal durch die riesigen Türen den Schokoladenraum betreten, ist in einer kurzen Spiegelung auf den Knöpfen von Willy Wonkas Jacke die Silhouette eines Crewmitglieds mit Ausrüstung zu erkennen."}'::jsonb WHERE id = 5229;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Violet Beauregarde mastica la gomma sperimentale e inizia a gonfiarsi, il bicchiere di succo di mirtillo sul tavolo vicino a lei sparisce e riappare tra un taglio di montaggio e il successivo.","en":"In the scene where Violet Beauregarde chews the experimental gum and begins to swell, the glass of blueberry juice on the table next to her disappears and reappears between cuts.","es":"En la escena en la que Violet Beauregarde mastica el chicle experimental y empieza a hincharse, el vaso de zumo de arándanos de la mesa situada a su lado desaparece y vuelve a aparecer entre un corte de montaje y el siguiente.","fr":"Dans la scène où Violet Beauregarde mâche le chewing-gum expérimental et commence à grossir, le verre de jus de myrtille posé sur la table à côté d''elle disparaît et réapparaît d''un plan à l''autre.","de":"In der Szene, in der Violet Beauregarde den experimentellen Kaugummi kaut und beginnt anzuschwellen, verschwindet das Glas Blaubeersaft auf dem Tisch neben ihr und taucht zwischen zwei Schnitten wieder auf."}'::jsonb WHERE id = 5230;
UPDATE errori SET descrizione_i18n = '{"it":"Sebbene il libro originale di Roald Dahl sia del 1964 e l''ambientazione generale sembri sospesa nel tempo, la televisione su cui viene trasmesso Mike Teavee mostra una trasmissione a colori con standard e grafiche che richiamano un periodo successivo.","en":"Although Roald Dahl''s original book is from 1964 and the overall setting feels timeless, the television on which Mike Teavee is broadcast shows a color transmission with standards and graphics reminiscent of a later period.","es":"Aunque el libro original de Roald Dahl es de 1964 y la ambientación general parece atemporal, el televisor en el que se emite a Mike Teavee muestra una transmisión en color con estándares y gráficos que recuerdan a una época posterior.","fr":"Bien que le livre original de Roald Dahl date de 1964 et que l''ambiance générale semble intemporelle, le téléviseur sur lequel passe Mike Teavee affiche une diffusion en couleur avec des standards et des graphismes d''une époque ultérieure.","de":"Obwohl Roald Dahls Originalbuch aus dem Jahr 1964 stammt und das allgemeine Setting zeitlos wirkt, zeigt der Fernseher, auf dem Mike Teavee übertragen wird, eine Farbfernsehübertragung mit Standards und Grafiken, die an eine spätere Zeit erinnern."}'::jsonb WHERE id = 5231;
UPDATE errori SET descrizione_i18n = '{"it":"Nel laboratorio di inventiva di Willy Wonka, i dolciumi e i macchinari sullo sfondo cambiano disposizione quando la telecamera passa da un primo piano di Johnny Depp a un campo medio.","en":"In Willy Wonka''s invention room, the sweets and machinery in the background change placement when the camera cuts from a close-up of Johnny Depp to a medium shot.","es":"En la sala de inventos de Willy Wonka, los dulces y la maquinaria del fondo cambian de disposición cuando la cámara pasa de un primer plano de Johnny Depp a un plano medio.","fr":"Dans la salle d''invention de Willy Wonka, les confiseries et les machines en arrière-plan changent de disposition lorsque la caméra passe d''un gros plan de Johnny Depp à un plan moyen.","de":"In Willy Wonkas Erfinderraum verändern die Süßigkeiten und Maschinen im Hintergrund ihre Position, wenn die Kamera von einer Nahaufnahme von Johnny Depp auf eine halbtotale Einstellung wechselt."}'::jsonb WHERE id = 5232;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Marty entra nel laboratorio di Doc e osserva il grande orologio che segna le 8:00, i cavi e gli oggetti sul tavolo cambiano disposizione tra un''inquadratura e l''altra quando Doc lo chiama al telefono.","en":"When Marty enters Doc''s lab and looks at the large clock reading 8:00, the cables and objects on the table change arrangement between shots when Doc calls him on the phone.","es":"Cuando Marty entra en el laboratorio de Doc y observa el gran reloj que marca las 8:00, los cables y objetos de la mesa cambian de disposición de un plano a otro cuando Doc le llama por teléfono.","fr":"Quand Marty entre dans le laboratoire de Doc et regarde la grande horloge qui indique 8h00, les câbles et les objets sur la table changent de disposition d''un plan à l''autre lorsque Doc l''appelle au téléphone.","de":"Als Marty Docks Labor betritt und die große Uhr betrachtet, die 8:00 Uhr anzeigt, verändern die Kabel und Gegenstände auf dem Tisch zwischen den Einstellungen ihre Anordnung, als Doc ihn am Telefon anruft."}'::jsonb WHERE id = 5233;
UPDATE errori SET descrizione_i18n = '{"it":"Nel 1955, quando Marty scende dalla DeLorean dopo essere arrivato al centro commerciale (poi fattoria di Peabody), i tergicristalli dell''auto si trovano in una posizione diversa rispetto all''inquadratura precedente in movimento.","en":"In 1955, when Marty gets out of the DeLorean after arriving at the mall (later Peabody''s farm), the car''s windshield wipers are in a different position compared to the previous moving shot.","es":"En 1955, cuando Marty se baja del DeLorean tras llegar al centro comercial (luego granja de Peabody), los limpiaparabrisas del coche están en una posición diferente a la del plano en movimiento anterior.","fr":"En 1955, lorsque Marty sort de la DeLorean après son arrivée au centre commercial (plus tard la ferme des Peabody), les essuie-glaces de la voiture sont dans une position différente par rapport au plan en mouvement précédent.","de":"Im Jahr 1955, als Marty nach seiner Ankunft am Einkaufszentrum (später Peabody-Farm) aus dem DeLorean steigt, befinden sich die Scheibenwischer des Autos in einer anderen Position als in der vorherigen Fahreinstellung."}'::jsonb WHERE id = 5234;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui il giovane Biff e i suoi amici inseguono Marty sullo skateboard in piazza, i cumuli di letame cambiano leggermente forma e consistenza nei vari stacchi di montaggio prima dell''impatto con la BMW.","en":"In the scene where young Biff and his friends chase Marty on his skateboard in the town square, the piles of manure slightly change shape and consistency across the editing cuts before the impact with the BMW.","es":"En la escena en la que el joven Biff y sus amigos persiguen a Marty en monopatín por la plaza, los montones de estiércol cambian ligeramente de forma y consistencia en los distintos cortes de montaje antes del impacto con el BMW.","fr":"Dans la scène où le jeune Biff et ses amis poursuivent Marty en skateboard sur la place de la ville, les tas de fumier changent légèrement de forme et de consistance d''un raccord à l''autre avant l''impact avec la BMW.","de":"In der Szene, in der der junge Biff und seine Freunde Marty auf dem Skateboard über den Marktplatz verfolgen, verändern die Mistaufen vor dem Zusammenstoß mit dem BMW in den verschiedenen Montageschnitten leicht ihre Form und Konsistenz."}'::jsonb WHERE id = 5235;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Marty mostra a Doc la videocamera JVC GR-C1 nel 1955 per ripassare il piano del fulmine, questo modello di videocamera portatile VHS-C è stato commercializzato solo a partire dal 1984, risultando anacronistico di quasi trent''anni.","en":"When Marty shows Doc the JVC GR-C1 camcorder in 1955 to review the lightning plan, this VHS-C portable camcorder model was only marketed starting in 1984, making it anachronistic by almost thirty years.","es":"Cuando Marty le muestra a Doc la videocámara JVC GR-C1 en 1955 para repasar el plan del rayo, este modelo de videocámara portátil VHS-C no se comercializó hasta 1984, lo que lo convierte en un anacronismo de casi treinta años.","fr":"Quand Marty montre à Doc le caméscope JVC GR-C1 en 1955 pour réviser le plan de la foudre, ce modèle de caméscope portable VHS-C n''a été commercialisé qu''à partir de 1984, ce qui en fait un anachronisme de près de trente ans.","de":"Als Marty Doc 1955 die Videokamera JVC GR-C1 zeigt, um den Blitz-Plan durchzugehen, kam dieses VHS-C-Camcorder-Modell erst ab 1984 auf den Markt, was es um fast dreißig Jahre anachronistisch macht."}'::jsonb WHERE id = 5236;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Marty parla con i suoi genitori adolescenti in auto (George e Lorraine), la posizione dei capelli di Lorraine e il colletto della sua giacca cambiano continuamente tra i campi e i controcampi.","en":"While Marty is talking to his teenage parents in the car (George and Lorraine), Lorraine''s hair position and jacket collar constantly change between shots and reverse shots.","es":"Mientras Marty habla con sus padres adolescentes en el coche (George y Lorraine), la posición del pelo de Lorraine y el cuello de su chaqueta cambian constantemente entre planos y contraplanos.","fr":"Pendant que Marty discute avec ses parents adolescents dans la voiture (George et Lorraine), la coiffure de Lorraine et le col de sa veste changent constamment entre les plans et contre-plans.","de":"Während Marty im Auto mit seinen jugendlichen Eltern (George und Lorraine) spricht, verändern sich Lorraines Haare und ihr Jackenkragen in den Schuss-Gegenschuss-Einstellungen kontinuierlich."}'::jsonb WHERE id = 5237;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Doc scala il municipio per collegare i cavi del fulmine nel 1955, in alcune inquadrature larghe si intravede brevemente l''ombra di un microfono a giraffa (boom) sulla facciata dell''edificio.","en":"In the sequence where Doc climbs the courthouse to connect the lightning cables in 1955, a boom mic shadow is briefly visible on the building''s facade in a few wide shots.","es":"En la secuencia en la que Doc trepa por el ayuntamiento para conectar los cables del rayo en 1955, en algunos planos generales se ve brevemente la sombra de un micrófono de pértiga en la fachada del edificio.","fr":"Dans la séquence où Doc escalade l''hôtel de ville pour brancher les câbles de la foudre en 1955, l''ombre d''un micro perche est brièvement visible sur la façade du bâtiment dans certains plans larges.","de":"In der Sequenz, in der Doc 1955 das Rathaus erklimmt, um die Blitzkabel zu verbinden, ist in einigen Totaleinstellungen kurz der Schatten eines Galgenmikrofons (Boom-Mic) an der Fassade des Gebäudes zu sehen."}'::jsonb WHERE id = 5238;
UPDATE errori SET descrizione_i18n = '{"it":"Quando la DeLorean si spegne e non vuole partire prima del fulmine, la chiave nel blocchetto di accensione scompare e riappare tra un primo piano sul volante e una visuale più ampia.","en":"When the DeLorean stalls and refuses to start before the lightning strike, the key in the ignition switch disappears and reappears between a close-up on the steering wheel and a wider shot.","es":"Cuando el DeLorean se cala y no arranca antes del rayo, la llave en el contacto desaparece y vuelve a aparecer entre un primer plano del volante y un plano más amplio.","fr":"Quand la DeLorean cale et refuse de démarrer avant l''éclair, la clé de contact disparaît et réapparaît entre un gros plan sur le volant et une vue plus large.","de":"Wenn der DeLorean abwürgt und vor dem Blitzeinschlag nicht anspringen will, verschwindet der Schlüssel im Zündschloss und taucht zwischen einer Nahaufnahme des Lenkrads und einer Totalen wieder auf."}'::jsonb WHERE id = 5239;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Marty arriva nel 1885 a Hill Valley e cammina nel fango, gli stivali che indossa sono modelli moderni con suola in gomma vulcanizzata, non disponibili all''epoca dei cowboy.","en":"When Marty arrives in 1885 Hill Valley and walks in the mud, the boots he is wearing are modern models with vulcanized rubber soles, which were not available in the cowboy era.","es":"Cuando Marty llega a Hill Valley en 1885 y camina por el barro, las botas que lleva son modelos modernos con suela de goma vulcanizada, que no estaban disponibles en la época de los vaqueros.","fr":"Quand Marty arrive en 1885 à Hill Valley et marche dans la boue, les bottes qu''il porte sont des modèles modernes à semelle en caoutchouc vulcanisé, indisponibles à l''époque des cow-boys.","de":"Als Marty 1885 in Hill Valley ankommt und durch den Schlamm läuft, trägt er moderne Stiefel mit vulkanisierten Gummisohlen, die es zur Zeit der Cowboys noch gar nicht gab."}'::jsonb WHERE id = 5240;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena in cui Marty entra nel saloon e affronta Buford Tannen, la bottiglia di whisky che Buford rompe sul banco cambia posizione e livello di liquido tra un''inquadratura e l''altra.","en":"During the scene where Marty enters the saloon and faces Buford Tannen, the whiskey bottle that Buford breaks on the bar changes position and liquid level between shots.","es":"Durante la escena en la que Marty entra en el salón y se enfrenta a Buford Tannen, la botella de whisky que Buford rompe en la barra cambia de posición y de nivel de líquido entre plano y plano.","fr":"Pendant la scène où Marty entre dans le saloon et affronte Buford Tannen, la bouteille de whisky que Buford brise sur le comptoir change de position et de niveau de liquide d''un plan à l''autre.","de":"In der Szene, in der Marty den Saloon betritt und sich Buford Tannen stellt, verändern sich die Position und der Füllstand der Whiskyflasche, die Buford auf dem Tresen zerschlägt, von Einstellung zu Einstellung."}'::jsonb WHERE id = 5241;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza in cui Doc ed Emmett guardano il modello del treno nel laboratorio improvvisato nella miniera, sulla destra si intravede brevemente l''ombra di un microfono a boom che oscilla sulla parete.","en":"In the sequence where Doc and Emmett look at the train model in the improvised mine laboratory, a boom mic''s shadow is briefly seen swaying on the wall to the right.","es":"En la secuencia en la que Doc y Emmett miran la maqueta del tren en el laboratorio improvisado de la mina, a la derecha se ve brevemente la sombra de un micrófono de pértiga oscilando en la pared.","fr":"Dans la séquence où Doc et Emmett regardent la maquette du train dans le labo improvisé de la mine, on aperçoit brièvement l''ombre d''un micro perche osciller sur le mur à droite.","de":"In der Sequenz, in der Doc und Emmett das Zugmodell im improvisierten Minenlabor betrachten, ist rechts kurz der Schatten eines Galgenmikrofons zu sehen, das an der Wand schwingt."}'::jsonb WHERE id = 5242;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Marty si trova nel 1885 e indossa le mutande con la fantasia di cavalli stampata, un capo del genere non era storicamente disponibile in quel periodo ed è un chiaro anacronismo stilistico.","en":"When Marty is in 1885 wearing horse-patterned underwear, such a garment was historically unavailable at the time and is a clear stylistic anachronism.","es":"Cuando Marty está en 1885 y lleva calzoncillos con estampado de caballos, una prenda así no existía históricamente en esa época y es un claro anacronismo estilístico.","fr":"Quand Marty se trouve en 1885 et porte des caleçons avec un motif de chevaux imprimé, un tel vêtement n''existait historiquement pas à cette époque et constitue un anachronisme stylistique évident.","de":"Wenn Marty sich im Jahr 1885 befindet und Unterwäsche mit Pferde-Print trägt, ist ein solches Kleidungsstück historisch gesehen zu dieser Zeit nicht verfügbar gewesen und ein klarer stilistischer Anachronismus."}'::jsonb WHERE id = 5243;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la scena del bacio tra Doc ed Emmett (Clara) al festival della cittadina, la posizione delle mani di Clara sulla spalla di Doc cambia visivamente tra un cambio di inquadratura e l''altro.","en":"During the kiss scene between Doc and Clara at the town festival, the position of Clara''s hands on Doc''s shoulder visibly changes between cuts.","es":"Durante la escena del beso entre Doc y Clara en la feria del pueblo, la posición de las manos de Clara en el hombro de Doc cambia visiblemente entre plano y plano.","fr":"Pendant la scène du baiser entre Doc et Clara à la fête du village, la position des mains de Clara sur l''épaule de Doc change visiblement d''un raccord à l''autre.","de":"Während der Kusszene zwischen Doc und Clara auf dem Stadtfest verändert sich die Position von Claras Händen auf Docs Schulter zwischen den einzelnen Schnitten sichtbar."}'::jsonb WHERE id = 5244;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Marty si misura i vestiti da cowboy nel negozio di Hill Valley, il cappello che tiene in mano passa ripetutamente da una mano all''altra tra i tagli di montaggio senza che lui compia il movimento per spostarlo.","en":"In the scene where Marty tries on cowboy clothes in the Hill Valley store, the hat he is holding repeatedly switches from one hand to the other across editing cuts without him making the motion to move it.","es":"En la escena en la que Marty se prueba ropa de vaquero en la tienda de Hill Valley, el sombrero que sostiene en la mano pasa repetidamente de una mano a otra entre los cortes de montaje sin que él realice el movimiento para cambiarlo.","fr":"Dans la scène où Marty essaie des vêtements de cow-boy dans le magasin de Hill Valley, le chapeau qu''il tient à la main passe de manière répétée d''une main à l''autre entre les raccords de montage sans qu''il ne fasse le mouvement pour le déplacer.","de":"In der Szene, in der Marty im Laden in Hill Valley Westernkleidung anprobiert, wechselt der Hut, den er in der Hand hält, zwischen den Filmschnitten wiederholt von einer Hand in die andere, ohne dass er die Bewegung macht, ihn zu wechseln."}'::jsonb WHERE id = 5245;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la sequenza in cui la DeLorean viene spinta dalla locomotiva prima del salto temporale, in un''inquadratura di sbieco si intravede brevemente il riflesso di una luce da studio cinematografico sulla carrozzeria lucida dell''auto.","en":"During the sequence where the DeLorean is pushed by the locomotive before the time jump, in an oblique shot the reflection of a studio light is briefly glimpsed on the car''s glossy bodywork.","es":"Durante la secuencia en la que la locomotora empuja al DeLorean antes del salto temporal, en un plano escorzo se divisa brevemente el reflejo de una luz de estudio cinematográfico en la carrocería brillante del coche.","fr":"Pendant la séquence où la DeLorean est poussée par la locomotive avant le saut temporel, dans un plan en angle on aperçoit brièvement le reflet d''un projecteur de studio sur la carrosserie brillante de la voiture.","de":"Während der Sequenz, in der der DeLorean vor dem Zeitsprung von der Lokomotive geschoben wird, ist in einer Schrägaufnahme kurz die Spiegelung eines Studiostcheinwerfers auf der glänzenden Karosserie des Autos zu sehen."}'::jsonb WHERE id = 5246;
UPDATE errori SET descrizione_i18n = '{"it":"Il fucile puntato da Buford Tannen e dai suoi uomini presentano dettagli e meccaniche di caricamento che appartengono a brevetti successivi al 1885.","en":"The rifles aimed by Buford Tannen and his men feature details and loading mechanisms belonging to patents later than 1885.","es":"Los rifles apuntados por Buford Tannen y sus hombres presentan detalles y mecanismos de carga que pertenecen a patentes posteriores a 1885.","fr":"Les fusils pointés par Buford Tannen et ses hommes présentent des détails et des mécanismes de chargement qui appartiennent à des brevets postérieurs à 1885.","de":"Die Gewehre, auf die Buford Tannen und seine Männer anlegen, weisen Details und Lademechanismen auf, die zu Patenten nach 1885 gehören."}'::jsonb WHERE id = 5247;
UPDATE errori SET descrizione_i18n = '{"it":"Nel film, ambientato nel 1936, si vedono in diverse scene automobili e camion con targhe stradali che presentano formati o colori introdotti nello stato dell''Illinois solo negli anni successivi.","en":"In the film, set in 1936, cars and trucks with license plates featuring formats or colors introduced in the state of Illinois only in later years can be seen in several scenes.","es":"En la película, ambientada en 1936, se pueden ver en varias escenas automóviles y camiones con matrículas que presentan formatos o colores introducidos en el estado de Illinois solo en años posteriores.","fr":"Dans le film, qui se déroule en 1936, on aperçoit dans plusieurs scènes des voitures et des camions dotés de plaques d''immatriculation aux formats ou aux couleurs introduits dans l''État de l''Illinois seulement les années suivantes.","de":"In dem Film, der 1936 spielt, sind in mehreren Szenen Autos und Lkw mit Nummernschildern zu sehen, deren Formate oder Farben erst in den Folgejahren im Bundesstaat Illinois eingeführt wurden."}'::jsonb WHERE id = 5248;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Norman Bates trasporta il corpo di Marion Crane per caricarlo nel bagagliaio della sua auto, la posizione delle braccia e delle gambe della donna cambia visibilmente tra il primo piano in cui la solleva e il campo medio in cui la depone.","en":"When Norman Bates carries Marion Crane''s body to load it into the trunk of his car, the position of the woman''s arms and legs visibly changes between the close-up where he lifts her and the medium shot where he lays her down.","es":"Cuando Norman Bates transporta el cuerpo de Marion Crane para meterlo en el maletero de su coche, la posición de los brazos y las piernas de la mujer cambia visiblemente entre el primer plano en la que la levanta y el plano medio en el que la deposita.","fr":"Lorsque Norman Bates transporte le corps de Marion Crane pour le charger dans le coffre de sa voiture, la position des bras et des jambes de la femme change visiblement entre le gros plan où il la soulève et le plan moyen où il la dépose.","de":"Als Norman Bates Marion Cranes Leiche trägt, um sie in den Kofferraum seines Autos zu laden, verändert sich die Position von Armen und Beinen der Frau sichtbar zwischen der Nahaufnahme, in der er sie hochhebt, und der Halbtotale, in der er sie ablegt."}'::jsonb WHERE id = 5249;
UPDATE errori SET descrizione_i18n = '{"it":"Nella scena in cui Marion Crane è nella sua camera d''albergo e conta i soldi prima di metterli nella busta, la disposizione dei fogli di giornale usati per nascondere il denaro sul tavolo cambia leggermente di angolazione tra un''inquadratura e l''altra.","en":"In the scene where Marion Crane is in her hotel room counting the money before putting it in the envelope, the arrangement of the newspaper sheets used to hide the cash on the table changes slightly in angle between cuts.","es":"En la escena en la que Marion Crane está en su habitación de hotel contando el dinero antes de meterlo en el sobre, la disposición de las hojas de periódico utilizadas para ocultar el dinero en la mesa cambia ligeramente de ángulo entre plano y plano.","fr":"Dans la scène où Marion Crane est dans sa chambre d''hôtel et compte l''argent avant de le mettre dans l''enveloppe, la disposition des feuilles de journal utilisées pour cacher l''argent sur la table change légèrement d''angle d''un plan à l''autre.","de":"In der Szene, in der Marion Crane in ihrem Hotelzimmer das Geld zählt, bevor sie es in den Umschlag steckt, verändert sich die Anordnung der Zeitungsausrisse auf dem Tisch, die das Bargeld verdecken sollen, von Einstellung zu Einstellung leicht im Winkel."}'::jsonb WHERE id = 5250;
UPDATE errori SET descrizione_i18n = '{"it":"Mentre Marion guida la sua auto di notte sotto la pioggia, il finestrino del lato passeggero passa dall''essere parzialmente abbassato a completamente chiuso a seconda dell''angolazione della telecamera dall''interno o dall''esterno.","en":"While Marion is driving her car at night in the rain, the passenger side window switches from being partially rolled down to completely closed depending on whether the camera angle is from the inside or the outside.","es":"Mientras Marion conduce su coche de noche bajo la lluvia, la ventanilla del lado del pasajero pasa de estar parcialmente bajada a completamente cerrada según si el ángulo de la cámara es desde el interior o el exterior.","fr":"Pendant que Marion conduit sa voiture la nuit sous la pluie, la vitre du côté passager passe d''entrouverte à complètement fermée selon que l''angle de caméra est intérieur ou extérieur.","de":"Während Marion nachts im Regen Auto fährt, wechselt das Beifahrerfenster je nach Kameraperspektive von innen oder außen zwischen teilweise heruntergelassen und komplett geschlossen."}'::jsonb WHERE id = 5251;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Sam Loomis e Lila Crane si trovano nell''ufficio dello Sceriffo Chambers, il cappello che Sam tiene in mano cambia posizione e orientamento tra le inquadrature frontali e quelle di profilo.","en":"When Sam Loomis and Lila Crane are in Sheriff Chambers'' office, the hat Sam is holding in his hand changes position and orientation between frontal and profile shots.","es":"Cuando Sam Loomis y Lila Crane están en el despacho del sheriff Chambers, el sombrero que Sam sostiene en la mano cambia de posición y orientación entre los planos frontales y los de perfil.","fr":"Quand Sam Loomis et Lila Crane se trouvent dans le bureau du shérif Chambers, le chapeau que Sam tient à la main change de position et d''orientation entre les plans de face et de profil.","de":"Als sich Sam Loomis und Lila Crane im Büro von Sheriff Chambers befinden, verändern sich Position und Ausrichtung des Hutes, den Sam in der Hand hält, zwischen Frontal- und Profileinstellungen."}'::jsonb WHERE id = 5252;
UPDATE errori SET descrizione_i18n = '{"it":"Nella sequenza finale nella cella della stazione di polizia, la tazza di caffè che Norman Bates tiene tra le mani cambia livello di riempimento e modo di impugnarla tra i vari cambi di inquadratura.","en":"In the final sequence in the police station cell, the coffee cup Norman Bates is holding changes its fill level and the way he grips it across various cuts.","es":"En la secuencia final en la celda de la comisaría, la taza de café que Norman Bates sostiene entre las manos cambia de nivel de llenado y de forma de agarrarla entre los distintos cambios de plano.","fr":"Dans la séquence finale dans la cellule du commissariat, la tasse de café que Norman Bates tient entre ses mains change de niveau de remplissage et de prise en main au fil des raccords.","de":"In der Schlussszene in der Zelle auf dem Revier verändert sich bei der Kaffeetasse, die Norman Bates in den Händen hält, zwischen den verschiedenen Schnitten sowohl der Füllstand als auch die Art und Weise, wie er sie hält."}'::jsonb WHERE id = 5253;
UPDATE errori SET descrizione_i18n = '{"it":"Durante la conversazione iniziale nell''appartamento tra Tony e Swann, la bottiglia e i bicchieri sul tavolino cambiano leggermente di disposizione e livello tra un''inquadratura e l''altra.","en":"During the initial apartment conversation between Tony and Swann, the bottle and glasses on the coffee table slightly change their arrangement and level between shots.","es":"Durante la conversación inicial en el apartamento entre Tony y Swann, la botella y los vasos de la mesa de centro cambian ligeramente de disposición y nivel de un plano a otro.","fr":"Pendant la conversation initiale dans l''appartement entre Tony et Swann, la bouteille et les verres sur la table basse changent légèrement de disposition et de niveau d''un plan à l''autre.","de":"Während des anfänglichen Gesprächs in der Wohnung zwischen Tony und Swann verändern sich die Anordnung und der Füllstand der Flasche und Gläser auf dem Couchtisch von Einstellung zu Einstellung leicht."}'::jsonb WHERE id = 5254;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Margot scrive la lettera alla sua scrivania, la posizione del foglio di carta e della penna varia nei passaggi dai piani medi ai primi piani.","en":"When Margot writes the letter at her desk, the position of the sheet of paper and the pen varies during transitions from medium shots to close-ups.","es":"Cuando Margot escribe la carta en su escritorio, la posición de la hoja de papel y del bolígrafo varía en las transiciones de planos medios a primeros planos.","fr":"Quand Margot écrit la lettre à son bureau, la position de la feuille de papier et du stylo varie lors des transitions des plans moyens aux gros plans.","de":"Als Margot an ihrem Schreibtisch den Brief schreibt, variiert die Position des Papierblatts und des Stifts bei den Übergängen von Halbtotalen zu Nahaufnahmen."}'::jsonb WHERE id = 5255;
UPDATE errori SET descrizione_i18n = '{"it":"In alcune scene girate all''interno del salotto di Tony, riflettendosi nei vetri della finestra o nei quadri incorniciati, si intravedono fugacemente le sagome di membri della troupe e attrezzature di illuminazione.","en":"In some scenes shot inside Tony''s living room, reflected in the window glass or framed paintings, the silhouettes of crew members and lighting equipment can be briefly glimpsed.","es":"En algunas escenas rodadas dentro del salón de Tony, reflejadas en los cristales de la ventana o en los cuadros enmarcados, se vislumbran fugazmente las siluetas de miembros del equipo técnico y de iluminación.","fr":"Dans certaines scènes tournées à l''intérieur du salon de Tony, se reflétant dans les vitres de la fenêtre ou les tableaux encadrés, on aperçoit brièvement les silhouettes de membres de l''équipe technique et du matériel d''éclairage.","de":"In einigen Szenen, die im Wohnzimmer von Tony gedreht wurden, sind im Spiegelbild der Fensterscheiben oder gerahmten Gemälde flüchtig die Silhouetten von Crewmitgliedern und Beleuchtungsequipment zu erkennen."}'::jsonb WHERE id = 5256;
UPDATE errori SET descrizione_i18n = '{"it":"Le chiavi che Tony lascia sulla giacca o sposta sul tavolo appaiono e scompaiono in modo sottile durante le sequenze di pianificazione del delitto.","en":"The keys that Tony leaves on the jacket or moves to the table subtly appear and disappear during the crime planning sequences.","es":"Las llaves que Tony deja en la chaqueta o mueve a la mesa aparecen y desaparecen sutilmente durante las secuencias de planificación del crimen.","fr":"Les clés que Tony laisse sur la veste ou déplace sur la table apparaissent et disparaissent subtilement lors des séquences de planification du crime.","de":"Die Schlüssel, die Tony auf der Jacke liegen lässt oder auf den Tisch legt, erscheinen und verschwinden während der Verbrechensplanungssequenzen auf subtile Weise."}'::jsonb WHERE id = 5257;
UPDATE errori SET descrizione_i18n = '{"it":"Quando Margot viene aggredita nella scena clou con le forbici, la posizione delle forbici stesse e il modo in cui cadono a terra variano tra il momento dell''attacco e le successive inquadrature della polizia.","en":"When Margot is attacked in the climax with the scissors, the position of the scissors themselves and the way they fall to the ground vary between the attack and the subsequent police shots.","es":"Cuando Margot es atacada en la escena culminante con las tijeras, la posición de las propias tijeras y la forma en que caen al suelo varían entre el momento del ataque y las tomas posteriores de la policía.","fr":"Lorsque Margot est attaquée dans la scène clé avec les ciseaux, la position des ciseaux eux-mêmes et la manière dont ils tombent au sol varient entre le moment de l''attaque et les plans suivants de la police.","de":"Als Margot in der Climax-Szene mit der Schere angegriffen wird, variieren die Position der Schere selbst und die Art, wie sie zu Boden fällt, zwischen dem Angriff und den späteren Polizeieinstellungen."}'::jsonb WHERE id = 5258;
